{
  "name": "Controle de Dados Pro",
  "description": "Sistema completo para gestão de horas e controle financeiro de funcionários registrados e fixos, com painel administrativo e cálculos automatizados."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum EmployeeType {
  REGISTRADO = 'REGISTRADO',
  FIXO = 'FIXO'
}

export enum RequestStatus {
  PENDENTE = 'PENDENTE',
  APROVADO = 'APROVADO',
  REJEITADO = 'REJEITADO'
}

export interface Sector {
  id: string;
  name: string;
  fixedRate: number; // Value for "Fixo" employees in this sector
}

export interface Employee {
  id: string;
  name: string;
  sectorId: string;
  type: EmployeeType;
  salary: number;
  monthlyHours: number;
}

export interface TimeRecord {
  date: string;
  realEntry: string;
  punchEntry: string;
  punchExit: string;
  realExit: string;
  isFolgaVendida: boolean;
}

export interface TimeRequest {
  id: string;
  employeeId: string;
  employeeName: string;
  employeeType: EmployeeType;
  sectorId: string;
  sectorName: string;
  weekStarting: string;
  records: TimeRecord[];
  status: RequestStatus;
  calculatedValue: number;
  totalTimeDecimal: number;
  createdAt: string;
}

export interface AppState {
  view: 'HOME' | 'SELECTION' | 'FLOW' | 'ADMIN';
  flowType: EmployeeType | null;
  adminSubView: 'DASHBOARD' | 'SECTORS' | 'EMPLOYEES' | 'REQUESTS' | 'INTEGRATIONS';
}

export const formatCurrency = (value: number) => {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
};

export const timeToDecimal = (time: string): number => {
  if (!time) return 0;
  const [hours, minutes] = time.split(':').map(Number);
  return hours + minutes / 60;
};

export const calculateTimeDiff = (real: string, punch: string): number => {
  return Math.abs(timeToDecimal(real) - timeToDecimal(punch));
};

export const getWeekDays = (baseDate: Date) => {
  const days = [];
  const start = new Date(baseDate);
  // Monday is start of week
  const day = start.getDay();
  const diff = start.getDate() - day + (day === 0 ? -6 : 1);
  start.setDate(diff);

  for (let i = 0; i < 7; i++) {
    const d = new Date(start);
    d.setDate(start.getDate() + i);
    days.push(d.toISOString().split('T')[0]);
  }
  return days;
};

import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Play, 
  ArrowLeft, 
  LayoutDashboard, 
  Users, 
  MapPin, 
  ClipboardList, 
  Link as LinkIcon,
  CheckCircle,
  XCircle,
  Clock,
  LogOut,
  ChevronRight,
  Filter,
  Download
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell
} from 'recharts';
import { 
  EmployeeType, 
  RequestStatus, 
  Sector, 
  Employee, 
  TimeRequest, 
  AppState,
  TimeRecord 
} from './types';
import { 
  formatCurrency, 
  timeToDecimal, 
  calculateTimeDiff, 
  getWeekDays 
} from './utils';

const STORAGE_KEY = 'controle_dados_db';

const App: React.FC = () => {
  // --- Data Persistence ---
  const [sectors, setSectors] = useState<Sector[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [requests, setRequests] = useState<TimeRequest[]>([]);
  const [state, setState] = useState<AppState>({
    view: 'HOME',
    flowType: null,
    adminSubView: 'DASHBOARD'
  });

  // --- Auth & Temp State ---
  const [adminPassword, setAdminPassword] = useState('');
  const [isAuth, setIsAuth] = useState(false);
  const [selectedSector, setSelectedSector] = useState<string>('');
  const [selectedEmployee, setSelectedEmployee] = useState<string>('');
  const [showFormModal, setShowFormModal] = useState(false);
  const [currentWeek, setCurrentWeek] = useState(new Date().toISOString().split('T')[0]);

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setSectors(parsed.sectors || []);
      setEmployees(parsed.employees || []);
      setRequests(parsed.requests || []);
    } else {
      // Default sample data
      const initialSectors = [
        { id: '1', name: 'Recepção', fixedRate: 80 },
        { id: '2', name: 'Governança', fixedRate: 70 },
        { id: '3', name: 'Reservas', fixedRate: 75 },
        { id: '4', name: 'Mensageria', fixedRate: 60 },
      ];
      setSectors(initialSectors);
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ sectors: initialSectors, employees: [], requests: [] }));
    }
  }, []);

  // Save changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ sectors, employees, requests }));
  }, [sectors, employees, requests]);

  const handleAdminLogin = () => {
    if (adminPassword === '123') {
      setIsAuth(true);
      setState({ ...state, view: 'ADMIN' });
      setAdminPassword('');
    } else {
      alert('Senha incorreta!');
    }
  };

  const submitRequest = (records: TimeRecord[]) => {
    const employee = employees.find(e => e.id === selectedEmployee);
    const sector = sectors.find(s => s.id === (employee?.sectorId || selectedSector));

    if (!employee && state.flowType === EmployeeType.REGISTRADO) return;

    let totalDiffHours = 0;
    let totalPayment = 0;

    if (state.flowType === EmployeeType.REGISTRADO && employee) {
      const hourlyBase = employee.salary / employee.monthlyHours;
      const hourlyWithExtra = hourlyBase * 1.25;

      records.forEach(r => {
        if (!r.isFolgaVendida) {
          const entryDiff = calculateTimeDiff(r.realEntry, r.punchEntry);
          const exitDiff = calculateTimeDiff(r.realExit, r.punchExit);
          totalDiffHours += (entryDiff + exitDiff);
        } else {
          // Folga vendida calculation for Registrado? 
          // Assuming just standard total duration if sold
          totalDiffHours += calculateTimeDiff(r.realExit, r.realEntry);
        }
      });
      totalPayment = totalDiffHours * hourlyWithExtra;
    } else {
      // FIXO Flow
      const dailyRate = sector?.fixedRate || 0;
      records.forEach(r => {
        if (r.realEntry && r.realExit) {
          totalPayment += dailyRate + 12; // Base + VT
        }
      });
    }

    const newRequest: TimeRequest = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: employee?.id || 'fixo-temp',
      employeeName: employee?.name || 'Funcionário Fixo',
      employeeType: state.flowType!,
      sectorId: sector?.id || '',
      sectorName: sector?.name || '',
      weekStarting: currentWeek,
      records: records,
      status: RequestStatus.PENDENTE,
      calculatedValue: totalPayment,
      totalTimeDecimal: totalDiffHours,
      createdAt: new Date().toISOString()
    };

    setRequests([newRequest, ...requests]);
    setShowFormModal(false);
    setState({ ...state, view: 'HOME' });
    alert('Solicitação enviada com sucesso!');
  };

  // --- Sub-Components ---

  const HomeView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-4">
      <div className="bg-white p-12 rounded-3xl shadow-2xl max-w-lg w-full transform transition hover:scale-105 duration-300">
        <div className="bg-blue-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-blue-200">
          <ClipboardList className="text-white w-10 h-10" />
        </div>
        <h1 className="text-4xl font-extrabold text-gray-800 mb-4 tracking-tight">Controle de Dados</h1>
        <p className="text-gray-500 mb-10 text-lg">Gerenciamento eficiente de jornadas e fechamentos semanais.</p>

        <button 
          onClick={() => setState({ ...state, view: 'SELECTION' })}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-8 rounded-xl transition flex items-center justify-center gap-3 shadow-xl shadow-blue-100 group"
        >
          <span>Começar</span>
          <Play className="w-5 h-5 group-hover:translate-x-1 transition" />
        </button>

        <div className="mt-8 pt-8 border-t border-gray-100">
          <div className="relative">
            <input 
              type="password"
              placeholder="Acesso Admin"
              className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              value={adminPassword}
              onChange={(e) => setAdminPassword(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleAdminLogin()}
            />
            <Settings className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <button 
              onClick={handleAdminLogin}
              className="absolute right-2 top-1/2 -translate-y-1/2 bg-gray-200 hover:bg-gray-300 p-1.5 rounded-lg transition"
            >
              <ChevronRight className="w-4 h-4 text-gray-600" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const SelectionView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <button 
        onClick={() => setState({ ...state, view: 'HOME' })}
        className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium"
      >
        <ArrowLeft className="w-5 h-5" /> Voltar ao Início
      </button>
      <div className="grid md:grid-cols-2 gap-8 max-w-4xl w-full">
        <button 
          onClick={() => setState({ ...state, view: 'FLOW', flowType: EmployeeType.REGISTRADO })}
          className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-blue-500 border-2 border-transparent transition-all group"
        >
          <div className="bg-blue-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-blue-600 transition">
            <Users className="text-blue-600 w-8 h-8 group-hover:text-white transition" />
          </div>
          <h2 className="text-2xl font-bold mb-2">Registrado</h2>
          <p className="text-gray-500">Colaboradores em regime CLT com controle de ponto manual.</p>
        </button>
        <button 
          onClick={() => setState({ ...state, view: 'FLOW', flowType: EmployeeType.FIXO })}
          className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-green-500 border-2 border-transparent transition-all group"
        >
          <div className="bg-green-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-green-600 transition">
            <MapPin className="text-green-600 w-8 h-8 group-hover:text-white transition" />
          </div>
          <h2 className="text-2xl font-bold mb-2">Fixo (Extra)</h2>
          <p className="text-gray-500">Colaboradores eventuais com diária fixa e vale-transporte.</p>
        </button>
      </div>
    </div>
  );

  const FlowView = () => {
    const filteredEmployees = employees.filter(e => e.sectorId === selectedSector && e.type === state.flowType);

    return (
      <div className="max-w-xl mx-auto py-12 px-4">
        <button 
          onClick={() => setState({ ...state, view: 'SELECTION' })}
          className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium"
        >
          <ArrowLeft className="w-5 h-5" /> Alterar Tipo
        </button>

        <div className="bg-white rounded-3xl shadow-xl p-8 space-y-8">
          <h2 className="text-2xl font-bold text-gray-800 border-b pb-4">
            {state.flowType === EmployeeType.REGISTRADO ? 'Lançamento Registrado' : 'Lançamento Fixo'}
          </h2>

          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Selecione o Setor</label>
            <select 
              className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none appearance-none"
              value={selectedSector}
              onChange={(e) => setSelectedSector(e.target.value)}
            >
              <option value="">Selecione um setor...</option>
              {sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>

          {selectedSector && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Selecione o Funcionário</label>
              {state.flowType === EmployeeType.REGISTRADO ? (
                <select 
                  className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none appearance-none"
                  value={selectedEmployee}
                  onChange={(e) => setSelectedEmployee(e.target.value)}
                >
                  <option value="">Selecione um funcionário...</option>
                  {filteredEmployees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
                </select>
              ) : (
                <input 
                  type="text"
                  placeholder="Nome do Funcionário Fixo"
                  className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                  onChange={(e) => setSelectedEmployee(e.target.value)}
                />
              )}
            </div>
          )}

          <button 
            disabled={!selectedSector || !selectedEmployee}
            onClick={() => setShowFormModal(true)}
            className="w-full bg-blue-600 disabled:bg-gray-300 hover:bg-blue-700 text-white font-bold py-4 rounded-xl transition shadow-lg"
          >
            Cadastrar Horários
          </button>
        </div>
      </div>
    );
  };

  const FormModal = () => {
    const days = getWeekDays(new Date(currentWeek));
    const [records, setRecords] = useState<TimeRecord[]>(
      days.map(d => ({ date: d, realEntry: '', punchEntry: '', punchExit: '', realExit: '', isFolgaVendida: false }))
    );

    const updateRecord = (index: number, field: keyof TimeRecord, value: any) => {
      const newRecords = [...records];
      newRecords[index] = { ...newRecords[index], [field]: value };
      setRecords(newRecords);
    };

    return (
      <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-y-auto p-8 relative">
          <button 
            onClick={() => setShowFormModal(false)}
            className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition"
          >
            <XCircle className="w-8 h-8" />
          </button>

          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h2 className="text-2xl font-bold">Fechamento Semanal</h2>
            <div className="flex items-center gap-4">
              <span className="text-sm font-medium text-gray-500">Semana de:</span>
              <input 
                type="date"
                className="p-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                value={currentWeek}
                onChange={(e) => setCurrentWeek(e.target.value)}
              />
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
                  <th className="p-4 border-b">Data</th>
                  <th className="p-4 border-b">Real Entrada</th>
                  <th className="p-4 border-b">Ponto Entrada</th>
                  <th className="p-4 border-b">Ponto Saída</th>
                  <th className="p-4 border-b">Real Saída</th>
                  <th className="p-4 border-b text-center">Ação</th>
                </tr>
              </thead>
              <tbody>
                {records.map((r, idx) => (
                  <tr key={idx} className="hover:bg-gray-50 transition border-b border-gray-100">
                    <td className="p-4 font-medium text-gray-700">
                      {new Date(r.date).toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' })}
                    </td>
                    <td className="p-2">
                      <input 
                        type="time"
                        className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                        value={r.realEntry}
                        onChange={(e) => updateRecord(idx, 'realEntry', e.target.value)}
                      />
                    </td>
                    {!r.isFolgaVendida ? (
                      <>
                        <td className="p-2">
                          <input 
                            type="time"
                            className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                            value={r.punchEntry}
                            onChange={(e) => updateRecord(idx, 'punchEntry', e.target.value)}
                          />
                        </td>
                        <td className="p-2">
                          <input 
                            type="time"
                            className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                            value={r.punchExit}
                            onChange={(e) => updateRecord(idx, 'punchExit', e.target.value)}
                          />
                        </td>
                      </>
                    ) : (
                      <td colSpan={2} className="p-2 text-center text-blue-600 font-bold bg-blue-50 rounded-lg">FOLGA VENDIDA</td>
                    )}
                    <td className="p-2">
                      <input 
                        type="time"
                        className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                        value={r.realExit}
                        onChange={(e) => updateRecord(idx, 'realExit', e.target.value)}
                      />
                    </td>
                    <td className="p-2 text-center">
                      <button 
                        onClick={() => updateRecord(idx, 'isFolgaVendida', !r.isFolgaVendida)}
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition ${r.isFolgaVendida ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                      >
                        {r.isFolgaVendida ? 'Remover Folga' : 'Folga Vendida'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="mt-10 flex justify-end gap-4">
            <button 
              onClick={() => setShowFormModal(false)}
              className="px-8 py-3 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold rounded-xl transition"
            >
              Cancelar
            </button>
            <button 
              onClick={() => submitRequest(records)}
              className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl transition shadow-lg shadow-blue-200"
            >
              Confirmar e Enviar
            </button>
          </div>
        </div>
      </div>
    );
  };

  const AdminView = () => {
    const [filterStatus, setFilterStatus] = useState<string>('ALL');
    const [filterType, setFilterType] = useState<string>('ALL');

    const filteredRequests = requests.filter(req => {
      if (filterStatus !== 'ALL' && req.status !== filterStatus) return false;
      if (filterType !== 'ALL' && req.employeeType !== filterType) return false;
      return true;
    });

    const Dashboard = () => {
      const totalSpending = requests.reduce((acc, r) => acc + (r.status === RequestStatus.APROVADO ? r.calculatedValue : 0), 0);
      const spendingBySector = sectors.map(s => ({
        name: s.name,
        value: requests.filter(r => r.sectorId === s.id && r.status === RequestStatus.APROVADO).reduce((acc, r) => acc + r.calculatedValue, 0)
      }));

      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
              <p className="text-gray-500 text-sm font-medium mb-1">Gasto Total Aprovado</p>
              <h3 className="text-3xl font-bold text-gray-800">{formatCurrency(totalSpending)}</h3>
            </div>
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
              <p className="text-gray-500 text-sm font-medium mb-1">Solicitações Pendentes</p>
              <h3 className="text-3xl font-bold text-blue-600">{requests.filter(r => r.status === RequestStatus.PENDENTE).length}</h3>
            </div>
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
              <p className="text-gray-500 text-sm font-medium mb-1">Setor com Mais Lançamentos</p>
              <h3 className="text-2xl font-bold text-gray-800">
                {spendingBySector.sort((a,b) => b.value - a.value)[0]?.name || '-'}
              </h3>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 h-[400px]">
              <h4 className="font-bold mb-6 flex items-center gap-2">
                <BarChart className="w-5 h-5" /> Gastos por Setor
              </h4>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={spendingBySector}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="name" />
                  <YAxis tickFormatter={(val) => `R$${val}`} />
                  <Tooltip formatter={(val: number) => formatCurrency(val)} />
                  <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 h-[400px]">
              <h4 className="font-bold mb-6 flex items-center gap-2">
                <PieChart className="w-5 h-5" /> Distribuição por Tipo
              </h4>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={[
                      { name: 'Registrado', value: requests.filter(r => r.employeeType === EmployeeType.REGISTRADO).length },
                      { name: 'Fixo', value: requests.filter(r => r.employeeType === EmployeeType.FIXO).length },
                    ]}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={100}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    <Cell fill="#3b82f6" />
                    <Cell fill="#10b981" />
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      );
    };

    const SectorsManager = () => {
      const [newSector, setNewSector] = useState({ name: '', fixedRate: 0 });

      const addSector = () => {
        if (!newSector.name) return;
        setSectors([...sectors, { ...newSector, id: Math.random().toString(36).substr(2, 9) }]);
        setNewSector({ name: '', fixedRate: 0 });
      };

      const removeSector = (id: string) => setSectors(sectors.filter(s => s.id !== id));

      return (
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="flex items-center justify-between">
            <h2 className="text-2xl font-bold">Gerenciar Setores</h2>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-gray-50 p-6 rounded-2xl">
            <input 
              type="text" 
              placeholder="Nome do Setor (ex: Recepção)"
              className="p-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              value={newSector.name}
              onChange={(e) => setNewSector({ ...newSector, name: e.target.value })}
            />
            <input 
              type="number" 
              placeholder="Valor Diária Extra (R$)"
              className="p-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              value={newSector.fixedRate || ''}
              onChange={(e) => setNewSector({ ...newSector, fixedRate: parseFloat(e.target.value) })}
            />
            <button 
              onClick={addSector}
              className="bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl transition"
            >
              Adicionar Setor
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-gray-400 text-xs uppercase font-bold border-b">
                  <th className="py-4">Setor</th>
                  <th className="py-4">Valor Fixo (Diária)</th>
                  <th className="py-4 text-right">Ações</th>
                </tr>
              </thead>
              <tbody>
                {sectors.map(s => (
                  <tr key={s.id} className="border-b last:border-0 hover:bg-gray-50 transition">
                    <td className="py-4 font-semibold text-gray-700">{s.name}</td>
                    <td className="py-4 text-gray-600">{formatCurrency(s.fixedRate)}</td>
                    <td className="py-4 text-right">
                      <button 
                        onClick={() => removeSector(s.id)}
                        className="text-red-500 hover:text-red-700 p-2 rounded-lg hover:bg-red-50 transition"
                      >
                        <XCircle className="w-5 h-5" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      );
    };

    const EmployeesManager = () => {
      const [newEmp, setNewEmp] = useState({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });

      const addEmployee = () => {
        if (!newEmp.name || !newEmp.sectorId) return;
        setEmployees([...employees, { ...newEmp, id: Math.random().toString(36).substr(2, 9) }]);
        setNewEmp({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });
      };

      return (
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <h2 className="text-2xl font-bold">Cadastrar Funcionários Registrados</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 bg-gray-50 p-6 rounded-2xl">
            <input 
              type="text" 
              placeholder="Nome"
              className="p-3 border rounded-xl outline-none"
              value={newEmp.name}
              onChange={(e) => setNewEmp({ ...newEmp, name: e.target.value })}
            />
            <select 
              className="p-3 border rounded-xl outline-none"
              value={newEmp.sectorId}
              onChange={(e) => setNewEmp({ ...newEmp, sectorId: e.target.value })}
            >
              <option value="">Setor...</option>
              {sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
            <input 
              type="number" 
              placeholder="Salário Base"
              className="p-3 border rounded-xl outline-none"
              value={newEmp.salary || ''}
              onChange={(e) => setNewEmp({ ...newEmp, salary: parseFloat(e.target.value) })}
            />
            <input 
              type="number" 
              placeholder="Carga Horária Mensal"
              className="p-3 border rounded-xl outline-none"
              value={newEmp.monthlyHours || ''}
              onChange={(e) => setNewEmp({ ...newEmp, monthlyHours: parseFloat(e.target.value) })}
            />
