              Adicionar
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-gray-400 text-xs uppercase font-bold border-b">
                  <th className="py-4">Nome</th>
                  <th className="py-4">Setor</th>
                  <th className="py-4">Valor Hora (+25%)</th>
                  <th className="py-4 text-right">Remover</th>
