              <tbody>
                {employees.map(e => {
                  const sector = sectors.find(s => s.id === e.sectorId);
                  const hourlyRate = (e.salary / e.monthlyHours) * 1.25;
                  return (
                    <tr key={e.id} className="border-b last:border-0 hover:bg-gray-50">
