                      <td className="py-4 text-gray-500">{sector?.name}</td>
                      <td className="py-4 text-blue-600 font-bold">{formatCurrency(hourlyRate)}</td>
                      <td className="py-4 text-right">
                        <button onClick={() => setEmployees(employees.filter(emp => emp.id !== e.id))} className="text-red-400 hover:text-red-600">
                          <XCircle className="w-5 h-5" />
                        </button>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      );
    };

    const RequestsManager = () => {
      const updateStatus = (id: string, status: RequestStatus) => {
        setRequests(requests.map(r => r.id === id ? { ...r, status } : r));
      };

      return (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
          <div className="flex flex-col md:flex-row gap-4 justify-between bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
            <h2 className="text-2xl font-bold">Solicitações</h2>
            <div className="flex items-center gap-3">
              <Filter className="w-4 h-4 text-gray-400" />
              <select className="border rounded-lg p-2 text-sm bg-gray-50 outline-none" value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
                <option value="ALL">Status: Todos</option>
                <option value={RequestStatus.PENDENTE}>Pendente</option>
                <option value={RequestStatus.APROVADO}>Aprovado</option>
                <option value={RequestStatus.REJEITADO}>Rejeitado</option>
              </select>
              <select className="border rounded-lg p-2 text-sm bg-gray-50 outline-none" value={filterType} onChange={(e) => setFilterType(e.target.value)}>
                <option value="ALL">Tipo: Todos</option>
                <option value={EmployeeType.REGISTRADO}>Registrado</option>
                <option value={EmployeeType.FIXO}>Fixo</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {filteredRequests.map(req => (
              <div key={req.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm hover:shadow-md transition">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className={`px-2 py-0.5 rounded-md text-[10px] font-extrabold uppercase ${req.employeeType === EmployeeType.REGISTRADO ? 'bg-blue-100 text-blue-700' : 'bg-green-100 text-green-700'}`}>
                        {req.employeeType}
                      </span>
                      <h4 className="text-lg font-bold">{req.employeeName}</h4>
                    </div>
                    <p className="text-sm text-gray-500 flex items-center gap-2">
                      <MapPin className="w-3 h-3" /> {req.sectorName} • <Clock className="w-3 h-3" /> Semana de {new Date(req.weekStarting).toLocaleDateString('pt-BR')}
                    </p>
                  </div>

                  <div className="flex items-center gap-6">
                    <div className="text-right">
                      <p className="text-xs text-gray-400 uppercase font-bold tracking-wider">A Pagar</p>
                      <p className="text-xl font-black text-gray-800">{formatCurrency(req.calculatedValue)}</p>
                      {req.employeeType === EmployeeType.REGISTRADO && (
                        <p className="text-[10px] text-blue-500 font-bold uppercase">{req.totalTimeDecimal.toFixed(2)}h de diff</p>
                      )}
                    </div>

                    {req.status === RequestStatus.PENDENTE ? (
                      <div className="flex gap-2">
                        <button onClick={() => updateStatus(req.id, RequestStatus.APROVADO)} className="bg-green-500 hover:bg-green-600 text-white p-2.5 rounded-xl shadow-lg shadow-green-100 transition">
                          <CheckCircle className="w-5 h-5" />
                        </button>
                        <button onClick={() => updateStatus(req.id, RequestStatus.REJEITADO)} className="bg-red-500 hover:bg-red-600 text-white p-2.5 rounded-xl shadow-lg shadow-red-100 transition">
                          <XCircle className="w-5 h-5" />
                        </button>
                      </div>
                    ) : (
                      <span className={`px-4 py-2 rounded-xl text-sm font-bold uppercase ${req.status === RequestStatus.APROVADO ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                        {req.status}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {filteredRequests.length === 0 && (
              <div className="text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
                <ClipboardList className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-400 font-medium">Nenhuma solicitação encontrada para os filtros aplicados.</p>
              </div>
            )}
          </div>
        </div>
      );
    };

    const Integrations = () => {
      const exportToCsv = (type: EmployeeType) => {
        const filtered = requests.filter(r => r.employeeType === type && r.status === RequestStatus.APROVADO);
        const headers = ["Data", "Funcionário", "Setor", "Valor"];
        const rows = filtered.map(r => [
          new Date(r.createdAt).toLocaleDateString('pt-BR'),
          r.employeeName,
          r.sectorName,
          r.calculatedValue.toFixed(2)
        ]);

        const csvContent = "data:text/csv;charset=utf-8," 
          + headers.join(",") + "\n"
          + rows.map(e => e.join(",")).join("\n");

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `integracao_${type.toLowerCase()}.csv`);
        document.body.appendChild(link);
        link.click();
      };

      return (
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <h2 className="text-2xl font-bold flex items-center gap-2">
            <LinkIcon className="w-6 h-6 text-blue-600" /> Integrações com Planilhas
          </h2>
          <p className="text-gray-500">Exporte os dados aprovados para alimentar suas planilhas de controle externo.</p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="p-8 border rounded-3xl hover:border-blue-500 transition-all bg-blue-50/50 group">
              <h3 className="text-xl font-bold mb-4">Planilha Registrados</h3>
              <p className="text-sm text-gray-600 mb-6">Contém dados de funcionários CLT, horas excedentes e valores calculados com adicional de 25%.</p>
              <button 
                onClick={() => exportToCsv(EmployeeType.REGISTRADO)}
                className="flex items-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-xl hover:bg-blue-700 transition"
              >
                <Download className="w-4 h-4" /> Exportar Dados Registrados
              </button>
            </div>

            <div className="p-8 border rounded-3xl hover:border-green-500 transition-all bg-green-50/50 group">
              <h3 className="text-xl font-bold mb-4">Planilha Fixos</h3>
              <p className="text-sm text-gray-600 mb-6">Contém dados de funcionários eventuais, diárias fixas por setor e auxílio transporte de R$12.</p>
              <button 
                onClick={() => exportToCsv(EmployeeType.FIXO)}
                className="flex items-center gap-2 bg-green-600 text-white px-6 py-3 rounded-xl hover:bg-green-700 transition"
              >
                <Download className="w-4 h-4" /> Exportar Dados Fixos
              </button>
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className="flex h-screen bg-gray-50 overflow-hidden">
        {/* Sidebar */}
        <div className="w-72 bg-white border-r border-gray-100 flex flex-col p-6 shadow-sm">
          <div className="flex items-center gap-3 mb-12">
            <div className="bg-blue-600 p-2 rounded-lg">
              <Settings className="text-white w-5 h-5" />
            </div>
            <h2 className="text-xl font-black text-gray-800">Admin Panel</h2>
          </div>

          <nav className="flex-1 space-y-2">
            {[
              { id: 'DASHBOARD', label: 'Dashboard', icon: LayoutDashboard },
              { id: 'SECTORS', label: 'Setores', icon: MapPin },
              { id: 'EMPLOYEES', label: 'Funcionários', icon: Users },
              { id: 'REQUESTS', label: 'Solicitações', icon: ClipboardList },
              { id: 'INTEGRATIONS', label: 'Integrações', icon: LinkIcon },
            ].map(item => (
              <button
                key={item.id}
                onClick={() => setState({ ...state, adminSubView: item.id as any })}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${state.adminSubView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'text-gray-500 hover:bg-gray-50 hover:text-blue-600'}`}
              >
                <item.icon className="w-5 h-5" />
                {item.label}
              </button>
            ))}
          </nav>

          <button 
            onClick={() => { setIsAuth(false); setState({ ...state, view: 'HOME' }) }}
            className="flex items-center gap-3 px-4 py-3 text-red-500 font-bold hover:bg-red-50 rounded-xl transition"
          >
            <LogOut className="w-5 h-5" /> Sair
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-10 bg-[#F9FBFF]">
          {state.adminSubView === 'DASHBOARD' && <Dashboard />}
          {state.adminSubView === 'SECTORS' && <SectorsManager />}
          {state.adminSubView === 'EMPLOYEES' && <EmployeesManager />}
          {state.adminSubView === 'REQUESTS' && <RequestsManager />}
          {state.adminSubView === 'INTEGRATIONS' && <Integrations />}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen">
      {state.view === 'HOME' && <HomeView />}
      {state.view === 'SELECTION' && <SelectionView />}
      {state.view === 'FLOW' && <FlowView />}
      {state.view === 'ADMIN' && <AdminView />}

      {showFormModal && <FormModal />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Play, 
  ArrowLeft, 
  LayoutDashboard, 
  Users, 
  MapPin, 
  ClipboardList, 
  Link as LinkIcon,
  CheckCircle,
  XCircle,
  Clock,
  LogOut,
  ChevronRight,
  Filter,
  Download
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell
} from 'recharts';
import { 
  EmployeeType, 
  RequestStatus, 
  Sector, 
  Employee, 
  TimeRequest, 
  AppState,
  TimeRecord 
} from './types';
import { 
  formatCurrency, 
  timeToDecimal, 
  calculateTimeDiff, 
  getWeekDays 
} from './utils';

const STORAGE_KEY = 'controle_dados_db';

const App: React.FC = () => {
  // --- Data Persistence ---
  const [sectors, setSectors] = useState<Sector[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [requests, setRequests] = useState<TimeRequest[]>([]);
  const [state, setState] = useState<AppState>({
    view: 'HOME',
    flowType: null,
    adminSubView: 'DASHBOARD'
  });

  // --- Auth & Temp State ---
  const [adminPassword, setAdminPassword] = useState('');
  const [isAuth, setIsAuth] = useState(false);
  const [selectedSector, setSelectedSector] = useState<string>('');
  const [selectedEmployee, setSelectedEmployee] = useState<string>('');
  const [showFormModal, setShowFormModal] = useState(false);
  const [currentWeek, setCurrentWeek] = useState(new Date().toISOString().split('T')[0]);

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setSectors(parsed.sectors || []);
      setEmployees(parsed.employees || []);
      setRequests(parsed.requests || []);
    } else {
      const initialSectors = [
        { id: '1', name: 'Recepção', fixedRate: 80 },
        { id: '2', name: 'Governança', fixedRate: 70 },
        { id: '3', name: 'Reservas', fixedRate: 75 },
        { id: '4', name: 'Mensageria', fixedRate: 60 },
      ];
      setSectors(initialSectors);
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ sectors: initialSectors, employees: [], requests: [] }));
    }
  }, []);

  // Save changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ sectors, employees, requests }));
  }, [sectors, employees, requests]);

  const handleAdminLogin = () => {
    if (adminPassword === '123') {
      setIsAuth(true);
      setState({ ...state, view: 'ADMIN' });
      setAdminPassword('');
    } else {
      alert('Senha incorreta!');
    }
  };

  const submitRequest = (records: TimeRecord[]) => {
    const employee = employees.find(e => e.id === selectedEmployee);
    const sector = sectors.find(s => s.id === (employee?.sectorId || selectedSector));

    if (!employee && state.flowType === EmployeeType.REGISTRADO) return;

    let totalDiffHours = 0;
    let totalPayment = 0;

    if (state.flowType === EmployeeType.REGISTRADO && employee) {
      const hourlyBase = employee.salary / employee.monthlyHours;
      const hourlyWithExtra = hourlyBase * 1.25;

      records.forEach(r => {
        if (!r.isFolgaVendida) {
          const entryDiff = calculateTimeDiff(r.realEntry, r.punchEntry);
          const exitDiff = calculateTimeDiff(r.realExit, r.punchExit);
          totalDiffHours += (entryDiff + exitDiff);
        } else {
          totalDiffHours += calculateTimeDiff(r.realExit, r.realEntry);
        }
      });
      totalPayment = totalDiffHours * hourlyWithExtra;
    } else {
      const dailyRate = sector?.fixedRate || 0;
      records.forEach(r => {
        if (r.realEntry && r.realExit) {
          totalPayment += dailyRate + 12;
        }
      });
    }

    const newRequest: TimeRequest = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: employee?.id || 'fixo-temp',
      employeeName: employee?.name || 'Funcionário Fixo',
      employeeType: state.flowType!,
      sectorId: sector?.id || '',
      sectorName: sector?.name || '',
      weekStarting: currentWeek,
      records: records,
      status: RequestStatus.PENDENTE,
      calculatedValue: totalPayment,
      totalTimeDecimal: totalDiffHours,
      createdAt: new Date().toISOString()
    };

    setRequests([newRequest, ...requests]);
    setShowFormModal(false);
    setState({ ...state, view: 'HOME' });
    alert('Solicitação enviada com sucesso!');
  };

  // --- View Render Functions (Not using as <Component /> to avoid focus loss) ---

  const renderHomeView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-4">
      <div className="bg-white p-12 rounded-3xl shadow-2xl max-w-lg w-full transform transition hover:scale-105 duration-300">
        <div className="bg-blue-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-blue-200">
          <ClipboardList className="text-white w-10 h-10" />
        </div>
        <h1 className="text-4xl font-extrabold text-gray-800 mb-4 tracking-tight">Controle de Dados</h1>
        <p className="text-gray-500 mb-10 text-lg">Gerenciamento eficiente de jornadas e fechamentos semanais.</p>

        <button 
          onClick={() => setState({ ...state, view: 'SELECTION' })}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-8 rounded-xl transition flex items-center justify-center gap-3 shadow-xl shadow-blue-100 group"
        >
          <span>Começar</span>
          <Play className="w-5 h-5 group-hover:translate-x-1 transition" />
        </button>

        <div className="mt-8 pt-8 border-t border-gray-100">
          <div className="relative">
            <input 
              type="password"
              placeholder="Acesso Admin"
              className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              value={adminPassword}
              onChange={(e) => setAdminPassword(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleAdminLogin()}
            />
            <Settings className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <button 
              onClick={handleAdminLogin}
              className="absolute right-2 top-1/2 -translate-y-1/2 bg-gray-200 hover:bg-gray-300 p-1.5 rounded-lg transition"
            >
              <ChevronRight className="w-4 h-4 text-gray-600" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderSelectionView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <button 
        onClick={() => setState({ ...state, view: 'HOME' })}
        className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium"
      >
        <ArrowLeft className="w-5 h-5" /> Voltar ao Início
      </button>
      <div className="grid md:grid-cols-2 gap-8 max-w-4xl w-full">
        <button 
          onClick={() => setState({ ...state, view: 'FLOW', flowType: EmployeeType.REGISTRADO })}
          className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-blue-500 border-2 border-transparent transition-all group"
        >
          <div className="bg-blue-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-blue-600 transition">
            <Users className="text-blue-600 w-8 h-8 group-hover:text-white transition" />
          </div>
          <h2 className="text-2xl font-bold mb-2">Registrado</h2>
          <p className="text-gray-500">Colaboradores em regime CLT com controle de ponto manual.</p>
        </button>
        <button 
          onClick={() => setState({ ...state, view: 'FLOW', flowType: EmployeeType.FIXO })}
          className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-green-500 border-2 border-transparent transition-all group"
        >
          <div className="bg-green-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-green-600 transition">
            <MapPin className="text-green-600 w-8 h-8 group-hover:text-white transition" />
          </div>
          <h2 className="text-2xl font-bold mb-2">Fixo (Extra)</h2>
          <p className="text-gray-500">Colaboradores eventuais com diária fixa e vale-transporte.</p>
        </button>
      </div>
    </div>
  );

  const renderFlowView = () => {
    const filteredEmployees = employees.filter(e => e.sectorId === selectedSector && e.type === state.flowType);

    return (
      <div className="max-w-xl mx-auto py-12 px-4">
        <button 
          onClick={() => setState({ ...state, view: 'SELECTION' })}
          className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium"
        >
          <ArrowLeft className="w-5 h-5" /> Alterar Tipo
        </button>

        <div className="bg-white rounded-3xl shadow-xl p-8 space-y-8">
          <h2 className="text-2xl font-bold text-gray-800 border-b pb-4">
            {state.flowType === EmployeeType.REGISTRADO ? 'Lançamento Registrado' : 'Lançamento Fixo'}
          </h2>

          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Selecione o Setor</label>
            <select 
              className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none appearance-none"
              value={selectedSector}
              onChange={(e) => setSelectedSector(e.target.value)}
            >
              <option value="">Selecione um setor...</option>
              {sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>

          {selectedSector && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Selecione o Funcionário</label>
              {state.flowType === EmployeeType.REGISTRADO ? (
                <select 
                  className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none appearance-none"
                  value={selectedEmployee}
                  onChange={(e) => setSelectedEmployee(e.target.value)}
                >
                  <option value="">Selecione um funcionário...</option>
                  {filteredEmployees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
                </select>
              ) : (
                <input 
                  type="text"
                  placeholder="Nome do Funcionário Fixo"
                  className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                  onChange={(e) => setSelectedEmployee(e.target.value)}
