          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
                  <th className="p-4 border-b">Data</th>
                  <th className="p-4 border-b">Real Entrada</th>
                  <th className="p-4 border-b">Ponto Entrada</th>
                  <th className="p-4 border-b">Ponto Saída</th>
                  <th className="p-4 border-b">Real Saída</th>
                  <th className="p-4 border-b text-center">Ação</th>
                </tr>
              </thead>
              <tbody>
                {modalRecords.map((r, idx) => (
                  <tr key={idx} className="hover:bg-gray-50 transition border-b border-gray-100">
                    <td className="p-4 font-medium text-gray-700">
                      {new Date(r.date).toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' })}
                    </td>
                    <td className="p-2">
                      <input 
                        type="time"
                        className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                        value={r.realEntry}
                        onChange={(e) => updateRecord(idx, 'realEntry', e.target.value)}
                      />
                    </td>
                    {!r.isFolgaVendida ? (
                      <>
                        <td className="p-2">
                          <input 
                            type="time"
                            className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                            value={r.punchEntry}
                            onChange={(e) => updateRecord(idx, 'punchEntry', e.target.value)}
                          />
                        </td>
                        <td className="p-2">
                          <input 
                            type="time"
                            className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                            value={r.punchExit}
                            onChange={(e) => updateRecord(idx, 'punchExit', e.target.value)}
                          />
                        </td>
                      </>
                    ) : (
                      <td colSpan={2} className="p-2 text-center text-blue-600 font-bold bg-blue-50 rounded-lg">FOLGA VENDIDA</td>
                    )}
                    <td className="p-2">
                      <input 
                        type="time"
                        className="w-full p-2 bg-transparent border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                        value={r.realExit}
                        onChange={(e) => updateRecord(idx, 'realExit', e.target.value)}
                      />
                    </td>
                    <td className="p-2 text-center">
                      <button 
                        onClick={() => updateRecord(idx, 'isFolgaVendida', !r.isFolgaVendida)}
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition ${r.isFolgaVendida ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                      >
                        {r.isFolgaVendida ? 'Remover Folga' : 'Folga Vendida'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="mt-10 flex justify-end gap-4">
            <button 
              onClick={() => setShowFormModal(false)}
              className="px-8 py-3 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold rounded-xl transition"
            >
              Cancelar
            </button>
            <button 
              onClick={() => submitRequest(modalRecords)}
              className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl transition shadow-lg shadow-blue-200"
            >
              Confirmar e Enviar
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderAdminView = () => {
    const [filterStatus, setFilterStatus] = useState<string>('ALL');
    const [filterType, setFilterType] = useState<string>('ALL');

    const filteredRequests = requests.filter(req => {
      if (filterStatus !== 'ALL' && req.status !== filterStatus) return false;
      if (filterType !== 'ALL' && req.employeeType !== filterType) return false;
      return true;
    });

    // Sub-renderers for Admin
    const renderDashboard = () => {
      const totalSpending = requests.reduce((acc, r) => acc + (r.status === RequestStatus.APROVADO ? r.calculatedValue : 0), 0);
      const spendingBySector = sectors.map(s => ({
        name: s.name,
        value: requests.filter(r => r.sectorId === s.id && r.status === RequestStatus.APROVADO).reduce((acc, r) => acc + r.calculatedValue, 0)
      }));

      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
              <p className="text-gray-500 text-sm font-medium mb-1">Gasto Total Aprovado</p>
              <h3 className="text-3xl font-bold text-gray-800">{formatCurrency(totalSpending)}</h3>
            </div>
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
              <p className="text-gray-500 text-sm font-medium mb-1">Solicitações Pendentes</p>
              <h3 className="text-3xl font-bold text-blue-600">{requests.filter(r => r.status === RequestStatus.PENDENTE).length}</h3>
            </div>
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
              <p className="text-gray-500 text-sm font-medium mb-1">Setor com Mais Lançamentos</p>
              <h3 className="text-2xl font-bold text-gray-800">
                {spendingBySector.sort((a,b) => b.value - a.value)[0]?.name || '-'}
              </h3>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 h-[400px]">
              <h4 className="font-bold mb-6 flex items-center gap-2">
                <BarChart className="w-5 h-5" /> Gastos por Setor
              </h4>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={spendingBySector}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="name" />
                  <YAxis tickFormatter={(val) => `R$${val}`} />
                  <Tooltip formatter={(val: number) => formatCurrency(val)} />
                  <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 h-[400px]">
              <h4 className="font-bold mb-6 flex items-center gap-2">
                <PieChart className="w-5 h-5" /> Distribuição por Tipo
              </h4>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={[
                      { name: 'Registrado', value: requests.filter(r => r.employeeType === EmployeeType.REGISTRADO).length },
                      { name: 'Fixo', value: requests.filter(r => r.employeeType === EmployeeType.FIXO).length },
                    ]}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={100}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    <Cell fill="#3b82f6" />
                    <Cell fill="#10b981" />
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      );
    };

    const renderSectorsManager = () => {
      const [newSec, setNewSec] = useState({ name: '', fixedRate: 0 });
      const addSector = () => {
        if (!newSec.name) return;
        setSectors([...sectors, { ...newSec, id: Math.random().toString(36).substr(2, 9) }]);
        setNewSec({ name: '', fixedRate: 0 });
      };
      const removeSector = (id: string) => setSectors(sectors.filter(s => s.id !== id));
      return (
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="flex items-center justify-between"><h2 className="text-2xl font-bold">Gerenciar Setores</h2></div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-gray-50 p-6 rounded-2xl">
            <input type="text" placeholder="Nome do Setor" className="p-3 border rounded-xl outline-none" value={newSec.name} onChange={(e) => setNewSec({ ...newSec, name: e.target.value })} />
            <input type="number" placeholder="Valor Diária Extra" className="p-3 border rounded-xl outline-none" value={newSec.fixedRate || ''} onChange={(e) => setNewSec({ ...newSec, fixedRate: parseFloat(e.target.value) })} />
            <button onClick={addSector} className="bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl">Adicionar Setor</button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead><tr className="text-gray-400 text-xs uppercase font-bold border-b"><th className="py-4">Setor</th><th className="py-4">Valor Fixo</th><th className="py-4 text-right">Ações</th></tr></thead>
              <tbody>{sectors.map(s => (<tr key={s.id} className="border-b last:border-0 hover:bg-gray-50 transition"><td className="py-4 font-semibold text-gray-700">{s.name}</td><td className="py-4 text-gray-600">{formatCurrency(s.fixedRate)}</td><td className="py-4 text-right"><button onClick={() => removeSector(s.id)} className="text-red-500 hover:text-red-700 p-2 rounded-lg hover:bg-red-50 transition"><XCircle className="w-5 h-5" /></button></td></tr>))}</tbody>
            </table>
          </div>
        </div>
      );
    };

    const renderEmployeesManager = () => {
      const [newEmpData, setNewEmpData] = useState({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });
      const addEmployee = () => {
        if (!newEmpData.name || !newEmpData.sectorId) return;
        setEmployees([...employees, { ...newEmpData, id: Math.random().toString(36).substr(2, 9) }]);
        setNewEmpData({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });
      };
      return (
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <h2 className="text-2xl font-bold">Funcionários Registrados</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 bg-gray-50 p-6 rounded-2xl">
            <input type="text" placeholder="Nome" className="p-3 border rounded-xl outline-none" value={newEmpData.name} onChange={(e) => setNewEmpData({ ...newEmpData, name: e.target.value })} />
            <select className="p-3 border rounded-xl outline-none" value={newEmpData.sectorId} onChange={(e) => setNewEmpData({ ...newEmpData, sectorId: e.target.value })}><option value="">Setor...</option>{sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select>
            <input type="number" placeholder="Salário" className="p-3 border rounded-xl outline-none" value={newEmpData.salary || ''} onChange={(e) => setNewEmpData({ ...newEmpData, salary: parseFloat(e.target.value) })} />
            <input type="number" placeholder="Horas" className="p-3 border rounded-xl outline-none" value={newEmpData.monthlyHours || ''} onChange={(e) => setNewEmpData({ ...newEmpData, monthlyHours: parseFloat(e.target.value) })} />
            <button onClick={addEmployee} className="bg-blue-600 text-white font-bold rounded-xl py-3 px-6 hover:bg-blue-700 transition">Adicionar</button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead><tr className="text-gray-400 text-xs uppercase font-bold border-b"><th className="py-4">Nome</th><th className="py-4">Setor</th><th className="py-4">Valor Hora</th><th className="py-4 text-right">Ações</th></tr></thead>
              <tbody>{employees.map(e => { const sec = sectors.find(s => s.id === e.sectorId); const hrRate = (e.salary / e.monthlyHours) * 1.25; return (<tr key={e.id} className="border-b last:border-0 hover:bg-gray-50"><td className="py-4 font-medium">{e.name}</td><td className="py-4 text-gray-500">{sec?.name}</td><td className="py-4 text-blue-600 font-bold">{formatCurrency(hrRate)}</td><td className="py-4 text-right"><button onClick={() => setEmployees(employees.filter(emp => emp.id !== e.id))} className="text-red-400 hover:text-red-600"><XCircle className="w-5 h-5" /></button></td></tr>)})}</tbody>
            </table>
          </div>
        </div>
      );
    };

    const renderRequestsManager = () => {
      const updateStatus = (id: string, status: RequestStatus) => setRequests(requests.map(r => r.id === id ? { ...r, status } : r));
      return (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
          <div className="flex flex-col md:flex-row gap-4 justify-between bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
            <h2 className="text-2xl font-bold">Solicitações</h2>
            <div className="flex items-center gap-3">
              <Filter className="w-4 h-4 text-gray-400" />
              <select className="border rounded-lg p-2 text-sm bg-gray-50 outline-none" value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}><option value="ALL">Status: Todos</option><option value={RequestStatus.PENDENTE}>Pendente</option><option value={RequestStatus.APROVADO}>Aprovado</option><option value={RequestStatus.REJEITADO}>Rejeitado</option></select>
              <select className="border rounded-lg p-2 text-sm bg-gray-50 outline-none" value={filterType} onChange={(e) => setFilterType(e.target.value)}><option value="ALL">Tipo: Todos</option><option value={EmployeeType.REGISTRADO}>Registrado</option><option value={EmployeeType.FIXO}>Fixo</option></select>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-4">
            {filteredRequests.map(req => (
              <div key={req.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm hover:shadow-md transition">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2"><span className={`px-2 py-0.5 rounded-md text-[10px] font-extrabold uppercase ${req.employeeType === EmployeeType.REGISTRADO ? 'bg-blue-100 text-blue-700' : 'bg-green-100 text-green-700'}`}>{req.employeeType}</span><h4 className="text-lg font-bold">{req.employeeName}</h4></div>
                    <p className="text-sm text-gray-500">{req.sectorName} • Semana de {new Date(req.weekStarting).toLocaleDateString('pt-BR')}</p>
                  </div>
                  <div className="flex items-center gap-6">
                    <div className="text-right"><p className="text-xl font-black text-gray-800">{formatCurrency(req.calculatedValue)}</p></div>
                    {req.status === RequestStatus.PENDENTE ? (<div className="flex gap-2"><button onClick={() => updateStatus(req.id, RequestStatus.APROVADO)} className="bg-green-500 text-white p-2.5 rounded-xl transition"><CheckCircle className="w-5 h-5" /></button><button onClick={() => updateStatus(req.id, RequestStatus.REJEITADO)} className="bg-red-500 text-white p-2.5 rounded-xl transition"><XCircle className="w-5 h-5" /></button></div>) : (<span className={`px-4 py-2 rounded-xl text-sm font-bold uppercase ${req.status === RequestStatus.APROVADO ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>{req.status}</span>)}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      );
    };

    const renderIntegrations = () => {
      const exportToCsv = (type: EmployeeType) => {
        const filtered = requests.filter(r => r.employeeType === type && r.status === RequestStatus.APROVADO);
        const headers = ["Data", "Funcionário", "Setor", "Valor"];
        const csv = [headers.join(","), ...filtered.map(r => [new Date(r.createdAt).toLocaleDateString('pt-BR'), r.employeeName, r.sectorName, r.calculatedValue.toFixed(2)].join(","))].join("\n");
        const link = document.createElement("a"); link.setAttribute("href", encodeURI("data:text/csv;charset=utf-8," + csv)); link.setAttribute("download", `integracao_${type.toLowerCase()}.csv`); document.body.appendChild(link); link.click();
      };
      return (
        <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <h2 className="text-2xl font-bold flex items-center gap-2"><LinkIcon className="w-6 h-6 text-blue-600" /> Integrações</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="p-8 border rounded-3xl bg-blue-50/50"><h3>Registrados</h3><button onClick={() => exportToCsv(EmployeeType.REGISTRADO)} className="mt-4 bg-blue-600 text-white px-6 py-3 rounded-xl">Exportar Registrados</button></div>
            <div className="p-8 border rounded-3xl bg-green-50/50"><h3>Fixos</h3><button onClick={() => exportToCsv(EmployeeType.FIXO)} className="mt-4 bg-green-600 text-white px-6 py-3 rounded-xl">Exportar Fixos</button></div>
          </div>
        </div>
      );
    };

    return (
      <div className="flex h-screen bg-gray-50 overflow-hidden">
        <div className="w-72 bg-white border-r border-gray-100 flex flex-col p-6 shadow-sm">
          <div className="flex items-center gap-3 mb-12"><div className="bg-blue-600 p-2 rounded-lg"><Settings className="text-white w-5 h-5" /></div><h2 className="text-xl font-black text-gray-800">Admin Panel</h2></div>
          <nav className="flex-1 space-y-2">
            {[
              { id: 'DASHBOARD', label: 'Dashboard', icon: LayoutDashboard },
              { id: 'SECTORS', label: 'Setores', icon: MapPin },
              { id: 'EMPLOYEES', label: 'Funcionários', icon: Users },
              { id: 'REQUESTS', label: 'Solicitações', icon: ClipboardList },
              { id: 'INTEGRATIONS', label: 'Integrações', icon: LinkIcon },
            ].map(item => (
              <button key={item.id} onClick={() => setState({ ...state, adminSubView: item.id as any })} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${state.adminSubView === item.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'text-gray-500 hover:bg-gray-50 hover:text-blue-600'}`}>
                <item.icon className="w-5 h-5" />{item.label}
              </button>
            ))}
          </nav>
          <button onClick={() => { setIsAuth(false); setState({ ...state, view: 'HOME' }) }} className="flex items-center gap-3 px-4 py-3 text-red-500 font-bold hover:bg-red-50 rounded-xl transition"><LogOut className="w-5 h-5" /> Sair</button>
        </div>
        <div className="flex-1 overflow-y-auto p-10 bg-[#F9FBFF]">
          {state.adminSubView === 'DASHBOARD' && renderDashboard()}
          {state.adminSubView === 'SECTORS' && renderSectorsManager()}
          {state.adminSubView === 'EMPLOYEES' && renderEmployeesManager()}
          {state.adminSubView === 'REQUESTS' && renderRequestsManager()}
          {state.adminSubView === 'INTEGRATIONS' && renderIntegrations()}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen">
      {state.view === 'HOME' && renderHomeView()}
      {state.view === 'SELECTION' && renderSelectionView()}
      {state.view === 'FLOW' && renderFlowView()}
      {state.view === 'ADMIN' && renderAdminView()}

      {showFormModal && renderFormModal()}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Play, 
  ArrowLeft, 
  LayoutDashboard, 
  Users, 
  MapPin, 
  ClipboardList, 
  Link as LinkIcon,
  CheckCircle,
  XCircle,
  Clock,
  LogOut,
  ChevronRight,
  Filter,
  Download
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  PieChart, 
  Pie, 
  Cell
} from 'recharts';
import { 
  EmployeeType, 
  RequestStatus, 
  Sector, 
  Employee, 
