const STORAGE_KEY = 'controle_dados_db';

const App: React.FC = () => {
  // --- Persistência de Dados ---
  const [sectors, setSectors] = useState<Sector[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [requests, setRequests] = useState<TimeRequest[]>([]);

  // --- Estado Global da Navegação ---
  const [state, setState] = useState<AppState>({
    view: 'HOME',
    flowType: null,
    adminSubView: 'DASHBOARD'
  });

  // --- Estados de Autenticação e Formulários (Nível Superior para evitar erro de Hooks) ---
  const [adminPassword, setAdminPassword] = useState('');
  const [isAuth, setIsAuth] = useState(false);
  const [selectedSector, setSelectedSector] = useState<string>('');
  const [selectedEmployee, setSelectedEmployee] = useState<string>('');
  const [showFormModal, setShowFormModal] = useState(false);
  const [currentWeek, setCurrentWeek] = useState(new Date().toISOString().split('T')[0]);

  // Estados temporários para formulários no Admin (Movidos para cá para evitar erro #310)
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [filterType, setFilterType] = useState<string>('ALL');
  const [newSec, setNewSec] = useState({ name: '', fixedRate: 0 });
  const [newEmpData, setNewEmpData] = useState({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });
  const [modalRecords, setModalRecords] = useState<TimeRecord[]>([]);

  // Carregar Dados Iniciais
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setSectors(parsed.sectors || []);
      setEmployees(parsed.employees || []);
      setRequests(parsed.requests || []);
    } else {
      const initialSectors = [
        { id: '1', name: 'Recepção', fixedRate: 80 },
        { id: '2', name: 'Governança', fixedRate: 70 },
        { id: '3', name: 'Reservas', fixedRate: 75 },
        { id: '4', name: 'Mensageria', fixedRate: 60 },
      ];
      setSectors(initialSectors);
    }
  }, []);

  // Salvar mudanças
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ sectors, employees, requests }));
  }, [sectors, employees, requests]);

  // Inicializar registros do modal quando a semana muda ou o modal abre
  useEffect(() => {
    if (showFormModal) {
      const days = getWeekDays(new Date(currentWeek));
      setModalRecords(days.map(d => ({ date: d, realEntry: '', punchEntry: '', punchExit: '', realExit: '', isFolgaVendida: false })));
    }
  }, [showFormModal, currentWeek]);

  const handleAdminLogin = () => {
    if (adminPassword === '123') {
      setIsAuth(true);
      setState(prev => ({ ...prev, view: 'ADMIN' }));
      setAdminPassword('');
    } else {
      alert('Senha incorreta!');
    }
  };

  const submitRequest = () => {
    const employee = employees.find(e => e.id === selectedEmployee);
    const sector = sectors.find(s => s.id === (employee?.sectorId || selectedSector));

    if (!employee && state.flowType === EmployeeType.REGISTRADO) return;

    let totalDiffHours = 0;
    let totalPayment = 0;

    if (state.flowType === EmployeeType.REGISTRADO && employee) {
      const hourlyBase = employee.salary / employee.monthlyHours;
      const hourlyWithExtra = hourlyBase * 1.25;

      modalRecords.forEach(r => {
        if (!r.isFolgaVendida) {
          const entryDiff = calculateTimeDiff(r.realEntry, r.punchEntry);
          const exitDiff = calculateTimeDiff(r.realExit, r.punchExit);
          totalDiffHours += (entryDiff + exitDiff);
        } else {
          totalDiffHours += calculateTimeDiff(r.realExit, r.realEntry);
        }
      });
      totalPayment = totalDiffHours * hourlyWithExtra;
    } else {
      const dailyRate = sector?.fixedRate || 0;
      modalRecords.forEach(r => {
        if (r.realEntry && r.realExit) {
          totalPayment += dailyRate + 12;
        }
      });
    }

    const newRequest: TimeRequest = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: employee?.id || 'fixo-temp',
      employeeName: employee?.name || selectedEmployee || 'Funcionário Fixo',
      employeeType: state.flowType!,
      sectorId: sector?.id || '',
      sectorName: sector?.name || '',
      weekStarting: currentWeek,
      records: modalRecords,
      status: RequestStatus.PENDENTE,
      calculatedValue: totalPayment,
      totalTimeDecimal: totalDiffHours,
      createdAt: new Date().toISOString()
    };

    setRequests([newRequest, ...requests]);
    setShowFormModal(false);
    setState(prev => ({ ...prev, view: 'HOME' }));
    alert('Solicitação enviada com sucesso!');
  };

  // --- Funções de Renderização Auxiliares (Não são componentes para manter o foco) ---

  const renderHomeView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-4">
      <div className="bg-white p-12 rounded-3xl shadow-2xl max-w-lg w-full transform transition hover:scale-105 duration-300">
        <div className="bg-blue-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-blue-200">
          <ClipboardList className="text-white w-10 h-10" />
        </div>
        <h1 className="text-4xl font-extrabold text-gray-800 mb-4 tracking-tight">Controle de Dados</h1>
        <p className="text-gray-500 mb-10 text-lg">Gerenciamento eficiente de jornadas e fechamentos semanais.</p>

        <button 
          onClick={() => setState(prev => ({ ...prev, view: 'SELECTION' }))}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-8 rounded-xl transition flex items-center justify-center gap-3 shadow-xl shadow-blue-100 group"
        >
          <span>Começar</span>
          <Play className="w-5 h-5 group-hover:translate-x-1 transition" />
        </button>

        <div className="mt-8 pt-8 border-t border-gray-100">
          <div className="relative">
            <input 
              type="password"
              placeholder="Acesso Admin"
              className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              value={adminPassword}
              onChange={(e) => setAdminPassword(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleAdminLogin()}
              autoFocus
            />
            <Settings className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <button 
              onClick={handleAdminLogin}
              className="absolute right-2 top-1/2 -translate-y-1/2 bg-gray-200 hover:bg-gray-300 p-1.5 rounded-lg transition"
            >
              <ChevronRight className="w-4 h-4 text-gray-600" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderSelectionView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <button onClick={() => setState(prev => ({ ...prev, view: 'HOME' }))} className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium">
        <ArrowLeft className="w-5 h-5" /> Voltar ao Início
      </button>
      <div className="grid md:grid-cols-2 gap-8 max-w-4xl w-full">
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.REGISTRADO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-blue-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-blue-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-blue-600 transition"><Users className="text-blue-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Registrado</h2>
          <p className="text-gray-500">Colaboradores em regime CLT com controle de ponto manual.</p>
        </button>
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.FIXO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-green-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-green-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-green-600 transition"><MapPin className="text-green-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Fixo (Extra)</h2>
          <p className="text-gray-500">Colaboradores eventuais com diária fixa e vale-transporte.</p>
        </button>
      </div>
    </div>
  );

  const renderFlowView = () => {
    const filteredEmployees = employees.filter(e => e.sectorId === selectedSector && e.type === state.flowType);
    return (
      <div className="max-w-xl mx-auto py-12 px-4">
        <button onClick={() => setState(prev => ({ ...prev, view: 'SELECTION' }))} className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium">
          <ArrowLeft className="w-5 h-5" /> Alterar Tipo
        </button>
        <div className="bg-white rounded-3xl shadow-xl p-8 space-y-8">
          <h2 className="text-2xl font-bold text-gray-800 border-b pb-4">
            {state.flowType === EmployeeType.REGISTRADO ? 'Lançamento Registrado' : 'Lançamento Fixo'}
          </h2>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Selecione o Setor</label>
            <select className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl outline-none" value={selectedSector} onChange={(e) => setSelectedSector(e.target.value)}>
              <option value="">Selecione um setor...</option>
              {sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>
          {selectedSector && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Funcionário</label>
              {state.flowType === EmployeeType.REGISTRADO ? (
