              )}
            </div>
          )}
          <button disabled={!selectedSector || !selectedEmployee} onClick={() => setShowFormModal(true)} className="w-full bg-blue-600 disabled:bg-gray-300 hover:bg-blue-700 text-white font-bold py-4 rounded-xl transition shadow-lg">Cadastrar Horários</button>
        </div>
      </div>
    );
  };

  const renderFormModal = () => {
