    return (
      <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-y-auto p-8 relative">
          <button onClick={() => setShowFormModal(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition"><XCircle className="w-8 h-8" /></button>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h2 className="text-2xl font-bold">Fechamento Semanal</h2>
            <div className="flex items-center gap-4"><span className="text-sm font-medium text-gray-500">Semana de:</span><input type="date" className="p-2 border rounded-lg" value={currentWeek} onChange={(e) => setCurrentWeek(e.target.value)} /></div>
