          const hr = (e.salary / e.monthlyHours) * 1.25;
          return (<tr key={e.id} className="border-b hover:bg-gray-50"><td className="py-4">{e.name}</td><td className="py-4">{s?.name}</td><td className="py-4 text-blue-600 font-bold">{formatCurrency(hr)}</td><td className="py-4 text-right"><button onClick={() => setEmployees(employees.filter(emp => emp.id !== e.id))} className="text-red-400"><XCircle className="w-5 h-5" /></button></td></tr>)
