                  </div>
                ) : (<span className={`px-4 py-2 rounded-xl text-sm font-bold uppercase ${req.status === RequestStatus.APROVADO ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>{req.status}</span>)}
