  const renderAdminIntegrations = () => {
    const exportCsv = (type: EmployeeType) => {
      const data = requests.filter(r => r.employeeType === type && r.status === RequestStatus.APROVADO);
      const csv = ["Data,Nome,Setor,Valor", ...data.map(r => `${new Date(r.createdAt).toLocaleDateString()},${r.employeeName},${r.sectorName},${r.calculatedValue.toFixed(2)}`)].join("\n");
      const a = document.createElement("a"); a.href = encodeURI("data:text/csv;charset=utf-8," + csv); a.download = `extra_${type.toLowerCase()}.csv`; a.click();
    };
    return (
      <div className="bg-white p-8 rounded-3xl border border-gray-100 space-y-8">
        <h2 className="text-2xl font-bold flex items-center gap-2"><LinkIcon /> Integrações</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="p-8 border rounded-3xl bg-blue-50/50"><h3>Registrados</h3><button onClick={() => exportCsv(EmployeeType.REGISTRADO)} className="mt-4 bg-blue-600 text-white px-6 py-3 rounded-xl hover:bg-blue-700 transition">Exportar CSV</button></div>
          <div className="p-8 border rounded-3xl bg-green-50/50"><h3>Fixos</h3><button onClick={() => exportCsv(EmployeeType.FIXO)} className="mt-4 bg-green-600 text-white px-6 py-3 rounded-xl hover:bg-green-700 transition">Exportar CSV</button></div>
        </div>
      </div>
    );
  };

  const renderAdminView = () => (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      <div className="w-72 bg-white border-r border-gray-100 flex flex-col p-6 shadow-sm">
        <div className="flex items-center gap-3 mb-12"><div className="bg-blue-600 p-2 rounded-lg"><Settings className="text-white w-5 h-5" /></div><h2 className="text-xl font-black">Admin Panel</h2></div>
        <nav className="flex-1 space-y-2">
          {[
            { id: 'DASHBOARD', label: 'Dashboard', icon: LayoutDashboard },
            { id: 'SECTORS', label: 'Setores', icon: MapPin },
            { id: 'EMPLOYEES', label: 'Funcionários', icon: Users },
            { id: 'REQUESTS', label: 'Solicitações', icon: ClipboardList },
            { id: 'INTEGRATIONS', label: 'Integrações', icon: LinkIcon },
          ].map(item => (
            <button key={item.id} onClick={() => setState(prev => ({ ...prev, adminSubView: item.id as any }))} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${state.adminSubView === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <item.icon className="w-5 h-5" />{item.label}
            </button>
          ))}
        </nav>
        <button onClick={() => setState(prev => ({ ...prev, view: 'HOME' }))} className="flex items-center gap-3 px-4 py-3 text-red-500 font-bold hover:bg-red-50 rounded-xl transition"><LogOut className="w-5 h-5" /> Sair</button>
      </div>
      <div className="flex-1 overflow-y-auto p-10">
        {state.adminSubView === 'DASHBOARD' && renderAdminDashboard()}
        {state.adminSubView === 'SECTORS' && renderAdminSectors()}
        {state.adminSubView === 'EMPLOYEES' && renderAdminEmployees()}
        {state.adminSubView === 'REQUESTS' && renderAdminRequests()}
        {state.adminSubView === 'INTEGRATIONS' && renderAdminIntegrations()}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen">
      {state.view === 'HOME' && renderHomeView()}
      {state.view === 'SELECTION' && renderSelectionView()}
      {state.view === 'FLOW' && renderFlowView()}
      {state.view === 'ADMIN' && renderAdminView()}
      {showFormModal && renderFormModal()}
    </div>
  );
};

export default App;

export enum EmployeeType {
  REGISTRADO = 'REGISTRADO',
  FIXO = 'FIXO'
}

export enum RequestStatus {
  PENDENTE = 'PENDENTE',
  APROVADO = 'APROVADO',
  REJEITADO = 'REJEITADO'
}

export interface Sector {
  id: string;
  name: string;
  fixedRate: number; // Value for "Fixo" employees in this sector
}

export interface Employee {
  id: string;
  name: string;
  sectorId: string;
  type: EmployeeType;
  salary: number;
  monthlyHours: number;
}

export interface TimeRecord {
  date: string;
  realEntry: string;
  punchEntry: string;
  punchExit: string;
  realExit: string;
  isFolgaVendida: boolean;
}

export interface TimeRequest {
  id: string;
  employeeId: string;
  employeeName: string;
  employeeType: EmployeeType;
  sectorId: string;
  sectorName: string;
  weekStarting: string;
  records: TimeRecord[];
  status: RequestStatus;
  calculatedValue: number;
  totalTimeDecimal: number;
  createdAt: string;
  editJustification?: string;
}

export interface AppState {
  view: 'HOME' | 'SELECTION' | 'FLOW' | 'ADMIN';
  flowType: EmployeeType | null;
  adminSubView: 'DASHBOARD' | 'SECTORS' | 'EMPLOYEES' | 'REQUESTS' | 'INTEGRATIONS';
}

import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Play, 
  ArrowLeft, 
  LayoutDashboard, 
  Users, 
  MapPin, 
  ClipboardList, 
  Link as LinkIcon,
  CheckCircle,
  XCircle,
  Clock,
  LogOut,
  ChevronRight,
  Filter,
  Download,
  Edit2
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  PieChart, 
  Pie, 
  Cell
} from 'recharts';
import { 
  EmployeeType, 
  RequestStatus, 
  Sector, 
  Employee, 
  TimeRequest, 
  AppState,
  TimeRecord 
} from './types';
import { 
  formatCurrency, 
  timeToDecimal, 
  calculateTimeDiff, 
  getWeekDays 
} from './utils';

const STORAGE_KEY = 'controle_dados_db';

const App: React.FC = () => {
  // --- Persistência de Dados ---
  const [sectors, setSectors] = useState<Sector[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [requests, setRequests] = useState<TimeRequest[]>([]);

  // --- Estado Global da Navegação ---
  const [state, setState] = useState<AppState>({
    view: 'HOME',
    flowType: null,
    adminSubView: 'DASHBOARD'
  });

  // --- Estados de Autenticação e Formulários ---
  const [adminPassword, setAdminPassword] = useState('');
  const [isAuth, setIsAuth] = useState(false);
  const [selectedSector, setSelectedSector] = useState<string>('');
  const [selectedEmployee, setSelectedEmployee] = useState<string>('');
  const [showFormModal, setShowFormModal] = useState(false);
  const [currentWeek, setCurrentWeek] = useState(new Date().toISOString().split('T')[0]);

  // Estados temporários para formulários no Admin
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [filterType, setFilterType] = useState<string>('ALL');
  const [newSec, setNewSec] = useState({ name: '', fixedRate: 0 });
  const [newEmpData, setNewEmpData] = useState({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });
  const [modalRecords, setModalRecords] = useState<TimeRecord[]>([]);

  // Estado para Edição pelo Admin
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);
  const [editJustification, setEditJustification] = useState('');

  // Carregar Dados Iniciais
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setSectors(parsed.sectors || []);
      setEmployees(parsed.employees || []);
      setRequests(parsed.requests || []);
    } else {
      const initialSectors = [
        { id: '1', name: 'Recepção', fixedRate: 80 },
        { id: '2', name: 'Governança', fixedRate: 70 },
        { id: '3', name: 'Reservas', fixedRate: 75 },
        { id: '4', name: 'Mensageria', fixedRate: 60 },
      ];
      setSectors(initialSectors);
    }
  }, []);

  // Salvar mudanças
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ sectors, employees, requests }));
  }, [sectors, employees, requests]);

  // Inicializar registros do modal
  useEffect(() => {
    if (showFormModal && !editingRequestId) {
      const days = getWeekDays(new Date(currentWeek));
      setModalRecords(days.map(d => ({ date: d, realEntry: '', punchEntry: '', punchExit: '', realExit: '', isFolgaVendida: false })));
    }
  }, [showFormModal, currentWeek, editingRequestId]);

  const handleAdminLogin = () => {
    if (adminPassword === '123') {
      setIsAuth(true);
      setState(prev => ({ ...prev, view: 'ADMIN' }));
      setAdminPassword('');
    } else {
      alert('Senha incorreta!');
    }
  };

  const submitRequest = () => {
    // Se for edição, usamos o request original para basear o cálculo
    const originalRequest = editingRequestId ? requests.find(r => r.id === editingRequestId) : null;
    const flowTypeToUse = originalRequest ? originalRequest.employeeType : state.flowType;
    const employeeIdToUse = originalRequest ? originalRequest.employeeId : selectedEmployee;
    const sectorIdToUse = originalRequest ? originalRequest.sectorId : selectedSector;

    const employee = employees.find(e => e.id === employeeIdToUse);
    const sector = sectors.find(s => s.id === (employee?.sectorId || sectorIdToUse));

    if (!employee && flowTypeToUse === EmployeeType.REGISTRADO) return;

    let totalDiffHours = 0;
    let totalPayment = 0;

    if (flowTypeToUse === EmployeeType.REGISTRADO && employee) {
      const hourlyBase = employee.salary / employee.monthlyHours;
      const hourlyWithExtra = hourlyBase * 1.25;

      modalRecords.forEach(r => {
        if (!r.isFolgaVendida) {
          const entryDiff = calculateTimeDiff(r.realEntry, r.punchEntry);
          const exitDiff = calculateTimeDiff(r.realExit, r.punchExit);
          totalDiffHours += (entryDiff + exitDiff);
        } else {
          totalDiffHours += calculateTimeDiff(r.realExit, r.realEntry);
        }
      });
      totalPayment = totalDiffHours * hourlyWithExtra;
    } else {
      const dailyRate = sector?.fixedRate || 0;
      modalRecords.forEach(r => {
        if (r.realEntry && r.realExit) {
          totalPayment += dailyRate + 12;
        }
      });
    }

    if (editingRequestId) {
      // Atualizar solicitação existente
      setRequests(requests.map(r => r.id === editingRequestId ? {
        ...r,
        records: modalRecords,
        calculatedValue: totalPayment,
        totalTimeDecimal: totalDiffHours,
        editJustification: editJustification
      } : r));
      setEditingRequestId(null);
      setEditJustification('');
    } else {
      // Criar nova solicitação
      const newRequest: TimeRequest = {
        id: Math.random().toString(36).substr(2, 9),
        employeeId: employee?.id || 'fixo-temp',
        employeeName: employee?.name || selectedEmployee || 'Funcionário Fixo',
        employeeType: state.flowType!,
        sectorId: sector?.id || '',
        sectorName: sector?.name || '',
        weekStarting: currentWeek,
        records: modalRecords,
        status: RequestStatus.PENDENTE,
        calculatedValue: totalPayment,
        totalTimeDecimal: totalDiffHours,
        createdAt: new Date().toISOString()
      };
      setRequests([newRequest, ...requests]);
      setState(prev => ({ ...prev, view: 'HOME' }));
    }

    setShowFormModal(false);
    alert(editingRequestId ? 'Solicitação editada com sucesso!' : 'Solicitação enviada com sucesso!');
  };

  const startAdminEdit = (req: TimeRequest) => {
    setEditingRequestId(req.id);
    setModalRecords(JSON.parse(JSON.stringify(req.records)));
    setEditJustification(req.editJustification || '');
    setCurrentWeek(req.weekStarting);
    setShowFormModal(true);
  };

  // --- Funções de Renderização Auxiliares ---

  const renderHomeView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-4">
      <div className="bg-white p-12 rounded-3xl shadow-2xl max-w-lg w-full transform transition hover:scale-105 duration-300">
        <div className="bg-blue-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-blue-200">
          <ClipboardList className="text-white w-10 h-10" />
        </div>
        <h1 className="text-4xl font-extrabold text-gray-800 mb-4 tracking-tight">Controle de Dados</h1>
        <p className="text-gray-500 mb-10 text-lg">Gerenciamento eficiente de jornadas e fechamentos semanais.</p>

        <button 
          onClick={() => setState(prev => ({ ...prev, view: 'SELECTION' }))}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-8 rounded-xl transition flex items-center justify-center gap-3 shadow-xl shadow-blue-100 group"
        >
          <span>Começar</span>
          <Play className="w-5 h-5 group-hover:translate-x-1 transition" />
        </button>

        <div className="mt-8 pt-8 border-t border-gray-100">
          <div className="relative">
            <input 
              type="password"
              placeholder="Acesso Admin"
              className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition"
              value={adminPassword}
              onChange={(e) => setAdminPassword(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleAdminLogin()}
            />
            <Settings className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <button 
              onClick={handleAdminLogin}
              className="absolute right-2 top-1/2 -translate-y-1/2 bg-gray-200 hover:bg-gray-300 p-1.5 rounded-lg transition"
            >
              <ChevronRight className="w-4 h-4 text-gray-600" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderSelectionView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <button onClick={() => setState(prev => ({ ...prev, view: 'HOME' }))} className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium">
        <ArrowLeft className="w-5 h-5" /> Voltar ao Início
      </button>
      <div className="grid md:grid-cols-2 gap-8 max-w-4xl w-full">
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.REGISTRADO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-blue-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-blue-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-blue-600 transition"><Users className="text-blue-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Registrado</h2>
          <p className="text-gray-500">Colaboradores em regime CLT com controle de ponto manual.</p>
        </button>
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.FIXO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-green-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-green-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-green-600 transition"><MapPin className="text-green-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Fixo (Extra)</h2>
          <p className="text-gray-500">Colaboradores eventuais com diária fixa e vale-transporte.</p>
        </button>
      </div>
    </div>
  );

  const renderFlowView = () => {
    const filteredEmployees = employees.filter(e => e.sectorId === selectedSector && e.type === state.flowType);
    return (
      <div className="max-w-xl mx-auto py-12 px-4">
        <button onClick={() => setState(prev => ({ ...prev, view: 'SELECTION' }))} className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium">
          <ArrowLeft className="w-5 h-5" /> Alterar Tipo
        </button>
        <div className="bg-white rounded-3xl shadow-xl p-8 space-y-8">
          <h2 className="text-2xl font-bold text-gray-800 border-b pb-4">
            {state.flowType === EmployeeType.REGISTRADO ? 'Lançamento Registrado' : 'Lançamento Fixo'}
          </h2>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Selecione o Setor</label>
            <select className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl outline-none" value={selectedSector} onChange={(e) => setSelectedSector(e.target.value)}>
              <option value="">Selecione um setor...</option>
              {sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>
          {selectedSector && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Funcionário</label>
              {state.flowType === EmployeeType.REGISTRADO ? (
                <select className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl outline-none" value={selectedEmployee} onChange={(e) => setSelectedEmployee(e.target.value)}>
                  <option value="">Selecione um funcionário...</option>
                  {filteredEmployees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
                </select>
              ) : (
                <input type="text" placeholder="Nome do Funcionário Fixo" className="w-full p-4 bg-gray-50 border border-gray-200 rounded-xl outline-none" value={selectedEmployee} onChange={(e) => setSelectedEmployee(e.target.value)} />
              )}
            </div>
          )}
          <button disabled={!selectedSector || !selectedEmployee} onClick={() => setShowFormModal(true)} className="w-full bg-blue-600 disabled:bg-gray-300 hover:bg-blue-700 text-white font-bold py-4 rounded-xl transition shadow-lg">Cadastrar Horários</button>
        </div>
      </div>
    );
  };

  const renderFormModal = () => {
    const updateRecord = (index: number, field: keyof TimeRecord, value: any) => {
      const newRecs = [...modalRecords];
      newRecs[index] = { ...newRecs[index], [field]: value };
      setModalRecords(newRecs);
    };

    const isAdminEditing = editingRequestId !== null;

    return (
      <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-y-auto p-8 relative">
          <button 
            onClick={() => { setShowFormModal(false); setEditingRequestId(null); }} 
            className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition"
          >
            <XCircle className="w-8 h-8" />
          </button>

          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h2 className="text-2xl font-bold">
              {isAdminEditing ? 'Editar Solicitação (Admin)' : 'Fechamento Semanal'}
            </h2>
            <div className="flex items-center gap-4">
              <span className="text-sm font-medium text-gray-500">Semana de:</span>
              <input 
                type="date" 
                className="p-2 border rounded-lg outline-none" 
                value={currentWeek} 
                onChange={(e) => !isAdminEditing && setCurrentWeek(e.target.value)} 
                disabled={isAdminEditing}
              />
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
                  <th className="p-4 border-b">Data</th>
                  <th className="p-4 border-b">Real Ent.</th>
                  <th className="p-4 border-b">Ponto Ent.</th>
                  <th className="p-4 border-b">Ponto Saída</th>
                  <th className="p-4 border-b">Real Saída</th>
                  <th className="p-4 border-b text-center">Ação</th>
                </tr>
              </thead>
              <tbody>
                {modalRecords.map((r, idx) => (
                  <tr key={idx} className="hover:bg-gray-50 border-b border-gray-100">
                    <td className="p-4 font-medium">{new Date(r.date).toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' })}</td>
                    <td className="p-2">
                      <input 
                        type="time" 
                        className="w-full p-2 border rounded-lg" 
                        value={r.realEntry} 
                        onChange={(e) => updateRecord(idx, 'realEntry', e.target.value)} 
                      />
                    </td>
                    {!r.isFolgaVendida ? (
                      <>
                        <td className="p-2">
                          <input 
                            type="time" 
                            className="w-full p-2 border rounded-lg" 
                            value={r.punchEntry} 
                            onChange={(e) => !isAdminEditing && updateRecord(idx, 'punchEntry', e.target.value)} 
                            disabled={isAdminEditing}
                          />
                        </td>
                        <td className="p-2">
                          <input 
                            type="time" 
                            className="w-full p-2 border rounded-lg" 
                            value={r.punchExit} 
                            onChange={(e) => !isAdminEditing && updateRecord(idx, 'punchExit', e.target.value)} 
                            disabled={isAdminEditing}
                          />
                        </td>
                      </>
                    ) : (
                      <td colSpan={2} className="p-2 text-center text-blue-600 font-bold bg-blue-50 rounded-lg uppercase">Folga Vendida</td>
                    )}
                    <td className="p-2">
                      <input 
                        type="time" 
                        className="w-full p-2 border rounded-lg" 
                        value={r.realExit} 
                        onChange={(e) => updateRecord(idx, 'realExit', e.target.value)} 
                      />
                    </td>
                    <td className="p-2 text-center">
                      <button 
                        disabled={isAdminEditing}
                        onClick={() => !isAdminEditing && updateRecord(idx, 'isFolgaVendida', !r.isFolgaVendida)} 
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition ${r.isFolgaVendida ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                      >
                        {r.isFolgaVendida ? 'Normal' : 'Vendida'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {isAdminEditing && (
            <div className="mt-8">
              <label className="block text-sm font-semibold text-gray-700 mb-2">Justificativa da Edição</label>
              <textarea 
                className="w-full p-4 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Explique o motivo da alteração dos horários..."
                rows={3}
                value={editJustification}
                onChange={(e) => setEditJustification(e.target.value)}
              />
            </div>
          )}

          <div className="mt-10 flex justify-end gap-4">
            <button 
              onClick={() => { setShowFormModal(false); setEditingRequestId(null); }} 
              className="px-8 py-3 bg-gray-100 hover:bg-gray-200 text-gray-700 font-bold rounded-xl transition"
            >
              Cancelar
            </button>
            <button 
              onClick={submitRequest} 
              className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl transition shadow-lg"
            >
              {isAdminEditing ? 'Salvar Edições' : 'Confirmar e Enviar'}
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderAdminDashboard = () => {
    const totalSpending = requests.reduce((acc, r) => acc + (r.status === RequestStatus.APROVADO ? r.calculatedValue : 0), 0);
    const spendingBySector = sectors.map(s => ({
      name: s.name,
      value: requests.filter(r => r.sectorId === s.id && r.status === RequestStatus.APROVADO).reduce((acc, r) => acc + r.calculatedValue, 0)
    }));
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <p className="text-gray-500 text-sm mb-1">Gasto Total Aprovado</p>
            <h3 className="text-3xl font-bold">{formatCurrency(totalSpending)}</h3>
          </div>
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <p className="text-gray-500 text-sm mb-1">Pendentes</p>
            <h3 className="text-3xl font-bold text-blue-600">{requests.filter(r => r.status === RequestStatus.PENDENTE).length}</h3>
          </div>
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <p className="text-gray-500 text-sm mb-1">Setor Principal</p>
            <h3 className="text-2xl font-bold">{spendingBySector.sort((a,b) => b.value - a.value)[0]?.name || '-'}</h3>
          </div>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-[400px]">
          <div className="bg-white p-8 rounded-3xl border border-gray-100">
            <h4 className="font-bold mb-6">Gastos por Setor</h4>
            <ResponsiveContainer width="100%" height="80%"><BarChart data={spendingBySector}><XAxis dataKey="name" /><YAxis /><Tooltip /><Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer>
          </div>
          <div className="bg-white p-8 rounded-3xl border border-gray-100">
            <h4 className="font-bold mb-6">Tipo de Funcionário</h4>
            <ResponsiveContainer width="100%" height="80%"><PieChart><Pie data={[{ name: 'Registrado', value: requests.filter(r => r.employeeType === EmployeeType.REGISTRADO).length }, { name: 'Fixo', value: requests.filter(r => r.employeeType === EmployeeType.FIXO).length }]} cx="50%" cy="50%" innerRadius={60} outerRadius={100} dataKey="value"><Cell fill="#3b82f6" /><Cell fill="#10b981" /></Pie><Tooltip /><Legend /></PieChart></ResponsiveContainer>
          </div>
        </div>
      </div>
    );
  };

  const renderAdminSectors = () => (
    <div className="bg-white p-8 rounded-3xl border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4">
      <h2 className="text-2xl font-bold">Setores</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-gray-50 p-6 rounded-2xl">
        <input type="text" placeholder="Nome" className="p-3 border rounded-xl" value={newSec.name} onChange={(e) => setNewSec({ ...newSec, name: e.target.value })} />
        <input type="number" placeholder="Diária Extra" className="p-3 border rounded-xl" value={newSec.fixedRate || ''} onChange={(e) => setNewSec({ ...newSec, fixedRate: parseFloat(e.target.value) })} />
        <button onClick={() => { if(newSec.name) setSectors([...sectors, {...newSec, id: Date.now().toString()}]); setNewSec({name: '', fixedRate: 0}) }} className="bg-blue-600 text-white font-bold rounded-xl">Adicionar</button>
      </div>
      <table className="w-full text-left">
        <thead><tr className="text-gray-400 text-xs uppercase border-b"><th className="py-4">Setor</th><th className="py-4">Diária</th><th className="py-4 text-right">Ação</th></tr></thead>
        <tbody>{sectors.map(s => (<tr key={s.id} className="border-b last:border-0 hover:bg-gray-50"><td className="py-4 font-semibold">{s.name}</td><td className="py-4">{formatCurrency(s.fixedRate)}</td><td className="py-4 text-right"><button onClick={() => setSectors(sectors.filter(sec => sec.id !== s.id))} className="text-red-500 hover:bg-red-50 p-2 rounded-lg"><XCircle className="w-5 h-5" /></button></td></tr>))}</tbody>
      </table>
    </div>
  );

  const renderAdminEmployees = () => (
    <div className="bg-white p-8 rounded-3xl border border-gray-100 space-y-8 animate-in slide-in-from-bottom-4">
      <h2 className="text-2xl font-bold">Funcionários Registrados</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 bg-gray-50 p-6 rounded-2xl">
        <input type="text" placeholder="Nome" className="p-3 border rounded-xl" value={newEmpData.name} onChange={(e) => setNewEmpData({ ...newEmpData, name: e.target.value })} />
        <select className="p-3 border rounded-xl" value={newEmpData.sectorId} onChange={(e) => setNewEmpData({ ...newEmpData, sectorId: e.target.value })}><option value="">Setor...</option>{sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select>
        <input type="number" placeholder="Salário" className="p-3 border rounded-xl" value={newEmpData.salary || ''} onChange={(e) => setNewEmpData({ ...newEmpData, salary: parseFloat(e.target.value) })} />
        <input type="number" placeholder="Horas/Mês" className="p-3 border rounded-xl" value={newEmpData.monthlyHours || ''} onChange={(e) => setNewEmpData({ ...newEmpData, monthlyHours: parseFloat(e.target.value) })} />
        <button onClick={() => { if(newEmpData.name && newEmpData.sectorId) setEmployees([...employees, {...newEmpData, id: Date.now().toString()}]); setNewEmpData({name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO}) }} className="bg-blue-600 text-white font-bold rounded-xl">Add</button>
      </div>
      <table className="w-full text-left">
        <thead><tr className="text-gray-400 text-xs border-b"><th className="py-4">Nome</th><th className="py-4">Setor</th><th className="py-4">Valor Hora (+25%)</th><th className="py-4 text-right">Ação</th></tr></thead>
        <tbody>{employees.map(e => {
          const s = sectors.find(sec => sec.id === e.sectorId);
          const hr = (e.salary / e.monthlyHours) * 1.25;
          return (<tr key={e.id} className="border-b hover:bg-gray-50"><td className="py-4">{e.name}</td><td className="py-4">{s?.name}</td><td className="py-4 text-blue-600 font-bold">{formatCurrency(hr)}</td><td className="py-4 text-right"><button onClick={() => setEmployees(employees.filter(emp => emp.id !== e.id))} className="text-red-400"><XCircle className="w-5 h-5" /></button></td></tr>)
        })}</tbody>
      </table>
    </div>
  );

  const renderAdminRequests = () => {
    const filtered = requests.filter(r => (filterStatus === 'ALL' || r.status === filterStatus) && (filterType === 'ALL' || r.employeeType === filterType));
    return (
      <div className="space-y-6">
        <div className="flex justify-between bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
          <h2 className="text-2xl font-bold">Solicitações</h2>
          <div className="flex gap-3">
            <select className="border rounded-lg p-2 text-sm" value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}><option value="ALL">Status</option><option value={RequestStatus.PENDENTE}>Pendente</option><option value={RequestStatus.APROVADO}>Aprovado</option><option value={RequestStatus.REJEITADO}>Rejeitado</option></select>
            <select className="border rounded-lg p-2 text-sm" value={filterType} onChange={(e) => setFilterType(e.target.value)}><option value="ALL">Tipo</option><option value={EmployeeType.REGISTRADO}>Registrado</option><option value={EmployeeType.FIXO}>Fixo</option></select>
          </div>
        </div>
        <div className="space-y-4">
          {filtered.map(req => (
            <div key={req.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex flex-col gap-4">
              <div className="flex justify-between items-center">
                <div>
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${req.employeeType === EmployeeType.REGISTRADO ? 'bg-blue-100 text-blue-700' : 'bg-green-100 text-green-700'}`}>{req.employeeType}</span>
                  <h4 className="text-lg font-bold">{req.employeeName}</h4>
                  <p className="text-sm text-gray-500">{req.sectorName} • {new Date(req.weekStarting).toLocaleDateString('pt-BR')}</p>
                </div>
                <div className="flex items-center gap-6">
                  <p className="text-xl font-black">{formatCurrency(req.calculatedValue)}</p>
                  <div className="flex gap-2">
                    {req.status === RequestStatus.PENDENTE ? (
                      <>
                        <button 
                          onClick={() => setRequests(requests.map(r => r.id === req.id ? {...r, status: RequestStatus.APROVADO} : r))} 
                          className="bg-green-500 hover:bg-green-600 text-white p-2 rounded-xl transition shadow-sm"
                          title="Aprovar"
                        >
                          <CheckCircle className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => setRequests(requests.map(r => r.id === req.id ? {...r, status: RequestStatus.REJEITADO} : r))} 
                          className="bg-red-500 hover:bg-red-600 text-white p-2 rounded-xl transition shadow-sm"
                          title="Rejeitar"
                        >
                          <XCircle className="w-5 h-5" />
                        </button>
                      </>
                    ) : (
                      <span className={`px-4 py-2 rounded-xl text-sm font-bold uppercase ${req.status === RequestStatus.APROVADO ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                        {req.status}
                      </span>
                    )}
                    <button 
                      onClick={() => startAdminEdit(req)}
                      className="bg-gray-100 hover:bg-gray-200 text-gray-600 p-2 rounded-xl transition shadow-sm"
                      title="Editar"
                    >
                      <Edit2 className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              </div>
              {req.editJustification && (
                <div className="p-3 bg-yellow-50 border border-yellow-100 rounded-xl">
                  <p className="text-xs text-yellow-800 font-bold uppercase mb-1">Justificativa da Edição:</p>
                  <p className="text-sm text-yellow-900">{req.editJustification}</p>
                </div>
              )}
            </div>
          ))}
          {filtered.length === 0 && (
            <div className="text-center py-12 bg-gray-50 rounded-2xl border-2 border-dashed">
              <p className="text-gray-400">Nenhuma solicitação encontrada.</p>
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderAdminIntegrations = () => {
    const exportCsv = (type: EmployeeType) => {
      const data = requests.filter(r => r.employeeType === type && r.status === RequestStatus.APROVADO);
      const csv = ["Data,Nome,Setor,Valor", ...data.map(r => `${new Date(r.createdAt).toLocaleDateString()},${r.employeeName},${r.sectorName},${r.calculatedValue.toFixed(2)}`)].join("\n");
      const a = document.createElement("a"); a.href = encodeURI("data:text/csv;charset=utf-8," + csv); a.download = `extra_${type.toLowerCase()}.csv`; a.click();
    };
    return (
      <div className="bg-white p-8 rounded-3xl border border-gray-100 space-y-8">
        <h2 className="text-2xl font-bold flex items-center gap-2"><LinkIcon /> Integrações</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="p-8 border rounded-3xl bg-blue-50/50"><h3>Registrados</h3><button onClick={() => exportCsv(EmployeeType.REGISTRADO)} className="mt-4 bg-blue-600 text-white px-6 py-3 rounded-xl hover:bg-blue-700 transition">Exportar CSV</button></div>
          <div className="p-8 border rounded-3xl bg-green-50/50"><h3>Fixos</h3><button onClick={() => exportCsv(EmployeeType.FIXO)} className="mt-4 bg-green-600 text-white px-6 py-3 rounded-xl hover:bg-green-700 transition">Exportar CSV</button></div>
        </div>
      </div>
    );
  };

  const renderAdminView = () => (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      <div className="w-72 bg-white border-r border-gray-100 flex flex-col p-6 shadow-sm">
        <div className="flex items-center gap-3 mb-12"><div className="bg-blue-600 p-2 rounded-lg"><Settings className="text-white w-5 h-5" /></div><h2 className="text-xl font-black">Admin Panel</h2></div>
        <nav className="flex-1 space-y-2">
          {[
            { id: 'DASHBOARD', label: 'Dashboard', icon: LayoutDashboard },
            { id: 'SECTORS', label: 'Setores', icon: MapPin },
            { id: 'EMPLOYEES', label: 'Funcionários', icon: Users },
            { id: 'REQUESTS', label: 'Solicitações', icon: ClipboardList },
            { id: 'INTEGRATIONS', label: 'Integrações', icon: LinkIcon },
          ].map(item => (
            <button key={item.id} onClick={() => setState(prev => ({ ...prev, adminSubView: item.id as any }))} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${state.adminSubView === item.id ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'}`}>
              <item.icon className="w-5 h-5" />{item.label}
            </button>
          ))}
        </nav>
        <button onClick={() => { setIsAuth(false); setState(prev => ({ ...prev, view: 'HOME' })) }} className="flex items-center gap-3 px-4 py-3 text-red-500 font-bold hover:bg-red-50 rounded-xl transition"><LogOut className="w-5 h-5" /> Sair</button>
      </div>
      <div className="flex-1 overflow-y-auto p-10">
        {state.adminSubView === 'DASHBOARD' && renderAdminDashboard()}
        {state.adminSubView === 'SECTORS' && renderAdminSectors()}
        {state.adminSubView === 'EMPLOYEES' && renderAdminEmployees()}
        {state.adminSubView === 'REQUESTS' && renderAdminRequests()}
        {state.adminSubView === 'INTEGRATIONS' && renderAdminIntegrations()}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen">
      {state.view === 'HOME' && renderHomeView()}
      {state.view === 'SELECTION' && renderSelectionView()}
      {state.view === 'FLOW' && renderFlowView()}
      {state.view === 'ADMIN' && renderAdminView()}
      {showFormModal && renderFormModal()}
    </div>
  );
};

export default App;

{
  "name": "Controle de Horas Pro",
  "description": "Sistema completo para gestão de horas e controle financeiro de funcionários registrados e fixos, com painel administrativo e cálculos automatizados.",
  "requestFramePermissions": []
}

import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Play, 
  ArrowLeft, 
  LayoutDashboard, 
  Users, 
  MapPin, 
  ClipboardList, 
  Link as LinkIcon,
  CheckCircle,
  XCircle,
  Clock,
  LogOut,
  ChevronRight,
  Filter,
  Download,
  Edit2,
  FileSpreadsheet
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  PieChart, 
  Pie, 
  Cell
} from 'recharts';
import * as XLSX from 'xlsx';
import { 
  EmployeeType, 
  RequestStatus, 
  Sector, 
  Employee, 
  TimeRequest, 
  AppState,
  TimeRecord 
} from './types';
import { 
  formatCurrency, 
  timeToDecimal, 
  calculateTimeDiff, 
  getWeekDays 
} from './utils';

const STORAGE_KEY = 'controle_horas_db';

const App: React.FC = () => {
  // --- Persistência de Dados ---
  const [sectors, setSectors] = useState<Sector[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [requests, setRequests] = useState<TimeRequest[]>([]);

  // --- Estado Global da Navegação ---
  const [state, setState] = useState<AppState>({
    view: 'HOME',
    flowType: null,
    adminSubView: 'DASHBOARD'
  });

  // --- Estados de Autenticação e Formulários ---
  const [adminPassword, setAdminPassword] = useState('');
  const [isAuth, setIsAuth] = useState(false);
  const [selectedSector, setSelectedSector] = useState<string>('');
  const [selectedEmployee, setSelectedEmployee] = useState<string>('');
  const [showFormModal, setShowFormModal] = useState(false);
  const [currentWeek, setCurrentWeek] = useState(new Date().toISOString().split('T')[0]);

  // Estados temporários para formulários no Admin
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [filterType, setFilterType] = useState<string>('ALL');
  const [newSec, setNewSec] = useState({ name: '', fixedRate: 0 });
  const [editingSectorId, setEditingSectorId] = useState<string | null>(null);
  const [newEmpData, setNewEmpData] = useState({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });
  const [modalRecords, setModalRecords] = useState<TimeRecord[]>([]);

  // Estado para Edição pelo Admin
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);
  const [editJustification, setEditJustification] = useState('');

  // Carregar Dados Iniciais
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setSectors(parsed.sectors || []);
      setEmployees(parsed.employees || []);
      setRequests(parsed.requests || []);
    } else {
      const initialSectors = [
        { id: '1', name: 'Recepção', fixedRate: 80 },
        { id: '2', name: 'Governança', fixedRate: 70 },
        { id: '3', name: 'Reservas', fixedRate: 75 },
        { id: '4', name: 'Mensageria', fixedRate: 60 },
      ];
      setSectors(initialSectors);
    }
  }, []);

  // Salvar mudanças
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ sectors, employees, requests }));
  }, [sectors, employees, requests]);

  // Inicializar registros do modal
  useEffect(() => {
    if (showFormModal && !editingRequestId) {
      const days = getWeekDays(new Date(currentWeek));
      setModalRecords(days.map(d => ({ date: d, realEntry: '', punchEntry: '', punchExit: '', realExit: '', isFolgaVendida: false })));
    }
  }, [showFormModal, currentWeek, editingRequestId]);

  const handleAdminLogin = () => {
    if (adminPassword === '123') {
      setIsAuth(true);
      setState(prev => ({ ...prev, view: 'ADMIN' }));
      setAdminPassword('');
    } else {
      alert('Senha incorreta!');
    }
  };

  const submitRequest = () => {
    const originalRequest = editingRequestId ? requests.find(r => r.id === editingRequestId) : null;
    const flowTypeToUse = originalRequest ? originalRequest.employeeType : state.flowType;
    const employeeIdToUse = originalRequest ? originalRequest.employeeId : selectedEmployee;
    const sectorIdToUse = originalRequest ? originalRequest.sectorId : selectedSector;

    const employee = employees.find(e => e.id === employeeIdToUse);
    const sector = sectors.find(s => s.id === (employee?.sectorId || sectorIdToUse));

    if (!employee && flowTypeToUse === EmployeeType.REGISTRADO) return;

    let totalDiffHours = 0;
    let totalPayment = 0;

    if (flowTypeToUse === EmployeeType.REGISTRADO && employee) {
      const hourlyBase = employee.salary / employee.monthlyHours;
      const hourlyWithExtra = hourlyBase * 1.25;

      modalRecords.forEach(r => {
        if (!r.isFolgaVendida) {
          const entryDiff = calculateTimeDiff(r.realEntry, r.punchEntry);
          const exitDiff = calculateTimeDiff(r.realExit, r.punchExit);
          totalDiffHours += (entryDiff + exitDiff);
        } else {
          totalDiffHours += calculateTimeDiff(r.realExit, r.realEntry);
        }
      });
      totalPayment = totalDiffHours * hourlyWithExtra;
    } else {
      const dailyRate = sector?.fixedRate || 0;
      modalRecords.forEach(r => {
        if (r.realEntry && r.realExit) {
          totalPayment += dailyRate + 12;
        }
      });
    }

    if (editingRequestId) {
      setRequests(requests.map(r => r.id === editingRequestId ? {
        ...r,
        records: modalRecords,
        calculatedValue: totalPayment,
        totalTimeDecimal: totalDiffHours,
        editJustification: editJustification
      } : r));
      setEditingRequestId(null);
      setEditJustification('');
    } else {
      const newRequest: TimeRequest = {
        id: Math.random().toString(36).substr(2, 9),
        employeeId: employee?.id || 'fixo-temp',
        employeeName: employee?.name || selectedEmployee || 'Funcionário Fixo',
        employeeType: state.flowType!,
        sectorId: sector?.id || '',
        sectorName: sector?.name || '',
        weekStarting: currentWeek,
        records: modalRecords,
        status: RequestStatus.PENDENTE,
        calculatedValue: totalPayment,
        totalTimeDecimal: totalDiffHours,
        createdAt: new Date().toISOString()
      };
      setRequests([newRequest, ...requests]);
      setState(prev => ({ ...prev, view: 'HOME' }));
    }

    setShowFormModal(false);
    alert(editingRequestId ? 'Solicitação editada com sucesso!' : 'Solicitação enviada com sucesso!');
  };

  const startAdminEdit = (req: TimeRequest) => {
    setEditingRequestId(req.id);
    setModalRecords(JSON.parse(JSON.stringify(req.records)));
    setEditJustification(req.editJustification || '');
    setCurrentWeek(req.weekStarting);
    setShowFormModal(true);
  };

  const startSectorEdit = (sec: Sector) => {
    setEditingSectorId(sec.id);
    setNewSec({ name: sec.name, fixedRate: sec.fixedRate });
  };

  const saveSector = () => {
    if (!newSec.name) return;
    if (editingSectorId) {
      setSectors(sectors.map(s => s.id === editingSectorId ? { ...s, name: newSec.name, fixedRate: newSec.fixedRate } : s));
      setEditingSectorId(null);
    } else {
      setSectors([...sectors, { ...newSec, id: Date.now().toString() }]);
    }
    setNewSec({ name: '', fixedRate: 0 });
  };

  // --- Funções de Renderização Auxiliares ---

  const renderHomeView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-4">
      <div className="bg-white p-12 rounded-3xl shadow-2xl max-w-lg w-full transform transition hover:scale-105 duration-300">
        <div className="bg-blue-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-blue-200">
          <ClipboardList className="text-white w-10 h-10" />
        </div>
        <h1 className="text-4xl font-extrabold text-gray-800 mb-4 tracking-tight">Controle de Horas</h1>
        <p className="text-gray-500 mb-10 text-lg">Gerenciamento eficiente de jornadas e fechamentos semanais.</p>

        <button 
          onClick={() => setState(prev => ({ ...prev, view: 'SELECTION' }))}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-8 rounded-xl transition flex items-center justify-center gap-3 shadow-xl shadow-blue-100 group"
        >
          <span>Começar</span>
          <Play className="w-5 h-5 group-hover:translate-x-1 transition" />
        </button>

        <div className="mt-8 pt-8 border-t border-gray-100">
          <div className="relative">
            <input 
              type="password"
              placeholder="Acesso Admin"
              className="w-full pl-12 pr-4 py-3 bg-white border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition text-black"
              value={adminPassword}
              onChange={(e) => setAdminPassword(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleAdminLogin()}
            />
            <Settings className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <button 
              onClick={handleAdminLogin}
              className="absolute right-2 top-1/2 -translate-y-1/2 bg-gray-200 hover:bg-gray-300 p-1.5 rounded-lg transition"
            >
              <ChevronRight className="w-4 h-4 text-gray-600" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderSelectionView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <button onClick={() => setState(prev => ({ ...prev, view: 'HOME' }))} className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium">
        <ArrowLeft className="w-5 h-5" /> Voltar ao Início
      </button>
      <div className="grid md:grid-cols-2 gap-8 max-w-4xl w-full">
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.REGISTRADO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-blue-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-blue-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-blue-600 transition"><Users className="text-blue-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Registrado</h2>
          <p className="text-gray-500">Colaboradores em regime CLT com controle de ponto manual.</p>
        </button>
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.FIXO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-green-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-green-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-green-600 transition"><MapPin className="text-green-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Fixo (Extra)</h2>
