      const data = requests.filter(r => r.employeeType === type && r.status === RequestStatus.APROVADO);

      const rows = data.map(r => ({
        "Data": new Date(r.createdAt).toLocaleDateString('pt-BR'),
        "Funcionário": r.employeeName,
        "Setor": r.sectorName,
        "Tipo": r.employeeType,
