        {state.adminSubView === 'INTEGRATIONS' && renderAdminIntegrations()}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen">
      {state.view === 'HOME' && renderHomeView()}
      {state.view === 'SELECTION' && renderSelectionView()}
      {state.view === 'FLOW' && renderFlowView()}
      {state.view === 'ADMIN' && renderAdminView()}
      {showFormModal && renderFormModal()}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Play, 
  ArrowLeft, 
  LayoutDashboard, 
  Users, 
  MapPin, 
  ClipboardList, 
  Link as LinkIcon,
  CheckCircle,
  XCircle,
  Clock,
  LogOut,
  ChevronRight,
  Filter,
  Edit2,
  CloudUpload,
  ExternalLink
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  PieChart, 
  Pie, 
  Cell
} from 'recharts';
import { 
  EmployeeType, 
  RequestStatus, 
  Sector, 
  Employee, 
  TimeRequest, 
  AppState,
  TimeRecord 
} from './types';
import { 
  formatCurrency, 
  timeToDecimal, 
  calculateTimeDiff, 
  getWeekDays 
} from './utils';

const STORAGE_KEY = 'controle_horas_db_v2';

const App: React.FC = () => {
  // --- Persistência de Dados ---
  const [sectors, setSectors] = useState<Sector[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [requests, setRequests] = useState<TimeRequest[]>([]);

  // URLs de Integração (Apps Script)
  const [registradoSheetUrl, setRegistradoSheetUrl] = useState('');
  const [fixoSheetUrl, setFixoSheetUrl] = useState('');

  // --- Estado Global da Navegação ---
  const [state, setState] = useState<AppState>({
    view: 'HOME',
    flowType: null,
    adminSubView: 'DASHBOARD'
  });

  // --- Estados de Autenticação e Formulários ---
  const [adminPassword, setAdminPassword] = useState('');
  const [isAuth, setIsAuth] = useState(false);
  const [selectedSector, setSelectedSector] = useState<string>('');
  const [selectedEmployee, setSelectedEmployee] = useState<string>('');
  const [showFormModal, setShowFormModal] = useState(false);
  const [currentWeek, setCurrentWeek] = useState(new Date().toISOString().split('T')[0]);

  // Estados temporários para formulários no Admin
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [filterType, setFilterType] = useState<string>('ALL');
  const [newSec, setNewSec] = useState({ name: '', fixedRate: 0 });
  const [editingSectorId, setEditingSectorId] = useState<string | null>(null);
  const [newEmpData, setNewEmpData] = useState({ name: '', sectorId: '', salary: 0, monthlyHours: 220, type: EmployeeType.REGISTRADO });
  const [modalRecords, setModalRecords] = useState<TimeRecord[]>([]);

  // Estado para Edição pelo Admin
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);
  const [editJustification, setEditJustification] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  // Carregar Dados Iniciais
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setSectors(parsed.sectors || []);
      setEmployees(parsed.employees || []);
      setRequests(parsed.requests || []);
      setRegistradoSheetUrl(parsed.registradoSheetUrl || '');
      setFixoSheetUrl(parsed.fixoSheetUrl || '');
    } else {
      const initialSectors = [
        { id: '1', name: 'Recepção', fixedRate: 80 },
        { id: '2', name: 'Governança', fixedRate: 70 },
        { id: '3', name: 'Reservas', fixedRate: 75 },
        { id: '4', name: 'Mensageria', fixedRate: 60 },
      ];
      setSectors(initialSectors);
    }
  }, []);

  // Salvar mudanças
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      sectors, 
      employees, 
      requests,
      registradoSheetUrl,
      fixoSheetUrl
    }));
  }, [sectors, employees, requests, registradoSheetUrl, fixoSheetUrl]);

  // Inicializar registros do modal
  useEffect(() => {
    if (showFormModal && !editingRequestId) {
      const days = getWeekDays(new Date(currentWeek));
      setModalRecords(days.map(d => ({ date: d, realEntry: '', punchEntry: '', punchExit: '', realExit: '', isFolgaVendida: false })));
    }
  }, [showFormModal, currentWeek, editingRequestId]);

  const handleAdminLogin = () => {
    if (adminPassword === '123') {
      setIsAuth(true);
      setState(prev => ({ ...prev, view: 'ADMIN' }));
      setAdminPassword('');
    } else {
      alert('Senha incorreta!');
    }
  };

  const submitRequest = () => {
    const originalRequest = editingRequestId ? requests.find(r => r.id === editingRequestId) : null;
    const flowTypeToUse = originalRequest ? originalRequest.employeeType : state.flowType;
    const employeeIdToUse = originalRequest ? originalRequest.employeeId : selectedEmployee;
    const sectorIdToUse = originalRequest ? originalRequest.sectorId : selectedSector;

    const employee = employees.find(e => e.id === employeeIdToUse);
    const sector = sectors.find(s => s.id === (employee?.sectorId || sectorIdToUse));

    if (!employee && flowTypeToUse === EmployeeType.REGISTRADO) return;

    let totalDiffHours = 0;
    let totalPayment = 0;

    if (flowTypeToUse === EmployeeType.REGISTRADO && employee) {
      const hourlyBase = employee.salary / employee.monthlyHours;
      const hourlyWithExtra = hourlyBase * 1.25;

      modalRecords.forEach(r => {
        if (!r.isFolgaVendida) {
          const entryDiff = calculateTimeDiff(r.realEntry, r.punchEntry);
          const exitDiff = calculateTimeDiff(r.realExit, r.punchExit);
          totalDiffHours += (entryDiff + exitDiff);
        } else {
          totalDiffHours += calculateTimeDiff(r.realExit, r.realEntry);
        }
      });
      totalPayment = totalDiffHours * hourlyWithExtra;
    } else {
      const dailyRate = sector?.fixedRate || 0;
      modalRecords.forEach(r => {
        if (r.realEntry && r.realExit) {
          totalPayment += dailyRate + 12;
        }
      });
    }

    if (editingRequestId) {
      setRequests(requests.map(r => r.id === editingRequestId ? {
        ...r,
        records: modalRecords,
        calculatedValue: totalPayment,
        totalTimeDecimal: totalDiffHours,
        editJustification: editJustification
      } : r));
      setEditingRequestId(null);
      setEditJustification('');
    } else {
      const newRequest: TimeRequest = {
        id: Math.random().toString(36).substr(2, 9),
        employeeId: employee?.id || 'fixo-temp',
        employeeName: employee?.name || selectedEmployee || 'Funcionário Fixo',
        employeeType: state.flowType!,
        sectorId: sector?.id || '',
        sectorName: sector?.name || '',
        weekStarting: currentWeek,
        records: modalRecords,
        status: RequestStatus.PENDENTE,
        calculatedValue: totalPayment,
        totalTimeDecimal: totalDiffHours,
        createdAt: new Date().toISOString()
      };
      setRequests([newRequest, ...requests]);
      setState(prev => ({ ...prev, view: 'HOME' }));
    }

    setShowFormModal(false);
    alert(editingRequestId ? 'Solicitação editada com sucesso!' : 'Solicitação enviada com sucesso!');
  };

  const startAdminEdit = (req: TimeRequest) => {
    setEditingRequestId(req.id);
    setModalRecords(JSON.parse(JSON.stringify(req.records)));
    setEditJustification(req.editJustification || '');
    setCurrentWeek(req.weekStarting);
    setShowFormModal(true);
  };

  const startSectorEdit = (sec: Sector) => {
    setEditingSectorId(sec.id);
    setNewSec({ name: sec.name, fixedRate: sec.fixedRate });
  };

  const saveSector = () => {
    if (!newSec.name) return;
    if (editingSectorId) {
      setSectors(sectors.map(s => s.id === editingSectorId ? { ...s, name: newSec.name, fixedRate: newSec.fixedRate } : s));
      setEditingSectorId(null);
    } else {
      setSectors([...sectors, { ...newSec, id: Date.now().toString() }]);
    }
    setNewSec({ name: '', fixedRate: 0 });
  };

  const syncToGoogleSheets = async (type: EmployeeType) => {
    const url = type === EmployeeType.REGISTRADO ? registradoSheetUrl : fixoSheetUrl;
    if (!url) {
      alert('Por favor, configure a URL do Apps Script primeiro.');
      return;
    }

    const dataToSync = requests.filter(r => r.employeeType === type && r.status === RequestStatus.APROVADO);
    if (dataToSync.length === 0) {
      alert('Não há solicitações aprovadas para integrar no momento.');
      return;
    }

    setIsSyncing(true);
    try {
      // Formatar dados para envio
      const payload = dataToSync.map(r => ({
        id: r.id,
        data_solicitacao: new Date(r.createdAt).toLocaleDateString('pt-BR'),
        funcionario: r.employeeName,
        setor: r.sectorName,
        tipo: r.employeeType,
        semana_fechamento: new Date(r.weekStarting).toLocaleDateString('pt-BR'),
        valor_total: r.calculatedValue,
        horas_extras: r.totalTimeDecimal.toFixed(2),
        justificativa: r.editJustification || ''
      }));

      // Nota: Apps Script Web Apps exigem redirecionamento ou CORS configurado.
      // Usamos no-cors se o script apenas processar e não precisar de resposta complexa,
      // mas POST JSON geralmente requer CORS.
      const response = await fetch(url, {
        method: 'POST',
        mode: 'no-cors', // Apps Script geralmente funciona assim para envios simples
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          type: type,
          items: payload
        }),
      });

      alert('Dados enviados para o Google Sheets! Verifique sua planilha.');
    } catch (error) {
      console.error('Erro na integração:', error);
      alert('Ocorreu um erro ao tentar integrar com o Google Sheets.');
    } finally {
      setIsSyncing(false);
    }
  };

  // --- Funções de Renderização Auxiliares ---

  const renderHomeView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-4">
      <div className="bg-white p-12 rounded-3xl shadow-2xl max-w-lg w-full transform transition hover:scale-105 duration-300">
        <div className="bg-blue-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-blue-200">
          <ClipboardList className="text-white w-10 h-10" />
        </div>
        <h1 className="text-4xl font-extrabold text-gray-800 mb-4 tracking-tight">Controle de Horas</h1>
        <p className="text-gray-500 mb-10 text-lg">Gerenciamento eficiente de jornadas e fechamentos semanais.</p>

        <button 
          onClick={() => setState(prev => ({ ...prev, view: 'SELECTION' }))}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-8 rounded-xl transition flex items-center justify-center gap-3 shadow-xl shadow-blue-100 group"
        >
          <span>Começar</span>
          <Play className="w-5 h-5 group-hover:translate-x-1 transition" />
        </button>

        <div className="mt-8 pt-8 border-t border-gray-100">
          <div className="relative">
            <input 
              type="password"
              placeholder="Acesso Admin"
              className="w-full pl-12 pr-4 py-3 bg-white border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition text-black placeholder-gray-400"
              value={adminPassword}
              onChange={(e) => setAdminPassword(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleAdminLogin()}
            />
            <Settings className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <button 
              onClick={handleAdminLogin}
              className="absolute right-2 top-1/2 -translate-y-1/2 bg-gray-200 hover:bg-gray-300 p-1.5 rounded-lg transition"
            >
              <ChevronRight className="w-4 h-4 text-gray-600" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderSelectionView = () => (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <button onClick={() => setState(prev => ({ ...prev, view: 'HOME' }))} className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium">
        <ArrowLeft className="w-5 h-5" /> Voltar ao Início
      </button>
      <div className="grid md:grid-cols-2 gap-8 max-w-4xl w-full">
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.REGISTRADO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-blue-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-blue-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-blue-600 transition"><Users className="text-blue-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Registrado</h2>
          <p className="text-gray-500">Colaboradores em regime CLT com controle de ponto manual.</p>
        </button>
        <button onClick={() => setState(prev => ({ ...prev, view: 'FLOW', flowType: EmployeeType.FIXO }))} className="bg-white p-10 rounded-3xl shadow-xl hover:shadow-2xl hover:border-green-500 border-2 border-transparent transition-all group text-left">
          <div className="bg-green-50 w-16 h-16 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-green-600 transition"><MapPin className="text-green-600 w-8 h-8 group-hover:text-white transition" /></div>
          <h2 className="text-2xl font-bold mb-2">Fixo (Extra)</h2>
          <p className="text-gray-500">Colaboradores eventuais com diária fixa e vale-transporte.</p>
        </button>
      </div>
    </div>
  );

  const renderFlowView = () => {
    const filteredEmployees = employees.filter(e => e.sectorId === selectedSector && e.type === state.flowType);
    return (
      <div className="max-w-xl mx-auto py-12 px-4">
        <button onClick={() => setState(prev => ({ ...prev, view: 'SELECTION' }))} className="mb-8 flex items-center gap-2 text-gray-500 hover:text-blue-600 transition font-medium">
          <ArrowLeft className="w-5 h-5" /> Alterar Tipo
        </button>
        <div className="bg-white rounded-3xl shadow-xl p-8 space-y-8">
          <h2 className="text-2xl font-bold text-gray-800 border-b pb-4">
            {state.flowType === EmployeeType.REGISTRADO ? 'Lançamento Registrado' : 'Lançamento Fixo'}
          </h2>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Selecione o Setor</label>
            <select className="w-full p-4 bg-white border border-gray-300 rounded-xl outline-none text-black" value={selectedSector} onChange={(e) => setSelectedSector(e.target.value)}>
              <option value="">Selecione um setor...</option>
              {sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </select>
          </div>
          {selectedSector && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Funcionário</label>
              {state.flowType === EmployeeType.REGISTRADO ? (
                <select className="w-full p-4 bg-white border border-gray-300 rounded-xl outline-none text-black" value={selectedEmployee} onChange={(e) => setSelectedEmployee(e.target.value)}>
                  <option value="">Selecione um funcionário...</option>
                  {filteredEmployees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
                </select>
              ) : (
                <input type="text" placeholder="Nome do Funcionário Fixo" className="w-full p-4 bg-white border border-gray-300 rounded-xl outline-none text-black" value={selectedEmployee} onChange={(e) => setSelectedEmployee(e.target.value)} />
              )}
            </div>
          )}
          <button disabled={!selectedSector || !selectedEmployee} onClick={() => setShowFormModal(true)} className="w-full bg-blue-600 disabled:bg-gray-300 hover:bg-blue-700 text-white font-bold py-4 rounded-xl transition shadow-lg">Cadastrar Horários</button>
        </div>
      </div>
    );
  };

  const renderFormModal = () => {
    const updateRecord = (index: number, field: keyof TimeRecord, value: any) => {
      const newRecs = [...modalRecords];
      newRecs[index] = { ...newRecs[index], [field]: value };
      setModalRecords(newRecs);
    };

    const isAdminEditing = editingRequestId !== null;

    return (
      <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-y-auto p-8 relative">
          <button 
            onClick={() => { setShowFormModal(false); setEditingRequestId(null); }} 
