          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
                  <th className="p-4 border-b">Data</th>
                  <th className="p-4 border-b">Real Ent.</th>
                  <th className="p-4 border-b">Ponto Ent.</th>
                  <th className="p-4 border-b">Ponto Saída</th>
                  <th className="p-4 border-b">Real Saída</th>
                  <th className="p-4 border-b text-center">Ação</th>
                </tr>
              </thead>
              <tbody>
                {modalRecords.map((r, idx) => (
                  <tr key={idx} className="hover:bg-gray-50 border-b border-gray-100">
                    <td className="p-4 font-medium">{new Date(r.date).toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' })}</td>
                    <td className="p-2">
                      <input 
                        type="time" 
                        className="w-full p-2 border border-gray-300 rounded-lg bg-white text-black" 
                        value={r.realEntry} 
                        onChange={(e) => updateRecord(idx, 'realEntry', e.target.value)} 
                      />
                    </td>
                    {!r.isFolgaVendida ? (
                      <>
                        <td className="p-2">
                          <input 
                            type="time" 
                            className="w-full p-2 border border-gray-300 rounded-lg bg-white text-black" 
                            value={r.punchEntry} 
                            onChange={(e) => !isAdminEditing && updateRecord(idx, 'punchEntry', e.target.value)} 
                            disabled={isAdminEditing}
                          />
                        </td>
                        <td className="p-2">
                          <input 
                            type="time" 
                            className="w-full p-2 border border-gray-300 rounded-lg bg-white text-black" 
                            value={r.punchExit} 
                            onChange={(e) => !isAdminEditing && updateRecord(idx, 'punchExit', e.target.value)} 
                            disabled={isAdminEditing}
                          />
                        </td>
                      </>
                    ) : (
                      <td colSpan={2} className="p-2 text-center text-blue-600 font-bold bg-blue-50 rounded-lg uppercase">Folga Vendida</td>
                    )}
                    <td className="p-2">
                      <input 
                        type="time" 
                        className="w-full p-2 border border-gray-300 rounded-lg bg-white text-black" 
                        value={r.realExit} 
                        onChange={(e) => updateRecord(idx, 'realExit', e.target.value)} 
                      />
                    </td>
                    <td className="p-2 text-center">
                      <button 
                        disabled={isAdminEditing}
                        onClick={() => !isAdminEditing && updateRecord(idx, 'isFolgaVendida', !r.isFolgaVendida)} 
                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition ${r.isFolgaVendida ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                      >
                        {r.isFolgaVendida ? 'Normal' : 'Vendida'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {isAdminEditing && (
            <div className="mt-8">
              <label className="block text-sm font-semibold text-gray-700 mb-2">Justificativa da Edição</label>
              <textarea 
                className="w-full p-4 border border-gray-300 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 bg-white text-black"
