            >
              {isAdminEditing ? 'Salvar Edições' : 'Confirmar e Enviar'}
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderAdminDashboard = () => {
    const totalSpending = requests.reduce((acc, r) => acc + (r.status === RequestStatus.APROVADO ? r.calculatedValue : 0), 0);
    const spendingBySector = sectors.map(s => ({
      name: s.name,
      value: requests.filter(r => r.sectorId === s.id && r.status === RequestStatus.APROVADO).reduce((acc, r) => acc + r.calculatedValue, 0)
