        {state.adminSubView === 'EMPLOYEES' && renderAdminEmployees()}
        {state.adminSubView === 'REQUESTS' && renderAdminRequests()}
        {state.adminSubView === 'INTEGRATIONS' && renderAdminIntegrations()}
      </div>
    </div>
  );

  return (
    <div className="min-h-screen">
      {state.view === 'HOME' && renderHomeView()}
      {state.view === 'SELECTION' && renderSelectionView()}
      {state.view === 'FLOW' && renderFlowView()}
      {state.view === 'ADMIN' && renderAdminView()}
      {showFormModal && renderFormModal()}
    </div>
  );
};

export default App;

payload.text:
Primeiro, apresento o código do **Google Apps Script** que você deve copiar e colar no Editor de Script de cada uma das suas planilhas (Extensões > Apps Script).

### Google Apps Script (Sincronização Automática)
Este script processa os dados de Apartamentos, Orçamentos (com os novos detalhes) e Funcionários.

```javascript
/**
 * Google Apps Script para Gestão Hotel Village
 * Versão: 7.0 (Suporte a Orçamentos Detalhados)
 */

function doPost(e) {
  try {
    var requestData = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheetName = '';

    // Identifica o tipo de dado para selecionar a aba correta
    if (requestData.dataType === 'BUDGET') sheetName = 'Orçamentos';
    else if (requestData.dataType === 'EMPLOYEE') sheetName = 'Funcionários';
    else if (requestData.dataType === 'APARTMENT') sheetName = 'Apartamentos';
    else sheetName = 'Logs_Gerais';

    var sheet = ss.getSheetByName(sheetName) || ss.insertSheet(sheetName);

    // Cria cabeçalhos se a planilha estiver vazia
    if (sheet.getLastRow() === 0) {
      if (requestData.dataType === 'BUDGET') {
        sheet.appendRow(['ID', 'Título', 'Objetivo', 'Itens Detalhados', 'Vencedor', 'Menor Valor', 'Status', 'Data']);
      } else if (requestData.dataType === 'EMPLOYEE') {
        sheet.appendRow(['ID', 'Nome', 'Cargo', 'Setor', 'Salário', 'Status', 'Atualizado em']);
      } else {
        sheet.appendRow(['Apto', 'Andar', 'Status Avarias', 'Última Vistoria']);
      }
      sheet.getRange(1, 1, 1, sheet.getLastColumn()).setFontWeight('bold').setBackground('#f3f3f3');
    }

    if (requestData.dataType === 'BUDGET') {
      // Formata os itens detalhados para uma string legível na célula
      var itemsStr = (requestData.items || []).map(function(item) {
        var mats = (item.materials || []).map(function(m) { 
          return m.name + " (" + m.quantity + "x R$" + m.price + ")"; 
        }).join("; ");
        return "[" + item.description + " | Mão de Obra: R$" + item.laborCost + " | Tempo: " + item.estimatedTime + " | Mat: " + mats + "]";
      }).join("\n");

      var quotes = requestData.quotes || [];
      var minVal = Math.min.apply(Math, quotes.map(function(q) { return q.value; }));
      var winner = quotes.filter(function(q) { return q.value === minVal; })[0];

      sheet.appendRow([
        requestData.id, 
        requestData.title, 
        requestData.objective, 
        itemsStr, 
        winner ? winner.supplier : '-', 
        minVal, 
        requestData.status, 
        new Date()
      ]);

      // Salva arquivos no Drive se houver
      processFiles(requestData, "Orçamentos");

    } else if (requestData.dataType === 'EMPLOYEE') {
      var empRow = [requestData.id, requestData.name, requestData.role, requestData.department, requestData.salary, requestData.status, new Date()];
      sheet.appendRow(empRow);
    } else if (requestData.dataType === 'APARTMENT') {
      var aptRow = [requestData.roomNumber, requestData.floor, requestData.defects ? requestData.defects.length : 0, new Date()];
      sheet.appendRow(aptRow);
      processFiles(requestData, "Vistorias_Aptos");
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function processFiles(requestData, folderName) {
  if (requestData.newFiles && requestData.newFiles.length > 0) {
    var root = getOrCreateFolder("Hotel Village - Arquivos");
    var ctx = getOrCreateFolder(folderName, root);
    var target = getOrCreateFolder(requestData.title || ("Apto_" + requestData.roomNumber), ctx);
    requestData.newFiles.forEach(function(f) { 
      if (f.data) target.createFile(Utilities.newBlob(Utilities.base64Decode(f.data), f.mimeType || "application/octet-stream", f.fileName)); 
    });
  }
}

function getOrCreateFolder(name, parent) {
  var folders = parent ? parent.getFoldersByName(name) : DriveApp.getFoldersByName(name);
  if (folders.hasNext()) return folders.next();
  return parent ? parent.createFolder(name) : DriveApp.createFolder(name);
}
```

Agora, seguem as atualizações no código da aplicação para incluir o detalhamento de materiais, mão de obra e tempo dentro do fluxo de orçamentos.

### Especificação das Alterações:
1.  **Interface de Dados**: Atualização do tipo `Budget` para suportar `items`, que contêm descrições de serviços, lista de materiais (nome, quantidade, preço), custo de mão de obra e tempo estimado.
2.  **Novo Orçamento (Modal)**:
    *   Renomeado de "Novo Pedido" para "Novo Orçamento".
    *   Inclusão de seção "Escopo do Projeto / O que será feito".
    *   Botão para adicionar múltiplos itens de serviço.
    *   Dentro de cada serviço, campos para adicionar materiais dinamicamente.
    *   Cálculo automático do subtotal do serviço (Materiais + Mão de Obra).
3.  **Visual**: Fundo branco com escrita preta nas caixas de texto, mantendo a estética premium e profissional.

