export enum ViewType {
  DASHBOARD = 'DASHBOARD',
  APARTMENTS = 'APARTMENTS',
  BUDGETS = 'BUDGETS',
  SETTINGS = 'SETTINGS',
  EMPLOYEES = 'EMPLOYEES'
}

export type UserRole = 'ROUPARIA' | 'GERENCIA' | 'DIRETORIA';

export interface User {
  role: UserRole;
  hotel?: HotelType;
}

export type HotelType = 'VILLAGE' | 'GOLDEN_PARK' | 'THERMAL_RESORT';

export interface HotelTheme {
  primary: string;
  secondary: string;
  accent: string;
  bg: string;
  text: string;
  chartColors: string[];
}

export interface Defect {
  id: string;
  driveLink: string;
  description: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface MaterialItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
}

export interface BudgetItem {
  id: string;
  description: string;
  materials: MaterialItem[];
  laborCost: number;
  estimatedTime: string;
}

export interface BudgetFile {
  id: string;
  driveLink: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface Quote {
  id: string;
  supplier: string;
  value: number;
  files: BudgetFile[];
}

export interface Budget {
  id: string;
  title: string;
  objective: string;
  items: BudgetItem[];
  quotes: Quote[];
  status: 'Pendente' | 'Aprovado' | 'Rejeitado';
  createdAt: number;
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  contact: string;
  startDate: string;
  salary: number;
  department: string;
  status: 'Ativo' | 'Inativo';
  scheduleType: '6x1' | '12x36' | 'Intermitente';
  shiftType?: 'Par' | 'Ímpar';
  workingHours: string;
  weeklyDayOff: string;
  monthlySundayOff: string;
  vacationStatus: 'Pendente' | 'Concedida';
}

export interface Integration {
  id: string;
  name: string;
  type: 'Spreadsheet' | 'ExternalAPI';
  status: 'Connected' | 'Disconnected' | 'Pending';
  lastSync?: number;
  url?: string;
}

export interface Apartment {
  id: string;
  floor: number;
  roomNumber: number;
  defects: Defect[];
  pisoType?: 'Granito' | 'Madeira' | 'Cerâmica';
  pisoStatus?: 'Bom estado' | 'Tolerável' | 'Reparo urgente';
  banheiroType?: 'Reformado' | 'Antigo';
  banheiroStatus?: 'Tolerável' | 'Reparo urgente';
  temCofre?: boolean;
  temCortina?: boolean;
  cortinaStatus?: 'Nova' | 'Antiga';
  cortinaSize?: string;
  cortinaCoverage?: 'Dois lados' | 'Um lado';
  temEspelhoCorpo?: boolean;
  espelhoCorpoStatus?: 'Bom estado' | 'Manchado' | 'Danificado';
  acBrand?: 'Midea' | 'LG' | 'Grey';
  moveisStatus?: 'Bom estado' | 'Danificado';
  moveisDetalhes?: string[];
  beds?: Array<{
    type: 'Casal' | 'Solteiro';
    baseStatus?: 'Nova' | 'Antiga';
    baseColor?: string;
    mattressStatus?: 'Novo' | 'Antigo';
    mattressColor?: string;
    hasSkirt?: boolean;
    skirtColor?: string;
  }>;
  temPortaControle?: boolean;
  temCabide?: boolean;
  cabideQuantity?: number;
  temSuportePapel?: boolean;
  temSuporteShampoo?: boolean;
  suporteShampooStatus?: 'Bom estado' | 'Enferrujado';
  luminariaType?: 'Arandela' | 'Vidro' | 'Quadrado';
  luminariaColor?: 'Branco' | 'Preto';
  tvBrand?: 'LG' | 'Samsung' | 'Philco' | 'Smart Roku' | 'Toshiba';
}

export interface HotelData {
  apartments: Record<string, Apartment>;
  budgets: Budget[];
  employees: Employee[];
}

export interface AppState {
  currentView: ViewType;
  currentHotel: HotelType;
  hotels: Record<HotelType, HotelData>;
  selectedFloor: number | null;
  selectedApartmentId: string | null;
  integrations: Integration[];
  currentUser: User | null;
}

import React, { useState, useRef } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  DollarSign, 
  Briefcase,
  ChevronDown,
  ChevronUp,
  X,
  CheckCircle,
  Clock,
  AlertCircle,
  Paperclip,
  FileText,
  File,
  Image as ImageIcon,
  Download,
  Eye,
  Info,
  ChevronRight,
  Trophy,
  TrendingDown,
  Layers,
  Wrench,
  Package,
  Calendar
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [viewingFile, setViewingFile] = useState<BudgetFile | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentQuoteIndexRef = useRef<number | null>(null);

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...item.materials, { id: Date.now().toString(), name: '', quantity: 1, price: 0 }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: item.materials.filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  const updateQuote = (index: number, field: keyof Quote, value: any) => {
    const newQuotes = [...quotes];
    newQuotes[index] = { ...newQuotes[index], [field]: value };
    setQuotes(newQuotes);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || quotes.some(q => !q.supplier)) {
      alert("Por favor, preencha o título e as informações dos fornecedores.");
      return;
    }

    const finalBudget: Budget = {
      id: Date.now().toString(),
      title,
      objective,
      items,
      quotes: quotes as Quote[],
      status,
      createdAt: Date.now()
    };

    const allFilesForSync: {data: string, mimeType: string, fileName: string}[] = [];
    quotes.forEach(q => {
      q.files?.forEach(f => {
        if (f.data) {
          allFilesForSync.push({ data: f.data, mimeType: f.fileType!, fileName: f.fileName! });
        }
      });
    });

    onSave(finalBudget, allFilesForSync);
    resetForm();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const quoteIndex = currentQuoteIndexRef.current;
    if (file && quoteIndex !== null) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = reader.result?.toString().split(',')[1] || '';
        const newBudgetFile: BudgetFile = {
          id: Date.now().toString(),
          driveLink: 'pendente',
          timestamp: Date.now(),
          fileName: file.name,
          fileType: file.type,
          data: base64Data
        };
        const newQuotes = [...quotes];
        newQuotes[quoteIndex].files = [...(newQuotes[quoteIndex].files || []), newBudgetFile];
        setQuotes(newQuotes);
        if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDownload = (file: BudgetFile) => {
    if (!file.data) return;
    const link = document.createElement('a');
    link.href = `data:${file.fileType};base64,${file.data}`;
    link.download = file.fileName || 'orcamento_anexo';
    link.click();
  };

  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500';
      default: return 'bg-amber-400 text-slate-800 border-amber-400';
    }
  };

  const getFileIcon = (type?: string) => {
    if (!type) return <File size={14} />;
    if (type.startsWith('image/')) return <ImageIcon size={14} />;
    if (type.includes('pdf')) return <FileText size={14} />;
    return <Paperclip size={14} />;
  };

  const calculateSubtotal = (item: BudgetItem) => {
    const materialsTotal = item.materials.reduce((acc, m) => acc + (m.quantity * m.price), 0);
    return materialsTotal + (item.laborCost || 0);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Buscar orçamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:border-blue-500 outline-none shadow-sm transition-all bg-white text-slate-800"
          />
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
          style={{ backgroundColor: theme.primary, boxShadow: `0 10px 15px -3px ${theme.primary}40` }}
        >
          <Plus size={20} />
          <span>Novo Orçamento</span>
        </button>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">Criação de Novo Orçamento</h2>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Detalhamento técnico e financeiro</p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-10">
                {/* DADOS GERAIS */}
                <section className="space-y-6">
                   <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                     <Info size={14} className="mr-2" /> Informações do Projeto
                   </h3>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="col-span-2">
                      <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Título do Orçamento</label>
                      <input required type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma Banheiro Apto 205" className="w-full px-5 py-4 rounded-2xl border-2 border-slate-100 focus:border-blue-400 outline-none transition-all bg-white font-bold text-slate-800" />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Objetivo da Obra / Serviço</label>
                      <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Descreva o propósito geral..." className="w-full px-5 py-4 rounded-2xl border-2 border-slate-100 focus:border-blue-400 outline-none transition-all h-24 bg-white font-bold text-slate-800" />
                    </div>
                  </div>
                </section>

                {/* DETALHAMENTO DE ITENS */}
                <section className="space-y-6">
                  <div className="flex justify-between items-center">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                      <Layers size={14} className="mr-2" /> O que será feito (Itens do Serviço)
                    </h3>
                    <button type="button" onClick={addServiceItem} className="flex items-center space-x-2 text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-100">
                      <Plus size={12} /> <span>Adicionar Item</span>
                    </button>
                  </div>

                  <div className="space-y-6">
                    {items.map((item, idx) => (
                      <div key={item.id} className="p-6 bg-slate-50/50 rounded-3xl border border-slate-200 relative animate-in slide-in-from-top-4">
                        <button type="button" onClick={() => removeServiceItem(item.id)} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500"><Trash2 size={16}/></button>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                          <div className="md:col-span-3">
                            <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5">Descrição do Serviço / Local</label>
                            <input type="text" value={item.description} onChange={(e) => updateItem(item.id, 'description', e.target.value)} placeholder="Ex: Troca de revestimento e louças sanitárias" className="w-full px-4 py-3 rounded-xl border border-slate-200 outline-none focus:border-blue-300 bg-white text-sm font-bold" />
                          </div>

                          <div className="space-y-4 md:col-span-2">
                            <div className="flex justify-between items-center">
                              <label className="block text-[9px] font-black text-slate-400 uppercase">Materiais Necessários</label>
                              <button type="button" onClick={() => addMaterial(item.id)} className="text-[8px] font-black text-emerald-600 bg-white border px-2 py-1 rounded shadow-sm">+ Material</button>
                            </div>
                            <div className="space-y-2">
                              {item.materials.map(mat => (
                                <div key={mat.id} className="flex items-center gap-2 animate-in slide-in-from-left-2">
                                  <input type="text" placeholder="Material" value={mat.name} onChange={e => updateMaterial(item.id, mat.id, 'name', e.target.value)} className="flex-1 px-3 py-2 rounded-lg border bg-white text-[10px] font-bold" />
                                  <input type="number" placeholder="Qtd" value={mat.quantity} onChange={e => updateMaterial(item.id, mat.id, 'quantity', parseFloat(e.target.value))} className="w-16 px-3 py-2 rounded-lg border bg-white text-[10px] font-bold" />
                                  <input type="number" step="0.01" placeholder="R$ Unit" value={mat.price} onChange={e => updateMaterial(item.id, mat.id, 'price', parseFloat(e.target.value))} className="w-24 px-3 py-2 rounded-lg border bg-white text-[10px] font-bold" />
                                  <button type="button" onClick={() => removeMaterial(item.id, mat.id)} className="text-rose-300 hover:text-rose-500"><Trash2 size={14}/></button>
                                </div>
                              ))}
                              {item.materials.length === 0 && <p className="text-[9px] text-slate-400 italic text-center py-2 bg-white rounded-lg border-2 border-dashed">Nenhum material listado.</p>}
                            </div>
                          </div>

                          <div className="space-y-4">
                            <div>
                               <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 flex items-center"><Wrench size={10} className="mr-1"/> Valor Mão de Obra</label>
                               <input type="number" step="0.01" value={item.laborCost} onChange={e => updateItem(item.id, 'laborCost', parseFloat(e.target.value))} className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                            </div>
                            <div>
                               <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 flex items-center"><Calendar size={10} className="mr-1"/> Tempo Estimado</label>
                               <input type="text" placeholder="Ex: 3 dias" value={item.estimatedTime} onChange={e => updateItem(item.id, 'estimatedTime', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                            </div>
                            <div className="pt-4 border-t border-slate-100">
                               <p className="text-[8px] font-black text-slate-400 uppercase">Subtotal do Item</p>
                               <p className="text-lg font-black text-slate-800">R$ {calculateSubtotal(item).toLocaleString('pt-BR')}</p>
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>

                {/* FORNECEDORES (QUADRO COMPARATIVO) */}
                <section className="space-y-6">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                    <TrendingDown size={14} className="mr-2" /> Quadro de Cotações Externas
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {quotes.map((quote, idx) => (
                      <div key={quote.id} className="p-6 bg-slate-50/50 rounded-[2rem] border border-slate-100 flex flex-col">
                        <span className="text-[9px] font-black text-slate-400 uppercase mb-3">Opção Fornecedor {idx + 1}</span>
                        <div className="space-y-4">
                           <input required type="text" value={quote.supplier} onChange={(e) => updateQuote(idx, 'supplier', e.target.value)} placeholder="Empresa / Profissional" className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                           <div className="relative">
                             <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14}/>
                             <input required type="number" step="0.01" value={quote.value || ''} onChange={(e) => updateQuote(idx, 'value', parseFloat(e.target.value))} placeholder="Valor Global" className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                           </div>
                           <button type="button" onClick={() => { currentQuoteIndexRef.current = idx; fileInputRef.current?.click(); }} className="w-full py-2.5 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 hover:text-blue-500 hover:bg-white transition-all text-[9px] font-black uppercase flex items-center justify-center space-x-2">
                             <Paperclip size={12}/> <span>Anexar PDF/Foto</span>
                           </button>
                           <div className="flex flex-wrap gap-1">
                             {quote.files?.map((f, fi) => (
                               <div key={fi} className="bg-white border rounded px-2 py-1 text-[8px] font-bold flex items-center gap-1">
                                 <File size={8}/> {f.fileName}
                               </div>
                             ))}
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>

                <div className="flex gap-4 pt-8 border-t border-slate-50">
                  <button type="button" onClick={resetForm} className="flex-1 py-5 rounded-2xl font-black text-xs text-slate-400 uppercase tracking-widest hover:bg-slate-50">Cancelar</button>
                  <button type="submit" className="flex-1 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl transition-all active:scale-95" style={{ backgroundColor: theme.primary }}>Finalizar Orçamento Detalhado</button>
                </div>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
              </form>
            </div>
          </div>
        </div>
      )}

      {/* LISTAGEM DE ORÇAMENTOS */}
      <div className="grid grid-cols-1 gap-6">
        {filteredBudgets.length === 0 ? (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300">
            <Receipt size={64} className="mb-4 opacity-10" />
            <p className="text-xl font-black italic uppercase tracking-tighter">Nenhum orçamento encontrado</p>
          </div>
        ) : (
          filteredBudgets.map(budget => {
            const minQuoteValue = Math.min(...budget.quotes.map(q => q.value));
            const minQuote = budget.quotes.find(q => q.value === minQuoteValue);

            return (
              <div key={budget.id} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all overflow-hidden">
                <div className="p-6 md:p-8 cursor-pointer" onClick={() => setExpandedId(expandedId === budget.id ? null : budget.id)}>
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center space-x-6">
                      <div className="p-5 bg-slate-50 text-slate-900 rounded-[1.5rem] border border-slate-100">
                        <Receipt size={28} />
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-xl leading-none mb-2">{budget.title}</h4>
                        <div className="flex items-center space-x-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                          <span className="flex items-center"><Layers size={12} className="mr-1" /> {budget.items?.length || 0} Itens</span>
                          <span className="w-1.5 h-1.5 bg-slate-100 rounded-full"></span>
                          <span>{new Date(budget.createdAt).toLocaleDateString('pt-BR')}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between md:justify-end space-x-8">
                      <div className="text-right">
                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Melhor Valor</p>
                        <p className="text-2xl font-black text-emerald-500 leading-none mt-1">R$ {minQuoteValue.toLocaleString('pt-BR')}</p>
                      </div>
                      <div className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase border-2 ${getStatusStyle(budget.status)}`}>
                        {budget.status}
                      </div>
                      {expandedId === budget.id ? <ChevronUp size={24} className="text-slate-300" /> : <ChevronDown size={24} className="text-slate-300" />}
                    </div>
                  </div>
                </div>

                {expandedId === budget.id && (
                  <div className="px-8 pb-10 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 bg-slate-50/30">
                    <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      {/* DETALHES TÉCNICOS */}
                      <div className="lg:col-span-3 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {(budget.items || []).map((item, iIdx) => (
                            <div key={item.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                              <div className="flex justify-between items-start mb-4">
                                <span className="text-[10px] font-black text-blue-500 uppercase">Item {iIdx + 1}</span>
                                <span className="text-[10px] font-bold text-slate-400 flex items-center"><Clock size={10} className="mr-1"/> {item.estimatedTime}</span>
                              </div>
                              <h6 className="font-black text-slate-800 mb-3">{item.description}</h6>
                              <div className="space-y-2 mb-4">
                                {item.materials.map(m => (
                                  <div key={m.id} className="flex justify-between text-[10px] text-slate-600 border-b border-slate-50 pb-1">
                                    <span>{m.quantity}x {m.name}</span>
                                    <span className="font-bold">R$ {(m.quantity * m.price).toLocaleString()}</span>
                                  </div>
                                ))}
                              </div>
                              <div className="flex justify-between items-center text-[10px] font-black uppercase pt-2">
                                <span className="text-slate-400">Mão de Obra</span>
                                <span className="text-slate-800">R$ {item.laborCost.toLocaleString()}</span>
                              </div>
                              <div className="flex justify-between items-center text-xs font-black uppercase pt-3 border-t border-slate-100 mt-3">
                                <span className="text-blue-600">Total do Item</span>
                                <span className="text-blue-600">R$ {calculateSubtotal(item).toLocaleString()}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* AÇÕES E COTAÇÕES */}
                      <div className="lg:col-span-1 space-y-4">
                        <div className="bg-white p-6 rounded-[2rem] border border-slate-100">
                          <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Ações do Pedido</h5>
                          <button onClick={() => updateStatus(budget, 'Aprovado')} className="w-full py-3 mb-2 rounded-xl bg-emerald-500 text-white font-black text-[10px] uppercase shadow-lg shadow-emerald-100">Aprovar Projeto</button>
                          <button onClick={() => updateStatus(budget, 'Rejeitado')} className="w-full py-3 rounded-xl bg-white border-2 border-rose-100 text-rose-500 font-black text-[10px] uppercase">Rejeitar</button>
                        </div>
                        <button onClick={() => onDelete(budget.id)} className="w-full flex items-center justify-center space-x-2 text-[10px] font-black text-slate-300 hover:text-rose-500 uppercase pt-4">
                          <Trash2 size={16} /> <span>Excluir</span>
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default BudgetsView;

export enum ViewType {
  DASHBOARD = 'DASHBOARD',
  APARTMENTS = 'APARTMENTS',
  BUDGETS = 'BUDGETS',
  SETTINGS = 'SETTINGS',
  EMPLOYEES = 'EMPLOYEES'
}

export type UserRole = 'ROUPARIA' | 'GERENCIA' | 'DIRETORIA';

export interface User {
  role: UserRole;
  hotel?: HotelType;
}

export type HotelType = 'VILLAGE' | 'GOLDEN_PARK' | 'THERMAL_RESORT';

export interface HotelTheme {
  primary: string;
  secondary: string;
  accent: string;
  bg: string;
  text: string;
  chartColors: string[];
}

export interface Defect {
  id: string;
  driveLink: string;
  description: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface MaterialItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
}

export interface BudgetItem {
  id: string;
  description: string;
  materials: MaterialItem[];
  laborCost: number;
  estimatedTime: string;
}

export interface BudgetFile {
  id: string;
  driveLink: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface Quote {
  id: string;
  supplier: string;
  value: number;
  files: BudgetFile[];
}

export interface Budget {
  id: string;
  title: string;
  objective: string;
  items: BudgetItem[];
  quotes: Quote[];
  status: 'Pendente' | 'Aprovado' | 'Rejeitado';
  createdAt: number;
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  contact: string;
  startDate: string;
  salary: number;
  department: string;
  status: 'Ativo' | 'Inativo';
  scheduleType: '6x1' | '12x36' | 'Intermitente';
  shiftType?: 'Par' | 'Ímpar';
  workingHours: string;
  weeklyDayOff: string;
  monthlySundayOff: string;
  vacationStatus: 'Pendente' | 'Concedida';
}

export interface Integration {
  id: string;
  name: string;
  type: 'Spreadsheet' | 'ExternalAPI';
  status: 'Connected' | 'Disconnected' | 'Pending';
  lastSync?: number;
  url?: string;
}

// Added BedConfig interface to fix import error in ApartmentDetailView.tsx
export interface BedConfig {
  type: 'Casal' | 'Solteiro';
  baseStatus?: 'Nova' | 'Antiga';
  baseColor?: string;
  mattressStatus?: 'Novo' | 'Antigo';
  mattressColor?: string;
  hasSkirt?: boolean;
  skirtColor?: string;
}

export interface Apartment {
  id: string;
  floor: number;
  roomNumber: number;
  defects: Defect[];
  pisoType?: 'Granito' | 'Madeira' | 'Cerâmica';
  pisoStatus?: 'Bom estado' | 'Tolerável' | 'Reparo urgente';
  banheiroType?: 'Reformado' | 'Antigo';
  banheiroStatus?: 'Tolerável' | 'Reparo urgente';
  temCofre?: boolean;
  temCortina?: boolean;
  cortinaStatus?: 'Nova' | 'Antiga';
  cortinaSize?: string;
  cortinaCoverage?: 'Dois lados' | 'Um lado';
  temEspelhoCorpo?: boolean;
  espelhoCorpoStatus?: 'Bom estado' | 'Manchado' | 'Danificado';
  acBrand?: 'Midea' | 'LG' | 'Grey';
  moveisStatus?: 'Bom estado' | 'Danificado';
  moveisDetalhes?: string[];
  // Updated to use the exported BedConfig interface
  beds?: BedConfig[];
  temPortaControle?: boolean;
  temCabide?: boolean;
  cabideQuantity?: number;
  temSuportePapel?: boolean;
  temSuporteShampoo?: boolean;
  suporteShampooStatus?: 'Bom estado' | 'Enferrujado';
  luminariaType?: 'Arandela' | 'Vidro' | 'Quadrado';
  luminariaColor?: 'Branco' | 'Preto';
  tvBrand?: 'LG' | 'Samsung' | 'Philco' | 'Smart Roku' | 'Toshiba';
}

export interface HotelData {
  apartments: Record<string, Apartment>;
  budgets: Budget[];
  employees: Employee[];
}

export interface AppState {
  currentView: ViewType;
  currentHotel: HotelType;
  hotels: Record<HotelType, HotelData>;
  selectedFloor: number | null;
  selectedApartmentId: string | null;
  integrations: Integration[];
  currentUser: User | null;
}

import React, { useState, useRef } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  DollarSign, 
  Briefcase,
  ChevronDown,
  ChevronUp,
  X,
  CheckCircle,
  Clock,
  AlertCircle,
  Paperclip,
  FileText,
  File,
  Image as ImageIcon,
  Download,
  Eye,
  Info,
  ChevronRight,
  Trophy,
  TrendingDown,
  Layers,
  Wrench,
  Package,
  Calendar
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentQuoteIndexRef = useRef<number | null>(null);

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...item.materials, { id: Date.now().toString(), name: '', quantity: 1, price: 0 }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: item.materials.filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  const updateQuote = (index: number, field: keyof Quote, value: any) => {
    const newQuotes = [...quotes];
    newQuotes[index] = { ...newQuotes[index], [field]: value };
    setQuotes(newQuotes);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // As per request, making fields optional, but we still need a basic identification
    const finalBudget: Budget = {
      id: Date.now().toString(),
      title: title || 'Orçamento Sem Título',
      objective,
      items,
      quotes: (quotes as Quote[]).filter(q => q.supplier || q.value > 0), // Filter empty quotes
      status,
      createdAt: Date.now()
    };

    // Ensure at least one quote placeholder if all were empty
    if (finalBudget.quotes.length === 0) {
      finalBudget.quotes = [{ id: 'empty', supplier: 'Não Informado', value: 0, files: [] }];
    }

    const allFilesForSync: {data: string, mimeType: string, fileName: string}[] = [];
    quotes.forEach(q => {
      q.files?.forEach(f => {
        if (f.data) {
          allFilesForSync.push({ data: f.data, mimeType: f.fileType!, fileName: f.fileName! });
        }
      });
    });

    onSave(finalBudget, allFilesForSync);
    resetForm();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const quoteIndex = currentQuoteIndexRef.current;
    if (file && quoteIndex !== null) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = reader.result?.toString().split(',')[1] || '';
        const newBudgetFile: BudgetFile = {
          id: Date.now().toString(),
          driveLink: 'pendente',
          timestamp: Date.now(),
          fileName: file.name,
          fileType: file.type,
          data: base64Data
        };
        const newQuotes = [...quotes];
        newQuotes[quoteIndex].files = [...(newQuotes[quoteIndex].files || []), newBudgetFile];
        setQuotes(newQuotes);
        if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsDataURL(file);
    }
  };

  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500';
      default: return 'bg-amber-400 text-slate-800 border-amber-400';
    }
  };

  const calculateSubtotal = (item: BudgetItem) => {
    const materialsTotal = item.materials.reduce((acc, m) => acc + (m.quantity * m.price), 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Buscar orçamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:border-blue-500 outline-none shadow-sm transition-all bg-white text-slate-800"
          />
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
          style={{ backgroundColor: theme.primary, boxShadow: `0 10px 15px -3px ${theme.primary}40` }}
        >
          <Plus size={20} />
          <span>Novo Orçamento</span>
        </button>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">Criação de Novo Orçamento</h2>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Detalhamento técnico e financeiro</p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-10">
                {/* DADOS GERAIS */}
                <section className="space-y-6">
                   <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                     <Info size={14} className="mr-2" /> Informações do Projeto
                   </h3>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="col-span-2">
                      <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Título do Orçamento</label>
                      <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma Banheiro Apto 205" className="w-full px-5 py-4 rounded-2xl border-2 border-slate-100 focus:border-blue-400 outline-none transition-all bg-white font-bold text-slate-800" />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Objetivo da Obra / Serviço</label>
                      <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Descreva o propósito geral..." className="w-full px-5 py-4 rounded-2xl border-2 border-slate-100 focus:border-blue-400 outline-none transition-all h-24 bg-white font-bold text-slate-800" />
                    </div>
                  </div>
                </section>

                {/* DETALHAMENTO DE ITENS */}
                <section className="space-y-6">
                  <div className="flex justify-between items-center">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                      <Layers size={14} className="mr-2" /> O que será feito (Itens do Serviço)
                    </h3>
                    <button type="button" onClick={addServiceItem} className="flex items-center space-x-2 text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-100">
                      <Plus size={12} /> <span>Adicionar Item</span>
                    </button>
                  </div>

                  <div className="space-y-6">
                    {items.map((item, idx) => (
                      <div key={item.id} className="p-6 bg-white rounded-3xl border border-slate-200 relative animate-in slide-in-from-top-4 shadow-sm">
                        <button type="button" onClick={() => removeServiceItem(item.id)} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500"><Trash2 size={16}/></button>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                          <div className="md:col-span-3">
                            <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5">Descrição do Serviço / Local</label>
                            <input type="text" value={item.description} onChange={(e) => updateItem(item.id, 'description', e.target.value)} placeholder="Ex: Troca de revestimento e louças sanitárias" className="w-full px-4 py-3 rounded-xl border border-slate-200 outline-none focus:border-blue-300 bg-white text-sm font-bold" />
                          </div>

                          <div className="space-y-4 md:col-span-2">
                            <div className="flex justify-between items-center">
                              <label className="block text-[9px] font-black text-slate-400 uppercase">Materiais Necessários</label>
                              <button type="button" onClick={() => addMaterial(item.id)} className="text-[8px] font-black text-emerald-600 bg-white border border-emerald-100 px-2 py-1 rounded shadow-sm">+ Material</button>
                            </div>
                            <div className="space-y-2">
                              {item.materials.map(mat => (
                                <div key={mat.id} className="flex items-center gap-2 animate-in slide-in-from-left-2">
                                  <input type="text" placeholder="Material" value={mat.name} onChange={e => updateMaterial(item.id, mat.id, 'name', e.target.value)} className="flex-1 px-3 py-2 rounded-lg border border-slate-100 bg-white text-[10px] font-bold" />
                                  <input type="number" placeholder="Qtd" value={mat.quantity} onChange={e => updateMaterial(item.id, mat.id, 'quantity', parseFloat(e.target.value))} className="w-16 px-3 py-2 rounded-lg border border-slate-100 bg-white text-[10px] font-bold" />
                                  <input type="number" step="0.01" placeholder="R$ Unit" value={mat.price} onChange={e => updateMaterial(item.id, mat.id, 'price', parseFloat(e.target.value))} className="w-24 px-3 py-2 rounded-lg border border-slate-100 bg-white text-[10px] font-bold" />
                                  <button type="button" onClick={() => removeMaterial(item.id, mat.id)} className="text-rose-300 hover:text-rose-500"><Trash2 size={14}/></button>
                                </div>
                              ))}
                              {item.materials.length === 0 && <p className="text-[9px] text-slate-400 italic text-center py-2 bg-slate-50 rounded-lg border-2 border-dashed">Nenhum material listado.</p>}
                            </div>
                          </div>

                          <div className="space-y-4">
                            <div>
                               <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 flex items-center"><Wrench size={10} className="mr-1"/> Valor Mão de Obra</label>
                               <input type="number" step="0.01" value={item.laborCost || ''} onChange={e => updateItem(item.id, 'laborCost', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                            </div>
                            <div>
                               <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 flex items-center"><Calendar size={10} className="mr-1"/> Tempo Estimado</label>
                               <input type="text" placeholder="Ex: 3 dias" value={item.estimatedTime} onChange={e => updateItem(item.id, 'estimatedTime', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                            </div>
                            <div className="pt-4 border-t border-slate-100">
                               <p className="text-[8px] font-black text-slate-400 uppercase">Subtotal do Item</p>
                               <p className="text-lg font-black text-slate-800">R$ {calculateSubtotal(item).toLocaleString('pt-BR')}</p>
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>

                {/* FORNECEDORES (QUADRO COMPARATIVO) */}
                <section className="space-y-6">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                    <TrendingDown size={14} className="mr-2" /> Quadro de Cotações Externas
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {quotes.map((quote, idx) => (
                      <div key={quote.id} className="p-6 bg-white rounded-[2rem] border border-slate-100 flex flex-col shadow-sm">
                        <span className="text-[9px] font-black text-slate-400 uppercase mb-3">Opção Fornecedor {idx + 1}</span>
                        <div className="space-y-4">
                           <input type="text" value={quote.supplier} onChange={(e) => updateQuote(idx, 'supplier', e.target.value)} placeholder="Empresa / Profissional" className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                           <div className="relative">
                             <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14}/>
                             <input type="number" step="0.01" value={quote.value || ''} onChange={(e) => updateQuote(idx, 'value', parseFloat(e.target.value))} placeholder="Valor Global" className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                           </div>
                           <button type="button" onClick={() => { currentQuoteIndexRef.current = idx; fileInputRef.current?.click(); }} className="w-full py-2.5 border-2 border-dashed border-slate-100 rounded-xl text-slate-400 hover:text-blue-500 hover:bg-slate-50 transition-all text-[9px] font-black uppercase flex items-center justify-center space-x-2">
                             <Paperclip size={12}/> <span>Anexar PDF/Foto</span>
                           </button>
                           <div className="flex flex-wrap gap-1">
                             {quote.files?.map((f, fi) => (
                               <div key={fi} className="bg-slate-50 border border-slate-100 rounded px-2 py-1 text-[8px] font-bold flex items-center gap-1">
                                 <File size={8}/> {f.fileName}
                               </div>
                             ))}
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>

                <div className="flex gap-4 pt-8 border-t border-slate-50">
                  <button type="button" onClick={resetForm} className="flex-1 py-5 rounded-2xl font-black text-xs text-slate-400 uppercase tracking-widest hover:bg-slate-50">Cancelar</button>
                  <button type="submit" className="flex-1 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl transition-all active:scale-95" style={{ backgroundColor: theme.primary }}>Finalizar Orçamento Detalhado</button>
                </div>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
              </form>
            </div>
          </div>
        </div>
      )}

      {/* LISTAGEM DE ORÇAMENTOS */}
      <div className="grid grid-cols-1 gap-6">
        {filteredBudgets.length === 0 ? (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300">
            <Receipt size={64} className="mb-4 opacity-10" />
            <p className="text-xl font-black italic uppercase tracking-tighter">Nenhum orçamento encontrado</p>
          </div>
        ) : (
          filteredBudgets.map(budget => {
            const minQuoteValue = budget.quotes.length > 0 ? Math.min(...budget.quotes.map(q => q.value)) : 0;

            return (
              <div key={budget.id} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all overflow-hidden">
                <div className="p-6 md:p-8 cursor-pointer" onClick={() => setExpandedId(expandedId === budget.id ? null : budget.id)}>
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center space-x-6">
                      <div className="p-5 bg-slate-50 text-slate-900 rounded-[1.5rem] border border-slate-100">
                        <Receipt size={28} />
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-xl leading-none mb-2">{budget.title}</h4>
                        <div className="flex items-center space-x-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                          <span className="flex items-center"><Layers size={12} className="mr-1" /> {budget.items?.length || 0} Itens</span>
                          <span className="w-1.5 h-1.5 bg-slate-100 rounded-full"></span>
                          <span>{new Date(budget.createdAt).toLocaleDateString('pt-BR')}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between md:justify-end space-x-8">
                      <div className="text-right">
                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Melhor Valor</p>
                        <p className="text-2xl font-black text-emerald-500 leading-none mt-1">R$ {minQuoteValue.toLocaleString('pt-BR')}</p>
                      </div>
                      <div className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase border-2 ${getStatusStyle(budget.status)}`}>
                        {budget.status}
                      </div>
                      {expandedId === budget.id ? <ChevronUp size={24} className="text-slate-300" /> : <ChevronDown size={24} className="text-slate-300" />}
                    </div>
                  </div>
                </div>

                {expandedId === budget.id && (
                  <div className="px-8 pb-10 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 bg-slate-50/30">
                    <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      {/* DETALHES TÉCNICOS */}
                      <div className="lg:col-span-3 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {(budget.items || []).map((item, iIdx) => (
                            <div key={item.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                              <div className="flex justify-between items-start mb-4">
                                <span className="text-[10px] font-black text-blue-500 uppercase">Item {iIdx + 1}</span>
                                <span className="text-[10px] font-bold text-slate-400 flex items-center"><Clock size={10} className="mr-1"/> {item.estimatedTime || 'N/A'}</span>
                              </div>
                              <h6 className="font-black text-slate-800 mb-3">{item.description || 'Sem Descrição'}</h6>
                              <div className="space-y-2 mb-4">
                                {item.materials.map(m => (
                                  <div key={m.id} className="flex justify-between text-[10px] text-slate-600 border-b border-slate-50 pb-1">
                                    <span>{m.quantity}x {m.name}</span>
                                    <span className="font-bold">R$ {(m.quantity * m.price).toLocaleString()}</span>
                                  </div>
                                ))}
                              </div>
                              <div className="flex justify-between items-center text-[10px] font-black uppercase pt-2">
                                <span className="text-slate-400">Mão de Obra</span>
                                <span className="text-slate-800">R$ {(Number(item.laborCost) || 0).toLocaleString()}</span>
                              </div>
                              <div className="flex justify-between items-center text-xs font-black uppercase pt-3 border-t border-slate-100 mt-3">
                                <span className="text-blue-600">Total do Item</span>
                                <span className="text-blue-600">R$ {calculateSubtotal(item).toLocaleString()}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                        {budget.objective && (
                          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                            <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Objetivo do Projeto</h5>
                            <p className="text-sm text-slate-600 font-medium">{budget.objective}</p>
                          </div>
                        )}
                      </div>

                      {/* AÇÕES E COTAÇÕES */}
                      <div className="lg:col-span-1 space-y-4">
                        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
                          <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Ações do Pedido</h5>
                          <button onClick={() => updateStatus(budget, 'Aprovado')} className="w-full py-3 mb-2 rounded-xl bg-emerald-500 text-white font-black text-[10px] uppercase shadow-lg shadow-emerald-100">Aprovar Projeto</button>
                          <button onClick={() => updateStatus(budget, 'Rejeitado')} className="w-full py-3 rounded-xl bg-white border-2 border-rose-100 text-rose-500 font-black text-[10px] uppercase">Rejeitar</button>
                        </div>
                        <button onClick={() => onDelete(budget.id)} className="w-full flex items-center justify-center space-x-2 text-[10px] font-black text-slate-300 hover:text-rose-500 uppercase pt-4">
                          <Trash2 size={16} /> <span>Excluir Orçamento</span>
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default BudgetsView;

{
  "name": "Gestão Hotel Village",
  "description": "Sistema completo para gestão de unidades Nacional Inn, incluindo controle de apartamentos, orçamentos detalhados de manutenção e gestão de equipe.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum ViewType {
  DASHBOARD = 'DASHBOARD',
  APARTMENTS = 'APARTMENTS',
  BUDGETS = 'BUDGETS',
  SETTINGS = 'SETTINGS',
  EMPLOYEES = 'EMPLOYEES'
}

export type UserRole = 'ROUPARIA' | 'GERENCIA' | 'DIRETORIA';

export interface User {
  role: UserRole;
  hotel?: HotelType;
}

export type HotelType = 'VILLAGE' | 'GOLDEN_PARK' | 'THERMAL_RESORT';

export interface HotelTheme {
  primary: string;
  secondary: string;
  accent: string;
  bg: string;
  text: string;
  chartColors: string[];
}

export interface Defect {
  id: string;
  driveLink: string;
  description: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface MaterialItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
}

export interface BudgetItem {
  id: string;
  description: string;
  materials: MaterialItem[];
  laborCost: number;
  estimatedTime: string;
}

export interface BudgetFile {
  id: string;
  driveLink: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface Quote {
  id: string;
  supplier: string;
  value: number;
  files: BudgetFile[];
}

export interface Budget {
  id: string;
  title: string;
  objective: string;
  items: BudgetItem[];
  quotes: Quote[];
  status: 'Pendente' | 'Aprovado' | 'Rejeitado';
  createdAt: number;
}

export interface UniformItem {
  name: string;
  quantity: number;
}

export interface Sector {
  id: string;
  name: string;
  standardUniform: UniformItem[];
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  contact: string;
  startDate: string;
  salary: number;
  department: string; // Mantido por compatibilidade, mas usaremos sectorId preferencialmente
  sectorId: string;
  status: 'Ativo' | 'Inativo';
  scheduleType: '6x1' | '12x36' | 'Intermitente';
  shiftType?: 'Par' | 'Ímpar';
  workingHours: string;
  weeklyDayOff: string;
  monthlySundayOff: string;
  vacationStatus: 'Pendente' | 'Concedida';
  uniforms: UniformItem[];
}

export interface Integration {
  id: string;
  name: string;
  type: 'Spreadsheet' | 'ExternalAPI';
  status: 'Connected' | 'Disconnected' | 'Pending';
  lastSync?: number;
  url?: string;
}

export interface BedConfig {
  type: 'Casal' | 'Solteiro';
  baseStatus?: 'Nova' | 'Antiga';
  baseColor?: string;
  mattressStatus?: 'Novo' | 'Antigo';
  mattressColor?: string;
  hasSkirt?: boolean;
  skirtColor?: string;
}

export interface Apartment {
  id: string;
  floor: number;
  roomNumber: number;
  defects: Defect[];
  pisoType?: 'Granito' | 'Madeira' | 'Cerâmica';
  pisoStatus?: 'Bom estado' | 'Tolerável' | 'Reparo urgente';
  banheiroType?: 'Reformado' | 'Antigo';
  banheiroStatus?: 'Tolerável' | 'Reparo urgente';
  temCofre?: boolean;
  temCortina?: boolean;
  cortinaStatus?: 'Nova' | 'Antiga';
  cortinaSize?: string;
  cortinaCoverage?: 'Dois lados' | 'Um lado';
  temEspelhoCorpo?: boolean;
  espelhoCorpoStatus?: 'Bom estado' | 'Manchado' | 'Danificado';
  acBrand?: 'Midea' | 'LG' | 'Grey';
  moveisStatus?: 'Bom estado' | 'Danificado';
  moveisDetalhes?: string[];
  beds?: BedConfig[];
  temPortaControle?: boolean;
  temCabide?: boolean;
  cabideQuantity?: number;
  temSuportePapel?: boolean;
  temSuporteShampoo?: boolean;
  suporteShampooStatus?: 'Bom estado' | 'Enferrujado';
  luminariaType?: 'Arandela' | 'Vidro' | 'Quadrado';
  luminariaColor?: 'Branco' | 'Preto';
  tvBrand?: 'LG' | 'Samsung' | 'Philco' | 'Smart Roku' | 'Toshiba';
}

export interface HotelData {
  apartments: Record<string, Apartment>;
  budgets: Budget[];
  employees: Employee[];
  sectors: Sector[];
}

export interface AppState {
  currentView: ViewType;
  currentHotel: HotelType;
  hotels: Record<HotelType, HotelData>;
  selectedFloor: number | null;
  selectedApartmentId: string | null;
  selectedSectorId: string | null;
  integrations: Integration[];
  currentUser: User | null;
}

import React, { useState, useEffect, useMemo } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';
import { LogOut } from 'lucide-react';

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
});

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v8');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { id: 'global-sync', name: 'Integração Global (Tabelas e Drive)', type: 'Spreadsheet', status: 'Disconnected', lastSync: Date.now() },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE':
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
      case 'GOLDEN_PARK':
        return {
          primary: '#BF984E',
          secondary: '#A68444',
          accent: '#A67A44',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6']
        };
      case 'THERMAL_RESORT':
        return {
          primary: '#68A672',
          secondary: '#4B94F2',
          accent: '#B49B5D',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D']
        };
      default:
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
    }
  }, [state.currentHotel]);

  useEffect(() => {
    const stateToSave = { ...state, currentUser: null };
    localStorage.setItem('hotel_village_state_v8', JSON.stringify(stateToSave));
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({
      ...prev,
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'ROUPARIA' ? ViewType.APARTMENTS : ViewType.DASHBOARD
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setHotel = (hotel: HotelType) => {
    if (state.currentUser?.role !== 'DIRETORIA') return;
    setState(prev => ({ ...prev, currentHotel: hotel, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setView = (view: ViewType) => {
    if (state.currentUser?.role === 'ROUPARIA' && view !== ViewType.APARTMENTS) return;
    setState(prev => ({ ...prev, currentView: view, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const selectFloor = (floor: number) => {
    setState(prev => ({ ...prev, selectedFloor: floor }));
  };

  const selectApartment = (id: string | null) => {
    setState(prev => ({ ...prev, selectedApartmentId: id }));
  };

  const selectSector = (id: string | null) => {
    setState(prev => ({ ...prev, selectedSectorId: id }));
  };

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR', data: any, files?: any[]) => {
    const integration = state.integrations[0];
    if (integration?.url && integration.status === 'Connected') {
      try {
        await fetch(integration.url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ dataType, ...data, newFiles: files })
        });
      } catch (err) {
        console.error('Falha na sincronização:', err);
      }
    }
  };

  const updateApartment = (apt: Apartment) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          apartments: {
            ...prev.hotels[prev.currentHotel].apartments,
            [apt.id]: apt
          }
        }
      }
    }));
    syncToSheet('APARTMENT', apt);
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.budgets.find(b => b.id === budget.id);
      const newBudgets = exists 
        ? hotel.budgets.map(b => b.id === budget.id ? budget : b)
        : [budget, ...hotel.budgets];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: newBudgets }
        }
      };
    });
    syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: hotel.budgets.filter(b => b.id !== id) }
        }
      };
    });
  };

  const handleSaveEmployee = (employee: Employee) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.employees.find(e => e.id === employee.id);
      const newEmployees = exists 
        ? hotel.employees.map(e => e.id === employee.id ? employee : e)
        : [employee, ...hotel.employees];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: newEmployees }
        }
      };
    });
    syncToSheet('EMPLOYEE', employee);
  };

  const handleDeleteEmployee = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: hotel.employees.filter(e => e.id !== id) }
        }
      };
    });
  };

  const handleSaveSector = (sector: Sector) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.sectors.find(s => s.id === sector.id);
      const newSectors = exists 
        ? hotel.sectors.map(s => s.id === sector.id ? sector : s)
        : [...hotel.sectors, sector];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, sectors: newSectors }
        }
      };
    });
    syncToSheet('SECTOR', sector);
  };

  const handleDeleteSector = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { 
            ...hotel, 
            sectors: hotel.sectors.filter(s => s.id !== id),
            employees: hotel.employees.filter(e => e.sectorId !== id)
          }
        }
      };
    });
  };

  const updateIntegration = (integration: Integration) => {
    setState(prev => ({
      ...prev,
      integrations: prev.integrations.map(i => i.id === integration.id ? integration : i)
    }));
  };

  const getHotelName = (type: HotelType) => {
    switch(type) {
      case 'VILLAGE': return 'Village Inn';
      case 'GOLDEN_PARK': return 'Hotel Golden Park';
      case 'THERMAL_RESORT': return 'Thermas Resort';
      default: return 'Hotel';
    }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || {
          id: aptId,
          floor: parseInt(aptId.split('-')[0]),
          roomNumber: parseInt(aptId.split('-')[1]),
          defects: []
        };
        const aptIntegration = state.integrations[0]?.url;
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme}
            integrationUrl={aptIntegration}
            onBack={() => selectApartment(null)} 
            onSave={updateApartment} 
          />
        );
      }

      if (state.selectedFloor !== null) {
        return (
          <FloorDetailView 
            floor={state.selectedFloor} 
            theme={theme}
            apartments={currentHotelData.apartments}
            onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))}
            onSelectApartment={selectApartment}
          />
        );
      }
      return <ApartmentsView onSelectFloor={selectFloor} theme={theme} hotelName={getHotelName(state.currentHotel)} />;
    }

    if (state.currentView === ViewType.BUDGETS) {
      return (
        <BudgetsView 
          budgets={currentHotelData.budgets} 
          theme={theme}
          onSave={handleSaveBudget} 
          onDelete={handleDeleteBudget}
        />
      );
    }

    if (state.currentView === ViewType.EMPLOYEES) {
      return (
        <EmployeesView 
          employees={currentHotelData.employees}
          sectors={currentHotelData.sectors}
          selectedSectorId={state.selectedSectorId}
          onSelectSector={selectSector}
          theme={theme}
          onSave={handleSaveEmployee}
          onDelete={handleDeleteEmployee}
          onSaveSector={handleSaveSector}
          onDeleteSector={handleDeleteSector}
        />
      );
    }

    if (state.currentView === ViewType.SETTINGS) {
      return (
        <SettingsView 
          integrations={state.integrations}
          theme={theme}
          onUpdate={updateIntegration}
        />
      );
    }

    if (state.currentView === ViewType.DASHBOARD) {
      return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} />;
    }

    return null;
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  const isFullscreenView = state.currentView === ViewType.APARTMENTS && state.selectedApartmentId;

  const getHeaderTitle = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      return state.selectedFloor ? `Andar ${state.selectedFloor}` : 'Apartamentos';
    }
    if (state.currentView === ViewType.BUDGETS) return 'Orçamentos';
    if (state.currentView === ViewType.EMPLOYEES) {
        if (state.selectedSectorId) {
            const sector = currentHotelData.sectors.find(s => s.id === state.selectedSectorId);
            return `Equipe: ${sector?.name || 'Setor'}`;
        }
        return 'Setores da Equipe';
    }
    if (state.currentView === ViewType.SETTINGS) return 'Configurações';
    if (state.currentView === ViewType.DASHBOARD) return 'Dashboard';
    return state.currentView;
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      {!isFullscreenView && (
        <>
          <Sidebar 
            currentView={state.currentView} 
            onViewChange={setView} 
            currentHotel={state.currentHotel}
            onHotelChange={setHotel}
            onLogout={handleLogout}
            theme={theme}
            role={state.currentUser.role}
          />
          <BottomNav 
            currentView={state.currentView}
            onViewChange={setView}
            theme={theme}
            role={state.currentUser.role}
          />
        </>
      )}

      <main className={`flex-1 transition-all duration-300 
        ${isFullscreenView ? 'p-0' : 'p-4 md:p-8'} 
        ${!isFullscreenView ? 'mb-20 md:mb-0 md:ml-64' : 'ml-0'}`}>

        {!isFullscreenView && (
          <header className="mb-6 flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm md:bg-transparent md:p-0 md:shadow-none md:mb-8">
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 md:hidden">
                {getHotelName(state.currentHotel)}
              </span>
              <h1 className="text-xl md:text-3xl font-black text-slate-800 leading-tight">
                {getHeaderTitle()}
              </h1>
            </div>

            <div className="flex items-center">
              <button 
                onClick={handleLogout}
                className="flex items-center space-x-3 hover:bg-slate-50 p-2 md:p-3 rounded-2xl transition-all active:scale-95 group"
                title="Sair da Conta"
              >
                <div className="text-right hidden sm:block">
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 group-hover:text-red-500 transition-colors">
                    {state.currentUser.role}
                  </p>
                  <p className="text-[9px] font-bold text-red-500 uppercase opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-end">
                    <LogOut size={10} className="mr-1" /> Encerrar
                  </p>
                  <p className="text-xs font-bold group-hover:opacity-0 transition-opacity" style={{ color: theme.primary }}>Online</p>
                </div>
                <div 
                  className="w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg group-hover:shadow-red-200 transition-all relative"
                  style={{ backgroundColor: theme.primary, boxShadow: `0 8px 12px -3px ${theme.primary}40` }}
                >
                  {state.currentUser.role[0]}
                  <div className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity border-2 border-white">
                    <LogOut size={10} />
                  </div>
                </div>
              </button>
            </div>
          </header>
        )}

        <div className="animate-in fade-in duration-500">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Employee, HotelTheme, Sector, UniformItem } from '../types';
import { 
  Search, 
  UserPlus, 
  Phone, 
  Calendar, 
  DollarSign, 
  UserCheck, 
  Trash2, 
  Briefcase, 
  Building2,
  X,
  Plus,
  Clock,
  Sun,
  Umbrella,
  AlertTriangle,
  CheckCircle2,
  CalendarDays,
  Activity,
  Layers,
  ChevronLeft,
  Settings,
  Shirt,
  Edit2,
  Package,
  ArrowRight
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee) => void;
  onDelete: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [editingSector, setEditingSector] = useState<Sector | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'DADOS' | 'UNIFORMES'>('DADOS');

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [weeklyDayOff, setWeeklyDayOff] = useState('Segunda-feira');
  const [monthlySundayOff, setMonthlySundayOff] = useState('1º Domingo');
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Form State Sector
  const [sectorName, setSectorName] = useState('');
  const [standardUniforms, setStandardUniforms] = useState<UniformItem[]>([]);

  const resetEmployeeForm = () => {
    setName('');
    setRole('');
    setContact('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setSalary('');
    setUniforms([]);
    setScheduleType('6x1');
    setShiftType('Par');
    setWorkingHours('08:00 - 16:20');
    setWeeklyDayOff('Segunda-feira');
    setMonthlySundayOff('1º Domingo');
    setVacationStatus('Pendente');
    setIsAddingEmployee(false);
    setEditingEmployee(null);
    setActiveTab('DADOS');
  };

  const resetSectorForm = () => {
    setSectorName('');
    setStandardUniforms([]);
    setIsAddingSector(false);
    setEditingSector(null);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name);
    setRole(emp.role);
    setContact(emp.contact);
    setStartDate(emp.startDate);
    setSalary(emp.salary.toString());
    setUniforms(emp.uniforms || []);
    setScheduleType(emp.scheduleType);
    setShiftType(emp.shiftType || 'Par');
    setWorkingHours(emp.workingHours);
    setWeeklyDayOff(emp.weeklyDayOff);
    setMonthlySundayOff(emp.monthlySundayOff);
    setVacationStatus(emp.vacationStatus);
    setIsAddingEmployee(true);
  };

  const handleEditSector = (e: React.MouseEvent, sec: Sector) => {
    e.stopPropagation();
    setEditingSector(sec);
    setSectorName(sec.name);
    setStandardUniforms(sec.standardUniform || []);
    setIsAddingSector(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !selectedSectorId) return;

    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name,
      role,
      contact,
      startDate,
      salary: parseFloat(salary) || 0,
      department: sectors.find(s => s.id === selectedSectorId)?.name || '',
      sectorId: selectedSectorId,
      status: 'Ativo',
      scheduleType,
      shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours,
      weeklyDayOff,
      monthlySundayOff,
      vacationStatus,
      uniforms
    };

    onSave(newEmp);
    resetEmployeeForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!sectorName) return;

    const newSec: Sector = {
      id: editingSector?.id || Date.now().toString(),
      name: sectorName,
      standardUniform: standardUniforms
    };

    onSaveSector(newSec);
    resetSectorForm();
  };

  const addUniformItem = (type: 'STANDARD' | 'EMPLOYEE') => {
    if (type === 'STANDARD') {
      setStandardUniforms([...standardUniforms, { name: '', quantity: 1 }]);
    } else {
      setUniforms([...uniforms, { name: '', quantity: 1 }]);
    }
  };

  const updateUniformItem = (type: 'STANDARD' | 'EMPLOYEE', idx: number, field: keyof UniformItem, val: any) => {
    if (type === 'STANDARD') {
      const next = [...standardUniforms];
      next[idx] = { ...next[idx], [field]: val };
      setStandardUniforms(next);
    } else {
      const next = [...uniforms];
      next[idx] = { ...next[idx], [field]: val };
      setUniforms(next);
    }
  };

  const removeUniformItem = (type: 'STANDARD' | 'EMPLOYEE', idx: number) => {
    if (type === 'STANDARD') {
      setStandardUniforms(standardUniforms.filter((_, i) => i !== idx));
    } else {
      setUniforms(uniforms.filter((_, i) => i !== idx));
    }
  };

  const filteredEmployees = employees.filter(e => e.sectorId === selectedSectorId && e.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  const calculateDiscrepancy = (emp: Employee, sec: Sector) => {
    return (sec.standardUniform || []).map(std => {
      const has = (emp.uniforms || []).find(u => u.name.toLowerCase() === std.name.toLowerCase());
      const missing = Math.max(0, std.quantity - (has?.quantity || 0));
      return { name: std.name, needed: std.quantity, has: has?.quantity || 0, missing };
    }).filter(d => d.missing > 0);
  };

  if (!selectedSectorId) {
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="flex justify-between items-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Selecione um Setor para gerenciar a equipe</p>
          <button 
            onClick={() => setIsAddingSector(true)}
            className="text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
            style={{ backgroundColor: theme.primary }}
          >
            <Plus size={18} />
            <span>Novo Setor</span>
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {sectors.map((sec) => (
            <button
              key={sec.id}
              onClick={() => onSelectSector(sec.id)}
              className="group relative bg-white h-48 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all duration-300 flex flex-col items-center justify-center border border-slate-50 overflow-hidden transform active:scale-95"
            >
              <div className="absolute top-0 left-0 w-full h-1.5 transition-all duration-300" style={{ backgroundColor: theme.primary }}></div>
              <div 
                className="p-6 rounded-2xl mb-4 group-hover:scale-110 transition-transform duration-300"
                style={{ backgroundColor: theme.primary + '10', color: theme.primary }}
              >
                <Building2 size={32} strokeWidth={1.5} />
              </div>
              <div className="text-center">
                <h3 className="text-xl font-black text-slate-800">{sec.name}</h3>
                <p className="text-slate-400 mt-1 font-black uppercase tracking-[0.2em] text-[9px]">
                  {employees.filter(e => e.sectorId === sec.id).length} Funcionários
                </p>
              </div>

              <div className="absolute top-4 right-4 flex space-x-2">
                <button 
                  onClick={(e) => handleEditSector(e, sec)}
                  className="p-2 bg-slate-50 text-slate-400 hover:text-blue-500 rounded-full transition-colors border"
                >
                  <Edit2 size={14} />
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); onDeleteSector(sec.id); }}
                  className="p-2 bg-slate-50 text-slate-400 hover:text-red-500 rounded-full transition-colors border"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </button>
          ))}
          {sectors.length === 0 && (
            <div className="col-span-full py-20 text-center text-slate-300 italic font-bold">Nenhum setor cadastrado.</div>
          )}
        </div>

        {isAddingSector && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
               <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                  <h2 className="text-xl font-black text-slate-800">{editingSector ? 'Editar Setor' : 'Novo Setor'}</h2>
                  <button onClick={resetSectorForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
               </div>
               <form onSubmit={handleSaveSectorSubmit} className="p-8 space-y-6">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Nome do Setor</label>
                    <input type="text" value={sectorName} onChange={e => setSectorName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none font-bold text-slate-800 bg-white" placeholder="Ex: Recepção" />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-3">
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Enxoval de Uniforme Padrão</label>
                      <button type="button" onClick={() => addUniformItem('STANDARD')} className="text-[8px] font-black text-emerald-600 uppercase">+ Adicionar Peça</button>
                    </div>
                    <div className="space-y-2 max-h-40 overflow-y-auto pr-2">
                       {standardUniforms.map((item, idx) => (
                         <div key={idx} className="flex gap-2 animate-in slide-in-from-left-2">
                           <input type="text" placeholder="Peça" value={item.name} onChange={e => updateUniformItem('STANDARD', idx, 'name', e.target.value)} className="flex-1 px-3 py-2 rounded-lg border bg-white text-[10px] font-bold" />
                           <input type="number" placeholder="Qtd" value={item.quantity} onChange={e => updateUniformItem('STANDARD', idx, 'quantity', parseInt(e.target.value))} className="w-16 px-3 py-2 rounded-lg border bg-white text-[10px] font-bold" />
                           <button type="button" onClick={() => removeUniformItem('STANDARD', idx)} className="text-rose-300 hover:text-rose-500"><Trash2 size={14}/></button>
                         </div>
                       ))}
                       {standardUniforms.length === 0 && <p className="text-[9px] text-slate-300 text-center py-4 italic border-2 border-dashed rounded-xl">Defina as peças que o funcionário deste setor deve ter.</p>}
                    </div>
                  </div>
                  <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all" style={{ backgroundColor: theme.primary }}>Salvar Configuração de Setor</button>
               </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="flex items-center space-x-3">
          <button onClick={() => onSelectSector(null)} className="p-2 bg-white rounded-xl shadow-sm text-slate-400 hover:text-slate-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-800">{currentSector?.name}</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase">{filteredEmployees.length} Funcionários registrados</p>
          </div>
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input 
              type="text"
              placeholder="Buscar por nome..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 focus:border-blue-500 outline-none shadow-sm transition-all text-sm font-bold bg-white"
            />
          </div>
          <button 
            onClick={() => setIsAddingEmployee(true)}
            className="text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
            style={{ backgroundColor: theme.primary }}
          >
            <UserPlus size={18} />
            <span className="hidden sm:inline">Adicionar Funcionário</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {filteredEmployees.map(emp => {
          const discrepancies = currentSector ? calculateDiscrepancy(emp, currentSector) : [];
          return (
            <div key={emp.id} className="bg-white rounded-[2rem] border border-slate-100 shadow-sm p-6 flex flex-col md:flex-row gap-6 hover:shadow-md transition-all">
              <div className="flex items-center space-x-4 min-w-[200px]">
                <div className="w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg" style={{ backgroundColor: theme.primary }}>
                  {(emp.name || "U")[0]}
                </div>
                <div>
                  <h4 className="font-black text-slate-800 leading-tight">{emp.name}</h4>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">{emp.role}</p>
                </div>
              </div>

              <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-4 border-t md:border-t-0 md:border-l border-slate-50 pt-4 md:pt-0 md:pl-6">
                <div>
                  <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Horário & Escala</p>
                  <div className="flex items-center text-xs font-black text-slate-900">
                    <Clock size={12} className="mr-1.5 text-slate-300" />
                    {emp.scheduleType} {emp.shiftType && `(${emp.shiftType})`}
                  </div>
                  <div className="flex items-center text-[10px] font-bold text-slate-500 mt-1">{emp.workingHours}</div>
                </div>
                <div>
                  <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Uniformes Cadastrados</p>
                  <div className="flex items-center text-xs font-bold text-slate-700">
                    <Shirt size={12} className="mr-1.5 text-slate-300" />
                    {emp.uniforms?.reduce((acc, u) => acc + u.quantity, 0) || 0} Peças no total
                  </div>
                </div>
                <div className="col-span-2">
                  <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Status Enxoval (Discrepância)</p>
                  {discrepancies.length > 0 ? (
                    <div className="flex flex-wrap gap-1.5">
                      {discrepancies.map((d, di) => (
                        <div key={di} className="px-2 py-0.5 bg-rose-50 border border-rose-100 text-rose-600 rounded-lg text-[8px] font-black uppercase flex items-center">
                          <AlertTriangle size={8} className="mr-1" /> Faltam {d.missing} {d.name}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="flex items-center text-emerald-500 text-[9px] font-black uppercase">
                      <CheckCircle2 size={12} className="mr-1.5" /> Enxoval Completo
                    </div>
                  )}
                </div>
              </div>

              <div className="flex items-center justify-end space-x-2">
                <button onClick={() => handleEditEmployee(emp)} className="p-3 text-slate-300 hover:text-blue-500 transition-colors bg-slate-50 rounded-xl">
                  <Edit2 size={20} />
                </button>
                <button onClick={() => onDelete(emp.id)} className="p-3 text-slate-300 hover:text-rose-500 transition-colors bg-slate-50 rounded-xl">
                  <Trash2 size={20} />
                </button>
              </div>
            </div>
          );
        })}
        {filteredEmployees.length === 0 && (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-100 flex flex-col items-center justify-center text-slate-300">
             <Package size={64} className="mb-4 opacity-10" />
             <p className="text-xl font-black italic uppercase tracking-tighter">Nenhum funcionário neste setor</p>
          </div>
        )}
      </div>

      {isAddingEmployee && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl max-h-[90vh] overflow-hidden flex flex-col animate-in zoom-in duration-200">
             <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">{editingEmployee ? 'Editar Funcionário' : 'Novo Funcionário'}</h2>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Setor: {currentSector?.name}</p>
                </div>
                <button onClick={resetEmployeeForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
             </div>

             <div className="flex bg-slate-50 p-2 mx-8 mt-6 rounded-2xl border border-slate-100">
                <button onClick={() => setActiveTab('DADOS')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'DADOS' ? 'bg-white shadow-md text-blue-600' : 'text-slate-400'}`}>Dados Pessoais & Escala</button>
                <button onClick={() => setActiveTab('UNIFORMES')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'UNIFORMES' ? 'bg-white shadow-md text-blue-600' : 'text-slate-400'}`}>Uniformes (Enxoval)</button>
             </div>

             <form onSubmit={handleSaveEmployeeSubmit} className="flex-1 overflow-y-auto p-8 space-y-8">
                {activeTab === 'DADOS' ? (
                  <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="col-span-1 md:col-span-2">
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Nome Completo</label>
                        <input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Cargo</label>
                        <input required type="text" value={role} onChange={e => setRole(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Data de Início</label>
                        <input required type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Salário (R$)</label>
                        <input required type="number" step="0.01" value={salary} onChange={e => setSalary(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Tipo de Escala</label>
                        <select value={scheduleType} onChange={e => setScheduleType(e.target.value as any)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold text-slate-800 outline-none">
                          <option value="6x1">6x1</option>
                          <option value="12x36">12x36</option>
                          <option value="Intermitente">Intermitente</option>
                        </select>
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                    <div className="bg-blue-50/50 p-6 rounded-[2rem] border border-blue-100">
                       <h4 className="text-[10px] font-black text-blue-700 uppercase tracking-widest flex items-center mb-4">
                         <Package size={14} className="mr-2" /> O que o funcionário já possui:
                       </h4>
                       <div className="space-y-3">
                          {uniforms.map((u, ui) => (
                            <div key={ui} className="flex gap-2">
                              <input type="text" placeholder="Peça (Ex: Camisa P)" value={u.name} onChange={e => updateUniformItem('EMPLOYEE', ui, 'name', e.target.value)} className="flex-1 px-4 py-3 rounded-xl border bg-white text-xs font-bold" />
                              <input type="number" placeholder="Qtd" value={u.quantity} onChange={e => updateUniformItem('EMPLOYEE', ui, 'quantity', parseInt(e.target.value))} className="w-20 px-4 py-3 rounded-xl border bg-white text-xs font-bold" />
                              <button type="button" onClick={() => removeUniformItem('EMPLOYEE', ui)} className="text-rose-300 hover:text-rose-500"><Trash2 size={18}/></button>
                            </div>
                          ))}
                          <button type="button" onClick={() => addUniformItem('EMPLOYEE')} className="w-full py-3 border-2 border-dashed border-blue-200 rounded-xl text-blue-400 text-[10px] font-black uppercase hover:bg-white transition-all">+ Adicionar Item de Uniforme</button>
                       </div>
                    </div>

                    <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                       <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center mb-4">
                         <Info size={14} className="mr-2" /> Padrão do Setor:
                       </h4>
                       <div className="flex flex-wrap gap-2">
                          {currentSector?.standardUniform?.map((std, si) => (
                            <div key={si} className="bg-white px-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold text-slate-600">
                              {std.quantity}x {std.name}
                            </div>
                          ))}
                          {(!currentSector?.standardUniform || currentSector?.standardUniform.length === 0) && (
                            <p className="text-[9px] text-slate-300 italic">Nenhum uniforme padrão configurado para este setor.</p>
                          )}
                       </div>
                    </div>
                  </div>
                )}

                <div className="flex gap-4 pt-4">
                   <button type="button" onClick={resetEmployeeForm} className="flex-1 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">Cancelar</button>
                   <button type="submit" className="flex-1 py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all" style={{ backgroundColor: theme.primary }}>
                     {editingEmployee ? 'Salvar Alterações' : 'Cadastrar Funcionário'}
                   </button>
                </div>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeesView;

import React, { useState, useRef } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  DollarSign, 
  Briefcase,
  ChevronDown,
  ChevronUp,
  X,
  CheckCircle,
  Clock,
  AlertCircle,
  Paperclip,
  FileText,
  File,
  Image as ImageIcon,
  Download,
  Eye,
  Info,
  ChevronRight,
  Trophy,
  TrendingDown,
  Layers,
  Wrench,
  Package,
  Calendar
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentQuoteIndexRef = useRef<number | null>(null);

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...item.materials, { id: Date.now().toString(), name: '', quantity: 1, price: 0 }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: item.materials.filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  const updateQuote = (index: number, field: keyof Quote, value: any) => {
    const newQuotes = [...quotes];
    newQuotes[index] = { ...newQuotes[index], [field]: value };
    setQuotes(newQuotes);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // As per request, making fields optional
    const finalBudget: Budget = {
      id: Date.now().toString(),
      title: title || 'Novo Orçamento sem Título',
      objective,
      items,
      quotes: (quotes as Quote[]).filter(q => q.supplier || q.value > 0), // Filter empty quotes
      status,
      createdAt: Date.now()
    };

    // Ensure at least one quote placeholder if all were empty
    if (finalBudget.quotes.length === 0) {
      finalBudget.quotes = [{ id: 'empty', supplier: 'Não Informado', value: 0, files: [] }];
    }

    const allFilesForSync: {data: string, mimeType: string, fileName: string}[] = [];
    quotes.forEach(q => {
      q.files?.forEach(f => {
        if (f.data) {
          allFilesForSync.push({ data: f.data, mimeType: f.fileType!, fileName: f.fileName! });
        }
      });
    });

    onSave(finalBudget, allFilesForSync);
    resetForm();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const quoteIndex = currentQuoteIndexRef.current;
    if (file && quoteIndex !== null) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = reader.result?.toString().split(',')[1] || '';
        const newBudgetFile: BudgetFile = {
          id: Date.now().toString(),
          driveLink: 'pendente',
          timestamp: Date.now(),
          fileName: file.name,
          fileType: file.type,
          data: base64Data
        };
        const newQuotes = [...quotes];
        newQuotes[quoteIndex].files = [...(newQuotes[quoteIndex].files || []), newBudgetFile];
        setQuotes(newQuotes);
        if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsDataURL(file);
    }
  };

  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500';
      default: return 'bg-amber-400 text-slate-800 border-amber-400';
    }
  };

  const calculateSubtotal = (item: BudgetItem) => {
    const materialsTotal = item.materials.reduce((acc, m) => acc + (m.quantity * m.price), 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Buscar orçamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:border-blue-500 outline-none shadow-sm transition-all bg-white text-slate-800"
          />
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
          style={{ backgroundColor: theme.primary, boxShadow: `0 10px 15px -3px ${theme.primary}40` }}
        >
          <Plus size={20} />
          <span>Novo Orçamento</span>
        </button>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">Criação de Novo Orçamento</h2>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Detalhamento técnico e financeiro</p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-10">
                {/* DADOS GERAIS */}
                <section className="space-y-6">
                   <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                     <Info size={14} className="mr-2" /> Informações do Projeto
                   </h3>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="col-span-2">
                      <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Título do Orçamento</label>
                      <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma Banheiro Apto 205" className="w-full px-5 py-4 rounded-2xl border-2 border-slate-100 focus:border-blue-400 outline-none transition-all bg-white font-bold text-slate-800" />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Objetivo da Obra / Serviço</label>
                      <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Descreva o propósito geral..." className="w-full px-5 py-4 rounded-2xl border-2 border-slate-100 focus:border-blue-400 outline-none transition-all h-24 bg-white font-bold text-slate-800" />
                    </div>
                  </div>
                </section>

                {/* DETALHAMENTO DE ITENS */}
                <section className="space-y-6">
                  <div className="flex justify-between items-center">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                      <Layers size={14} className="mr-2" /> O que será feito (Itens do Serviço)
                    </h3>
                    <button type="button" onClick={addServiceItem} className="flex items-center space-x-2 text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-100">
                      <Plus size={12} /> <span>Adicionar Item</span>
                    </button>
                  </div>

                  <div className="space-y-6">
                    {items.map((item, idx) => (
                      <div key={item.id} className="p-6 bg-white rounded-3xl border border-slate-200 relative animate-in slide-in-from-top-4 shadow-sm">
                        <button type="button" onClick={() => removeServiceItem(item.id)} className="absolute top-4 right-4 text-slate-300 hover:text-rose-500"><Trash2 size={16}/></button>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                          <div className="md:col-span-3">
                            <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5">Descrição do Serviço / Local</label>
                            <input type="text" value={item.description} onChange={(e) => updateItem(item.id, 'description', e.target.value)} placeholder="Ex: Troca de revestimento e louças sanitárias" className="w-full px-4 py-3 rounded-xl border border-slate-200 outline-none focus:border-blue-300 bg-white text-sm font-bold" />
                          </div>

                          <div className="space-y-4 md:col-span-2">
                            <div className="flex justify-between items-center">
                              <label className="block text-[9px] font-black text-slate-400 uppercase">Materiais Necessários</label>
                              <button type="button" onClick={() => addMaterial(item.id)} className="text-[8px] font-black text-emerald-600 bg-white border border-emerald-100 px-2 py-1 rounded shadow-sm">+ Material</button>
                            </div>
                            <div className="space-y-2">
                              {item.materials.map(mat => (
                                <div key={mat.id} className="flex items-center gap-2 animate-in slide-in-from-left-2">
                                  <input type="text" placeholder="Material" value={mat.name} onChange={e => updateMaterial(item.id, mat.id, 'name', e.target.value)} className="flex-1 px-3 py-2 rounded-lg border border-slate-100 bg-white text-[10px] font-bold" />
                                  <input type="number" placeholder="Qtd" value={mat.quantity} onChange={e => updateMaterial(item.id, mat.id, 'quantity', parseFloat(e.target.value))} className="w-16 px-3 py-2 rounded-lg border border-slate-100 bg-white text-[10px] font-bold" />
                                  <input type="number" step="0.01" placeholder="R$ Unit" value={mat.price} onChange={e => updateMaterial(item.id, mat.id, 'price', parseFloat(e.target.value))} className="w-24 px-3 py-2 rounded-lg border border-slate-100 bg-white text-[10px] font-bold" />
                                  <button type="button" onClick={() => removeMaterial(item.id, mat.id)} className="text-rose-300 hover:text-rose-500"><Trash2 size={14}/></button>
                                </div>
                              ))}
                              {item.materials.length === 0 && <p className="text-[9px] text-slate-400 italic text-center py-2 bg-slate-50 rounded-lg border-2 border-dashed">Nenhum material listado.</p>}
                            </div>
                          </div>

                          <div className="space-y-4">
                            <div>
                               <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 flex items-center"><Wrench size={10} className="mr-1"/> Valor Mão de Obra</label>
                               <input type="number" step="0.01" value={item.laborCost || ''} onChange={e => updateItem(item.id, 'laborCost', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                            </div>
                            <div>
                               <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 flex items-center"><Calendar size={10} className="mr-1"/> Tempo Estimado</label>
                               <input type="text" placeholder="Ex: 3 dias" value={item.estimatedTime} onChange={e => updateItem(item.id, 'estimatedTime', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                            </div>
                            <div className="pt-4 border-t border-slate-100">
                               <p className="text-[8px] font-black text-slate-400 uppercase">Subtotal do Item</p>
                               <p className="text-lg font-black text-slate-800">R$ {calculateSubtotal(item).toLocaleString('pt-BR')}</p>
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>

                {/* FORNECEDORES (QUADRO COMPARATIVO) */}
                <section className="space-y-6">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
                    <TrendingDown size={14} className="mr-2" /> Quadro de Cotações Externas
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {quotes.map((quote, idx) => (
                      <div key={quote.id} className="p-6 bg-white rounded-[2rem] border border-slate-100 flex flex-col shadow-sm">
                        <span className="text-[9px] font-black text-slate-400 uppercase mb-3">Opção Fornecedor {idx + 1}</span>
                        <div className="space-y-4">
                           <input type="text" value={quote.supplier} onChange={(e) => updateQuote(idx, 'supplier', e.target.value)} placeholder="Empresa / Profissional" className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                           <div className="relative">
                             <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14}/>
                             <input type="number" step="0.01" value={quote.value || ''} onChange={(e) => updateQuote(idx, 'value', parseFloat(e.target.value))} placeholder="Valor Global" className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold" />
                           </div>
                           <button type="button" onClick={() => { currentQuoteIndexRef.current = idx; fileInputRef.current?.click(); }} className="w-full py-2.5 border-2 border-dashed border-slate-100 rounded-xl text-slate-400 hover:text-blue-500 hover:bg-slate-50 transition-all text-[9px] font-black uppercase flex items-center justify-center space-x-2">
                             <Paperclip size={12}/> <span>Anexar PDF/Foto</span>
                           </button>
                           <div className="flex flex-wrap gap-1">
                             {quote.files?.map((f, fi) => (
                               <div key={fi} className="bg-slate-50 border border-slate-100 rounded px-2 py-1 text-[8px] font-bold flex items-center gap-1">
                                 <File size={8}/> {f.fileName}
                               </div>
                             ))}
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>

                <div className="flex gap-4 pt-8 border-t border-slate-50">
                  <button type="button" onClick={resetForm} className="flex-1 py-5 rounded-2xl font-black text-xs text-slate-400 uppercase tracking-widest hover:bg-slate-50">Cancelar</button>
                  <button type="submit" className="flex-1 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl transition-all active:scale-95" style={{ backgroundColor: theme.primary }}>Finalizar Orçamento Detalhado</button>
                </div>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
              </form>
            </div>
          </div>
        </div>
      )}

      {/* LISTAGEM DE ORÇAMENTOS */}
      <div className="grid grid-cols-1 gap-6">
        {filteredBudgets.length === 0 ? (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300">
            <Receipt size={64} className="mb-4 opacity-10" />
            <p className="text-xl font-black italic uppercase tracking-tighter">Nenhum orçamento encontrado</p>
          </div>
        ) : (
          filteredBudgets.map(budget => {
            const minQuoteValue = budget.quotes.length > 0 ? Math.min(...budget.quotes.map(q => q.value)) : 0;

            return (
              <div key={budget.id} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all overflow-hidden">
                <div className="p-6 md:p-8 cursor-pointer" onClick={() => setExpandedId(expandedId === budget.id ? null : budget.id)}>
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center space-x-6">
                      <div className="p-5 bg-slate-50 text-slate-900 rounded-[1.5rem] border border-slate-100">
                        <Receipt size={28} />
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-xl leading-none mb-2">{budget.title}</h4>
                        <div className="flex items-center space-x-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                          <span className="flex items-center"><Layers size={12} className="mr-1" /> {budget.items?.length || 0} Itens</span>
                          <span className="w-1.5 h-1.5 bg-slate-100 rounded-full"></span>
                          <span>{new Date(budget.createdAt).toLocaleDateString('pt-BR')}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between md:justify-end space-x-8">
                      <div className="text-right">
                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Melhor Valor</p>
                        <p className="text-2xl font-black text-emerald-500 leading-none mt-1">R$ {minQuoteValue.toLocaleString('pt-BR')}</p>
                      </div>
                      <div className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase border-2 ${getStatusStyle(budget.status)}`}>
                        {budget.status}
                      </div>
                      {expandedId === budget.id ? <ChevronUp size={24} className="text-slate-300" /> : <ChevronDown size={24} className="text-slate-300" />}
                    </div>
                  </div>
                </div>

                {expandedId === budget.id && (
                  <div className="px-8 pb-10 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 bg-slate-50/30">
                    <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      {/* DETALHES TÉCNICOS */}
                      <div className="lg:col-span-3 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {(budget.items || []).map((item, iIdx) => (
                            <div key={item.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                              <div className="flex justify-between items-start mb-4">
                                <span className="text-[10px] font-black text-blue-500 uppercase">Item {iIdx + 1}</span>
                                <span className="text-[10px] font-bold text-slate-400 flex items-center"><Clock size={10} className="mr-1"/> {item.estimatedTime || 'N/A'}</span>
                              </div>
                              <h6 className="font-black text-slate-800 mb-3">{item.description || 'Sem Descrição'}</h6>
                              <div className="space-y-2 mb-4">
                                {item.materials.map(m => (
                                  <div key={m.id} className="flex justify-between text-[10px] text-slate-600 border-b border-slate-50 pb-1">
                                    <span>{m.quantity}x {m.name}</span>
                                    <span className="font-bold">R$ {(m.quantity * m.price).toLocaleString()}</span>
                                  </div>
                                ))}
                              </div>
                              <div className="flex justify-between items-center text-[10px] font-black uppercase pt-2">
                                <span className="text-slate-400">Mão de Obra</span>
                                <span className="text-slate-800">R$ {(Number(item.laborCost) || 0).toLocaleString()}</span>
                              </div>
                              <div className="flex justify-between items-center text-xs font-black uppercase pt-3 border-t border-slate-100 mt-3">
                                <span className="text-blue-600">Total do Item</span>
                                <span className="text-blue-600">R$ {calculateSubtotal(item).toLocaleString()}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                        {budget.objective && (
                          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                            <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Objetivo do Projeto</h5>
                            <p className="text-sm text-slate-600 font-medium">{budget.objective}</p>
                          </div>
                        )}
                      </div>

                      {/* AÇÕES E COTAÇÕES */}
                      <div className="lg:col-span-1 space-y-4">
                        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
                          <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Ações do Pedido</h5>
                          <button onClick={() => updateStatus(budget, 'Aprovado')} className="w-full py-3 mb-2 rounded-xl bg-emerald-500 text-white font-black text-[10px] uppercase shadow-lg shadow-emerald-100">Aprovar Projeto</button>
                          <button onClick={() => updateStatus(budget, 'Rejeitado')} className="w-full py-3 rounded-xl bg-white border-2 border-rose-100 text-rose-500 font-black text-[10px] uppercase">Rejeitar</button>
                        </div>
                        <button onClick={() => onDelete(budget.id)} className="w-full flex items-center justify-center space-x-2 text-[10px] font-black text-slate-300 hover:text-rose-500 uppercase pt-4">
                          <Trash2 size={16} /> <span>Excluir Orçamento</span>
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default BudgetsView;

import React, { useState, useMemo } from 'react';
import { Employee, HotelTheme, Sector, UniformItem } from '../types';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Building2,
  X,
  Plus,
  Clock,
  AlertTriangle,
  CheckCircle2,
  Layers,
  ChevronLeft,
  Shirt,
  Edit2,
  Package,
  Info
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee) => void;
  onDelete: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [editingSector, setEditingSector] = useState<Sector | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'DADOS' | 'UNIFORMES'>('DADOS');

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [weeklyDayOff, setWeeklyDayOff] = useState('Segunda-feira');
  const [monthlySundayOff, setMonthlySundayOff] = useState('1º Domingo');
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Form State Sector
  const [sectorName, setSectorName] = useState('');
  const [standardUniforms, setStandardUniforms] = useState<UniformItem[]>([]);

  const resetEmployeeForm = () => {
    setName('');
    setRole('');
    setContact('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setSalary('');
    setUniforms([]);
    setScheduleType('6x1');
    setShiftType('Par');
    setWorkingHours('08:00 - 16:20');
    setWeeklyDayOff('Segunda-feira');
    setMonthlySundayOff('1º Domingo');
    setVacationStatus('Pendente');
    setIsAddingEmployee(false);
    setEditingEmployee(null);
    setActiveTab('DADOS');
  };

  const resetSectorForm = () => {
    setSectorName('');
    setStandardUniforms([]);
    setIsAddingSector(false);
    setEditingSector(null);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name);
    setRole(emp.role);
    setContact(emp.contact);
    setStartDate(emp.startDate);
    setSalary(emp.salary.toString());
    setUniforms(emp.uniforms || []);
    setScheduleType(emp.scheduleType);
    setShiftType(emp.shiftType || 'Par');
    setWorkingHours(emp.workingHours);
    setWeeklyDayOff(emp.weeklyDayOff);
    setMonthlySundayOff(emp.monthlySundayOff);
    setVacationStatus(emp.vacationStatus);
    setIsAddingEmployee(true);
  };

  const handleEditSector = (e: React.MouseEvent, sec: Sector) => {
    e.stopPropagation();
    setEditingSector(sec);
    setSectorName(sec.name);
    setStandardUniforms(sec.standardUniform || []);
    setIsAddingSector(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name && !role) { // Non-mandatory logic
       // alert("Pelo menos o nome ou cargo deve ser informado.");
    }

    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Funcionário sem Nome',
      role: role || 'Cargo não informado',
      contact,
      startDate,
      salary: parseFloat(salary) || 0,
      department: sectors.find(s => s.id === selectedSectorId)?.name || '',
      sectorId: selectedSectorId!,
      status: 'Ativo',
      scheduleType,
      shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours,
      weeklyDayOff,
      monthlySundayOff,
      vacationStatus,
      uniforms
    };

    onSave(newEmp);
    resetEmployeeForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!sectorName) return;

    const newSec: Sector = {
      id: editingSector?.id || Date.now().toString(),
      name: sectorName,
      standardUniform: standardUniforms
    };

    onSaveSector(newSec);
    resetSectorForm();
  };

  const addUniformItem = (type: 'STANDARD' | 'EMPLOYEE') => {
    if (type === 'STANDARD') {
      setStandardUniforms([...standardUniforms, { name: '', quantity: 1 }]);
    } else {
      setUniforms([...uniforms, { name: '', quantity: 1 }]);
    }
  };

  const updateUniformItem = (type: 'STANDARD' | 'EMPLOYEE', idx: number, field: keyof UniformItem, val: any) => {
    if (type === 'STANDARD') {
      const next = [...standardUniforms];
      next[idx] = { ...next[idx], [field]: val };
      setStandardUniforms(next);
    } else {
      const next = [...uniforms];
      next[idx] = { ...next[idx], [field]: val };
      setUniforms(next);
    }
  };

  const removeUniformItem = (type: 'STANDARD' | 'EMPLOYEE', idx: number) => {
    if (type === 'STANDARD') {
      setStandardUniforms(standardUniforms.filter((_, i) => i !== idx));
    } else {
      setUniforms(uniforms.filter((_, i) => i !== idx));
    }
  };

  const filteredEmployees = employees.filter(e => e.sectorId === selectedSectorId && e.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  const calculateDiscrepancy = (emp: Employee, sec: Sector) => {
    return (sec.standardUniform || []).map(std => {
      const has = (emp.uniforms || []).find(u => u.name.toLowerCase().trim() === std.name.toLowerCase().trim());
      const missing = Math.max(0, std.quantity - (has?.quantity || 0));
      return { name: std.name, needed: std.quantity, has: has?.quantity || 0, missing };
    }).filter(d => d.missing > 0);
  };

  if (!selectedSectorId) {
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="flex justify-between items-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Escolha o setor para gerenciar</p>
          <button 
            onClick={() => setIsAddingSector(true)}
            className="text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
            style={{ backgroundColor: theme.primary }}
          >
            <Plus size={18} />
            <span>Novo Setor</span>
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
          {sectors.map((sec) => (
            <button
              key={sec.id}
              onClick={() => onSelectSector(sec.id)}
              className="group relative bg-white h-48 md:h-72 rounded-[2.5rem] shadow-sm hover:shadow-2xl transition-all duration-500 flex flex-col items-center justify-center border border-slate-50 overflow-hidden transform active:scale-95 md:hover:-translate-y-2"
            >
              <div className="absolute top-0 left-0 w-full h-1.5 transition-all duration-500" style={{ backgroundColor: theme.primary }}></div>
              <div 
                className="p-5 md:p-8 rounded-2xl md:rounded-3xl mb-3 md:mb-6 group-hover:scale-110 transition-transform duration-500"
                style={{ backgroundColor: theme.primary + '10', color: theme.primary }}
              >
                <Building2 size={32} strokeWidth={1.5} className="md:w-14 md:h-14" />
              </div>
              <div className="text-center">
                <h3 className="text-xl md:text-3xl font-black text-slate-800">{sec.name}</h3>
                <p className="text-slate-400 mt-1 font-black uppercase tracking-[0.2em] text-[8px] md:text-[10px]">
                  {employees.filter(e => e.sectorId === sec.id).length} Colaboradores
                </p>
              </div>

              <div className="absolute top-4 right-4 flex space-x-2">
                <button 
                  onClick={(e) => handleEditSector(e, sec)}
                  className="p-2 bg-white/80 text-slate-400 hover:text-blue-500 rounded-full transition-colors border shadow-sm"
                >
                  <Edit2 size={14} />
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); onDeleteSector(sec.id); }}
                  className="p-2 bg-white/80 text-slate-400 hover:text-red-500 rounded-full transition-colors border shadow-sm"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </button>
          ))}
          {sectors.length === 0 && (
            <div className="col-span-full py-20 text-center text-slate-300 italic font-bold">Nenhum setor cadastrado.</div>
          )}
        </div>

        {isAddingSector && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
               <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                  <h2 className="text-xl font-black text-slate-800">{editingSector ? 'Editar Setor' : 'Novo Setor'}</h2>
                  <button onClick={resetSectorForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
               </div>
               <form onSubmit={handleSaveSectorSubmit} className="p-8 space-y-6">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Nome do Setor</label>
                    <input type="text" value={sectorName} onChange={e => setSectorName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none font-bold text-slate-800 bg-white" placeholder="Ex: Recepção" />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-3">
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Enxoval de Uniforme Padrão</label>
                      <button type="button" onClick={() => addUniformItem('STANDARD')} className="text-[8px] font-black text-emerald-600 uppercase">+ Adicionar Peça</button>
                    </div>
                    <div className="space-y-2 max-h-40 overflow-y-auto pr-2">
                       {standardUniforms.map((item, idx) => (
                         <div key={idx} className="flex gap-2 animate-in slide-in-from-left-2">
                           <input type="text" placeholder="Peça" value={item.name} onChange={e => updateUniformItem('STANDARD', idx, 'name', e.target.value)} className="flex-1 px-3 py-2 rounded-lg border bg-white text-[10px] font-bold" />
                           <input type="number" placeholder="Qtd" value={item.quantity} onChange={e => updateUniformItem('STANDARD', idx, 'quantity', parseInt(e.target.value))} className="w-16 px-3 py-2 rounded-lg border bg-white text-[10px] font-bold" />
                           <button type="button" onClick={() => removeUniformItem('STANDARD', idx)} className="text-rose-300 hover:text-rose-500"><Trash2 size={14}/></button>
                         </div>
                       ))}
                       {standardUniforms.length === 0 && <p className="text-[9px] text-slate-300 text-center py-4 italic border-2 border-dashed rounded-xl">Defina as peças que o funcionário deste setor deve ter.</p>}
                    </div>
                  </div>
                  <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all" style={{ backgroundColor: theme.primary }}>Salvar Configuração de Setor</button>
               </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="flex items-center space-x-3">
          <button onClick={() => onSelectSector(null)} className="p-2 bg-white rounded-xl shadow-sm text-slate-400 hover:text-slate-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-800">{currentSector?.name}</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase">{filteredEmployees.length} Colaboradores registrados</p>
          </div>
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input 
              type="text"
              placeholder="Buscar por nome..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 focus:border-blue-500 outline-none shadow-sm transition-all text-sm font-bold bg-white"
            />
          </div>
          <button 
            onClick={() => setIsAddingEmployee(true)}
            className="text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
            style={{ backgroundColor: theme.primary }}
          >
            <UserPlus size={18} />
            <span className="hidden sm:inline">Adicionar Funcionário</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {filteredEmployees.map(emp => {
          const discrepancies = currentSector ? calculateDiscrepancy(emp, currentSector) : [];
          return (
            <div key={emp.id} className="bg-white rounded-[2rem] border border-slate-100 shadow-sm p-6 flex flex-col md:flex-row gap-6 hover:shadow-md transition-all">
              <div className="flex items-center space-x-4 min-w-[200px]">
                <div className="w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg" style={{ backgroundColor: theme.primary }}>
                  {(emp.name || "U")[0]}
                </div>
                <div>
                  <h4 className="font-black text-slate-800 leading-tight">{emp.name}</h4>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">{emp.role}</p>
                </div>
              </div>

              <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-4 border-t md:border-t-0 md:border-l border-slate-50 pt-4 md:pt-0 md:pl-6">
                <div>
                  <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Horário & Escala</p>
                  <div className="flex items-center text-xs font-black text-slate-900">
                    <Clock size={12} className="mr-1.5 text-slate-300" />
                    {emp.scheduleType} {emp.shiftType && `(${emp.shiftType})`}
                  </div>
                  <div className="flex items-center text-[10px] font-bold text-slate-500 mt-1">{emp.workingHours}</div>
                </div>
                <div>
                  <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Uniformes Possuídos</p>
                  <div className="flex items-center text-xs font-bold text-slate-700">
                    <Shirt size={12} className="mr-1.5 text-slate-300" />
                    {emp.uniforms?.reduce((acc, u) => acc + u.quantity, 0) || 0} Peças no total
                  </div>
                </div>
                <div className="col-span-2">
                  <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Necessidade de Uniforme</p>
                  {discrepancies.length > 0 ? (
                    <div className="flex flex-wrap gap-1.5">
                      {discrepancies.map((d, di) => (
                        <div key={di} className="px-2 py-0.5 bg-rose-50 border border-rose-100 text-rose-600 rounded-lg text-[8px] font-black uppercase flex items-center">
                          <AlertTriangle size={8} className="mr-1" /> Faltam {d.missing} {d.name}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="flex items-center text-emerald-500 text-[9px] font-black uppercase">
                      <CheckCircle2 size={12} className="mr-1.5" /> Enxoval Completo
                    </div>
                  )}
                </div>
              </div>

              <div className="flex items-center justify-end space-x-2">
                <button onClick={() => handleEditEmployee(emp)} className="p-3 text-slate-300 hover:text-blue-500 transition-colors bg-slate-50 rounded-xl">
                  <Edit2 size={20} />
                </button>
                <button onClick={() => onDelete(emp.id)} className="p-3 text-slate-300 hover:text-rose-500 transition-colors bg-slate-50 rounded-xl">
                  <Trash2 size={20} />
                </button>
              </div>
            </div>
          );
        })}
        {filteredEmployees.length === 0 && (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-100 flex flex-col items-center justify-center text-slate-300">
             <Package size={64} className="mb-4 opacity-10" />
             <p className="text-xl font-black italic uppercase tracking-tighter">Nenhum funcionário cadastrado aqui</p>
          </div>
        )}
      </div>

      {isAddingEmployee && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl max-h-[90vh] overflow-hidden flex flex-col animate-in zoom-in duration-200">
             <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">{editingEmployee ? 'Editar Cadastro' : 'Novo Cadastro'}</h2>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Setor: {currentSector?.name}</p>
                </div>
                <button onClick={resetEmployeeForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
             </div>

             <div className="flex bg-slate-50 p-2 mx-8 mt-6 rounded-2xl border border-slate-100">
                <button onClick={() => setActiveTab('DADOS')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'DADOS' ? 'bg-white shadow-md text-blue-600' : 'text-slate-400'}`}>Dados & Escala</button>
                <button onClick={() => setActiveTab('UNIFORMES')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'UNIFORMES' ? 'bg-white shadow-md text-blue-600' : 'text-slate-400'}`}>Uniforme (O que possui)</button>
             </div>

             <form onSubmit={handleSaveEmployeeSubmit} className="flex-1 overflow-y-auto p-8 space-y-8">
                {activeTab === 'DADOS' ? (
                  <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="col-span-1 md:col-span-2">
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Nome Completo</label>
                        <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Cargo</label>
                        <input type="text" value={role} onChange={e => setRole(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Data de Admissão</label>
                        <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Salário Base (R$)</label>
                        <input type="number" step="0.01" value={salary} onChange={e => setSalary(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none bg-white font-bold text-slate-900" />
                      </div>
                      <div>
                        <label className="block text-[9px] font-black text-slate-500 uppercase mb-1.5 ml-1">Tipo de Escala</label>
                        <select value={scheduleType} onChange={e => setScheduleType(e.target.value as any)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold text-slate-800 outline-none">
                          <option value="6x1">6x1</option>
                          <option value="12x36">12x36</option>
                          <option value="Intermitente">Intermitente</option>
                        </select>
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                    <div className="bg-blue-50/50 p-6 rounded-[2rem] border border-blue-100">
                       <h4 className="text-[10px] font-black text-blue-700 uppercase tracking-widest flex items-center mb-4">
                         <Package size={14} className="mr-2" /> Peças em posse do funcionário:
                       </h4>
                       <div className="space-y-3">
                          {uniforms.map((u, ui) => (
                            <div key={ui} className="flex gap-2 animate-in slide-in-from-left-2">
                              <input type="text" placeholder="Nome da Peça (Ex: Camisa G)" value={u.name} onChange={e => updateUniformItem('EMPLOYEE', ui, 'name', e.target.value)} className="flex-1 px-4 py-3 rounded-xl border border-slate-200 bg-white text-xs font-bold" />
                              <input type="number" placeholder="Qtd" value={u.quantity} onChange={e => updateUniformItem('EMPLOYEE', ui, 'quantity', parseInt(e.target.value))} className="w-20 px-4 py-3 rounded-xl border border-slate-200 bg-white text-xs font-bold" />
                              <button type="button" onClick={() => removeUniformItem('EMPLOYEE', ui)} className="text-rose-300 hover:text-rose-500"><Trash2 size={18}/></button>
                            </div>
                          ))}
                          <button type="button" onClick={() => addUniformItem('EMPLOYEE')} className="w-full py-3 border-2 border-dashed border-blue-200 rounded-xl text-blue-400 text-[10px] font-black uppercase hover:bg-white transition-all">+ Adicionar Peça Recebida</button>
                       </div>
                    </div>

                    <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                       <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center mb-4">
                         <Info size={14} className="mr-2" /> Enxoval Obrigatório do Setor:
                       </h4>
                       <div className="flex flex-wrap gap-2">
                          {currentSector?.standardUniform?.map((std, si) => (
                            <div key={si} className="bg-white px-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold text-slate-600">
                              {std.quantity}x {std.name}
                            </div>
                          ))}
                          {(!currentSector?.standardUniform || currentSector?.standardUniform.length === 0) && (
                            <p className="text-[9px] text-slate-300 italic">Nenhum enxoval padrão configurado.</p>
                          )}
                       </div>
                    </div>
                  </div>
                )}

                <div className="flex gap-4 pt-4">
                   <button type="button" onClick={resetEmployeeForm} className="flex-1 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">Cancelar</button>
                   <button type="submit" className="flex-1 py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all" style={{ backgroundColor: theme.primary }}>
                     {editingEmployee ? 'Atualizar Cadastro' : 'Salvar Cadastro'}
                   </button>
                </div>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeesView;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';
import { LogOut, RefreshCw } from 'lucide-react';

// URL fornecida pelo usuário para integração direta
const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwLZEB6qtG__uXIrkpQYhbG40lHXjAkNQ-QQ5IDmIC5YsFZiUYPWv6F3ciXqYx97gBy/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v9');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets', 
          type: 'Spreadsheet', 
          status: 'Connected', 
          lastSync: Date.now(),
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE':
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
      case 'GOLDEN_PARK':
        return {
          primary: '#BF984E',
          secondary: '#A68444',
          accent: '#A67A44',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6']
        };
      case 'THERMAL_RESORT':
        return {
          primary: '#68A672',
          secondary: '#4B94F2',
          accent: '#B49B5D',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D']
        };
      default:
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
    }
  }, [state.currentHotel]);

  // Função para carregar dados da Planilha (Reflexão)
  const loadDataFromSheet = useCallback(async () => {
    setIsRefreshing(true);
    try {
      const response = await fetch(GLOBAL_SCRIPT_URL);
      if (!response.ok) throw new Error("Erro ao buscar dados");
      const data = await response.json();

      if (data && data.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [prev.currentHotel]: {
              ...prev.hotels[prev.currentHotel],
              apartments: data.data.apartments || prev.hotels[prev.currentHotel].apartments,
              budgets: data.data.budgets || prev.hotels[prev.currentHotel].budgets,
              employees: data.data.employees || prev.hotels[prev.currentHotel].employees,
              sectors: data.data.sectors || prev.hotels[prev.currentHotel].sectors,
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
      }
    } catch (error) {
      console.error("Erro ao sincronizar dados da planilha:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [state.currentHotel]);

  // Carrega dados na inicialização
  useEffect(() => {
    loadDataFromSheet();
  }, []);

  useEffect(() => {
    const stateToSave = { ...state, currentUser: null };
    localStorage.setItem('hotel_village_state_v9', JSON.stringify(stateToSave));
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({
      ...prev,
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'ROUPARIA' ? ViewType.APARTMENTS : ViewType.DASHBOARD
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setHotel = (hotel: HotelType) => {
    if (state.currentUser?.role !== 'DIRETORIA') return;
    setState(prev => ({ ...prev, currentHotel: hotel, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setView = (view: ViewType) => {
    if (state.currentUser?.role === 'ROUPARIA' && view !== ViewType.APARTMENTS) return;
    setState(prev => ({ ...prev, currentView: view, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const selectFloor = (floor: number) => {
    setState(prev => ({ ...prev, selectedFloor: floor }));
  };

  const selectApartment = (id: string | null) => {
    setState(prev => ({ ...prev, selectedApartmentId: id }));
  };

  const selectSector = (id: string | null) => {
    setState(prev => ({ ...prev, selectedSectorId: id }));
  };

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR', data: any, files?: any[]) => {
    const integration = state.integrations[0];
    if (integration?.url) {
      try {
        await fetch(integration.url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ dataType, ...data, newFiles: files })
        });
        // Opcional: Recarregar após salvar para garantir reflexão
        // loadDataFromSheet(); 
      } catch (err) {
        console.error('Falha na sincronização:', err);
      }
    }
  };

  const updateApartment = (apt: Apartment) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          apartments: {
            ...prev.hotels[prev.currentHotel].apartments,
            [apt.id]: apt
          }
        }
      }
    }));
    syncToSheet('APARTMENT', apt);
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.budgets.find(b => b.id === budget.id);
      const newBudgets = exists 
        ? hotel.budgets.map(b => b.id === budget.id ? budget : b)
        : [budget, ...hotel.budgets];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: newBudgets }
        }
      };
    });
    syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: hotel.budgets.filter(b => b.id !== id) }
        }
      };
    });
  };

  const handleSaveEmployee = (employee: Employee) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.employees.find(e => e.id === employee.id);
      const newEmployees = exists 
        ? hotel.employees.map(e => e.id === employee.id ? employee : e)
        : [employee, ...hotel.employees];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: newEmployees }
        }
      };
    });
    syncToSheet('EMPLOYEE', employee);
  };

  const handleDeleteEmployee = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: hotel.employees.filter(e => e.id !== id) }
        }
      };
    });
  };

  const handleSaveSector = (sector: Sector) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.sectors.find(s => s.id === sector.id);
      const newSectors = exists 
        ? hotel.sectors.map(s => s.id === sector.id ? sector : s)
        : [...hotel.sectors, sector];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, sectors: newSectors }
        }
      };
    });
    syncToSheet('SECTOR', sector);
  };

  const handleDeleteSector = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { 
            ...hotel, 
            sectors: hotel.sectors.filter(s => s.id !== id),
            employees: hotel.employees.filter(e => e.sectorId !== id)
          }
        }
      };
    });
  };

  const updateIntegration = (integration: Integration) => {
    setState(prev => ({
      ...prev,
      integrations: prev.integrations.map(i => i.id === integration.id ? integration : i)
    }));
  };

  const getHotelName = (type: HotelType) => {
    switch(type) {
      case 'VILLAGE': return 'Village Inn';
      case 'GOLDEN_PARK': return 'Hotel Golden Park';
      case 'THERMAL_RESORT': return 'Thermas Resort';
      default: return 'Hotel';
    }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || {
          id: aptId,
          floor: parseInt(aptId.split('-')[0]),
          roomNumber: parseInt(aptId.split('-')[1]),
          defects: []
        };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme}
            integrationUrl={GLOBAL_SCRIPT_URL}
            onBack={() => selectApartment(null)} 
            onSave={updateApartment} 
          />
        );
      }

      if (state.selectedFloor !== null) {
        return (
          <FloorDetailView 
            floor={state.selectedFloor} 
            theme={theme}
            apartments={currentHotelData.apartments}
            onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))}
            onSelectApartment={selectApartment}
          />
        );
      }
      return <ApartmentsView onSelectFloor={selectFloor} theme={theme} hotelName={getHotelName(state.currentHotel)} />;
    }

    if (state.currentView === ViewType.BUDGETS) {
      return (
        <BudgetsView 
          budgets={currentHotelData.budgets} 
          theme={theme}
          onSave={handleSaveBudget} 
          onDelete={handleDeleteBudget}
        />
      );
    }

    if (state.currentView === ViewType.EMPLOYEES) {
      return (
        <EmployeesView 
          employees={currentHotelData.employees}
          sectors={currentHotelData.sectors}
          selectedSectorId={state.selectedSectorId}
          onSelectSector={selectSector}
          theme={theme}
          onSave={handleSaveEmployee}
          onDelete={handleDeleteEmployee}
          onSaveSector={handleSaveSector}
          onDeleteSector={handleDeleteSector}
        />
      );
    }

    if (state.currentView === ViewType.SETTINGS) {
      return (
        <SettingsView 
          integrations={state.integrations}
          theme={theme}
          onUpdate={updateIntegration}
        />
      );
    }

    if (state.currentView === ViewType.DASHBOARD) {
      return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={loadDataFromSheet} isRefreshing={isRefreshing} />;
    }

    return null;
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  const isFullscreenView = state.currentView === ViewType.APARTMENTS && state.selectedApartmentId;

  const getHeaderTitle = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      return state.selectedFloor ? `Andar ${state.selectedFloor}` : 'Apartamentos';
    }
    if (state.currentView === ViewType.BUDGETS) return 'Orçamentos';
    if (state.currentView === ViewType.EMPLOYEES) {
        if (state.selectedSectorId) {
            const sector = currentHotelData.sectors.find(s => s.id === state.selectedSectorId);
            return `Equipe: ${sector?.name || 'Setor'}`;
        }
        return 'Setores da Equipe';
    }
    if (state.currentView === ViewType.SETTINGS) return 'Configurações';
    if (state.currentView === ViewType.DASHBOARD) return 'Dashboard';
    return state.currentView;
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      {!isFullscreenView && (
        <>
          <Sidebar 
            currentView={state.currentView} 
            onViewChange={setView} 
            currentHotel={state.currentHotel}
            onHotelChange={setHotel}
            onLogout={handleLogout}
            theme={theme}
            role={state.currentUser.role}
          />
          <BottomNav 
            currentView={state.currentView}
            onViewChange={setView}
            theme={theme}
            role={state.currentUser.role}
          />
        </>
      )}

      <main className={`flex-1 transition-all duration-300 
        ${isFullscreenView ? 'p-0' : 'p-4 md:p-8'} 
        ${!isFullscreenView ? 'mb-20 md:mb-0 md:ml-64' : 'ml-0'}`}>

        {!isFullscreenView && (
          <header className="mb-6 flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm md:bg-transparent md:p-0 md:shadow-none md:mb-8">
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 md:hidden">
                {getHotelName(state.currentHotel)}
              </span>
              <h1 className="text-xl md:text-3xl font-black text-slate-800 leading-tight">
                {getHeaderTitle()}
              </h1>
            </div>

            <div className="flex items-center space-x-4">
              <button 
                onClick={loadDataFromSheet}
                disabled={isRefreshing}
                className={`p-2 rounded-xl bg-slate-50 text-slate-400 transition-all ${isRefreshing ? 'animate-spin' : 'hover:bg-slate-100 hover:text-blue-500'}`}
                title="Sincronizar Planilha"
              >
                <RefreshCw size={18} />
              </button>

              <button 
                onClick={handleLogout}
                className="flex items-center space-x-3 hover:bg-slate-50 p-2 md:p-3 rounded-2xl transition-all active:scale-95 group"
                title="Sair da Conta"
              >
                <div className="text-right hidden sm:block">
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 group-hover:text-red-500 transition-colors">
                    {state.currentUser.role}
                  </p>
                  <p className="text-[9px] font-bold text-red-500 uppercase opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-end">
                    <LogOut size={10} className="mr-1" /> Encerrar
                  </p>
                  <p className="text-xs font-bold group-hover:opacity-0 transition-opacity" style={{ color: theme.primary }}>Online</p>
                </div>
                <div 
                  className="w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg group-hover:shadow-red-200 transition-all relative"
                  style={{ backgroundColor: theme.primary, boxShadow: `0 8px 12px -3px ${theme.primary}40` }}
                >
                  {state.currentUser.role[0]}
                </div>
              </button>
            </div>
          </header>
        )}

        <div className="animate-in fade-in duration-500">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { Apartment, Employee, HotelTheme } from '../types';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell
} from 'recharts';
import { AlertCircle, ClipboardList, Users, Database, Link, DollarSign, RefreshCw, Clock } from 'lucide-react';

interface DashboardProps {
  apartments: Record<string, Apartment>;
  employees: Employee[];
  theme: HotelTheme;
  lastSync?: number;
  onRefresh?: () => void;
  isRefreshing?: boolean;
}

const Dashboard: React.FC<DashboardProps> = ({ apartments, employees, theme, lastSync, onRefresh, isRefreshing }) => {
  const aptList: Apartment[] = Object.values(apartments);
  const totalDefects = aptList.reduce((acc, curr) => acc + (curr.defects?.length || 0), 0);
  const apartmentsWithIssues = aptList.filter(a => (a.defects?.length || 0) > 0).length;

  const floorData = [200, 300, 400, 500, 600, 700].map(floor => ({
    name: `${floor}`,
    defects: aptList.filter(a => a.floor === floor).reduce((acc, curr) => acc + (curr.defects?.length || 0), 0)
  }));

  const pieData = [
    { name: 'Com Avarias', value: apartmentsWithIssues, color: '#ef4444' },
    { name: 'Sem Avarias', value: Math.max(0, 210 - apartmentsWithIssues), color: theme.secondary }
  ];

  const totalSalary = employees.reduce((acc, curr) => acc + (Number(curr.salary) || 0), 0);

  return (
    <div className="space-y-4 md:space-y-6 animate-in fade-in duration-700 pb-10">

      {/* Barra de Status de Sincronização */}
      <div className="flex flex-col sm:flex-row justify-between items-center bg-white/50 backdrop-blur-sm p-3 rounded-2xl border border-slate-100 gap-3">
        <div className="flex items-center space-x-3 text-[10px] font-black uppercase tracking-widest text-slate-400">
           <Database size={14} className="text-emerald-500" />
           <span>Planilha Conectada</span>
           {lastSync && (
             <div className="flex items-center space-x-1 border-l pl-3 ml-1 border-slate-200">
               <Clock size={12} />
               <span>Refletido em: {new Date(lastSync).toLocaleTimeString()}</span>
             </div>
           )}
        </div>
        <button 
          onClick={onRefresh}
          disabled={isRefreshing}
          className="flex items-center space-x-2 bg-white px-4 py-1.5 rounded-xl border-2 border-slate-100 shadow-sm text-[9px] font-black uppercase tracking-widest hover:border-blue-200 hover:text-blue-500 transition-all active:scale-95 disabled:opacity-50"
        >
          <RefreshCw size={12} className={isRefreshing ? 'animate-spin' : ''} />
          <span>{isRefreshing ? 'Refletindo...' : 'Refletir Planilha'}</span>
        </button>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-6">
        <div className="bg-white p-4 md:p-6 rounded-[2rem] shadow-sm border border-slate-50 flex flex-col md:flex-row md:items-center space-y-2 md:space-y-0 md:space-x-4">
          <div className="p-3 md:p-4 bg-red-50 text-red-500 rounded-2xl w-fit">
            <AlertCircle size={22} className="md:w-[28px] md:h-[28px]" />
          </div>
          <div>
            <p className="text-[9px] md:text-[10px] text-slate-400 font-black uppercase tracking-widest">Avarias</p>
            <h3 className="text-xl md:text-3xl font-black text-slate-800">{totalDefects}</h3>
          </div>
        </div>

        <div className="bg-white p-4 md:p-6 rounded-[2rem] shadow-sm border border-slate-50 flex flex-col md:flex-row md:items-center space-y-2 md:space-y-0 md:space-x-4">
          <div className="p-3 md:p-4 rounded-2xl w-fit" style={{ backgroundColor: theme.primary + '10', color: theme.primary }}>
            <ClipboardList size={22} className="md:w-[28px] md:h-[28px]" />
          </div>
          <div>
            <p className="text-[9px] md:text-[10px] text-slate-400 font-black uppercase tracking-widest">Unidades</p>
            <h3 className="text-xl md:text-3xl font-black text-slate-800">{apartmentsWithIssues}</h3>
          </div>
        </div>

        <div className="bg-white p-4 md:p-6 rounded-[2rem] shadow-sm border border-slate-50 flex flex-col md:flex-row md:items-center space-y-2 md:space-y-0 md:space-x-4">
          <div className="p-3 md:p-4 rounded-2xl w-fit" style={{ backgroundColor: theme.secondary + '10', color: theme.secondary }}>
            <Users size={22} className="md:w-[28px] md:h-[28px]" />
          </div>
          <div>
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Equipe</p>
            <h4 className="text-2xl font-black text-slate-800">{employees.length}</h4>
          </div>
        </div>

        <div className="bg-white p-4 md:p-6 rounded-[2rem] shadow-sm border border-slate-50 flex flex-col md:flex-row md:items-center space-y-2 md:space-y-0 md:space-x-4">
          <div className="p-3 md:p-4 rounded-2xl w-fit" style={{ backgroundColor: theme.accent + '10', color: theme.accent }}>
            <DollarSign size={22} className="md:w-[28px] md:h-[28px]" />
          </div>
          <div>
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Folha</p>
            <h4 className="text-xl font-black text-slate-800">
              R$ {Math.round(totalSalary / 1000)}k
            </h4>
          </div>
        </div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 md:gap-6">
        <div className="bg-white p-6 md:p-8 rounded-[2rem] shadow-sm border border-slate-50">
          <h3 className="text-lg font-black text-slate-800 mb-6 flex items-center">
            Defeitos por Andar
          </h3>
          <div className="h-48 md:h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={floorData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '12px' }}
                />
                <Bar dataKey="defects" fill={theme.primary} radius={[8, 8, 0, 0]} barSize={35} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

