// URL fornecida pelo usuário para integração direta
const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwLZEB6qtG__uXIrkpQYhbG40lHXjAkNQ-QQ5IDmIC5YsFZiUYPWv6F3ciXqYx97gBy/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v11');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE':
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
      case 'GOLDEN_PARK':
        return {
          primary: '#BF984E',
          secondary: '#A68444',
          accent: '#A67A44',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6']
        };
      case 'THERMAL_RESORT':
        return {
          primary: '#68A672',
          secondary: '#4B94F2',
          accent: '#B49B5D',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D']
        };
      default:
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
    }
  }, [state.currentHotel]);

  // Função para carregar dados da Planilha (Reflexão)
  const loadDataFromSheet = useCallback(async () => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);

    try {
      // Usando cache: "no-store" para garantir que a reflexão seja imediata e constante
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${state.currentHotel}&t=${Date.now()}`, {
        method: 'GET',
        mode: 'cors',
        credentials: 'omit',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`Status: ${response.status}`);
      const data = await response.json();

      if (data && data.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [prev.currentHotel]: {
              ...prev.hotels[prev.currentHotel],
              apartments: data.data.apartments || prev.hotels[prev.currentHotel].apartments,
              budgets: data.data.budgets || prev.hotels[prev.currentHotel].budgets,
              employees: data.data.employees || prev.hotels[prev.currentHotel].employees,
              sectors: data.data.sectors || prev.hotels[prev.currentHotel].sectors,
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
      }
    } catch (error) {
      console.warn("Erro na reflexão dos dados:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [state.currentHotel]);

  // Sincroniza sempre que o hotel muda ou o app inicia
  useEffect(() => {
    loadDataFromSheet();
  }, [state.currentHotel, loadDataFromSheet]);

  useEffect(() => {
    const stateToSave = { ...state, currentUser: null };
    localStorage.setItem('hotel_village_state_v11', JSON.stringify(stateToSave));
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({
      ...prev,
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'ROUPARIA' ? ViewType.APARTMENTS : ViewType.DASHBOARD
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setHotel = (hotel: HotelType) => {
    if (state.currentUser?.role !== 'DIRETORIA') return;
    setState(prev => ({ ...prev, currentHotel: hotel, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setView = (view: ViewType) => {
    if (state.currentUser?.role === 'ROUPARIA' && view !== ViewType.APARTMENTS) return;
    setState(prev => ({ ...prev, currentView: view, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const selectFloor = (floor: number) => {
    setState(prev => ({ ...prev, selectedFloor: floor }));
  };

  const selectApartment = (id: string | null) => {
    setState(prev => ({ ...prev, selectedApartmentId: id }));
  };

  const selectSector = (id: string | null) => {
    setState(prev => ({ ...prev, selectedSectorId: id }));
  };

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR', data: any, files?: any[]) => {
    const integration = state.integrations[0];
    if (integration?.url) {
      try {
        await fetch(integration.url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files })
        });

        setState(prev => ({
          ...prev,
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i)
        }));
      } catch (err) {
        console.error('Falha na sincronização POST:', err);
      }
    }
  };

  const updateApartment = (apt: Apartment) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          apartments: {
            ...prev.hotels[prev.currentHotel].apartments,
            [apt.id]: apt
          }
        }
      }
    }));
    syncToSheet('APARTMENT', apt);
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.budgets.find(b => b.id === budget.id);
      const newBudgets = exists 
        ? hotel.budgets.map(b => b.id === budget.id ? budget : b)
        : [budget, ...hotel.budgets];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: newBudgets }
        }
      };
    });
    syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: hotel.budgets.filter(b => b.id !== id) }
        }
      };
    });
  };

  const handleSaveEmployee = (employee: Employee) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.employees.find(e => e.id === employee.id);
      const newEmployees = exists 
        ? hotel.employees.map(e => e.id === employee.id ? employee : e)
        : [employee, ...hotel.employees];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: newEmployees }
        }
      };
    });
    syncToSheet('EMPLOYEE', employee);
  };

  const handleDeleteEmployee = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: hotel.employees.filter(e => e.id !== id) }
        }
      };
    });
  };

  const handleSaveSector = (sector: Sector) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.sectors.find(s => s.id === sector.id);
      const newSectors = exists 
        ? hotel.sectors.map(s => s.id === sector.id ? sector : s)
        : [...hotel.sectors, sector];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, sectors: newSectors }
        }
      };
    });
    syncToSheet('SECTOR', sector);
  };

  const handleDeleteSector = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { 
            ...hotel, 
            sectors: hotel.sectors.filter(s => s.id !== id),
            employees: hotel.employees.filter(e => e.sectorId !== id)
          }
        }
      };
    });
  };

  const updateIntegration = (integration: Integration) => {
    setState(prev => ({
      ...prev,
      integrations: prev.integrations.map(i => i.id === integration.id ? integration : i)
    }));
  };

  const getHotelName = (type: HotelType) => {
    switch(type) {
      case 'VILLAGE': return 'Village Inn';
      case 'GOLDEN_PARK': return 'Hotel Golden Park';
      case 'THERMAL_RESORT': return 'Thermas Resort';
      default: return 'Hotel';
    }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || {
          id: aptId,
          floor: parseInt(aptId.split('-')[0]),
          roomNumber: parseInt(aptId.split('-')[1]),
          defects: []
        };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme}
            integrationUrl={GLOBAL_SCRIPT_URL}
            onBack={() => selectApartment(null)} 
            onSave={updateApartment} 
          />
        );
      }

      if (state.selectedFloor !== null) {
        return (
          <FloorDetailView 
            floor={state.selectedFloor} 
            theme={theme}
            apartments={currentHotelData.apartments}
            onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))}
            onSelectApartment={selectApartment}
          />
        );
      }
      return <ApartmentsView onSelectFloor={selectFloor} theme={theme} hotelName={getHotelName(state.currentHotel)} />;
    }

    if (state.currentView === ViewType.BUDGETS) {
      return (
        <BudgetsView 
          budgets={currentHotelData.budgets} 
          theme={theme}
          onSave={handleSaveBudget} 
          onDelete={handleDeleteBudget}
        />
      );
    }

    if (state.currentView === ViewType.EMPLOYEES) {
      return (
        <EmployeesView 
          employees={currentHotelData.employees}
          sectors={currentHotelData.sectors}
          selectedSectorId={state.selectedSectorId}
          onSelectSector={selectSector}
          theme={theme}
          onSave={handleSaveEmployee}
          onDelete={handleDeleteEmployee}
          onSaveSector={handleSaveSector}
          onDeleteSector={handleDeleteSector}
        />
      );
    }

    if (state.currentView === ViewType.SETTINGS) {
      return (
        <SettingsView 
          integrations={state.integrations}
          theme={theme}
          onUpdate={updateIntegration}
        />
      );
    }

    if (state.currentView === ViewType.DASHBOARD) {
      return (
        <Dashboard 
          apartments={currentHotelData.apartments} 
          employees={currentHotelData.employees} 
          theme={theme} 
          lastSync={state.integrations[0].lastSync} 
          onRefresh={loadDataFromSheet} 
          isRefreshing={isRefreshing} 
        />
      );
    }

    return null;
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  const isFullscreenView = state.currentView === ViewType.APARTMENTS && state.selectedApartmentId;

  const getHeaderTitle = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      return state.selectedFloor ? `Andar ${state.selectedFloor}` : 'Apartamentos';
    }
    if (state.currentView === ViewType.BUDGETS) return 'Orçamentos';
    if (state.currentView === ViewType.EMPLOYEES) {
        if (state.selectedSectorId) {
            const sector = currentHotelData.sectors.find(s => s.id === state.selectedSectorId);
            return `Equipe: ${sector?.name || 'Setor'}`;
        }
        return 'Setores da Equipe';
    }
    if (state.currentView === ViewType.SETTINGS) return 'Configurações';
    if (state.currentView === ViewType.DASHBOARD) return 'Dashboard';
    return state.currentView;
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      {!isFullscreenView && (
        <>
          <Sidebar 
            currentView={state.currentView} 
            onViewChange={setView} 
            currentHotel={state.currentHotel}
            onHotelChange={setHotel}
            onLogout={handleLogout}
            theme={theme}
            role={state.currentUser.role}
          />
          <BottomNav 
            currentView={state.currentView}
            onViewChange={setView}
            theme={theme}
            role={state.currentUser.role}
          />
        </>
      )}

      <main className={`flex-1 transition-all duration-300 
        ${isFullscreenView ? 'p-0' : 'p-4 md:p-8'} 
        ${!isFullscreenView ? 'mb-20 md:mb-0 md:ml-64' : 'ml-0'}`}>

        {!isFullscreenView && (
          <header className="mb-6 flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm md:bg-transparent md:p-0 md:shadow-none md:mb-8">
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 md:hidden">
                {getHotelName(state.currentHotel)}
              </span>
              <h1 className="text-xl md:text-3xl font-black text-slate-800 leading-tight">
                {getHeaderTitle()}
              </h1>
            </div>

            <div className="flex items-center space-x-4">
              <button 
                onClick={loadDataFromSheet}
                disabled={isRefreshing}
                className={`p-2 rounded-xl bg-slate-50 text-slate-400 transition-all ${isRefreshing ? 'animate-spin' : 'hover:bg-slate-100 hover:text-blue-500'}`}
                title="Sincronizar Planilha"
              >
                <RefreshCw size={18} />
              </button>

              <button 
                onClick={handleLogout}
                className="flex items-center space-x-3 hover:bg-slate-50 p-2 md:p-3 rounded-2xl transition-all active:scale-95 group"
                title="Sair da Conta"
              >
                <div className="text-right hidden sm:block">
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 group-hover:text-red-500 transition-colors">
                    {state.currentUser.role}
                  </p>
                  <p className="text-[9px] font-bold text-red-500 uppercase opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-end">
                    <LogOut size={10} className="mr-1" /> Encerrar
                  </p>
                  <p className="text-xs font-bold group-hover:opacity-0 transition-opacity" style={{ color: theme.primary }}>Online</p>
                </div>
                <div 
                  className="w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg group-hover:shadow-red-200 transition-all relative"
                  style={{ backgroundColor: theme.primary, boxShadow: `0 8px 12px -3px ${theme.primary}40` }}
                >
                  {state.currentUser.role[0]}
                </div>
              </button>
            </div>
          </header>
        )}

        <div className="animate-in fade-in duration-500">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Integration, HotelTheme } from '../types';
import { CheckCircle, Clock, Database, Code, Copy, Save, FileSpreadsheet, ExternalLink, XCircle } from 'lucide-react';

interface IntegrationsViewProps {
  integrations: Integration[];
  theme: HotelTheme;
  onUpdate: (integration: Integration) => void;
}

const APPS_SCRIPT_CODE = `/**
 * Google Apps Script para Gestão Hotel Village - V11 (Conexão Constante Total)
 * Instruções: 
 * 1. No Google Sheets, vá em Extensões -> Apps Script.
 * 2. Substitua o código atual por este.
 * 3. Clique em "Implantar" -> "Nova Implantação".
 * 4. Tipo: Web App | Executar como: Eu | Quem tem acesso: Qualquer pessoa.
 */

function doGet(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = e.parameter.hotel || 'VILLAGE';
    var result = {
      apartments: {},
      budgets: [],
      employees: [],
      sectors: []
    };

    // 1. Carregar Apartamentos
    var sheetApts = ss.getSheetByName('Apartamentos_' + hotel) || ss.getSheetByName('Apartamentos');
    if (sheetApts) {
      var data = sheetApts.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        var num = data[i][0];
        var floor = data[i][1];
        if(!num || !floor) continue;

        var aptId = floor + "-" + num;
        result.apartments[aptId] = {
          id: aptId,
          roomNumber: num,
          floor: floor,
          pisoType: data[i][2],
          pisoStatus: data[i][3],
          banheiroType: data[i][4],
          banheiroStatus: data[i][5],
          temCofre: data[i][6] === 'Sim',
          temCortina: data[i][7] === 'Sim',
          cortinaStatus: data[i][8],
          cortinaSize: data[i][9],
          cortinaCoverage: data[i][10],
          temEspelhoCorpo: data[i][11] === 'Sim',
          espelhoCorpoStatus: data[i][12],
          acBrand: data[i][13],
          moveisStatus: data[i][14],
          moveisDetalhes: data[i][15] ? JSON.parse(data[i][15]) : [],
          beds: data[i][16] ? JSON.parse(data[i][16]) : [],
          temPortaControle: data[i][17] === 'Sim',
          temCabide: data[i][18] === 'Sim',
          cabideQuantity: data[i][19] || 0,
          temSuportePapel: data[i][20] === 'Sim',
          temSuporteShampoo: data[i][21] === 'Sim',
          suporteShampooStatus: data[i][22],
          luminariaType: data[i][23],
          luminariaColor: data[i][24],
          tvBrand: data[i][25],
          defects: data[i][26] ? JSON.parse(data[i][26]) : []
        };
      }
    }

    // 2. Carregar Setores (Geral)
    var sheetSectors = ss.getSheetByName('Setores');
    if (sheetSectors) {
      var dataS = sheetSectors.getDataRange().getValues();
      for (var j = 1; j < dataS.length; j++) {
        if(!dataS[j][0]) continue;
        result.sectors.push({
          id: dataS[j][0].toString(),
          name: dataS[j][1],
          standardUniform: dataS[j][2] ? JSON.parse(dataS[j][2]) : []
        });
      }
    }

    // 3. Carregar Funcionários
    var sheetEmps = ss.getSheetByName('Funcionários_' + hotel) || ss.getSheetByName('Funcionários');
    if (sheetEmps) {
      var dataE = sheetEmps.getDataRange().getValues();
      for (var k = 1; k < dataE.length; k++) {
        if(!dataE[k][0]) continue;
        result.employees.push({
          id: dataE[k][0].toString(),
          name: dataE[k][1],
          role: dataE[k][2],
          sectorId: dataE[k][3].toString(),
          salary: dataE[k][4],
          startDate: dataE[k][5],
          vacationStatus: dataE[k][6],
          scheduleType: dataE[k][8],
          shiftType: dataE[k][9],
          workingHours: dataE[k][10],
          weeklyDayOff: dataE[k][11],
          monthlySundayOff: dataE[k][12],
          uniforms: dataE[k][15] ? JSON.parse(dataE[k][15]) : []
        });
      }
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var requestData = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = requestData.hotel || 'VILLAGE';

    var sheetName = '';
    if (requestData.dataType === 'BUDGET') sheetName = 'Orçamentos';
    else if (requestData.dataType === 'EMPLOYEE') sheetName = 'Funcionários_' + hotel;
    else if (requestData.dataType === 'SECTOR') sheetName = 'Setores';
    else sheetName = 'Apartamentos_' + hotel;

    var sheet = ss.getSheetByName(sheetName) || ss.insertSheet(sheetName);

    if (sheet.getLastRow() === 0) {
      setupHeaders(sheet, requestData.dataType);
    }

    if (requestData.dataType === 'EMPLOYEE') {
      var empRow = [requestData.id, requestData.name, requestData.role, requestData.sectorId, requestData.salary, requestData.startDate, requestData.vacationStatus, "", requestData.scheduleType, requestData.shiftType, requestData.workingHours, requestData.weeklyDayOff, requestData.monthlySundayOff, "Ativo", new Date(), JSON.stringify(requestData.uniforms || [])];
      upsert(sheet, requestData.id, empRow);
    } else if (requestData.dataType === 'SECTOR') {
      var secRow = [requestData.id, requestData.name, JSON.stringify(requestData.standardUniform || []), new Date()];
      upsert(sheet, requestData.id, secRow);
    } else if (requestData.dataType === 'APARTMENT') {
      var aptRow = [
        requestData.roomNumber, requestData.floor, 
        requestData.pisoType || '', requestData.pisoStatus || '', 
        requestData.banheiroType || '', requestData.banheiroStatus || '', 
        requestData.temCofre ? 'Sim' : 'Não', requestData.temCortina ? 'Sim' : 'Não', 
        requestData.cortinaStatus || '', requestData.cortinaSize || '', requestData.cortinaCoverage || '',
        requestData.temEspelhoCorpo ? 'Sim' : 'Não', requestData.espelhoCorpoStatus || '',
        requestData.acBrand || '', requestData.moveisStatus || '', 
        JSON.stringify(requestData.moveisDetalhes || []), JSON.stringify(requestData.beds || []),
        requestData.temPortaControle ? 'Sim' : 'Não', requestData.temCabide ? 'Sim' : 'Não', requestData.cabideQuantity || 0,
        requestData.temSuportePapel ? 'Sim' : 'Não', requestData.temSuporteShampoo ? 'Sim' : 'Não', requestData.suporteShampooStatus || '',
        requestData.luminariaType || '', requestData.luminariaColor || '', requestData.tvBrand || '',
        JSON.stringify(requestData.defects || []), new Date()
      ];
      upsert(sheet, requestData.roomNumber, aptRow);
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function setupHeaders(sheet, type) {
  var headers = [];
  if (type === 'BUDGET') headers = ['ID', 'Título', 'Objetivo', 'Qtd', 'Fornec', 'Valor', 'Status', 'Data'];
  else if (type === 'EMPLOYEE') headers = ['ID', 'Nome', 'Cargo', 'SetorID', 'Salário', 'Início', 'Férias', 'Venc', 'Escala', 'EscalaDet', 'Horário', 'Folga', 'Dom', 'Status', 'Data', 'Uniformes'];
  else if (type === 'SECTOR') headers = ['ID', 'Nome', 'Padrão', 'Data'];
  else headers = ['Apto', 'Andar', 'PisoT', 'PisoS', 'BanhT', 'BanhS', 'Cofre', 'Cortina', 'CortinaS', 'CortinaM', 'CortinaC', 'Espelho', 'EspelhoS', 'AC', 'MoveisS', 'MoveisD', 'Camas', 'PortaCont', 'Cabide', 'CabideQ', 'SuportPap', 'SuportSham', 'SuportShamS', 'LuminType', 'LuminColor', 'TV', 'Avarias', 'Atualizado'];

  sheet.appendRow(headers);
  sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#f3f3f3');
}

function upsert(sheet, id, rowData) {
  var data = sheet.getDataRange().getValues();
  var idx = -1;
  for (var i = 1; i < data.length; i++) { if (data[i][0] == id) { idx = i + 1; break; } }
  if (idx > -1) sheet.getRange(idx, 1, 1, rowData.length).setValues([rowData]);
  else sheet.appendRow(rowData);
}
`;

