const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v13');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE':
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
      case 'GOLDEN_PARK':
        return {
          primary: '#BF984E',
          secondary: '#A68444',
          accent: '#A67A44',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6']
        };
      case 'THERMAL_RESORT':
        return {
          primary: '#68A672',
          secondary: '#4B94F2',
          accent: '#B49B5D',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D']
        };
      default:
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
    }
  }, [state.currentHotel]);

  // Função para carregar dados da Planilha (Reflexão)
  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);

    const targetHotel = hotelOverride || state.currentHotel;

    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, {
        method: 'GET',
        mode: 'cors',
        credentials: 'omit',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`Status: ${response.status}`);
      const data = await response.json();

      if (data && data.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              apartments: data.data.apartments || {},
              budgets: data.data.budgets || [],
              employees: data.data.employees || [],
              inventory: data.data.inventory || [],
              sectors: data.data.sectors && data.data.sectors.length > 0 ? data.data.sectors : prev.hotels[targetHotel].sectors,
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return data.data;
      }
    } catch (error) {
      console.warn("Erro na reflexão dos dados:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [state.currentHotel]);

  // Sincroniza sempre que o hotel muda ou o app inicia
  useEffect(() => {
    loadDataFromSheet();
  }, [state.currentHotel, loadDataFromSheet]);

  useEffect(() => {
    const stateToSave = { ...state, currentUser: null };
    localStorage.setItem('hotel_village_state_v13', JSON.stringify(stateToSave));
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({
      ...prev,
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setHotel = (hotel: HotelType) => {
    if (state.currentUser?.role !== 'DIRETORIA' && state.currentUser?.role !== 'GERENCIA') return;
    setState(prev => ({ ...prev, currentHotel: hotel, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setView = (view: ViewType) => {
    if (state.currentUser?.role === 'FUNCIONARIO' && (view !== ViewType.APARTMENTS && view !== ViewType.INVENTORY)) return;
    setState(prev => ({ ...prev, currentView: view, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const selectFloor = (floor: number) => {
    setState(prev => ({ ...prev, selectedFloor: floor }));
  };

  const selectApartment = (id: string | null) => {
    setState(prev => ({ ...prev, selectedApartmentId: id }));
  };

  const selectSector = (id: string | null) => {
    setState(prev => ({ ...prev, selectedSectorId: id }));
  };

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY', data: any, files?: any[]) => {
    const integration = state.integrations[0];
    if (integration?.url) {
      try {
        await fetch(integration.url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files })
        });

        setState(prev => ({
          ...prev,
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i)
        }));
      } catch (err) {
        console.error('Falha na sincronização POST:', err);
      }
    }
  };

  const updateApartment = (apt: Apartment) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          apartments: {
            ...prev.hotels[prev.currentHotel].apartments,
            [apt.id]: apt
          }
        }
      }
    }));
    syncToSheet('APARTMENT', apt);
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.budgets.find(b => b.id === budget.id);
      const newBudgets = exists 
        ? hotel.budgets.map(b => b.id === budget.id ? budget : b)
        : [budget, ...hotel.budgets];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: newBudgets }
        }
      };
    });
    syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: hotel.budgets.filter(b => b.id !== id) }
        }
      };
    });
  };

  const handleSaveEmployee = (employee: Employee) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.employees.find(e => e.id === employee.id);
      const newEmployees = exists 
        ? hotel.employees.map(e => e.id === employee.id ? employee : e)
        : [employee, ...hotel.employees];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: newEmployees }
        }
      };
    });
    syncToSheet('EMPLOYEE', employee);
  };

  const handleDeleteEmployee = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: hotel.employees.filter(e => e.id !== id) }
        }
      };
    });
  };

  const handleSaveSector = (sector: Sector) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.sectors.find(s => s.id === sector.id);
      const newSectors = exists 
        ? hotel.sectors.map(s => s.id === sector.id ? sector : s)
        : [...hotel.sectors, sector];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, sectors: newSectors }
        }
      };
    });
    syncToSheet('SECTOR', sector);
  };

  const handleDeleteSector = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { 
            ...hotel, 
            sectors: hotel.sectors.filter(s => s.id !== id),
            employees: hotel.employees.filter(e => e.sectorId !== id)
          }
        }
      };
    });
  };

  const handleSaveInventory = (item: InventoryItem) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.inventory.find(i => i.id === item.id);
      const newInventory = exists 
        ? hotel.inventory.map(i => i.id === item.id ? item : i)
        : [...hotel.inventory, item];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, inventory: newInventory }
        }
      };
    });
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) }
        }
      };
    });
  };

  const updateIntegration = (integration: Integration) => {
    setState(prev => ({
      ...prev,
      integrations: prev.integrations.map(i => i.id === integration.id ? integration : i)
    }));
  };

  const getHotelName = (type: HotelType) => {
    switch(type) {
      case 'VILLAGE': return 'Village Inn';
      case 'GOLDEN_PARK': return 'Hotel Golden Park';
      case 'THERMAL_RESORT': return 'Thermas Resort';
      default: return 'Hotel';
    }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || {
          id: aptId,
          floor: parseInt(aptId.split('-')[0]),
          roomNumber: parseInt(aptId.split('-')[1]),
          defects: []
        };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme}
            integrationUrl={GLOBAL_SCRIPT_URL}
            onBack={() => selectApartment(null)} 
            onSave={updateApartment} 
          />
        );
      }

      if (state.selectedFloor !== null) {
        return (
          <FloorDetailView 
            floor={state.selectedFloor} 
            theme={theme}
            apartments={currentHotelData.apartments}
            onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))}
            onSelectApartment={selectApartment}
          />
        );
      }
      return <ApartmentsView onSelectFloor={selectFloor} theme={theme} hotelName={getHotelName(state.currentHotel)} />;
    }

    if (state.currentView === ViewType.BUDGETS) {
      return (
        <BudgetsView 
          budgets={currentHotelData.budgets} 
          theme={theme}
          onSave={handleSaveBudget} 
          onDelete={handleDeleteBudget}
        />
      );
    }

    if (state.currentView === ViewType.EMPLOYEES) {
      return (
        <EmployeesView 
          employees={currentHotelData.employees}
          sectors={currentHotelData.sectors}
          selectedSectorId={state.selectedSectorId}
          onSelectSector={selectSector}
          theme={theme}
          onSave={handleSaveEmployee}
          onDelete={handleDeleteEmployee}
          onSaveSector={handleSaveSector}
          onDeleteSector={handleDeleteSector}
        />
      );
    }

    if (state.currentView === ViewType.INVENTORY) {
      return (
        <InventoryView 
          inventory={currentHotelData.inventory}
          theme={theme}
          onSave={handleSaveInventory}
          onDelete={handleDeleteInventory}
          role={state.currentUser?.role}
        />
      );
    }

    if (state.currentView === ViewType.SETTINGS) {
      return (
        <SettingsView 
          integrations={state.integrations}
          theme={theme}
          onUpdate={updateIntegration}
        />
      );
    }

    if (state.currentView === ViewType.DASHBOARD) {
      return (
        <Dashboard 
          apartments={currentHotelData.apartments} 
          employees={currentHotelData.employees} 
          theme={theme} 
          lastSync={state.integrations[0].lastSync} 
          onRefresh={loadDataFromSheet} 
          isRefreshing={isRefreshing} 
        />
      );
    }

    return null;
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  }

  const isFullscreenView = state.currentView === ViewType.APARTMENTS && state.selectedApartmentId;

  const getHeaderTitle = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      return state.selectedFloor ? `Andar ${state.selectedFloor}` : 'Apartamentos';
    }
    if (state.currentView === ViewType.BUDGETS) return 'Orçamentos';
    if (state.currentView === ViewType.INVENTORY) return 'Controle de Estoque';
    if (state.currentView === ViewType.EMPLOYEES) {
        if (state.selectedSectorId) {
            const sector = currentHotelData.sectors.find(s => s.id === state.selectedSectorId);
            return `Equipe: ${sector?.name || 'Setor'}`;
        }
        return 'Setores da Equipe';
    }
    if (state.currentView === ViewType.SETTINGS) return 'Configurações';
    if (state.currentView === ViewType.DASHBOARD) return 'Dashboard';
    return state.currentView;
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      {!isFullscreenView && (
        <>
          <Sidebar 
            currentView={state.currentView} 
            onViewChange={setView} 
            currentHotel={state.currentHotel}
            onHotelChange={setHotel}
            onLogout={handleLogout}
            theme={theme}
            role={state.currentUser.role}
          />
          <BottomNav 
            currentView={state.currentView}
            onViewChange={setView}
            theme={theme}
            role={state.currentUser.role}
          />
        </>
      )}

      <main className={`flex-1 transition-all duration-300 
        ${isFullscreenView ? 'p-0' : 'p-4 md:p-8'} 
        ${!isFullscreenView ? 'mb-20 md:mb-0 md:ml-64' : 'ml-0'}`}>

        {!isFullscreenView && (
          <header className="mb-6 flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm md:bg-transparent md:p-0 md:shadow-none md:mb-8">
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 md:hidden">
                {getHotelName(state.currentHotel)}
              </span>
              <h1 className="text-xl md:text-3xl font-black text-slate-800 leading-tight">
                {getHeaderTitle()}
              </h1>
            </div>

            <div className="flex items-center space-x-4">
              <button 
                onClick={() => loadDataFromSheet()}
                disabled={isRefreshing}
                className={`p-2 rounded-xl bg-slate-50 text-slate-400 transition-all ${isRefreshing ? 'animate-spin' : 'hover:bg-slate-100 hover:text-blue-500'}`}
                title="Sincronizar Planilha"
              >
                <RefreshCw size={18} />
              </button>

              <button 
                onClick={handleLogout}
                className="flex items-center space-x-3 hover:bg-slate-50 p-2 md:p-3 rounded-2xl transition-all active:scale-95 group"
                title="Sair da Conta"
              >
                <div className="text-right hidden sm:block">
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 group-hover:text-red-500 transition-colors">
                    {state.currentUser.name || state.currentUser.role}
                  </p>
                  <p className="text-[9px] font-bold text-red-500 uppercase opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-end">
                    <LogOut size={10} className="mr-1" /> Encerrar
                  </p>
                  <p className="text-xs font-bold group-hover:opacity-0 transition-opacity" style={{ color: theme.primary }}>Online</p>
                </div>
                <div 
                  className="w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg group-hover:shadow-red-200 transition-all relative"
                  style={{ backgroundColor: theme.primary, boxShadow: `0 8px 12px -3px ${theme.primary}40` }}
                >
                  {(state.currentUser.name || state.currentUser.role)[0]}
                </div>
              </button>
            </div>
          </header>
        )}

        <div className="animate-in fade-in duration-500">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserRole, HotelType, User, Sector, Employee } from '../types';
import { Hotel, User as UserIcon, Lock, ChevronRight, AlertCircle, Settings, Users, Building2, Briefcase } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
  onFetchHotelData: (hotel: HotelType) => Promise<any>;
}

const Login: React.FC<LoginProps> = ({ onLogin, onFetchHotelData }) => {
  const [accessType, setAccessType] = useState<'ADMIN' | 'EMPLOYEE' | null>(null);
  const [role, setRole] = useState<UserRole | null>(null);
  const [hotel, setHotel] = useState<HotelType | ''>('');
  const [selectedSectorId, setSelectedSectorId] = useState<string>('');
  const [selectedEmployeeName, setSelectedEmployeeName] = useState<string>('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const [availableSectors, setAvailableSectors] = useState<Sector[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);

  const hotels: { id: HotelType; label: string }[] = [
    { id: 'VILLAGE', label: 'Village Inn' },
    { id: 'GOLDEN_PARK', label: 'Hotel Golden Park' },
    { id: 'THERMAL_RESORT', label: 'Thermas Resort' },
  ];

  const handleFetchData = async (h: HotelType) => {
    setIsLoading(true);
    setError('');
    try {
      const data = await onFetchHotelData(h);
      if (data) {
        setAvailableSectors(data.sectors || []);
        setAvailableEmployees(data.employees || []);
      }
    } catch (err) {
      setError('Erro ao carregar dados do hotel. Verifique a conexão.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleEnter = () => {
    if (accessType === 'ADMIN') {
      if (!role) return;
      if (role === 'GERENCIA') {
        if (!hotel) { setError('Selecione uma unidade'); return; }
        if (password === '123') onLogin({ role, hotel });
        else setError('Senha incorreta para Supervisão');
      } else if (role === 'DIRETORIA') {
        if (password === '0000') onLogin({ role });
        else setError('Senha incorreta para Diretoria');
      }
    } else if (accessType === 'EMPLOYEE') {
      if (!hotel || !selectedSectorId || !selectedEmployeeName) {
        setError('Preencha todos os campos para entrar');
        return;
      }
      onLogin({ 
        role: 'FUNCIONARIO', 
        hotel: hotel as HotelType, 
        name: selectedEmployeeName, 
        sectorId: selectedSectorId 
      });
    }
  };

  const getThemeColor = () => {
    if (hotel === 'VILLAGE') return '#26A6A6';
    if (hotel === 'GOLDEN_PARK') return '#BF984E';
    if (hotel === 'THERMAL_RESORT') return '#68A672';
    return '#1e293b';
  };

  const filteredEmployees = availableEmployees.filter(e => e.sectorId === selectedSectorId);

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-500">
        <div className="p-10 space-y-8">
          <div className="text-center space-y-2">
            <h1 className="text-4xl font-black text-slate-800 tracking-tighter">Nacional Inn</h1>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em]">Gestão Hotel Village v5.0</p>
          </div>

          {!accessType ? (
            <div className="space-y-4">
              <p className="text-sm font-bold text-slate-500 text-center mb-6">Como você deseja acessar?</p>
              <button 
                onClick={() => setAccessType('EMPLOYEE')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-emerald-50 border-2 border-transparent hover:border-emerald-200 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white rounded-2xl text-emerald-500 shadow-sm"><Users size={24} /></div>
                  <div className="text-left">
                    <p className="font-black text-slate-800">Funcionário</p>
                    <p className="text-xs text-slate-400 font-medium">Acesso via Unidade/Setor</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-emerald-500" />
              </button>

              <button 
                onClick={() => setAccessType('ADMIN')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-slate-900 hover:text-white border-2 border-transparent hover:border-slate-800 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white group-hover:bg-slate-800 rounded-2xl text-slate-800 group-hover:text-white shadow-sm transition-colors"><Shield size={24} /></div>
                  <div className="text-left">
                    <p className="font-black group-hover:text-white text-slate-800">Administrador</p>
                    <p className="text-xs text-slate-400 group-hover:text-slate-400 font-medium">Supervisão & Diretoria</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-white" />
              </button>
            </div>
          ) : accessType === 'ADMIN' && !role ? (
            <div className="space-y-4 animate-in slide-in-from-right-4 duration-300">
              <button onClick={() => setAccessType(null)} className="text-xs font-black text-blue-500 hover:underline">← Voltar</button>
              <p className="text-sm font-bold text-slate-500 text-center mb-6">Perfil Administrativo</p>

              <button 
                onClick={() => setRole('GERENCIA')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-amber-50 border-2 border-transparent hover:border-amber-200 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white rounded-2xl text-amber-500 shadow-sm"><Hotel size={24} /></div>
                  <div className="text-left">
                    <p className="font-black text-slate-800">Supervisão</p>
                    <p className="text-xs text-slate-400 font-medium">Gestão da Unidade</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-amber-500" />
              </button>

              <button 
                onClick={() => setRole('DIRETORIA')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-slate-200 border-2 border-transparent hover:border-slate-800 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white rounded-2xl text-slate-800 shadow-sm transition-colors"><Settings size={24} /></div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Diretoria</p>
                    <p className="text-xs text-slate-500 opacity-60 font-medium">Acesso Global</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-slate-900" />
              </button>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <button 
                onClick={() => { setAccessType(null); setRole(null); setError(''); setHotel(''); setPassword(''); }}
                className="text-xs font-black text-blue-500 hover:underline"
              >
                ← Voltar
              </button>

              <div className="space-y-4">
                {/* Seleção de Unidade (comum aos dois fluxos exceto diretoria) */}
                {(accessType === 'EMPLOYEE' || role === 'GERENCIA') && (
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Building2 size={12} className="mr-1"/> Unidade</label>
                    <div className="grid grid-cols-1 gap-2">
                      {hotels.map(h => (
                        <button 
                          key={h.id}
                          onClick={() => { setHotel(h.id); handleFetchData(h.id); setError(''); }}
                          className={`p-4 rounded-2xl border-2 text-sm font-bold transition-all text-left ${
                            hotel === h.id ? 'border-slate-800 bg-slate-800 text-white shadow-md' : 'border-slate-100 bg-slate-50 text-slate-500 hover:border-slate-300'
                          }`}
                        >
                          {h.label}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Fluxo de Funcionário (Dinamico) */}
                {accessType === 'EMPLOYEE' && hotel && (
                  <div className="space-y-4 animate-in slide-in-from-top-2">
                    {isLoading ? (
                      <div className="flex flex-col items-center py-8">
                        <div className="w-8 h-8 border-4 border-slate-100 border-t-blue-500 rounded-full animate-spin"></div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-4">Buscando base de dados...</p>
                      </div>
                    ) : (
                      <>
                        <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Briefcase size={12} className="mr-1"/> Setor</label>
                          <select 
                            value={selectedSectorId} 
                            onChange={(e) => { setSelectedSectorId(e.target.value); setSelectedEmployeeName(''); }}
                            className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                          >
                            <option value="">Selecione o setor...</option>
                            {availableSectors.map(s => (
                              <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                          </select>
                        </div>

                        {selectedSectorId && (
                          <div className="animate-in slide-in-from-top-2">
                            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><UserIcon size={12} className="mr-1"/> Seu Nome</label>
                            <select 
                              value={selectedEmployeeName} 
                              onChange={(e) => setSelectedEmployeeName(e.target.value)}
                              className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                            >
                              <option value="">Quem está acessando?</option>
                              {filteredEmployees.map(e => (
                                <option key={e.id} value={e.name}>{e.name}</option>
                              ))}
                            </select>
                          </div>
                        )}
                      </>
                    )}
                  </div>
                )}

                {/* Senha Administrativa */}
                {accessType === 'ADMIN' && (role === 'GERENCIA' || role === 'DIRETORIA') && (
                  <div className="animate-in slide-in-from-top-2">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Lock size={12} className="mr-1"/> Senha</label>
                    <input 
                      type="password"
                      placeholder="••••••••"
                      value={password}
                      onChange={(e) => { setPassword(e.target.value); setError(''); }}
                      className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-blue-400 outline-none transition-all font-bold tracking-widest text-slate-900"
                    />
                  </div>
                )}

                {error && (
                  <div className="p-4 bg-red-50 text-red-500 rounded-2xl flex items-center space-x-3 text-xs font-bold border border-red-100 animate-shake">
                    <AlertCircle size={16} />
                    <span>{error}</span>
                  </div>
                )}

                <button 
                  onClick={handleEnter}
                  disabled={isLoading}
                  className="w-full py-5 rounded-[1.5rem] font-black text-white shadow-xl transition-all active:scale-95 hover:brightness-110 disabled:opacity-50"
                  style={{ backgroundColor: getThemeColor() }}
                >
                  Entrar no Sistema
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="bg-slate-50 p-6 text-center">
          <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">© 2024 Hotel Village Gestão Inteligente</p>
        </div>
      </div>
    </div>
  );
};

