import React, { useState } from 'react';
import { InventoryItem, HotelTheme, UserRole } from '../types';
import { 
  Package, 
  Search, 
  Plus, 
  Trash2, 
  AlertTriangle, 
  TrendingDown, 
  Layers, 
  Filter,
  ArrowUpRight,
  ArrowDownRight,
  X,
  Edit2,
  CheckCircle2,
  History
