const InventoryView: React.FC<InventoryViewProps> = ({ inventory, theme, onSave, onDelete, role }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('Todos');

  // Form State
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [name, setName] = useState('');
  const [category, setCategory] = useState('Limpeza');
  const [quantity, setQuantity] = useState(0);
  const [minQuantity, setMinQuantity] = useState(0);
  const [unit, setUnit] = useState('Unidade');

  const categories = ['Limpeza', 'Rouparia', 'Amenidades', 'Escritório', 'Manutenção'];

  const resetForm = () => {
    setName('');
    setCategory('Limpeza');
    setQuantity(0);
    setMinQuantity(0);
    setUnit('Unidade');
    setEditingItem(null);
    setIsAdding(false);
  };

  const handleEdit = (item: InventoryItem) => {
    setEditingItem(item);
    setName(item.name);
    setCategory(item.category);
    setQuantity(item.quantity);
    setMinQuantity(item.minQuantity);
    setUnit(item.unit);
    setIsAdding(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;

    const newItem: InventoryItem = {
      id: editingItem?.id || Date.now().toString(),
      name,
      category,
      quantity,
      minQuantity,
      unit,
      lastUpdate: Date.now()
    };

    onSave(newItem);
    resetForm();
  };

  const filteredItems = inventory.filter(i => 
    (categoryFilter === 'Todos' || i.category === categoryFilter) &&
    i.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const lowStockItems = inventory.filter(i => i.quantity <= i.minQuantity);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center space-x-4">
           <div className="p-4 bg-blue-50 text-blue-500 rounded-2xl"><Package size={24}/></div>
           <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total de Itens</p>
              <h3 className="text-2xl font-black text-slate-800">{inventory.length}</h3>
           </div>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center space-x-4">
           <div className={`p-4 rounded-2xl ${lowStockItems.length > 0 ? 'bg-rose-50 text-rose-500' : 'bg-emerald-50 text-emerald-500'}`}>
              <AlertTriangle size={24}/>
           </div>
           <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Estoque Crítico</p>
              <h3 className={`text-2xl font-black ${lowStockItems.length > 0 ? 'text-rose-500' : 'text-emerald-500'}`}>
                {lowStockItems.length} {lowStockItems.length === 1 ? 'item' : 'itens'}
              </h3>
           </div>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center space-x-4">
           <div className="p-4 bg-amber-50 text-amber-500 rounded-2xl"><Layers size={24}/></div>
           <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Categorias</p>
              <h3 className="text-2xl font-black text-slate-800">{new Set(inventory.map(i => i.category)).size}</h3>
           </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="flex gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input 
              type="text"
              placeholder="Buscar item..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 focus:border-blue-500 outline-none shadow-sm transition-all text-sm font-bold bg-white"
            />
          </div>
          <select 
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="px-4 py-3 rounded-xl border border-slate-100 focus:border-blue-500 outline-none bg-white text-sm font-bold shadow-sm"
          >
            <option value="Todos">Todas Categorias</option>
            {categories.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>

        {role !== 'FUNCIONARIO' && (
          <button 
            onClick={() => setIsAdding(true)}
            className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
            style={{ backgroundColor: theme.primary }}
          >
            <Plus size={18} />
            <span>Cadastrar Insumo</span>
          </button>
        )}
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Item / Insumo</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Categoria</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Saldo Atual</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Mínimo</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Status</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredItems.map(item => {
                const isLow = item.quantity <= item.minQuantity;
                return (
                  <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-5">
                      <div>
                        <p className="font-black text-slate-800 leading-none mb-1">{item.name}</p>
                        <p className="text-[9px] text-slate-400 font-bold uppercase">{item.unit}</p>
                      </div>
                    </td>
                    <td className="px-8 py-5">
                       <span className="px-3 py-1 bg-slate-100 rounded-full text-[9px] font-black text-slate-500 uppercase">{item.category}</span>
                    </td>
                    <td className="px-8 py-5 text-center">
                       <p className={`text-lg font-black ${isLow ? 'text-rose-500' : 'text-slate-800'}`}>{item.quantity}</p>
                    </td>
                    <td className="px-8 py-5 text-center">
                       <p className="text-xs font-bold text-slate-400">{item.minQuantity}</p>
                    </td>
                    <td className="px-8 py-5">
                       <div className="flex justify-center">
                         {isLow ? (
                           <div className="flex items-center space-x-1.5 text-rose-500 text-[9px] font-black uppercase">
                             <AlertTriangle size={12}/> <span>Repor Já</span>
                           </div>
                         ) : (
                           <div className="flex items-center space-x-1.5 text-emerald-500 text-[9px] font-black uppercase">
                             <CheckCircle2 size={12}/> <span>Ok</span>
                           </div>
                         )}
                       </div>
                    </td>
                    <td className="px-8 py-5">
                       <div className="flex items-center justify-end space-x-2">
                         <button onClick={() => handleEdit(item)} className="p-2 text-slate-300 hover:text-blue-500 transition-colors"><Edit2 size={18}/></button>
                         {role !== 'FUNCIONARIO' && (
                           <button onClick={() => onDelete(item.id)} className="p-2 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={18}/></button>
                         )}
                       </div>
                    </td>
                  </tr>
                );
              })}
              {filteredItems.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-8 py-20 text-center text-slate-300 italic font-bold">Nenhum insumo encontrado.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">{editingItem ? 'Editar Insumo' : 'Novo Insumo'}</h2>
                 <button onClick={resetForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSubmit} className="p-8 space-y-5">
                 <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Nome do Insumo</label>
                    <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none font-bold text-slate-800 bg-white" placeholder="Ex: Sabonete 20g" />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Categoria</label>
                      <select value={category} onChange={e => setCategory(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold text-slate-800">
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Unidade de Medida</label>
                      <select value={unit} onChange={e => setUnit(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold text-slate-800">
                        <option value="Unidade">Unidade</option>
                        <option value="Caixa">Caixa</option>
                        <option value="Litro">Litro</option>
                        <option value="Kg">Kg</option>
                        <option value="Pacote">Pacote</option>
                      </select>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="bg-slate-50 p-4 rounded-2xl">
                       <label className="block text-[9px] font-black text-slate-400 uppercase mb-2">Saldo Atual</label>
                       <input type="number" value={quantity} onChange={e => setQuantity(parseInt(e.target.value) || 0)} className="w-full bg-transparent text-xl font-black text-slate-800 outline-none" />
                    </div>
                    <div className="bg-rose-50 p-4 rounded-2xl">
                       <label className="block text-[9px] font-black text-rose-400 uppercase mb-2">Aviso de Mínimo</label>
                       <input type="number" value={minQuantity} onChange={e => setMinQuantity(parseInt(e.target.value) || 0)} className="w-full bg-transparent text-xl font-black text-rose-500 outline-none" />
                    </div>
                 </div>
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all" style={{ backgroundColor: theme.primary }}>
                   {editingItem ? 'Salvar Alterações' : 'Cadastrar no Estoque'}
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default InventoryView;

