const APPS_SCRIPT_CODE = `/**
 * Google Apps Script para Gestão Hotel Village - V13 (Reflexão Total + Estoque)
 */

function doGet(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = e.parameter.hotel || 'VILLAGE';
    var result = {
      apartments: {},
      budgets: [],
      employees: [],
      sectors: [],
      inventory: []
    };

    // 1. Carregar Apartamentos
    var sheetApts = ss.getSheetByName('Apartamentos_' + hotel) || ss.getSheetByName('Apartamentos');
    if (sheetApts) {
      var data = sheetApts.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        var num = data[i][0];
        var floor = data[i][1];
        if(!num || !floor) continue;
        var aptId = floor + "-" + num;
        result.apartments[aptId] = {
          id: aptId, roomNumber: num, floor: floor, pisoType: data[i][2], pisoStatus: data[i][3],
          banheiroType: data[i][4], banheiroStatus: data[i][5], temCofre: data[i][6] === 'Sim',
          temCortina: data[i][7] === 'Sim', cortinaStatus: data[i][8], cortinaSize: data[i][9],
          cortinaCoverage: data[i][10], temEspelhoCorpo: data[i][11] === 'Sim', espelhoCorpoStatus: data[i][12],
          acBrand: data[i][13], moveisStatus: data[i][14], moveisDetalhes: data[i][15] ? JSON.parse(data[i][15]) : [],
          beds: data[i][16] ? JSON.parse(data[i][16]) : [], temPortaControle: data[i][17] === 'Sim',
          temCabide: data[i][18] === 'Sim', cabideQuantity: data[i][19] || 0, temSuportePapel: data[i][20] === 'Sim',
          temSuporteShampoo: data[i][21] === 'Sim', suporteShampooStatus: data[i][22], luminariaType: data[i][23],
          luminariaColor: data[i][24], tvBrand: data[i][25], defects: data[i][26] ? JSON.parse(data[i][26]) : []
        };
      }
    }

    // 2. Carregar Setores (Geral)
    var sheetSectors = ss.getSheetByName('Setores');
    if (sheetSectors) {
      var dataS = sheetSectors.getDataRange().getValues();
      for (var j = 1; j < dataS.length; j++) {
        if(!dataS[j][0]) continue;
        result.sectors.push({ id: dataS[j][0].toString(), name: dataS[j][1], standardUniform: dataS[j][2] ? JSON.parse(dataS[j][2]) : [] });
      }
    }

    // 3. Carregar Funcionários (Necessário para o login dinâmico)
    var sheetEmps = ss.getSheetByName('Funcionários_' + hotel) || ss.getSheetByName('Funcionários');
    if (sheetEmps) {
      var dataE = sheetEmps.getDataRange().getValues();
      for (var k = 1; k < dataE.length; k++) {
        if(!dataE[k][0]) continue;
        result.employees.push({
          id: dataE[k][0].toString(), name: dataE[k][1], role: dataE[k][2], sectorId: dataE[k][3].toString(),
          salary: dataE[k][4], startDate: dataE[k][5], vacationStatus: dataE[k][6],
          scheduleType: dataE[k][8], shiftType: dataE[k][9], workingHours: dataE[k][10],
          weeklyDayOff: dataE[k][11], monthlySundayOff: dataE[k][12], uniforms: dataE[k][15] ? JSON.parse(dataE[k][15]) : []
        });
      }
    }

    // 4. Carregar Estoque
    var sheetInv = ss.getSheetByName('Estoque_' + hotel) || ss.getSheetByName('Estoque');
    if (sheetInv) {
      var dataI = sheetInv.getDataRange().getValues();
      for (var m = 1; m < dataI.length; m++) {
        if(!dataI[m][0]) continue;
        result.inventory.push({ id: dataI[m][0].toString(), name: dataI[m][1], category: dataI[m][2], quantity: dataI[m][3], minQuantity: dataI[m][4], unit: dataI[m][5], lastUpdate: new Date(dataI[m][6]).getTime() });
      }
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var requestData = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = requestData.hotel || 'VILLAGE';
    var sheetName = '';

    if (requestData.dataType === 'BUDGET') sheetName = 'Orçamentos';
    else if (requestData.dataType === 'EMPLOYEE') sheetName = 'Funcionários_' + hotel;
    else if (requestData.dataType === 'INVENTORY') sheetName = 'Estoque_' + hotel;
    else if (requestData.dataType === 'SECTOR') sheetName = 'Setores';
    else sheetName = 'Apartamentos_' + hotel;

    var sheet = ss.getSheetByName(sheetName) || ss.insertSheet(sheetName);
    if (sheet.getLastRow() === 0) setupHeaders(sheet, requestData.dataType);

    if (requestData.dataType === 'INVENTORY') {
      var invRow = [requestData.id, requestData.name, requestData.category, requestData.quantity, requestData.minQuantity, requestData.unit, new Date()];
      upsert(sheet, requestData.id, invRow);
    } else if (requestData.dataType === 'EMPLOYEE') {
      var empRow = [requestData.id, requestData.name, requestData.role, requestData.sectorId, requestData.salary, requestData.startDate, requestData.vacationStatus, "", requestData.scheduleType, requestData.shiftType, requestData.workingHours, requestData.weeklyDayOff, requestData.monthlySundayOff, "Ativo", new Date(), JSON.stringify(requestData.uniforms || [])];
      upsert(sheet, requestData.id, empRow);
    } else if (requestData.dataType === 'SECTOR') {
      var secRow = [requestData.id, requestData.name, JSON.stringify(requestData.standardUniform || []), new Date()];
      upsert(sheet, requestData.id, secRow);
    } else if (requestData.dataType === 'APARTMENT') {
      var aptRow = [requestData.roomNumber, requestData.floor, requestData.pisoType || '', requestData.pisoStatus || '', requestData.banheiroType || '', requestData.banheiroStatus || '', requestData.temCofre ? 'Sim' : 'Não', requestData.temCortina ? 'Sim' : 'Não', requestData.cortinaStatus || '', requestData.cortinaSize || '', requestData.cortinaCoverage || '', requestData.temEspelhoCorpo ? 'Sim' : 'Não', requestData.espelhoCorpoStatus || '', requestData.acBrand || '', requestData.moveisStatus || '', JSON.stringify(requestData.moveisDetalhes || []), JSON.stringify(requestData.beds || []), requestData.temPortaControle ? 'Sim' : 'Não', requestData.temCabide ? 'Sim' : 'Não', requestData.cabideQuantity || 0, requestData.temSuportePapel ? 'Sim' : 'Não', requestData.temSuporteShampoo ? 'Sim' : 'Não', requestData.suporteShampooStatus || '', requestData.luminariaType || '', requestData.luminariaColor || '', requestData.tvBrand || '', JSON.stringify(requestData.defects || []), new Date()];
      upsert(sheet, requestData.roomNumber, aptRow);
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function setupHeaders(sheet, type) {
  var headers = [];
  if (type === 'INVENTORY') headers = ['ID', 'Item', 'Categoria', 'Saldo', 'Mínimo', 'Unidade', 'Atualizado'];
  else if (type === 'EMPLOYEE') headers = ['ID', 'Nome', 'Cargo', 'SetorID', 'Salário', 'Início', 'Férias', 'Venc', 'Escala', 'EscalaDet', 'Horário', 'Folga', 'Dom', 'Status', 'Data', 'Uniformes'];
  else if (type === 'SECTOR') headers = ['ID', 'Nome', 'Padrão', 'Data'];
  else headers = ['Apto', 'Andar', 'PisoT', 'PisoS', 'BanhT', 'BanhS', 'Cofre', 'Cortina', 'CortinaS', 'CortinaM', 'CortinaC', 'Espelho', 'EspelhoS', 'AC', 'MoveisS', 'MoveisD', 'Camas', 'PortaCont', 'Cabide', 'CabideQ', 'SuportPap', 'SuportSham', 'SuportShamS', 'LuminType', 'LuminColor', 'TV', 'Avarias', 'Atualizado'];
  sheet.appendRow(headers);
  sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#f3f3f3');
}

function upsert(sheet, id, rowData) {
  var data = sheet.getDataRange().getValues();
  var idx = -1;
  for (var i = 1; i < data.length; i++) { if (data[i][0] == id) { idx = i + 1; break; } }
  if (idx > -1) sheet.getRange(idx, 1, 1, rowData.length).setValues([rowData]);
  else sheet.appendRow(rowData);
}
`;

