const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v13');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE':
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
      case 'GOLDEN_PARK':
        return {
          primary: '#BF984E',
          secondary: '#A68444',
          accent: '#A67A44',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6']
        };
      case 'THERMAL_RESORT':
        return {
          primary: '#68A672',
          secondary: '#4B94F2',
          accent: '#B49B5D',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D']
        };
      default:
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
    }
  }, [state.currentHotel]);

  // Função para carregar dados da Planilha (Reflexão)
  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);

    const targetHotel = hotelOverride || state.currentHotel;

    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, {
        method: 'GET',
        mode: 'cors',
        credentials: 'omit',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`Status: ${response.status}`);
      const data = await response.json();

      if (data && data.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              apartments: data.data.apartments || {},
              budgets: data.data.budgets || [],
              employees: data.data.employees || [],
              inventory: data.data.inventory || [],
              sectors: data.data.sectors && data.data.sectors.length > 0 ? data.data.sectors : prev.hotels[targetHotel].sectors,
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return data.data;
      }
    } catch (error) {
      console.warn("Erro na reflexão dos dados:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [state.currentHotel]);

  // Sincroniza sempre que o hotel muda ou o app inicia
  useEffect(() => {
    loadDataFromSheet();
  }, [state.currentHotel, loadDataFromSheet]);

  useEffect(() => {
    const stateToSave = { ...state, currentUser: null };
    localStorage.setItem('hotel_village_state_v13', JSON.stringify(stateToSave));
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({
      ...prev,
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setHotel = (hotel: HotelType) => {
    if (state.currentUser?.role !== 'DIRETORIA' && state.currentUser?.role !== 'GERENCIA') return;
    setState(prev => ({ ...prev, currentHotel: hotel, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setView = (view: ViewType) => {
    if (state.currentUser?.role === 'FUNCIONARIO' && (view !== ViewType.APARTMENTS && view !== ViewType.INVENTORY)) return;
    setState(prev => ({ ...prev, currentView: view, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const selectFloor = (floor: number) => {
    setState(prev => ({ ...prev, selectedFloor: floor }));
  };

  const selectApartment = (id: string | null) => {
    setState(prev => ({ ...prev, selectedApartmentId: id }));
  };

  const selectSector = (id: string | null) => {
    setState(prev => ({ ...prev, selectedSectorId: id }));
  };

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY', data: any, files?: any[]) => {
    const integration = state.integrations[0];
    if (integration?.url) {
      try {
        await fetch(integration.url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files })
        });

        setState(prev => ({
          ...prev,
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i)
        }));
      } catch (err) {
        console.error('Falha na sincronização POST:', err);
      }
    }
  };

  const updateApartment = (apt: Apartment) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          apartments: {
            ...prev.hotels[prev.currentHotel].apartments,
            [apt.id]: apt
          }
        }
      }
    }));
    syncToSheet('APARTMENT', apt);
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.budgets.find(b => b.id === budget.id);
      const newBudgets = exists 
        ? hotel.budgets.map(b => b.id === budget.id ? budget : b)
        : [budget, ...hotel.budgets];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: newBudgets }
        }
      };
    });
    syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, budgets: hotel.budgets.filter(b => b.id !== id) }
        }
      };
    });
  };

  const handleSaveEmployee = (employee: Employee) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.employees.find(e => e.id === employee.id);
      const newEmployees = exists 
        ? hotel.employees.map(e => e.id === employee.id ? employee : e)
        : [employee, ...hotel.employees];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: newEmployees }
        }
      };
    });
    syncToSheet('EMPLOYEE', employee);
  };

  const handleDeleteEmployee = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, employees: hotel.employees.filter(e => e.id !== id) }
        }
      };
    });
  };

  const handleSaveSector = (sector: Sector) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.sectors.find(s => s.id === sector.id);
      const newSectors = exists 
        ? hotel.sectors.map(s => s.id === sector.id ? sector : s)
        : [...hotel.sectors, sector];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, sectors: newSectors }
        }
      };
    });
    syncToSheet('SECTOR', sector);
  };

  const handleDeleteSector = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { 
            ...hotel, 
            sectors: hotel.sectors.filter(s => s.id !== id),
            employees: hotel.employees.filter(e => e.sectorId !== id)
          }
        }
      };
    });
  };

  const handleSaveInventory = (item: InventoryItem) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.inventory.find(i => i.id === item.id);
      const newInventory = exists 
        ? hotel.inventory.map(i => i.id === item.id ? item : i)
        : [...hotel.inventory, item];

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, inventory: newInventory }
        }
      };
    });
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) }
        }
      };
    });
  };

  const updateIntegration = (integration: Integration) => {
    setState(prev => ({
      ...prev,
      integrations: prev.integrations.map(i => i.id === integration.id ? integration : i)
    }));
  };

  const getHotelName = (type: HotelType) => {
    switch(type) {
      case 'VILLAGE': return 'Village Inn';
      case 'GOLDEN_PARK': return 'Hotel Golden Park';
      case 'THERMAL_RESORT': return 'Thermas Resort';
      default: return 'Hotel';
    }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || {
          id: aptId,
          floor: parseInt(aptId.split('-')[0]),
          roomNumber: parseInt(aptId.split('-')[1]),
          defects: []
        };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme}
            integrationUrl={GLOBAL_SCRIPT_URL}
            onBack={() => selectApartment(null)} 
            onSave={updateApartment} 
          />
        );
      }

      if (state.selectedFloor !== null) {
        return (
          <FloorDetailView 
            floor={state.selectedFloor} 
            theme={theme}
            apartments={currentHotelData.apartments}
            onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))}
            onSelectApartment={selectApartment}
          />
        );
      }
      return <ApartmentsView onSelectFloor={selectFloor} theme={theme} hotelName={getHotelName(state.currentHotel)} />;
    }

    if (state.currentView === ViewType.BUDGETS) {
      return (
        <BudgetsView 
          budgets={currentHotelData.budgets} 
          theme={theme}
          onSave={handleSaveBudget} 
          onDelete={handleDeleteBudget}
        />
      );
    }

    if (state.currentView === ViewType.EMPLOYEES) {
      return (
        <EmployeesView 
          employees={currentHotelData.employees}
          sectors={currentHotelData.sectors}
          selectedSectorId={state.selectedSectorId}
          onSelectSector={selectSector}
          theme={theme}
          onSave={handleSaveEmployee}
          onDelete={handleDeleteEmployee}
          onSaveSector={handleSaveSector}
          onDeleteSector={handleDeleteSector}
        />
      );
    }

    if (state.currentView === ViewType.INVENTORY) {
      return (
        <InventoryView 
          inventory={currentHotelData.inventory}
          theme={theme}
          onSave={handleSaveInventory}
          onDelete={handleDeleteInventory}
          role={state.currentUser?.role}
        />
      );
    }

    if (state.currentView === ViewType.REPORTS) {
      return (
        <ReportsView 
          apartments={currentHotelData.apartments}
          theme={theme}
          onSelectApartment={(id) => {
            setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }));
          }}
        />
      );
    }

    if (state.currentView === ViewType.SETTINGS) {
      return (
        <SettingsView 
          integrations={state.integrations}
          theme={theme}
          onUpdate={updateIntegration}
        />
      );
    }

    if (state.currentView === ViewType.DASHBOARD) {
      return (
        <Dashboard 
          apartments={currentHotelData.apartments} 
          employees={currentHotelData.employees} 
          theme={theme} 
          lastSync={state.integrations[0].lastSync} 
          onRefresh={loadDataFromSheet} 
          isRefreshing={isRefreshing} 
        />
      );
    }

    return null;
  };

  if (!state.currentUser) {
    return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  }

  const isFullscreenView = state.currentView === ViewType.APARTMENTS && state.selectedApartmentId;

  const getHeaderTitle = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      return state.selectedFloor ? `Andar ${state.selectedFloor}` : 'Apartamentos';
    }
    if (state.currentView === ViewType.BUDGETS) return 'Orçamentos';
    if (state.currentView === ViewType.INVENTORY) return 'Controle de Estoque';
    if (state.currentView === ViewType.REPORTS) return 'Relatórios de Unidades';
    if (state.currentView === ViewType.EMPLOYEES) {
        if (state.selectedSectorId) {
            const sector = currentHotelData.sectors.find(s => s.id === state.selectedSectorId);
            return `Equipe: ${sector?.name || 'Setor'}`;
        }
        return 'Setores da Equipe';
    }
    if (state.currentView === ViewType.SETTINGS) return 'Configurações';
    if (state.currentView === ViewType.DASHBOARD) return 'Dashboard';
    return state.currentView;
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      {!isFullscreenView && (
        <>
          <Sidebar 
            currentView={state.currentView} 
            onViewChange={setView} 
            currentHotel={state.currentHotel}
            onHotelChange={setHotel}
            onLogout={handleLogout}
            theme={theme}
            role={state.currentUser.role}
          />
          <BottomNav 
            currentView={state.currentView}
            onViewChange={setView}
            theme={theme}
            role={state.currentUser.role}
          />
        </>
      )}

      <main className={`flex-1 transition-all duration-300 
        ${isFullscreenView ? 'p-0' : 'p-4 md:p-8'} 
        ${!isFullscreenView ? 'mb-20 md:mb-0 md:ml-64' : 'ml-0'}`}>

        {!isFullscreenView && (
          <header className="mb-6 flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm md:bg-transparent md:p-0 md:shadow-none md:mb-8">
            <div className="flex flex-col">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 md:hidden">
                {getHotelName(state.currentHotel)}
              </span>
              <h1 className="text-xl md:text-3xl font-black text-slate-800 leading-tight">
                {getHeaderTitle()}
              </h1>
            </div>

            <div className="flex items-center space-x-4">
              <button 
                onClick={() => loadDataFromSheet()}
                disabled={isRefreshing}
                className={`p-2 rounded-xl bg-slate-50 text-slate-400 transition-all ${isRefreshing ? 'animate-spin' : 'hover:bg-slate-100 hover:text-blue-500'}`}
                title="Sincronizar Planilha"
              >
                <RefreshCw size={18} />
              </button>

              <button 
                onClick={handleLogout}
                className="flex items-center space-x-3 hover:bg-slate-50 p-2 md:p-3 rounded-2xl transition-all active:scale-95 group"
                title="Sair da Conta"
              >
                <div className="text-right hidden sm:block">
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 group-hover:text-red-500 transition-colors">
                    {state.currentUser.name || state.currentUser.role}
                  </p>
                  <p className="text-[9px] font-bold text-red-500 uppercase opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-end">
                    <LogOut size={10} className="mr-1" /> Encerrar
                  </p>
                  <p className="text-xs font-bold group-hover:opacity-0 transition-opacity" style={{ color: theme.primary }}>Online</p>
                </div>
                <div 
                  className="w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg group-hover:shadow-red-200 transition-all relative"
                  style={{ backgroundColor: theme.primary, boxShadow: `0 8px 12px -3px ${theme.primary}40` }}
                >
                  {(state.currentUser.name || state.currentUser.role)[0]}
                </div>
              </button>
            </div>
          </header>
        )}

        <div className="animate-in fade-in duration-500">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

