  const [selectedFloor, setSelectedFloor] = useState<number | 'all'>('all');
  const [activeReport, setActiveReport] = useState<string>('PISO_DANIFICADO');
  const [searchTerm, setSearchTerm] = useState('');

  const floors = [200, 300, 400, 500, 600, 700];

  const reportPresets = [
    { id: 'PISO_DANIFICADO', label: 'Piso Danificado', icon: Droplets, color: 'text-rose-500', bg: 'bg-rose-50' },
    { id: 'LUMINARIA_ARANDELA', label: 'Luminária Arandela', icon: Lightbulb, color: 'text-amber-500', bg: 'bg-amber-50' },
    { id: 'TV_LG', label: 'TV LG', icon: Tv, color: 'text-blue-500', bg: 'bg-blue-50' },
    { id: 'TV_SAMSUNG', label: 'TV Samsung', icon: Tv, color: 'text-indigo-500', bg: 'bg-indigo-50' },
    { id: 'AVARIAS_GERAIS', label: 'Com Avarias', icon: AlertTriangle, color: 'text-orange-500', bg: 'bg-orange-50' },
    { id: 'BANHEIRO_ANTIGO', label: 'Banheiro Antigo', icon: Layers, color: 'text-slate-500', bg: 'bg-slate-50' }
  ];

  const filteredData = useMemo(() => {
    let list = Object.values(apartments);

    // Filter by floor
    if (selectedFloor !== 'all') {
      list = list.filter(apt => apt.floor === selectedFloor);
    }

    // Filter by preset
    switch (activeReport) {
      case 'PISO_DANIFICADO':
        list = list.filter(apt => apt.pisoStatus === 'Reparo urgente' || apt.pisoStatus === 'Tolerável');
