  tvBrand?: 'LG' | 'Samsung' | 'Philco' | 'Smart Roku' | 'Toshiba';
}

export interface HotelData {
  apartments: Record<string, Apartment>;
  budgets: Budget[];
  employees: Employee[];
  sectors: Sector[];
  inventory: InventoryItem[];
  inventoryHistory: InventoryOperation[];
}

export interface AppState {
  currentView: ViewType;
  currentHotel: HotelType;
  hotels: Record<HotelType, HotelData>;
  selectedFloor: number | null;
  selectedApartmentId: string | null;
  selectedSectorId: string | null;
  integrations: Integration[];
  currentUser: User | null;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector, InventoryItem, InventoryOperation } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';
import { LogOut, RefreshCw } from 'lucide-react';

// URL fornecida pelo usuário para integração direta
const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwLZEB6qtG__uXIrkpQYhbG40lHXjAkNQ-QQ5IDmIC5YsFZiUYPWv6F3ciXqYx97gBy/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  inventory: [],
  inventoryHistory: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v14');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE':
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
      case 'GOLDEN_PARK':
        return {
          primary: '#BF984E',
          secondary: '#A68444',
          accent: '#A67A44',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6']
        };
      case 'THERMAL_RESORT':
        return {
          primary: '#68A672',
          secondary: '#4B94F2',
          accent: '#B49B5D',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D']
        };
      default:
        return {
          primary: '#26A6A6',
          secondary: '#34BFA6',
          accent: '#29D9A7',
          bg: '#F8FAFC',
          text: '#1E293B',
          chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373']
        };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);

    const targetHotel = hotelOverride || state.currentHotel;

    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, {
        method: 'GET',
        mode: 'cors',
        credentials: 'omit',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`Status: ${response.status}`);
      const data = await response.json();

      if (data && data.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              apartments: data.data.apartments || {},
              budgets: data.data.budgets || [],
              employees: data.data.employees || [],
              inventory: data.data.inventory || [],
              inventoryHistory: data.data.inventoryHistory || [],
              sectors: data.data.sectors && data.data.sectors.length > 0 ? data.data.sectors : prev.hotels[targetHotel].sectors,
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return data.data;
      }
    } catch (error) {
      console.warn("Erro na reflexão dos dados:", error);
    } finally {
      setIsRefreshing(false);
    }
  }, [state.currentHotel]);

  useEffect(() => {
    loadDataFromSheet();
  }, [state.currentHotel, loadDataFromSheet]);

  useEffect(() => {
    const stateToSave = { ...state, currentUser: null };
    localStorage.setItem('hotel_village_state_v14', JSON.stringify(stateToSave));
  }, [state]);

  const handleLogin = (user: User) => {
    setState(prev => ({
      ...prev,
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD
    }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setHotel = (hotel: HotelType) => {
    if (state.currentUser?.role !== 'DIRETORIA' && state.currentUser?.role !== 'GERENCIA') return;
    setState(prev => ({ ...prev, currentHotel: hotel, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const setView = (view: ViewType) => {
    if (state.currentUser?.role === 'FUNCIONARIO' && (view !== ViewType.APARTMENTS && view !== ViewType.INVENTORY)) return;
    setState(prev => ({ ...prev, currentView: view, selectedFloor: null, selectedApartmentId: null, selectedSectorId: null }));
  };

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP', data: any, files?: any[]) => {
    const integration = state.integrations[0];
    if (integration?.url) {
      try {
        await fetch(integration.url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files })
        });

        setState(prev => ({
          ...prev,
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i)
        }));
      } catch (err) {
        console.error('Falha na sincronização POST:', err);
      }
    }
  };

  const updateApartment = (apt: Apartment) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          apartments: { ...prev.hotels[prev.currentHotel].apartments, [apt.id]: apt }
        }
      }
    }));
    syncToSheet('APARTMENT', apt);
  };

  const handleSaveBudget = (budget: Budget, newFiles?: any[]) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.budgets.find(b => b.id === budget.id);
      const newBudgets = exists ? hotel.budgets.map(b => b.id === budget.id ? budget : b) : [budget, ...hotel.budgets];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, budgets: newBudgets } } };
    });
    syncToSheet('BUDGET', budget, newFiles);
  };

  const handleDeleteBudget = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, budgets: hotel.budgets.filter(b => b.id !== id) } } };
    });
  };

  const handleSaveEmployee = (employee: Employee) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.employees.find(e => e.id === employee.id);
      const newEmployees = exists ? hotel.employees.map(e => e.id === employee.id ? employee : e) : [employee, ...hotel.employees];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, employees: newEmployees } } };
    });
    syncToSheet('EMPLOYEE', employee);
  };

  const handleDeleteEmployee = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, employees: hotel.employees.filter(e => e.id !== id) } } };
    });
  };

  const handleSaveSector = (sector: Sector) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.sectors.find(s => s.id === sector.id);
      const newSectors = exists ? hotel.sectors.map(s => s.id === sector.id ? sector : s) : [...hotel.sectors, sector];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, sectors: newSectors } } };
    });
    syncToSheet('SECTOR', sector);
  };

  const handleDeleteSector = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, sectors: hotel.sectors.filter(s => s.id !== id), employees: hotel.employees.filter(e => e.sectorId !== id) } } };
    });
  };

  const handleSaveInventory = (item: InventoryItem) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.inventory.find(i => i.id === item.id);
      const newInventory = exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: newInventory } } };
    });
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } };
    });
  };

  const handleInventoryOperation = (op: InventoryOperation) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const item = hotel.inventory.find(i => i.id === op.itemId);
      if (!item) return prev;

      const newQuantity = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity;
      const updatedItem = { ...item, quantity: newQuantity, lastUpdate: Date.now() };

      return {
        ...prev,
        hotels: {
          ...prev.hotels,
          [prev.currentHotel]: {
            ...hotel,
            inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i),
            inventoryHistory: [op, ...hotel.inventoryHistory]
          }
        }
      };
    });
    syncToSheet('INVENTORY_OP', op);
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return <ApartmentDetailView apartment={apt} theme={theme} integrationUrl={GLOBAL_SCRIPT_URL} onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} onSave={updateApartment} />;
      }
      if (state.selectedFloor !== null) {
        return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      }
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }
    if (state.currentView === ViewType.BUDGETS) return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={handleSaveBudget} onDelete={handleDeleteBudget} />;
    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={handleSaveEmployee} onDelete={handleDeleteEmployee} onSaveSector={handleSaveSector} onDeleteSector={handleDeleteSector} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} theme={theme} onSave={handleSaveInventory} onDelete={handleDeleteInventory} onOperation={handleInventoryOperation} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} theme={theme} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;

  const isFullscreenView = state.currentView === ViewType.APARTMENTS && state.selectedApartmentId;

  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      {!isFullscreenView && (
        <>
          <Sidebar currentView={state.currentView} onViewChange={setView} currentHotel={state.currentHotel} onHotelChange={setHotel} onLogout={handleLogout} theme={theme} role={state.currentUser.role} />
          <BottomNav currentView={state.currentView} onViewChange={setView} theme={theme} role={state.currentUser.role} />
        </>
      )}
      <main className={`flex-1 transition-all duration-300 ${isFullscreenView ? 'p-0' : 'p-4 md:p-8'} ${!isFullscreenView ? 'mb-20 md:mb-0 md:ml-64' : 'ml-0'}`}>
        {!isFullscreenView && (
          <header className="mb-6 flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm md:bg-transparent md:p-0 md:shadow-none md:mb-8">
            <h1 className="text-xl md:text-3xl font-black text-slate-800 leading-tight">
              {state.currentView === ViewType.INVENTORY ? 'Estoque' : state.currentView}
            </h1>
            <div className="flex items-center space-x-4">
              <button onClick={() => loadDataFromSheet()} disabled={isRefreshing} className={`p-2 rounded-xl bg-slate-50 text-slate-400 ${isRefreshing ? 'animate-spin' : ''}`}><RefreshCw size={18} /></button>
              <div className="text-right hidden sm:block">
                <p className="text-[10px] font-black uppercase text-slate-900">{state.currentUser.name || state.currentUser.role}</p>
                <p className="text-xs font-bold" style={{ color: theme.primary }}>Online</p>
              </div>
            </div>
          </header>
        )}
        <div className="animate-in fade-in duration-500">{renderContent()}</div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { InventoryItem, InventoryOperation, HotelTheme, UserRole } from '../types';
import { 
  Package, 
  Search, 
  Plus, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Filter,
  X,
  Edit2,
  CheckCircle2,
  ArrowUpRight,
  ArrowDownRight,
  History,
  ShoppingCart,
  PlusCircle,
  MinusCircle,
  Calendar,
  User as UserIcon,
  Tag
} from 'lucide-react';

interface InventoryViewProps {
  inventory: InventoryItem[];
  history: InventoryOperation[];
  theme: HotelTheme;
  onSave: (item: InventoryItem) => void;
  onDelete: (id: string) => void;
  onOperation: (op: InventoryOperation) => void;
  role?: UserRole;
  currentUser?: string;
}

const InventoryView: React.FC<InventoryViewProps> = ({ 
  inventory, 
  history, 
  theme, 
  onSave, 
  onDelete, 
  onOperation, 
  role,
  currentUser 
}) => {
  const [activeTab, setActiveTab] = useState<'ESTOQUE' | 'OPERACAO' | 'SUGESTAO'>('ESTOQUE');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isAddingOp, setIsAddingOp] = useState(false);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('Todos');

  // Form States (Item)
  const [name, setName] = useState('');
  const [category, setCategory] = useState('Limpeza');
  const [initialQuantity, setInitialQuantity] = useState(0);
  const [minQuantity, setMinQuantity] = useState(0);
  const [unit, setUnit] = useState('Unidade');

  // Form States (Operation)
  const [opItemId, setOpItemId] = useState('');
  const [opType, setOpType] = useState<'Entrada' | 'Saída'>('Entrada');
  const [opQuantity, setOpQuantity] = useState(0);
  const [opReason, setOpReason] = useState('');

  const categories = ['Limpeza', 'Rouparia', 'Amenidades', 'Escritório', 'Manutenção'];

  const resetItemForm = () => {
    setName(''); setCategory('Limpeza'); setInitialQuantity(0); setMinQuantity(0); setUnit('Unidade');
    setEditingItem(null); setIsAddingItem(false);
  };

  const resetOpForm = () => {
    setOpItemId(''); setOpType('Entrada'); setOpQuantity(0); setOpReason('');
    setIsAddingOp(false);
  };

  const handleEditItem = (item: InventoryItem) => {
    setEditingItem(item); setName(item.name); setCategory(item.category);
    setInitialQuantity(item.quantity); setMinQuantity(item.minQuantity); setUnit(item.unit);
    setIsAddingItem(true);
  };

  const handleSaveItemSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    onSave({
      id: editingItem?.id || Date.now().toString(),
      name, category, quantity: initialQuantity, minQuantity, unit,
      lastUpdate: Date.now()
    });
    resetItemForm();
  };

  const handleOpSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!opItemId || opQuantity <= 0) return;
    const selectedItem = inventory.find(i => i.id === opItemId);
    if (!selectedItem) return;

    onOperation({
      id: Date.now().toString(),
      itemId: opItemId,
      itemName: selectedItem.name,
      type: opType,
      quantity: opQuantity,
      timestamp: Date.now(),
      user: currentUser || 'Sistema',
      reason: opReason
    });
    resetOpForm();
  };

  const filteredItems = useMemo(() => inventory.filter(i => 
    (categoryFilter === 'Todos' || i.category === categoryFilter) &&
    i.name.toLowerCase().includes(searchTerm.toLowerCase())
  ), [inventory, categoryFilter, searchTerm]);

  const suggestions = useMemo(() => inventory.filter(i => i.quantity <= i.minQuantity), [inventory]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">

      {/* Tab Navigation */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm max-w-2xl mx-auto mb-8">
        {[
          { id: 'ESTOQUE', label: 'Estoque Atual', icon: Package },
          { id: 'OPERACAO', label: 'Entradas e Saídas', icon: History },
          { id: 'SUGESTAO', label: 'Sugestão de Pedido', icon: ShoppingCart }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 flex items-center justify-center space-x-2 py-3 px-4 rounded-xl text-xs font-black uppercase transition-all ${
              activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'
            }`}
          >
            <tab.icon size={16} />
            <span className="hidden sm:inline">{tab.label}</span>
          </button>
        ))}
      </div>

      {activeTab === 'ESTOQUE' && (
        <div className="space-y-6 animate-in slide-in-from-bottom-2">
          <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
            <div className="flex gap-3 w-full md:w-auto">
              <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
