                       <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Motivo / Notas</label>
                       <input type="text" value={opReason} onChange={e => setOpReason(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold text-slate-800" placeholder="Ex: Consumo governança, Reposição fornecedor..." />
