              <h3 className="text-xl font-black text-slate-800">Apps Script V14 (Estoque Full)</h3>
              <button onClick={() => setShowScriptModal(false)} className="p-3 text-slate-400"><XCircle size={32} /></button>
            </div>
            <div className="p-8 overflow-y-auto flex-1">
              <pre className="bg-slate-950 text-blue-400 p-10 rounded-[2.5rem] overflow-x-auto text-[10px] font-mono border border-slate-800">{APPS_SCRIPT_CODE}</pre>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

