  Package, 
  Search, 
  Plus, 
  Trash2, 
  AlertTriangle, 
  Layers, 
  Filter,
  X,
  Edit2,
  CheckCircle2,
  ArrowUpRight,
  ArrowDownRight,
  History,
  ShoppingCart,
  PlusCircle,
  MinusCircle,
  Calendar,
  User as UserIcon,
