  Barcode
} from 'lucide-react';

interface InventoryViewProps {
  inventory: InventoryItem[];
  history: InventoryOperation[];
  theme: HotelTheme;
  onSave: (item: InventoryItem) => void;
  onDelete: (id: string) => void;
  onOperation: (op: InventoryOperation) => void;
  role?: UserRole;
  currentUser?: string;
}

const InventoryView: React.FC<InventoryViewProps> = ({ 
  inventory, 
  history, 
  theme, 
  onSave, 
  onDelete, 
  onOperation, 
  role,
  currentUser 
}) => {
  const [activeTab, setActiveTab] = useState<'ESTOQUE' | 'OPERACAO' | 'SUGESTAO'>('ESTOQUE');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isAddingOp, setIsAddingOp] = useState(false);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('Todos');

  // Form States (Item)
  const [name, setName] = useState('');
  const [ean, setEan] = useState('');
  const [category, setCategory] = useState('Limpeza');
  const [initialQuantity, setInitialQuantity] = useState(0);
  const [minQuantity, setMinQuantity] = useState(0);
  const [unit, setUnit] = useState('Unidade');

  // Form States (Operation)
  const [opItemId, setOpItemId] = useState('');
  const [opType, setOpType] = useState<'Entrada' | 'Saída'>('Entrada');
  const [opQuantity, setOpQuantity] = useState(0);
  const [opReason, setOpReason] = useState('');

  const categories = ['Limpeza', 'Rouparia', 'Amenidades', 'Escritório', 'Manutenção'];

  const resetItemForm = () => {
    setName(''); setEan(''); setCategory('Limpeza'); setInitialQuantity(0); setMinQuantity(0); setUnit('Unidade');
    setEditingItem(null); setIsAddingItem(false);
  };

  const resetOpForm = () => {
    setOpItemId(''); setOpType('Entrada'); setOpQuantity(0); setOpReason('');
    setIsAddingOp(false);
  };

  const handleEditItem = (item: InventoryItem) => {
    setEditingItem(item); setName(item.name); setEan(item.ean || ''); setCategory(item.category);
    setInitialQuantity(item.quantity); setMinQuantity(item.minQuantity); setUnit(item.unit);
    setIsAddingItem(true);
  };

  const handleSaveItemSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    onSave({
      id: editingItem?.id || Date.now().toString(),
      ean,
      name, category, quantity: initialQuantity, minQuantity, unit,
      lastUpdate: Date.now()
    });
    resetItemForm();
  };

  const handleOpSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!opItemId || opQuantity <= 0) return;
    const selectedItem = inventory.find(i => i.id === opItemId);
    if (!selectedItem) return;

    onOperation({
      id: Date.now().toString(),
      itemId: opItemId,
      itemName: selectedItem.name,
      type: opType,
      quantity: opQuantity,
      timestamp: Date.now(),
      user: currentUser || 'Sistema',
      reason: opReason
    });
    resetOpForm();
  };

  const filteredItems = useMemo(() => inventory.filter(i => 
    (categoryFilter === 'Todos' || i.category === categoryFilter) &&
    (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || (i.ean && i.ean.includes(searchTerm)))
  ), [inventory, categoryFilter, searchTerm]);

  const suggestions = useMemo(() => inventory.filter(i => i.quantity <= i.minQuantity), [inventory]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">

      {/* Tab Navigation */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm max-w-2xl mx-auto mb-8">
        {[
          { id: 'ESTOQUE', label: 'Estoque Atual', icon: Package },
          { id: 'OPERACAO', label: 'Entradas e Saídas', icon: History },
          { id: 'SUGESTAO', label: 'Sugestão de Pedido', icon: ShoppingCart }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex-1 flex items-center justify-center space-x-2 py-3 px-4 rounded-xl text-xs font-black uppercase transition-all ${
              activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'
            }`}
          >
            <tab.icon size={16} />
            <span className="hidden sm:inline">{tab.label}</span>
          </button>
        ))}
      </div>

      {activeTab === 'ESTOQUE' && (
        <div className="space-y-6 animate-in slide-in-from-bottom-2">
          <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
            <div className="flex gap-3 w-full md:w-auto">
              <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input type="text" placeholder="Buscar por nome ou EAN..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 outline-none text-sm font-bold bg-white" />
              </div>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="px-4 py-3 rounded-xl border border-slate-100 outline-none bg-white text-sm font-bold">
                <option value="Todos">Categorias</option>
                {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div className="flex gap-2 w-full md:w-auto">
               <button onClick={() => setIsAddingOp(true)} className="flex-1 md:w-auto border-2 border-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 bg-white transition-all active:scale-95">
                 <PlusCircle size={18} />
                 <span>Movimentação</span>
               </button>
               {role !== 'FUNCIONARIO' && (
                 <button onClick={() => setIsAddingItem(true)} className="flex-1 md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95" style={{ backgroundColor: theme.primary }}>
                   <Plus size={18} />
                   <span>Novo Item</span>
                 </button>
               )}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Insumo / EAN</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Saldo</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Mínimo</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Status</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredItems.map(item => {
                  const isLow = item.quantity <= item.minQuantity;
                  return (
                    <tr key={item.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-8 py-5">
                        <p className="font-black text-slate-800 leading-tight">{item.name}</p>
                        {item.ean && (
                          <p className="text-[9px] text-blue-500 font-bold uppercase flex items-center mt-0.5">
                            <Barcode size={10} className="mr-1" /> {item.ean}
                          </p>
                        )}
                        <p className="text-[9px] text-slate-400 font-bold uppercase">{item.category} • {item.unit}</p>
                      </td>
                      <td className="px-8 py-5 text-center">
                        <span className={`text-lg font-black ${isLow ? 'text-rose-500' : 'text-slate-800'}`}>{item.quantity}</span>
                      </td>
                      <td className="px-8 py-5 text-center text-xs font-bold text-slate-400">{item.minQuantity}</td>
                      <td className="px-8 py-5">
                        <div className="flex justify-center">
                          {isLow ? <span className="flex items-center text-rose-500 text-[9px] font-black uppercase bg-rose-50 px-3 py-1 rounded-full"><AlertTriangle size={12} className="mr-1"/> Repor</span> : <span className="flex items-center text-emerald-500 text-[9px] font-black uppercase bg-emerald-50 px-3 py-1 rounded-full"><CheckCircle2 size={12} className="mr-1"/> OK</span>}
                        </div>
                      </td>
                      <td className="px-8 py-5 text-right">
                        <button onClick={() => handleEditItem(item)} className="p-2 text-slate-300 hover:text-blue-500"><Edit2 size={18}/></button>
                        {role !== 'FUNCIONARIO' && <button onClick={() => onDelete(item.id)} className="p-2 text-slate-300 hover:text-rose-500 ml-2"><Trash2 size={18}/></button>}
                      </td>
                    </tr>
                  );
                })}
                {filteredItems.length === 0 && (
                   <tr>
                     <td colSpan={5} className="px-8 py-20 text-center text-slate-300 italic font-bold">Nenhum item encontrado.</td>
                   </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'OPERACAO' && (
        <div className="space-y-6 animate-in slide-in-from-right-4">
           <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
              <div className="flex items-center justify-between mb-8">
                 <h3 className="text-xl font-black text-slate-800 flex items-center"><History size={24} className="mr-3 text-slate-400"/> Histórico de Movimentações</h3>
                 <button onClick={() => setIsAddingOp(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg">Nova Operação</button>
              </div>
              <div className="space-y-4">
                 {history.length === 0 ? (
                    <p className="text-center py-20 text-slate-300 italic font-bold">Nenhuma movimentação registrada.</p>
                 ) : (
                    history.map(op => (
                       <div key={op.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <div className="flex items-center space-x-4">
                             <div className={`p-3 rounded-xl ${op.type === 'Entrada' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                                {op.type === 'Entrada' ? <ArrowUpRight size={20}/> : <ArrowDownRight size={20}/>}
                             </div>
                             <div>
                                <p className="font-black text-slate-800">{op.itemName}</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase flex items-center">
                                   <UserIcon size={10} className="mr-1"/> {op.user} • <Calendar size={10} className="mx-1"/> {new Date(op.timestamp).toLocaleString()}
                                </p>
                             </div>
                          </div>
                          <div className="text-right">
                             <p className={`text-lg font-black ${op.type === 'Entrada' ? 'text-emerald-500' : 'text-rose-500'}`}>
                                {op.type === 'Entrada' ? '+' : '-'}{op.quantity}
                             </p>
                             {op.reason && <p className="text-[9px] text-slate-400 font-medium">{op.reason}</p>}
                          </div>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>
      )}

      {activeTab === 'SUGESTAO' && (
        <div className="space-y-6 animate-in slide-in-from-left-4">
           <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
              <div className="mb-8">
                 <h3 className="text-xl font-black text-slate-800 flex items-center"><ShoppingCart size={24} className="mr-3 text-emerald-500"/> Sugestão Inteligente de Pedido</h3>
                 <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Calculado com base no estoque mínimo configurado</p>
              </div>

              {suggestions.length === 0 ? (
                 <div className="text-center py-20 bg-slate-50 rounded-3xl">
                    <CheckCircle2 size={48} className="mx-auto text-emerald-400 mb-4"/>
                    <p className="text-slate-400 font-bold italic">Todos os itens estão acima do estoque mínimo.</p>
                 </div>
              ) : (
                 <div className="space-y-4">
                    {suggestions.map(item => {
                       const needed = Math.max(0, (item.minQuantity * 1.5) - item.quantity); 
                       return (
                          <div key={item.id} className="flex items-center justify-between p-6 bg-rose-50 rounded-2xl border border-rose-100">
                             <div className="flex items-center space-x-4">
                                <div className="p-4 bg-white rounded-2xl text-rose-500 shadow-sm"><AlertTriangle size={24}/></div>
                                <div>
                                   <p className="font-black text-slate-800">{item.name}</p>
                                   <p className="text-[9px] text-rose-400 font-black uppercase tracking-widest">Estoque Crítico: {item.quantity} {item.unit}</p>
                                </div>
                             </div>
                             <div className="text-right bg-white p-4 rounded-2xl shadow-sm min-w-[140px] border border-rose-100">
                                <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest mb-1">Pedido Sugerido</p>
                                <p className="text-xl font-black text-slate-800">{Math.ceil(needed)} <span className="text-xs">{item.unit}</span></p>
                             </div>
                          </div>
                       );
                    })}
                 </div>
              )}
           </div>
        </div>
      )}

      {/* Item Modal */}
      {isAddingItem && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">{editingItem ? 'Editar Insumo' : 'Novo Insumo'}</h2>
                 <button onClick={resetItemForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
