              <h3 className="text-xl font-black text-slate-800">Apps Script V15 (Estoque com EAN)</h3>
              <button onClick={() => setShowScriptModal(false)} className="p-3 hover:bg-slate-100 rounded-full transition-colors text-slate-400"><XCircle size={32} /></button>
            </div>
            <div className="p-8 overflow-y-auto flex-1">
              <div className="relative">
                <button onClick={copyToClipboard} className="absolute top-4 right-4 p-3 bg-slate-900 text-white rounded-2xl shadow-xl flex items-center space-x-2 text-[10px] font-black uppercase">
                  <Copy size={16} />
                  <span>Copiar Código V15</span>
                </button>
                <pre className="bg-slate-950 text-blue-400 p-10 rounded-[2.5rem] overflow-x-auto text-[10px] leading-relaxed font-mono shadow-inner border border-slate-800">
                  {APPS_SCRIPT_CODE}
                </pre>
