                       </div>
                       <div className="p-4 bg-slate-50 rounded-2xl">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">R$ Valor Unitário</label>
                          <input type="number" step="0.01" value={price} onChange={e => setPrice(parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-xl font-black outline-none" />
                       </div>
                    </div>
                    <p className="text-[9px] text-slate-400 italic font-bold text-center py-2 px-4 bg-slate-50 rounded-xl">O sistema sugerirá compras baseadas no ciclo de cada fornecedor.</p>
                 </div>
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Salvar Cadastro</button>
              </form>
           </div>
        </div>
      )}

      {/* Supplier Modal */}
      {isAddingSupplier && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Cadastrar Fornecedor</h2>
                 <button onClick={() => setIsAddingSupplier(false)} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveSupplierSubmit} className="p-8 space-y-4">
                 <input type="text" value={supName} onChange={e => setSupName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Nome da Empresa" required />
                 <input type="text" value={supContact} onChange={e => setSupContact(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Contato (WhatsApp/Email)" />
                 <input type="text" value={supCategory} onChange={e => setSupCategory(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 outline-none font-bold" placeholder="Categoria (Ex: Alimentos, Limpeza...)" />
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Cadastrar Fornecedor</button>
              </form>
           </div>
        </div>
      )}

      {/* Operation Modal */}
      {isAddingOp && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Lançar Movimentação</h2>
                 <button onClick={() => setIsAddingOp(false)} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
              </div>
              <form onSubmit={(e) => {
                e.preventDefault();
                const selectedItem = inventory.find(i => i.id === opItemId);
                if (!selectedItem || opQuantity <= 0) return;
                onOperation({ id: Date.now().toString(), itemId: opItemId, itemName: selectedItem.name, type: opType, quantity: opQuantity, timestamp: Date.now(), user: currentUser || 'Sistema', reason: opReason });
                setIsAddingOp(false); setOpItemId(''); setOpQuantity(0); setOpReason('');
              }} className="p-8 space-y-6">
                 <div className="space-y-4">
                    <select value={opItemId} onChange={e => setOpItemId(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold" required>
                       <option value="">Selecione o insumo...</option>
                       {inventory.map(i => <option key={i.id} value={i.id}>{i.name} (Saldo: {i.quantity})</option>)}
                    </select>
                    <div className="grid grid-cols-2 gap-4">
                       <div className="flex bg-slate-50 p-1 rounded-xl">
                          <button type="button" onClick={() => setOpType('Entrada')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase ${opType === 'Entrada' ? 'bg-white shadow-sm text-emerald-500' : 'text-slate-400'}`}>Entrada</button>
                          <button type="button" onClick={() => setOpType('Saída')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase ${opType === 'Saída' ? 'bg-white shadow-sm text-rose-500' : 'text-slate-400'}`}>Saída</button>
                       </div>
                       <input type="number" value={opQuantity} onChange={e => setOpQuantity(parseInt(e.target.value) || 0)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold" placeholder="Qtd" />
                    </div>
                    <input type="text" value={opReason} onChange={e => setOpReason(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold" placeholder="Motivo / Notas" />
                 </div>
                 <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl" style={{ backgroundColor: theme.primary }}>Confirmar Movimentação</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

