  apartments: {},
  budgets: [],
  employees: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v17');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);
    const targetHotel = hotelOverride || state.currentHotel;
    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, { method: 'GET', mode: 'cors' });
      const data = await response.json();
      if (data && data.status === 'success') {
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              apartments: data.data.apartments || {},
              budgets: data.data.budgets || [],
              employees: data.data.employees || [],
              inventory: data.data.inventory || [],
              inventoryHistory: data.data.inventoryHistory || [],
              suppliers: data.data.suppliers || [],
              sectors: data.data.sectors && data.data.sectors.length > 0 ? data.data.sectors : prev.hotels[targetHotel].sectors,
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
      }
    } catch (error) { console.warn("Erro na reflexão:", error); } finally { setIsRefreshing(false); }
  }, [state.currentHotel]);

  useEffect(() => { loadDataFromSheet(); }, [state.currentHotel, loadDataFromSheet]);

  useEffect(() => { 
    const stateToSave = { ...state, currentUser: null }; 
    localStorage.setItem('hotel_village_state_v17', JSON.stringify(stateToSave)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    const integration = state.integrations[0];
    if (integration?.url) {
      try {
        await fetch(integration.url, { method: 'POST', mode: 'no-cors', body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files }) });
        setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));
        // Se for uma alteração crítica, recarregar após um delay para garantir espelhamento
        if(dataType === 'DELETE' || dataType === 'INVENTORY_OP') setTimeout(() => loadDataFromSheet(), 2000);
      } catch (err) { console.error('Falha na sincronização:', err); }
    }
  };

  const handleUpdateConfig = (config: any) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } }
      }
    }));
    syncToSheet('CONFIG', config);
  };

  const handleSaveInventory = (item: InventoryItem) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.inventory.find(i => i.id === item.id);
      const newInventory = exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: newInventory } } };
    });
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'INVENTORY', id });
  };

  const handleSaveSupplier = (supplier: Supplier) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.suppliers.find(s => s.id === supplier.id);
      const newSuppliers = exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: newSuppliers } } };
    });
    syncToSheet('SUPPLIER', supplier);
  };

  const handleDeleteSupplier = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'SUPPLIER', id });
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return <ApartmentDetailView apartment={apt} theme={theme} integrationUrl={GLOBAL_SCRIPT_URL} onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} onSave={(apt) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], apartments: {...prev.hotels[prev.currentHotel].apartments, [apt.id]: apt}}}})); syncToSheet('APARTMENT', apt); }} />;
      }
      if (state.selectedFloor !== null) {
        return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      }
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }
    if (state.currentView === ViewType.BUDGETS) return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={(b, f) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], budgets: prev.hotels[prev.currentHotel].budgets.find(ex => ex.id === b.id) ? prev.hotels[prev.currentHotel].budgets.map(ex => ex.id === b.id ? b : ex) : [b, ...prev.hotels[prev.currentHotel].budgets]}}})); syncToSheet('BUDGET', b, f); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], budgets: prev.hotels[prev.currentHotel].budgets.filter(b => b.id !== id)}}})); syncToSheet('DELETE', { targetType: 'BUDGET', id }); }} />;
    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={handleSaveInventory} onDelete={handleDeleteInventory} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const newQuantity = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity; const updatedItem = { ...item, quantity: newQuantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={handleUpdateConfig} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} currentHotel={state.currentHotel} onHotelChange={h => setState(prev => ({...prev, currentHotel: h}))} onLogout={() => setState(prev => ({...prev, currentUser: null}))} theme={theme} role={state.currentUser.role} />
      <BottomNav currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} theme={theme} role={state.currentUser.role} />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { InventoryItem, InventoryOperation, HotelTheme, UserRole, Supplier } from '../types';
import { 
  Package, 
  Search, 
  Plus, 
  Trash2, 
  X,
  Edit2,
  CheckCircle2,
  ArrowUpRight,
  ArrowDownRight,
  History,
  ShoppingCart,
  PlusCircle,
  Calendar,
  User as UserIcon,
  Barcode,
  Truck,
  DollarSign,
  Briefcase
} from 'lucide-react';

interface InventoryViewProps {
  inventory: InventoryItem[];
  history: InventoryOperation[];
  suppliers: Supplier[];
  showSuppliersTab?: boolean;
  theme: HotelTheme;
  onSave: (item: InventoryItem) => void;
  onDelete: (id: string) => void;
  onOperation: (op: InventoryOperation) => void;
  onSaveSupplier: (supplier: Supplier) => void;
  onDeleteSupplier: (id: string) => void;
  role?: UserRole;
  currentUser?: string;
}

const InventoryView: React.FC<InventoryViewProps> = ({ 
  inventory, 
  history, 
  suppliers,
  showSuppliersTab = true,
  theme, 
  onSave, 
  onDelete, 
  onOperation, 
  onSaveSupplier, 
  onDeleteSupplier,
  role,
  currentUser 
}) => {
  const [activeTab, setActiveTab] = useState<'ESTOQUE' | 'OPERACAO' | 'SUGESTAO' | 'FORNECEDORES'>('ESTOQUE');
  const [isAddingItem, setIsAddingItem] = useState(false);
  const [isAddingOp, setIsAddingOp] = useState(false);
  const [isAddingSupplier, setIsAddingSupplier] = useState(false);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [editingSupplier, setEditingSupplier] = useState<Supplier | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('Todos');

  // Form Item
  const [name, setName] = useState('');
  const [ean, setEan] = useState('');
  const [category, setCategory] = useState('Limpeza');
  const [initialQuantity, setInitialQuantity] = useState(0);
  const [unit, setUnit] = useState('Unidade');
  const [price, setPrice] = useState(0);
  const [supplierId, setSupplierId] = useState('');

  // Form Operation - Busca Preditiva
  const [opSearchQuery, setOpSearchQuery] = useState('');
  const [opItemId, setOpItemId] = useState('');
  const [opType, setOpType] = useState<'Entrada' | 'Saída'>('Entrada');
  const [opQuantity, setOpQuantity] = useState(0);
  const [opReason, setOpReason] = useState('');
  const [isSearchDropdownOpen, setIsSearchDropdownOpen] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  const categories = ['Limpeza', 'Rouparia', 'Amenidades', 'Escritório', 'Manutenção'];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setIsSearchDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const calculateOrderSuggestion = (item: InventoryItem) => {
    const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
    const itemExits = history.filter(op => op.itemId === item.id && op.type === 'Saída' && op.timestamp > thirtyDaysAgo);
    const totalExited = itemExits.reduce((acc, curr) => acc + curr.quantity, 0);
    const mcd = totalExited / 30;
    const supplier = suppliers.find(s => s.id === item.supplierId);
    const isVMarketing = supplier?.name.toLowerCase().includes('v-marketing');
    const targetDays = isVMarketing ? 12 : 8;
    const targetStock = Math.ceil(mcd * targetDays);
    const suggestedQuantity = Math.max(0, targetStock - item.quantity);
    return { mcd, targetDays, targetStock, suggestedQuantity, isVMarketing, reason: isVMarketing ? "Ciclo de Quinta (V-Marketing): 12 dias" : "Ciclo de Quarta: 8 dias" };
  };

  const enrichedInventory = useMemo(() => inventory.map(item => {
    const suggestion = calculateOrderSuggestion(item);
    return { ...item, minQuantity: Math.ceil(suggestion.mcd * 7), suggestion, totalValue: item.quantity * (item.price || 0) };
  }), [inventory, history, suppliers]);

  const globalTotalValue = useMemo(() => enrichedInventory.reduce((acc, curr) => acc + curr.totalValue, 0), [enrichedInventory]);

  const resetItemForm = () => {
    setName(''); setEan(''); setCategory('Limpeza'); setInitialQuantity(0); setUnit('Unidade'); setPrice(0); setSupplierId('');
    setEditingItem(null); setIsAddingItem(false);
  };

  const handleSaveItemSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ id: editingItem?.id || Date.now().toString(), ean, name, category, quantity: initialQuantity, unit, price, supplierId, minQuantity: 0, lastUpdate: Date.now() });
    resetItemForm();
  };

  const handleSaveSupplierSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSaveSupplier({ id: editingSupplier?.id || Date.now().toString(), name: supName, contact: supContact, category: supCategory });
    setSupName(''); setSupContact(''); setSupCategory(''); setIsAddingSupplier(false); setEditingSupplier(null);
  };

  const filteredItems = useMemo(() => enrichedInventory.filter(i => 
    (categoryFilter === 'Todos' || i.category === categoryFilter) &&
    (i.name.toLowerCase().includes(searchTerm.toLowerCase()) || (i.ean && i.ean.includes(searchTerm)))
  ), [enrichedInventory, categoryFilter, searchTerm]);

  const predictiveResults = useMemo(() => {
    if (!opSearchQuery || opSearchQuery.length < 2) return [];
    return inventory.filter(i => 
      i.name.toLowerCase().includes(opSearchQuery.toLowerCase()) || 
      (i.ean && i.ean.includes(opSearchQuery))
    ).slice(0, 5);
  }, [inventory, opSearchQuery]);

  const suggestedOrders = useMemo(() => enrichedInventory.filter(i => i.suggestion.suggestedQuantity > 0), [enrichedInventory]);

  const handleSelectPredictiveItem = (item: InventoryItem) => {
    setOpItemId(item.id);
    setOpSearchQuery(item.name);
    setIsSearchDropdownOpen(false);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">

      {/* Header com Valor Total */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
         <div className="flex items-center space-x-4">
            <div className="p-4 bg-emerald-50 text-emerald-500 rounded-2xl"><DollarSign size={24}/></div>
            <div>
               <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Valor Total do Estoque</p>
               <h3 className="text-2xl font-black text-slate-800">R$ {globalTotalValue.toLocaleString('pt-BR')}</h3>
            </div>
         </div>
         <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100 shadow-sm w-full md:w-auto">
            {[
              { id: 'ESTOQUE', label: 'Estoque', icon: Package },
              { id: 'OPERACAO', label: 'Movimentos', icon: History },
              { id: 'SUGESTAO', label: 'Pedido Sugerido', icon: ShoppingCart },
              ...(showSuppliersTab ? [{ id: 'FORNECEDORES', label: 'Fornecedores', icon: Truck }] : [])
            ].map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 flex items-center justify-center space-x-2 py-2.5 px-4 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === tab.id ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                <tab.icon size={14} /> <span className="hidden sm:inline">{tab.label}</span>
              </button>
            ))}
         </div>
      </div>

      {activeTab === 'ESTOQUE' && (
        <div className="space-y-6 animate-in slide-in-from-bottom-2">
          <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
            <div className="flex gap-3 w-full md:w-auto">
              <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input type="text" placeholder="Buscar por nome ou EAN..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 outline-none text-sm font-bold bg-white shadow-inner" />
              </div>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="px-4 py-3 rounded-xl border border-slate-100 outline-none bg-white text-sm font-bold shadow-inner">
                <option value="Todos">Categorias</option>
                {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div className="flex gap-2 w-full md:w-auto">
               <button onClick={() => setIsAddingOp(true)} className="flex-1 md:w-auto border-2 border-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 bg-white transition-all active:scale-95">
                 <PlusCircle size={18} /> <span>Movimentação</span>
               </button>
               {role !== 'FUNCIONARIO' && (
                 <button onClick={() => setIsAddingItem(true)} className="flex-1 md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95" style={{ backgroundColor: theme.primary }}>
                   <Plus size={18} /> <span>Novo Item</span>
                 </button>
               )}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-100">
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Insumo</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Saldo</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Consumo Médio</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">R$ Unit</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">R$ Total</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {filteredItems.map(item => {
                    const isLow = item.quantity <= item.minQuantity;
                    return (
                      <tr key={item.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-8 py-5">
                          <p className="font-black text-slate-800 leading-tight">{item.name}</p>
                          <div className="flex items-center space-x-2 mt-1">
                            {item.ean && <span className="text-[8px] text-blue-500 font-black uppercase flex items-center bg-blue-50 px-1.5 py-0.5 rounded"><Barcode size={8} className="mr-1" /> {item.ean}</span>}
                            <span className="text-[8px] text-slate-400 font-bold uppercase">{item.category} • {item.unit}</span>
                          </div>
                        </td>
                        <td className="px-8 py-5 text-center">
                          <span className={`text-lg font-black ${isLow ? 'text-rose-500' : 'text-slate-800'}`}>{item.quantity}</span>
                        </td>
                        <td className="px-8 py-5 text-center text-xs font-bold text-slate-400">{item.suggestion.mcd.toFixed(2)}/dia</td>
                        <td className="px-8 py-5 text-center text-xs font-bold text-slate-600">R$ {(item.price || 0).toLocaleString('pt-BR')}</td>
                        <td className="px-8 py-5 text-center text-sm font-black text-slate-900">R$ {item.totalValue.toLocaleString('pt-BR')}</td>
                        <td className="px-8 py-5 text-right">
                          <button onClick={() => { setEditingItem(item); setName(item.name); setEan(item.ean || ''); setCategory(item.category); setInitialQuantity(item.quantity); setUnit(item.unit); setPrice(item.price || 0); setSupplierId(item.supplierId || ''); setIsAddingItem(true); }} className="p-2 text-slate-300 hover:text-blue-500"><Edit2 size={18}/></button>
                          {role !== 'FUNCIONARIO' && <button onClick={() => onDelete(item.id)} className="p-2 text-slate-300 hover:text-rose-500 ml-2"><Trash2 size={18}/></button>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* Operation Modal - Busca Preditiva */}
      {isAddingOp && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                 <h2 className="text-xl font-black text-slate-800">Lançar Movimentação</h2>
