                          <button type="button" onClick={() => setOpType('Saída')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${opType === 'Saída' ? 'bg-white shadow-sm text-rose-500' : 'text-slate-400 hover:text-slate-500'}`}>Saída</button>
                       </div>
                       <input type="number" value={opQuantity || ''} onChange={e => setOpQuantity(parseInt(e.target.value) || 0)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none focus:border-blue-300 transition-all" placeholder="Quantidade" required />
                    </div>
                    <input type="text" value={opReason} onChange={e => setOpReason(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 font-bold outline-none focus:border-blue-300 transition-all" placeholder="Motivo / Justificativa" />
                 </div>
                 <button type="submit" disabled={!opItemId} className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 disabled:opacity-50 disabled:grayscale" style={{ backgroundColor: theme.primary }}>Confirmar Movimentação</button>
              </form>
           </div>
        </div>
      )}

      {/* Omissão de outros abas para brevidade, mantendo-as no arquivo final se necessário */}
      {/* ... (abas OPERACAO, SUGESTAO, FORNECEDORES continuam como no arquivo original) ... */}
    </div>
  );
};

