const APPS_SCRIPT_CODE = `/**
 * Google Apps Script para Gestão Hotel Village - V17 (Drive + Mirror Sync + Deletions)
 */

function doGet(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = e.parameter.hotel || 'VILLAGE';
    var result = {
      apartments: {}, budgets: [], employees: [], sectors: [], inventory: [], inventoryHistory: [], suppliers: [], config: {}
    };

    // 1. Apartamentos
    var sheetApts = ss.getSheetByName('Apartamentos_' + hotel) || ss.getSheetByName('Apartamentos');
    if (sheetApts) {
      var data = sheetApts.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        var num = data[i][0]; var floor = data[i][1]; if(!num || !floor) continue;
        var aptId = floor + "-" + num;
        result.apartments[aptId] = {
          id: aptId, roomNumber: num, floor: floor, pisoType: data[i][2], pisoStatus: data[i][3], banheiroType: data[i][4],
          banheiroStatus: data[i][5], temCofre: data[i][6] === 'Sim', temCortina: data[i][7] === 'Sim',
          cortinaStatus: data[i][8], cortinaSize: data[i][9], cortinaCoverage: data[i][10], temEspelhoCorpo: data[i][11] === 'Sim',
          espelhoCorpoStatus: data[i][12], acBrand: data[i][13], moveisStatus: data[i][14],
          moveisDetalhes: data[i][15] ? JSON.parse(data[i][15]) : [], beds: data[i][16] ? JSON.parse(data[i][16]) : [],
          temPortaControle: data[i][17] === 'Sim', temCabide: data[i][18] === 'Sim', cabideQuantity: data[i][19] || 0,
          temSuportePapel: data[i][20] === 'Sim', temSuporteShampoo: data[i][21] === 'Sim', suporteShampooStatus: data[i][22],
          luminariaType: data[i][23], luminariaColor: data[i][24], tvBrand: data[i][25], defects: data[i][26] ? JSON.parse(data[i][26]) : []
        };
      }
    }

    // 2. Estoque (Mirror Mode)
    var sheetInv = ss.getSheetByName('Estoque_' + hotel) || ss.getSheetByName('Estoque');
    if (sheetInv) {
      var dataI = sheetInv.getDataRange().getValues();
      for (var m = 1; m < dataI.length; m++) {
        if(!dataI[m][0]) continue;
        result.inventory.push({ 
          id: dataI[m][0].toString(), ean: dataI[m][1].toString(), name: dataI[m][2], category: dataI[m][3], 
          quantity: dataI[m][4], minQuantity: dataI[m][5], unit: dataI[m][6], price: dataI[m][7] || 0, 
          supplierId: dataI[m][8] || '', lastUpdate: new Date(dataI[m][9]).getTime() 
        });
      }
    }

    // 3. Fornecedores
    var sheetSup = ss.getSheetByName('Fornecedores_' + hotel) || ss.getSheetByName('Fornecedores');
    if (sheetSup) {
      var dataS = sheetSup.getDataRange().getValues();
      for (var j = 1; j < dataS.length; j++) {
        if(!dataS[j][0]) continue;
        result.suppliers.push({ id: dataS[j][0].toString(), name: dataS[j][1], contact: dataS[j][2], category: dataS[j][3] });
      }
    }

    // 4. Movimentações (Aba Espelho)
    var sheetMov = ss.getSheetByName('Movimentacoes_' + hotel);
    if (sheetMov) {
      var dataM = sheetMov.getDataRange().getValues();
      for (var k = 1; k < dataM.length; k++) {
        result.inventoryHistory.push({
          id: dataM[k][0].toString(), itemId: dataM[k][1], itemName: dataM[k][2], type: dataM[k][3],
          quantity: dataM[k][4], timestamp: new Date(dataM[k][5]).getTime(), user: dataM[k][6], reason: dataM[k][7]
        });
      }
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var req = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = req.hotel || 'VILLAGE';
    var folder = getFolder("Gestão Hotel Village - Arquivos");

    // Lógica de Arquivos (Drive)
    if (req.newFiles && req.newFiles.length > 0) {
      req.newFiles.forEach(function(f) {
        var blob = Utilities.newBlob(Utilities.base64Decode(f.data), f.mimeType, f.fileName);
        var driveFile = folder.createFile(blob);
        driveFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

        // Atualiza o link na estrutura de dados que será salva
        if (req.dataType === 'APARTMENT') {
           req.defects.forEach(function(d) { if(d.fileName === f.fileName) d.driveLink = driveFile.getUrl(); });
        } else if (req.dataType === 'BUDGET') {
           req.quotes.forEach(function(q) { q.files.forEach(function(qf) { if(qf.fileName === f.fileName) qf.driveLink = driveFile.getUrl(); }); });
        }
      });
    }

    if (req.dataType === 'DELETE') {
       var targetSheet = "";
       if(req.targetType === 'INVENTORY') targetSheet = 'Estoque_' + hotel;
       if(req.targetType === 'SUPPLIER') targetSheet = 'Fornecedores_' + hotel;
       if(req.targetType === 'EMPLOYEE') targetSheet = 'Funcionarios_' + hotel;
       if(req.targetType === 'BUDGET') targetSheet = 'Orcamentos_' + hotel;
       if(targetSheet) deleteRow(ss.getSheetByName(targetSheet), req.id);
    } else if (req.dataType === 'INVENTORY_OP') {
       var sheetMov = ss.getSheetByName('Movimentacoes_' + hotel) || ss.insertSheet('Movimentacoes_' + hotel);
       if (sheetMov.getLastRow() === 0) sheetMov.appendRow(['ID', 'ItemID', 'ItemName', 'Tipo', 'Qtd', 'Data', 'Usuario', 'Motivo']);
       sheetMov.appendRow([req.id, req.itemId, req.itemName, req.type, req.quantity, new Date(), req.user, req.reason]);

       // Atualiza Saldo na aba de Estoque
       var sheetEst = ss.getSheetByName('Estoque_' + hotel);
       updateInventoryBalance(sheetEst, req.itemId, req.type, req.quantity);
    } else if (req.dataType === 'INVENTORY') {
       var sheet = ss.getSheetByName('Estoque_' + hotel) || ss.insertSheet('Estoque_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['ID', 'EAN', 'Item', 'Categoria', 'Saldo', 'Mínimo', 'Unidade', 'Preço', 'FornecedorID', 'Atualizado']);
       upsert(sheet, req.id, [req.id, req.ean || '', req.name, req.category, req.quantity, 0, req.unit, req.price || 0, req.supplierId || '', new Date()]);
    } else if (req.dataType === 'SUPPLIER') {
       var sheet = ss.getSheetByName('Fornecedores_' + hotel) || ss.insertSheet('Fornecedores_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['ID', 'Nome', 'Contato', 'Categoria']);
       upsert(sheet, req.id, [req.id, req.name, req.contact, req.category]);
    } else if (req.dataType === 'APARTMENT') {
       var sheet = ss.getSheetByName('Apartamentos_' + hotel) || ss.insertSheet('Apartamentos_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['Numero', 'Andar', 'PisoType', 'PisoStatus', 'BanheiroType', 'BanheiroStatus', 'Cofre', 'Cortina', 'CortinaStatus', 'CortinaSize', 'CortinaCoverage', 'Espelho', 'EspelhoStatus', 'AC', 'MoveisStatus', 'MoveisDetalhes', 'Camas', 'PortaControle', 'Cabides', 'CabideQtd', 'SuportePapel', 'SuporteShampoo', 'SuporteShampooStatus', 'LuminariaType', 'LuminariaColor', 'TV', 'Avarias']);
       upsert(sheet, req.id, [req.roomNumber, req.floor, req.pisoType, req.pisoStatus, req.banheiroType, req.banheiroStatus, req.temCofre?'Sim':'Não', req.temCortina?'Sim':'Não', req.cortinaStatus, req.cortinaSize, req.cortinaCoverage, req.temEspelhoCorpo?'Sim':'Não', req.espelhoCorpoStatus, req.acBrand, req.moveisStatus, JSON.stringify(req.moveisDetalhes), JSON.stringify(req.beds), req.temPortaControle?'Sim':'Não', req.temCabide?'Sim':'Não', req.cabideQuantity, req.temSuportePapel?'Sim':'Não', req.temSuporteShampoo?'Sim':'Não', req.suporteShampooStatus, req.luminariaType, req.luminariaColor, req.tvBrand, JSON.stringify(req.defects)]);
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function getFolder(name) {
  var folders = DriveApp.getFoldersByName(name);
  if (folders.hasNext()) return folders.next();
  return DriveApp.createFolder(name);
}

function upsert(sheet, id, rowData) {
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) { if (data[i][0] == id) { sheet.getRange(i+1, 1, 1, rowData.length).setValues([rowData]); return; } }
  sheet.appendRow(rowData);
}

function deleteRow(sheet, id) {
  if(!sheet) return;
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) { if (data[i][0] == id) { sheet.deleteRow(i + 1); break; } }
}

function updateInventoryBalance(sheet, itemId, type, qty) {
  if(!sheet) return;
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (data[i][0] == itemId) {
      var current = parseFloat(data[i][4]) || 0;
      var next = (type === 'Entrada') ? current + qty : current - qty;
      sheet.getRange(i + 1, 5).setValue(next);
      sheet.getRange(i + 1, 10).setValue(new Date());
      break;
    }
  }
}
`;

