          />
          <button 
            onClick={() => fileInputRef.current?.click()} 
            className="w-full bg-rose-500 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center space-x-3 active:scale-95 transition-all shadow-lg shadow-rose-100 uppercase tracking-widest"
          >
            <ImageIcon size={20} />
            <span>TIRAR FOTO / ANEXAR</span>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*,application/pdf" />

          <div className="space-y-4 pt-2">
            {data.defects.map(defect => (
              <div key={defect.id} className="flex flex-col p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-right-2">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-start space-x-4 flex-1">
                    {renderThumbnail(defect)}
                    <div className="flex-1 min-w-0">
                      <p className="text-[11px] font-black text-slate-800 uppercase tracking-tight leading-tight">{defect.description}</p>
                      <div className="flex items-center gap-2 mt-2">
                        {defect.driveLink && defect.driveLink !== 'pendente' && (
                          <a href={defect.driveLink} target="_blank" rel="noopener noreferrer" className="flex items-center text-[8px] font-black text-blue-500 bg-blue-50 px-2 py-1 rounded uppercase hover:bg-blue-100">
                            <ExternalLink size={8} className="mr-1" /> Ver no Drive
                          </a>
                        )}
                        <span className="text-[7px] text-slate-300 uppercase font-bold">
                          {new Date(defect.timestamp).toLocaleDateString()}
                        </span>
                      </div>
                    </div>
                  </div>
                  <button 
                    onClick={() => {
                      setData(prev => ({ ...prev, defects: prev.defects.filter(d => d.id !== defect.id) }));
                      setNewFiles(prev => prev.filter(f => f.fileName !== defect.fileName));
                    }} 
                    className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                  >
                    <Trash2 size={20} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      <div className="fixed bottom-8 left-0 right-0 px-6 z-[120] animate-in slide-in-from-bottom-8">
        <button 
          onClick={handleSaveAndExit}
          disabled={isSaving}
          className="w-full bg-slate-900 text-white py-5 rounded-[2.2rem] font-black text-sm shadow-2xl flex items-center justify-center space-x-3 active:scale-95 transition-all hover:bg-slate-800 disabled:opacity-50"
          style={{ boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5)' }}
        >
          {isSaving ? (
            <div className="flex items-center space-x-3">
               <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
               <span className="tracking-widest">SINCRONIZANDO...</span>
            </div>
          ) : (
            <div className="flex items-center space-x-3">
              <Save size={20} className="text-emerald-400" />
              <span className="tracking-widest">SALVAR VISTORIA</span>
            </div>
          )}
        </button>
      </div>
    </div>
  );
};

