import React, { useState, useMemo } from 'react';
import { Apartment, HotelTheme } from '../types';
import { 
  FileBarChart, 
  Search, 
  Filter, 
  Printer, 
  AlertTriangle,
  Tv,
  Lightbulb,
  Droplets,
  Layers,
  CheckCircle2,
  Building2,
  Bed,
  Box,
