        var aptId = floor + "-" + num;
        result.apartments[aptId] = {
          id: aptId, roomNumber: num, floor: floor, pisoType: data[i][2], pisoStatus: data[i][3], banheiroType: data[i][4],
          banheiroStatus: data[i][5], temCofre: data[i][6] === 'Sim', temCortina: data[i][7] === 'Sim',
          cortinaStatus: data[i][8], cortinaSize: data[i][9], cortinaCoverage: data[i][10], temEspelhoCorpo: data[i][11] === 'Sim',
          espelhoCorpoStatus: data[i][12], acBrand: data[i][13], moveisStatus: data[i][14],
          moveisDetalhes: safeParse(data[i][15], []), beds: safeParse(data[i][16], []),
          temPortaControle: data[i][17] === 'Sim', temCabide: data[i][18] === 'Sim', cabideQuantity: data[i][19] || 0,
          temSuportePapel: data[i][20] === 'Sim', temSuporteShampoo: data[i][21] === 'Sim', suporteShampooStatus: data[i][22],
          luminariaType: data[i][23], luminariaColor: data[i][24], tvBrand: data[i][25], defects: safeParse(data[i][26], [])
        };
      }
    }

    // 2. Estoque
    var sheetInv = ss.getSheetByName('Estoque_' + hotel);
    if (sheetInv) {
      var dataI = sheetInv.getDataRange().getValues();
      for (var m = 1; m < dataI.length; m++) {
        if(!dataI[m][0]) continue;
        result.inventory.push({ 
          id: dataI[m][0].toString(), ean: dataI[m][1].toString(), name: dataI[m][2], category: dataI[m][3], 
          quantity: parseFloat(dataI[m][4]) || 0, minQuantity: dataI[m][5] || 0, unit: dataI[m][6], price: dataI[m][7] || 0, 
          supplierId: dataI[m][8] || '', lastUpdate: dataI[m][9] ? new Date(dataI[m][9]).getTime() : Date.now()
        });
      }
    }

    // 3. Fornecedores
    var sheetSup = ss.getSheetByName('Fornecedores_' + hotel);
    if (sheetSup) {
      var dataS = sheetSup.getDataRange().getValues();
      for (var j = 1; j < dataS.length; j++) {
        if(!dataS[j][0]) continue;
        result.suppliers.push({ id: dataS[j][0].toString(), name: dataS[j][1], contact: dataS[j][2], category: dataS[j][3] });
      }
    }

    // 4. Funcionários
    var sheetEmp = ss.getSheetByName('Funcionarios_' + hotel);
    if (sheetEmp) {
      var dataE = sheetEmp.getDataRange().getValues();
      for (var k = 1; k < dataE.length; k++) {
        if(!dataE[k][0]) continue;
        result.employees.push({
          id: dataE[k][0].toString(), name: dataE[k][1], role: dataE[k][2], contact: dataE[k][3], startDate: dataE[k][4],
          salary: dataE[k][5], department: dataE[k][6], sectorId: dataE[k][7], status: dataE[k][8],
          scheduleType: dataE[k][9], shiftType: dataE[k][10], workingHours: dataE[k][11],
          weeklyDayOff: dataE[k][12], monthlySundayOff: dataE[k][13], vacationStatus: dataE[k][14],
          uniforms: safeParse(dataE[k][15], [])
        });
      }
    }

    // 5. Orçamentos
    var sheetBud = ss.getSheetByName('Orcamentos_' + hotel);
    if (sheetBud) {
      var dataB = sheetBud.getDataRange().getValues();
      for (var n = 1; n < dataB.length; n++) {
        if(!dataB[n][0]) continue;
        result.budgets.push({
          id: dataB[n][0].toString(), title: dataB[n][1], objective: dataB[n][2], items: safeParse(dataB[n][3], []),
          quotes: safeParse(dataB[n][4], []), status: dataB[n][5], createdAt: new Date(dataB[n][6]).getTime()
        });
      }
    }

    // 6. Movimentações (Histórico)
    var sheetMov = ss.getSheetByName('Movimentacoes_' + hotel);
    if (sheetMov) {
      var dataM = sheetMov.getDataRange().getValues();
      for (var p = 1; p < dataM.length; p++) {
        if(!dataM[p][0]) continue;
        result.inventoryHistory.push({
          id: dataM[p][0].toString(), itemId: dataM[p][1], itemName: dataM[p][2], type: dataM[p][3],
          quantity: dataM[p][4], timestamp: new Date(dataM[p][5]).getTime(), user: dataM[p][6], reason: dataM[p][7]
        });
      }
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var req = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = req.hotel || 'VILLAGE';
    var folder = getFolder("Gestão Hotel Village - Arquivos");

    // Lógica de Drive (Anexos de Fotos/PDF)
    if (req.newFiles && req.newFiles.length > 0) {
      req.newFiles.forEach(function(f) {
        var blob = Utilities.newBlob(Utilities.base64Decode(f.data), f.mimeType, f.fileName);
        var driveFile = folder.createFile(blob);
        driveFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
        var driveUrl = driveFile.getUrl();

        if (req.dataType === 'APARTMENT') {
           req.defects.forEach(function(d) { 
             if(d.fileName === f.fileName) {
               d.driveLink = driveUrl;
               delete d.data; // Remove o base64 pesado antes de salvar na célula
             }
           });
        } else if (req.dataType === 'BUDGET') {
           req.quotes.forEach(function(q) { 
             q.files.forEach(function(qf) { 
               if(qf.fileName === f.fileName) {
                 qf.driveLink = driveUrl;
                 delete qf.data;
               }
             }); 
           });
        }
      });
    }

    if (req.dataType === 'DELETE') {
       var targetSheet = getTargetSheetName(req.targetType, hotel);
       if(targetSheet) deleteRow(ss.getSheetByName(targetSheet), req.id);
    } 
    else if (req.dataType === 'INVENTORY_OP') {
       var sheetMov = ss.getSheetByName('Movimentacoes_' + hotel) || ss.insertSheet('Movimentacoes_' + hotel);
       if (sheetMov.getLastRow() === 0) sheetMov.appendRow(['ID', 'ItemID', 'ItemName', 'Tipo', 'Qtd', 'Data', 'Usuario', 'Motivo']);
       sheetMov.appendRow([req.id, req.itemId, req.itemName, req.type, req.quantity, new Date(), req.user, req.reason]);

       // Atualiza apenas a célula de saldo (coluna 5) no estoque existente
       var sheetEst = ss.getSheetByName('Estoque_' + hotel);
       if (sheetEst) updateInventoryBalance(sheetEst, req.itemId, req.type, req.quantity);
    } 
    else if (req.dataType === 'INVENTORY') {
       var sheet = ss.getSheetByName('Estoque_' + hotel) || ss.insertSheet('Estoque_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['ID', 'EAN', 'Item', 'Categoria', 'Saldo', 'Mínimo', 'Unidade', 'Preço', 'FornecedorID', 'Atualizado']);
       upsert(sheet, req.id, [req.id, req.ean || '', req.name, req.category, req.quantity, 0, req.unit, req.price || 0, req.supplierId || '', new Date()]);
    } 
    else if (req.dataType === 'SUPPLIER') {
       var sheet = ss.getSheetByName('Fornecedores_' + hotel) || ss.insertSheet('Fornecedores_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['ID', 'Nome', 'Contato', 'Categoria']);
       upsert(sheet, req.id, [req.id, req.name, req.contact, req.category]);
    } 
    else if (req.dataType === 'EMPLOYEE') {
       var sheet = ss.getSheetByName('Funcionarios_' + hotel) || ss.insertSheet('Funcionarios_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['ID', 'Nome', 'Cargo', 'Contato', 'Inicio', 'Salario', 'Setor', 'SectorID', 'Status', 'Escala', 'Turno', 'Horas', 'FolgaSemanal', 'FolgaDomingo', 'Ferias', 'Uniformes']);
       upsert(sheet, req.id, [req.id, req.name, req.role, req.contact, req.startDate, req.salary, req.department, req.sectorId, req.status, req.scheduleType, req.shiftType, req.workingHours, req.weeklyDayOff, req.monthlySundayOff, req.vacationStatus, JSON.stringify(req.uniforms)]);
    }
    else if (req.dataType === 'BUDGET') {
       var sheet = ss.getSheetByName('Orcamentos_' + hotel) || ss.insertSheet('Orcamentos_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['ID', 'Titulo', 'Objetivo', 'Itens', 'Cotacoes', 'Status', 'CriadoEm']);
       upsert(sheet, req.id, [req.id, req.title, req.objective, JSON.stringify(req.items), JSON.stringify(req.quotes), req.status, new Date(req.createdAt)]);
    }
    else if (req.dataType === 'APARTMENT') {
       var sheet = ss.getSheetByName('Apartamentos_' + hotel) || ss.insertSheet('Apartamentos_' + hotel);
       if (sheet.getLastRow() === 0) sheet.appendRow(['Numero', 'Andar', 'PisoType', 'PisoStatus', 'BanheiroType', 'BanheiroStatus', 'Cofre', 'Cortina', 'CortinaStatus', 'CortinaSize', 'CortinaCoverage', 'Espelho', 'EspelhoStatus', 'AC', 'MoveisStatus', 'MoveisDetalhes', 'Camas', 'PortaControle', 'Cabides', 'CabideQtd', 'SuportePapel', 'SuporteShampoo', 'SuporteShampooStatus', 'LuminariaType', 'LuminariaColor', 'TV', 'Avarias']);
       upsert(sheet, req.roomNumber + '-' + req.floor, [req.roomNumber, req.floor, req.pisoType, req.pisoStatus, req.banheiroType, req.banheiroStatus, req.temCofre?'Sim':'Não', req.temCortina?'Sim':'Não', req.cortinaStatus, req.cortinaSize, req.cortinaCoverage, req.temEspelhoCorpo?'Sim':'Não', req.espelhoCorpoStatus, req.acBrand, req.moveisStatus, JSON.stringify(req.moveisDetalhes), JSON.stringify(req.beds), req.temPortaControle?'Sim':'Não', req.temCabide?'Sim':'Não', req.cabideQuantity, req.temSuportePapel?'Sim':'Não', req.temSuporteShampoo?'Sim':'Não', req.suporteShampooStatus, req.luminariaType, req.luminariaColor, req.tvBrand, JSON.stringify(req.defects)]);
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function safeParse(str, fallback) {
  try { if (!str || str == "") return fallback; return JSON.parse(str); } catch(e) { return fallback; }
}

function getTargetSheetName(type, hotel) {
  if(type === 'INVENTORY') return 'Estoque_' + hotel;
  if(type === 'SUPPLIER') return 'Fornecedores_' + hotel;
  if(type === 'EMPLOYEE') return 'Funcionarios_' + hotel;
  if(type === 'BUDGET') return 'Orcamentos_' + hotel;
  return null;
}

function getFolder(name) {
  var folders = DriveApp.getFoldersByName(name);
  if (folders.hasNext()) return folders.next();
  return DriveApp.createFolder(name);
}

function upsert(sheet, id, rowData) {
  var data = sheet.getDataRange().getValues();
  var idStr = id.toString().trim();
  for (var i = 1; i < data.length; i++) { 
    if (data[i][0].toString().trim() == idStr) { 
      sheet.getRange(i+1, 1, 1, rowData.length).setValues([rowData]); 
      return; 
    } 
  }
  sheet.appendRow(rowData);
}

function deleteRow(sheet, id) {
  if(!sheet) return;
  var data = sheet.getDataRange().getValues();
  var idStr = id.toString().trim();
  for (var i = 1; i < data.length; i++) { if (data[i][0].toString().trim() == idStr) { sheet.deleteRow(i + 1); break; } }
}

function updateInventoryBalance(sheet, itemId, type, qty) {
  if(!sheet) return;
  var data = sheet.getDataRange().getValues();
  var idStr = itemId.toString().trim();
  for (var i = 1; i < data.length; i++) {
    if (data[i][0].toString().trim() == idStr) {
      var current = parseFloat(data[i][4]) || 0;
      var next = (type === 'Entrada') ? current + qty : current - qty;
      sheet.getRange(i + 1, 5).setValue(next); // Atualiza saldo na coluna 5
      sheet.getRange(i + 1, 10).setValue(new Date()); // Data de atualização na coluna 10
      return;
    }
  }
}
`;

