                    <div className="grid grid-cols-1 gap-1">
                      <button onClick={() => updateBed(idx, { mattressStatus: 'Novo' })} className={getStatusBtnClass(bed.mattressStatus, 'Novo', 'bg-emerald-500')}>NOVO</button>
                      <button onClick={() => updateBed(idx, { mattressStatus: 'Antigo' })} className={getStatusBtnClass(bed.mattressStatus, 'Antigo', 'bg-amber-400 !text-slate-900')}>ANTIGO</button>
                    </div>
                  </div>
                </div>
              </section>
            ))}
          </div>
        </div>

        {/* AVARIAS, MANUTENÇÕES E ANEXOS (COM MINIATURAS) */}
        <section className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-xl space-y-4">
          <SectionTitle icon={Paperclip} title="Defeitos & Manutenção" color="text-rose-500" />
          <textarea 
            value={newDefectText} 
            onChange={(e) => setNewDefectText(e.target.value)} 
            placeholder="Descreva o problema ou necessidade de manutenção..." 
            className="w-full p-4 rounded-2xl bg-slate-50 border-transparent focus:bg-white focus:border-rose-200 outline-none transition-all text-xs font-bold min-h-[100px] shadow-inner text-slate-700" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()} 
            className="w-full bg-rose-500 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center space-x-3 active:scale-95 transition-all shadow-lg shadow-rose-100 uppercase tracking-widest"
          >
            <ImageIcon size={20} />
            <span>TIRAR FOTO / ANEXAR</span>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*,application/pdf" />

          <div className="space-y-4 pt-2">
            {data.defects.map(defect => (
              <div key={defect.id} className="flex flex-col p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-right-2">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-start space-x-4 flex-1">
                    {renderThumbnail(defect)}
                    <div className="flex-1 min-w-0">
                      <p className="text-[11px] font-black text-slate-800 uppercase tracking-tight leading-tight">{defect.description}</p>
                      <div className="flex items-center gap-2 mt-2">
                        {defect.driveLink && defect.driveLink !== 'pendente' && (
                          <a href={defect.driveLink} target="_blank" rel="noopener noreferrer" className="flex items-center text-[8px] font-black text-blue-500 bg-blue-50 px-2 py-1 rounded uppercase hover:bg-blue-100">
                            <ExternalLink size={8} className="mr-1" /> Ver no Drive
                          </a>
                        )}
                        <span className="text-[7px] text-slate-300 uppercase font-bold">
                          {new Date(defect.timestamp).toLocaleDateString()}
                        </span>
                      </div>
                    </div>
                  </div>
                  <button 
                    onClick={() => {
                      setData(prev => ({ ...prev, defects: prev.defects.filter(d => d.id !== defect.id) }));
                      setNewFiles(prev => prev.filter(f => f.fileName !== defect.fileName));
                    }} 
                    className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                  >
                    <Trash2 size={20} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      <div className="fixed bottom-8 left-0 right-0 px-6 z-[120] animate-in slide-in-from-bottom-8">
        <button 
          onClick={handleSaveAndExit}
          disabled={isSaving}
          className="w-full bg-slate-900 text-white py-5 rounded-[2.2rem] font-black text-sm shadow-2xl flex items-center justify-center space-x-3 active:scale-95 transition-all hover:bg-slate-800 disabled:opacity-50"
          style={{ boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5)' }}
        >
          {isSaving ? (
            <div className="flex items-center space-x-3">
               <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
               <span className="tracking-widest">SINCRONIZANDO...</span>
            </div>
          ) : (
            <div className="flex items-center space-x-3">
              <Save size={20} className="text-emerald-400" />
              <span className="tracking-widest">SALVAR VISTORIA</span>
            </div>
          )}
        </button>
      </div>
    </div>
  );
};

export default ApartmentDetailView;

import React, { useState, useRef } from 'react';
import { Apartment, Defect, HotelTheme, BedConfig } from '../types';
import { 
  ChevronLeft, 
  Save, 
  Trash2, 
  Wind,
  Bed,
  Tv,
  Lightbulb,
  Box,
  Droplets,
  Layers,
  Layout,
  Image as ImageIcon,
  Paperclip,
  ExternalLink,
  DoorOpen,
  Shirt,
  FileText
} from 'lucide-react';

interface ApartmentDetailViewProps {
  apartment: Apartment;
  theme: HotelTheme;
  onBack: () => void;
  onSave: (apt: Apartment, files?: any[]) => void;
  integrationUrl?: string;
}

const ApartmentDetailView: React.FC<ApartmentDetailViewProps> = ({ apartment, theme, onBack, onSave, integrationUrl }) => {
  const [data, setData] = useState<Apartment>(() => {
    const initial = { ...apartment };
    if (!initial.beds || initial.beds.length === 0) {
      if (initial.floor === 200) {
        initial.beds = [
          { type: 'Casal', baseStatus: 'Nova', mattressStatus: 'Novo', hasSkirt: false },
          { type: 'Casal', baseStatus: 'Nova', mattressStatus: 'Novo', hasSkirt: false }
        ];
      } else {
        initial.beds = [
          { type: 'Casal', baseStatus: 'Nova', mattressStatus: 'Novo', hasSkirt: false },
          { type: 'Solteiro', baseStatus: 'Nova', mattressStatus: 'Novo', hasSkirt: false },
          { type: 'Solteiro', baseStatus: 'Nova', mattressStatus: 'Novo', hasSkirt: false }
        ];
      }
    }
    if (!initial.moveisDetalhes) initial.moveisDetalhes = [];
    return initial;
  });

  const [newDefectText, setNewDefectText] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [newFiles, setNewFiles] = useState<{data: string, mimeType: string, fileName: string}[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const updateField = (field: keyof Apartment, value: any) => {
    setData(prev => ({ ...prev, [field]: value }));
  };

  const updateBed = (index: number, bedUpdate: Partial<BedConfig>) => {
    const newBeds = [...(data.beds || [])];
    newBeds[index] = { ...newBeds[index], ...bedUpdate };
    updateField('beds', newBeds);
  };

  const toggleMoveisDetalhe = (item: string) => {
    const current = data.moveisDetalhes || [];
    const next = current.includes(item) ? current.filter(i => i !== item) : [...current, item];
    updateField('moveisDetalhes', next);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && newDefectText.trim()) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const fullBase64 = reader.result?.toString() || '';
        const base64Data = fullBase64.split(',')[1] || '';
        const newDefect: Defect = {
          id: `${data.id}-${Date.now()}`,
          description: newDefectText,
          driveLink: 'pendente',
          timestamp: Date.now(),
          fileName: file.name,
          fileType: file.type,
          data: fullBase64
        };
        setNewFiles(prev => [...prev, { data: base64Data, mimeType: file.type, fileName: file.name }]);
        setData(prev => ({ ...prev, defects: [...prev.defects, newDefect] }));
        setNewDefectText('');
        if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsDataURL(file);
    } else if (!newDefectText.trim()) {
      alert('Descreva o defeito antes de anexar a foto.');
    }
  };

  const handleSaveAndExit = async () => {
    setIsSaving(true);
    onSave(data, newFiles);
    setTimeout(() => { setIsSaving(false); onBack(); }, 800);
  };

  const SectionTitle = ({ icon: Icon, title, color = "text-slate-800" }: { icon: any, title: string, color?: string }) => (
    <div className="flex items-center space-x-2 mb-4 border-l-4 pl-3 py-1" style={{ borderColor: color.replace('text-', '') }}>
      <div className={`${color}`}><Icon size={18} /></div>
      <h3 className={`text-[11px] font-black ${color} uppercase tracking-widest`}>{title}</h3>
    </div>
  );

  const getStatusBtnClass = (current: any, target: any, activeBg: string) => {
    return `flex-1 py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${
      current === target ? `${activeBg} text-white border-transparent shadow-lg` : 'bg-slate-50 border-slate-100 text-slate-400'
    }`;
  };

  return (
    <div className="bg-slate-50 min-h-screen pb-40 font-sans text-slate-900">
      <div className="sticky top-0 z-[110] bg-white border-b border-slate-100 px-4 py-4 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-3">
          <button onClick={onBack} className="p-2 -ml-2 text-slate-400 active:bg-slate-100 rounded-full transition-colors"><ChevronLeft size={24} /></button>
          <div>
            <h2 className="text-xl font-black text-slate-800 leading-none">Apto {data.roomNumber}</h2>
            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Vistoria Detalhada</p>
          </div>
        </div>
      </div>

      <div className="px-4 py-6 space-y-5 max-w-lg mx-auto">

        {/* PISO */}
        <section className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
          <SectionTitle icon={Droplets} title="Piso do Quarto" color="text-blue-600" />
          <div className="grid grid-cols-3 gap-2">
            {['Granito', 'Madeira', 'Cerâmica'].map(t => (
              <button key={t} onClick={() => updateField('pisoType', t)} className={getStatusBtnClass(data.pisoType, t, 'bg-blue-600')}>{t}</button>
            ))}
          </div>
          <div className="grid grid-cols-3 gap-2">
            <button onClick={() => updateField('pisoStatus', 'Bom estado')} className={getStatusBtnClass(data.pisoStatus, 'Bom estado', 'bg-emerald-500')}>BOM</button>
            <button onClick={() => updateField('pisoStatus', 'Tolerável')} className={getStatusBtnClass(data.pisoStatus, 'Tolerável', 'bg-amber-400 !text-slate-900')}>TOLERÁVEL</button>
            <button onClick={() => updateField('pisoStatus', 'Reparo urgente')} className={getStatusBtnClass(data.pisoStatus, 'Reparo urgente', 'bg-rose-500')}>URGENTE</button>
          </div>
        </section>

        {/* MOBILIÁRIO */}
        <section className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
          <SectionTitle icon={Layout} title="Mobiliário" color="text-slate-700" />
          <div className="grid grid-cols-2 gap-2">
            <button onClick={() => { updateField('moveisStatus', 'Bom estado'); updateField('moveisDetalhes', []); }} className={getStatusBtnClass(data.moveisStatus, 'Bom estado', 'bg-emerald-500')}>BOM ESTADO</button>
            <button onClick={() => updateField('moveisStatus', 'Danificado')} className={getStatusBtnClass(data.moveisStatus, 'Danificado', 'bg-rose-500')}>DANIFICADO</button>
          </div>
          {data.moveisStatus === 'Danificado' && (
            <div className="flex flex-col gap-2">
              {['Guarda Roupa', 'Criado mudo', 'Cômoda'].map(item => (
                <button key={item} onClick={() => toggleMoveisDetalhe(item)} className={`py-3 rounded-xl text-[10px] font-bold border-2 transition-all ${data.moveisDetalhes?.includes(item) ? 'bg-rose-500 text-white border-transparent' : 'bg-white text-rose-300 border-rose-100'}`}>{item}</button>
              ))}
            </div>
          )}
        </section>

        {/* BANHEIRO COMPLETO */}
        <section className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
          <SectionTitle icon={Layers} title="Banheiro & Suportes" color="text-indigo-600" />
          <div className="grid grid-cols-2 gap-2">
            {['Reformado', 'Antigo'].map(t => (
              <button key={t} onClick={() => updateField('banheiroType', t)} className={getStatusBtnClass(data.banheiroType, t, 'bg-indigo-600')}>{t}</button>
            ))}
          </div>
          <div className="grid grid-cols-2 gap-2">
            <button onClick={() => updateField('banheiroStatus', 'Tolerável')} className={getStatusBtnClass(data.banheiroStatus, 'Tolerável', 'bg-amber-400 !text-slate-900')}>TOLERÁVEL</button>
            <button onClick={() => updateField('banheiroStatus', 'Reparo urgente')} className={getStatusBtnClass(data.banheiroStatus, 'Reparo urgente', 'bg-rose-500')}>URGENTE</button>
          </div>
          <div className="grid grid-cols-1 gap-3 pt-2">
            <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl">
              <span className="text-[10px] font-black text-slate-500">SUPORTE PAPEL</span>
              <button onClick={() => updateField('temSuportePapel', !data.temSuportePapel)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black ${data.temSuportePapel ? 'bg-indigo-500 text-white' : 'bg-white text-slate-300'}`}>{data.temSuportePapel ? 'POSSUI' : 'NÃO TEM'}</button>
            </div>
            <div className="flex flex-col p-3 bg-slate-50 rounded-xl gap-2">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-500">SUPORTE SHAMPOO</span>
                <button onClick={() => updateField('temSuporteShampoo', !data.temSuporteShampoo)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black ${data.temSuporteShampoo ? 'bg-indigo-500 text-white' : 'bg-white text-slate-300'}`}>{data.temSuporteShampoo ? 'POSSUI' : 'NÃO TEM'}</button>
              </div>
              {data.temSuporteShampoo && (
                <div className="grid grid-cols-2 gap-1 animate-in fade-in">
                  <button onClick={() => updateField('suporteShampooStatus', 'Bom estado')} className={getStatusBtnClass(data.suporteShampooStatus, 'Bom estado', 'bg-emerald-500')}>BOM</button>
                  <button onClick={() => updateField('suporteShampooStatus', 'Enferrujado')} className={getStatusBtnClass(data.suporteShampooStatus, 'Enferrujado', 'bg-rose-500')}>ENFERRUJADO</button>
                </div>
              )}
            </div>
          </div>
        </section>

        {/* ACESSÓRIOS DO QUARTO (PORTA CONTROLE, CABIDES, LUMINÁRIA) */}
        <section className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
          <SectionTitle icon={Box} title="Acessórios do Quarto" color="text-amber-600" />
          <div className="grid grid-cols-1 gap-3">
             <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl">
              <span className="text-[10px] font-black text-slate-500 flex items-center"><DoorOpen size={14} className="mr-2"/> PORTA CONTROLE</span>
              <button onClick={() => updateField('temPortaControle', !data.temPortaControle)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black ${data.temPortaControle ? 'bg-amber-500 text-white' : 'bg-white text-slate-300'}`}>{data.temPortaControle ? 'POSSUI' : 'NÃO TEM'}</button>
            </div>
            <div className="flex flex-col p-3 bg-slate-50 rounded-xl gap-2">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-500 flex items-center"><Shirt size={14} className="mr-2"/> CABIDES</span>
                <button onClick={() => updateField('temCabide', !data.temCabide)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black ${data.temCabide ? 'bg-amber-500 text-white' : 'bg-white text-slate-300'}`}>{data.temCabide ? 'POSSUI' : 'NÃO TEM'}</button>
              </div>
              {data.temCabide && (
                <div className="flex items-center space-x-2 animate-in fade-in">
                  <span className="text-[9px] font-bold text-slate-400">QUANTIDADE:</span>
                  <input type="number" value={data.cabideQuantity || 0} onChange={e => updateField('cabideQuantity', parseInt(e.target.value))} className="w-16 px-2 py-1 rounded bg-white border border-slate-200 text-xs font-bold" />
                </div>
              )}
            </div>
            <div className="flex flex-col p-3 bg-slate-50 rounded-xl gap-2">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-500 flex items-center"><Lightbulb size={14} className="mr-2"/> LUMINÁRIA</span>
              </div>
              <div className="grid grid-cols-3 gap-1">
                {['Arandela', 'Vidro', 'Quadrado'].map(l => (
                  <button key={l} onClick={() => updateField('luminariaType', l)} className={getStatusBtnClass(data.luminariaType, l, 'bg-amber-500')}>{l}</button>
                ))}
              </div>
            </div>
            <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl">
              <span className="text-[10px] font-black text-slate-500 flex items-center"><Box size={14} className="mr-2"/> COFRE</span>
              <button onClick={() => updateField('temCofre', !data.temCofre)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black ${data.temCofre ? 'bg-amber-500 text-white' : 'bg-white text-slate-300'}`}>{data.temCofre ? 'POSSUI' : 'NÃO TEM'}</button>
            </div>
          </div>
        </section>

        {/* CORTINA, AR E TV */}
        <section className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
          <SectionTitle icon={Wind} title="Climatização & Cortina" color="text-cyan-600" />
          <div>
            <p className="text-[9px] font-black text-slate-400 uppercase mb-2">Marca do Ar:</p>
            <div className="grid grid-cols-3 gap-2">
              {['Midea', 'Grey', 'LG'].map(b => (
                <button key={b} onClick={() => updateField('acBrand', b)} className={getStatusBtnClass(data.acBrand, b, 'bg-cyan-600')}>{b}</button>
              ))}
            </div>
          </div>
          <div>
            <p className="text-[9px] font-black text-slate-400 uppercase mb-2">Marca da TV:</p>
            <div className="grid grid-cols-3 gap-2">
              {['LG', 'Samsung', 'Philco', 'Smart Roku', 'Toshiba'].map(b => (
                <button key={b} onClick={() => updateField('tvBrand', b)} className={getStatusBtnClass(data.tvBrand, b, 'bg-slate-800')}>{b}</button>
              ))}
            </div>
          </div>
          <div className="p-3 bg-slate-50 rounded-xl space-y-3">
             <div className="flex items-center justify-between">
                <span className="text-[10px] font-black text-slate-500">CORTINA</span>
                <button onClick={() => updateField('temCortina', !data.temCortina)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black ${data.temCortina ? 'bg-cyan-600 text-white' : 'bg-white text-slate-300'}`}>{data.temCortina ? 'POSSUI' : 'NÃO TEM'}</button>
             </div>
             {data.temCortina && (
               <div className="space-y-2 animate-in fade-in">
                 <div className="grid grid-cols-2 gap-1">
                    <button onClick={() => updateField('cortinaStatus', 'Nova')} className={getStatusBtnClass(data.cortinaStatus, 'Nova', 'bg-emerald-500')}>NOVA</button>
                    <button onClick={() => updateField('cortinaStatus', 'Antiga')} className={getStatusBtnClass(data.cortinaStatus, 'Antiga', 'bg-rose-500')}>ANTIGA</button>
                 </div>
               </div>
             )}
          </div>
        </section>

        {/* CAMAS */}
        <SectionTitle icon={Bed} title="Configuração de Camas" color="text-emerald-600" />
        {(data.beds || []).map((bed, idx) => (
          <section key={idx} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
            <h4 className="text-[10px] font-black text-slate-800 uppercase">Cama {idx + 1} ({bed.type})</h4>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <p className="text-[8px] font-black text-slate-400 uppercase">Base</p>
                <button onClick={() => updateBed(idx, { baseStatus: 'Nova' })} className={getStatusBtnClass(bed.baseStatus, 'Nova', 'bg-emerald-500')}>NOVA</button>
                <button onClick={() => updateBed(idx, { baseStatus: 'Antiga' })} className={getStatusBtnClass(bed.baseStatus, 'Antiga', 'bg-rose-500')}>ANTIGA</button>
              </div>
              <div className="space-y-2">
                <p className="text-[8px] font-black text-slate-400 uppercase">Colchão</p>
                <button onClick={() => updateBed(idx, { mattressStatus: 'Novo' })} className={getStatusBtnClass(bed.mattressStatus, 'Novo', 'bg-emerald-500')}>NOVO</button>
                <button onClick={() => updateBed(idx, { mattressStatus: 'Antigo' })} className={getStatusBtnClass(bed.mattressStatus, 'Antigo', 'bg-rose-500')}>ANTIGO</button>
              </div>
            </div>
          </section>
        ))}

        {/* DEFEITOS E FOTOS */}
        <section className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-xl space-y-4">
          <SectionTitle icon={Paperclip} title="Defeitos & Manutenção" color="text-rose-500" />
          <textarea value={newDefectText} onChange={(e) => setNewDefectText(e.target.value)} placeholder="Descreva o problema observado..." className="w-full p-4 rounded-2xl bg-slate-50 border-transparent focus:bg-white outline-none text-xs font-bold min-h-[100px]" />
          <button onClick={() => fileInputRef.current?.click()} className="w-full bg-rose-500 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center space-x-3 shadow-lg uppercase tracking-widest active:scale-95 transition-all">
            <ImageIcon size={20} /> <span>TIRAR FOTO / ANEXAR</span>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*,application/pdf" />

          <div className="space-y-4 pt-2">
            {data.defects.map(defect => (
              <div key={defect.id} className="flex flex-col p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-right-2">
                <div className="flex items-start justify-between gap-4">
                   <div className="flex items-start space-x-3 flex-1">
                      {defect.data && <img src={defect.data} className="w-16 h-16 rounded-xl object-cover shadow-sm" />}
                      <div className="flex-1">
                        <p className="text-[11px] font-black text-slate-800 uppercase leading-tight">{defect.description}</p>
                        {defect.driveLink && defect.driveLink !== 'pendente' && (
                          <a href={defect.driveLink} target="_blank" className="text-[8px] font-black text-blue-500 bg-blue-50 px-2 py-1 rounded mt-2 inline-flex items-center uppercase"><ExternalLink size={8} className="mr-1"/> No Drive</a>
                        )}
                      </div>
                   </div>
                   <button onClick={() => setData(prev => ({ ...prev, defects: prev.defects.filter(d => d.id !== defect.id) }))} className="text-slate-300 hover:text-rose-500"><Trash2 size={20}/></button>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      <div className="fixed bottom-8 left-0 right-0 px-6 z-[120]">
        <button onClick={handleSaveAndExit} disabled={isSaving} className="w-full bg-slate-900 text-white py-5 rounded-[2.2rem] font-black text-sm shadow-2xl flex items-center justify-center space-x-3 active:scale-95 transition-all">
          {isSaving ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Save size={20} className="text-emerald-400" />}
          <span>{isSaving ? 'SINCRONIZANDO...' : 'SALVAR VISTORIA'}</span>
        </button>
      </div>
    </div>
  );
};

