            <button onClick={() => updateField('temSuportePapel', !data.temSuportePapel)} className={`w-full p-5 rounded-2xl border-2 flex items-center justify-between transition-all ${data.temSuportePapel ? 'bg-slate-800 border-transparent text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400'}`}>
               <span className="text-[9px] font-black uppercase">Suporte de Papel Higiênico</span>
               <span className="text-xs font-black">{data.temSuportePapel ? 'POSSUI' : 'NÃO TEM'}</span>
            </button>
