                </div>
                <div className="bg-emerald-50 text-emerald-500 px-3 py-1 rounded-full border border-emerald-100 text-[8px] font-black uppercase tracking-widest">
                  {bed.type}
                </div>
              </div>

              {/* Base da Cama */}
              <div className="space-y-3">
                <label className="text-[9px] font-black text-slate-300 uppercase tracking-widest ml-1">Base da Cama:</label>
