                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => updateBed(idx, { mattressStatus: 'Novo', mattressColor: undefined })} className={getStatusBtnClass(bed.mattressStatus, 'Novo', 'bg-emerald-500')}>NOVO</button>
                  <button onClick={() => updateBed(idx, { mattressStatus: 'Antigo' })} className={getStatusBtnClass(bed.mattressStatus, 'Antigo', 'bg-amber-400 !text-slate-900')}>ANTIGO</button>
