                 <span className="text-[7px] font-black uppercase mb-1">Possui Cofre?</span>
                 <span className="text-xs font-black">{data.temCofre ? 'SIM' : 'NÃO'}</span>
               </button>
               <button onClick={() => updateField('temPortaControle', !data.temPortaControle)} className={`p-5 rounded-2xl border-2 flex flex-col items-center transition-all ${data.temPortaControle ? 'bg-slate-800 border-transparent text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400'}`}>
