    // 3. Fornecedores
    var sheetSup = ss.getSheetByName('Fornecedores_' + hotel);
    if (sheetSup) {
      var dataS = sheetSup.getDataRange().getValues();
      for (var j = 1; j < dataS.length; j++) {
