      }
    }

    // 4. Funcionários
    var sheetEmp = ss.getSheetByName('Funcionarios_' + hotel);
    if (sheetEmp) {
      var dE = sheetEmp.getDataRange().getValues();
      for (var k = 1; k < dE.length; k++) { 
        if(!dE[k][0]) continue; 
        result.employees.push({ id: dE[k][0].toString(), name: dE[k][1], role: dE[k][2], contact: dE[k][3], startDate: dE[k][4], salary: dE[k][5], department: dE[k][6], sectorId: dE[k][7], status: dE[k][8], scheduleType: dE[k][9], shiftType: dE[k][10], workingHours: dE[k][11], weeklyDayOff: dE[k][12], monthlySundayOff: dE[k][13], vacationStatus: dE[k][14], uniforms: safeParse(dE[k][15], []) }); 
      }
    }

    // 5. Setores
    var sheetSec = ss.getSheetByName('Setores_' + hotel);
    if (sheetSec) {
