import React, { useState, useEffect } from 'react';
import { UserRole, HotelType, User, Sector, Employee } from '../types';
import { Hotel, User as UserIcon, Lock, ChevronRight, AlertCircle, Building2, Briefcase, Eye, EyeOff, Users } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
  onFetchHotelData: (hotel: HotelType) => Promise<any>;
}

const Login: React.FC<LoginProps> = ({ onLogin, onFetchHotelData }) => {
  const [accessType, setAccessType] = useState<'ADMIN' | 'EMPLOYEE' | null>(null);
  const [role, setRole] = useState<UserRole | null>(null);
  const [hotel, setHotel] = useState<HotelType | ''>('');
  const [selectedSectorId, setSelectedSectorId] = useState<string>('');
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<string>('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const [availableSectors, setAvailableSectors] = useState<Sector[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);

  const hotels: { id: HotelType; label: string }[] = [
    { id: 'VILLAGE', label: 'Village Inn' },
    { id: 'GOLDEN_PARK', label: 'Hotel Golden Park' },
    { id: 'THERMAL_RESORT', label: 'Thermas Resort' },
  ];

  const handleFetchData = async (h: HotelType) => {
    setIsLoading(true);
    setError('');
    try {
      const data = await onFetchHotelData(h);
      if (data) {
        setAvailableSectors(data.sectors || []);
        setAvailableEmployees(data.employees || []);
      }
    } catch (err) {
      setError('Erro ao carregar dados do hotel. Verifique a conexão.');
    } finally {
      setIsLoading(false);
    }
  };

  const normalizeString = (str: string) => {
    if (!str) return '';
    return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
  };

  const handleEnter = () => {
    setError('');

    if (accessType === 'ADMIN') {
      if (!role) return;
      if (role === 'GERENCIA') {
        if (!hotel) { setError('Selecione uma unidade'); return; }
        if (password === '123') onLogin({ role, hotel });
        else setError('Senha incorreta para Supervisão');
      } else if (role === 'DIRETORIA') {
        if (password === '0000') onLogin({ role });
        else setError('Senha incorreta para Diretoria');
      }
    } else if (accessType === 'EMPLOYEE') {
      if (!hotel || !selectedSectorId || !selectedEmployeeId) {
        setError('Preencha todos os campos para entrar');
        return;
      }

      const employee = availableEmployees.find(e => e.id === selectedEmployeeId);
      const sector = availableSectors.find(s => s.id === selectedSectorId);

      if (employee && sector) {
        const firstName = normalizeString(employee.name.split(' ')[0]);

        // Extração robusta do ano da data (suporta YYYY-MM-DD ou DD/MM/YYYY)
        let regYear = '2024';
        if (employee.startDate) {
          if (employee.startDate.includes('-')) {
            regYear = employee.startDate.split('-')[0];
          } else if (employee.startDate.includes('/')) {
            const parts = employee.startDate.split('/');
            regYear = parts[parts.length - 1];
          }
        }

        const expectedPassword = firstName + regYear;

        if (normalizeString(password) === expectedPassword) {
          onLogin({ 
            role: 'FUNCIONARIO', 
            hotel: hotel as HotelType, 
            name: employee.name, 
            sectorId: selectedSectorId,
            sectorName: sector.name
          });
        } else {
          setError(`Senha incorreta. Dica: seu primeiro nome + ano de registro (${regYear})`);
        }
      }
    }
  };

  const getThemeColor = () => {
    if (hotel === 'VILLAGE') return '#26A6A6';
    if (hotel === 'GOLDEN_PARK') return '#BF984E';
    if (hotel === 'THERMAL_RESORT') return '#68A672';
    return '#1e293b';
  };

  const filteredEmployees = availableEmployees.filter(e => e.sectorId === selectedSectorId);

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans text-slate-900">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-500">
        <div className="p-10 space-y-8">
          <div className="text-center space-y-2">
            <h1 className="text-4xl font-black text-slate-800 tracking-tighter">Nacional Inn</h1>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em]">Gestão Hotel Village</p>
          </div>

          {!accessType ? (
            <div className="space-y-4">
              <p className="text-sm font-bold text-slate-500 text-center mb-6">Selecione o tipo de acesso</p>
              <button 
                onClick={() => setAccessType('EMPLOYEE')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-emerald-50 border-2 border-transparent hover:border-emerald-200 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white rounded-2xl text-emerald-500 shadow-sm"><Users size={24} /></div>
                  <div className="text-left">
                    <p className="font-black text-slate-800">Colaborador</p>
                    <p className="text-xs text-slate-400 font-medium">Equipe Operacional</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-emerald-500" />
              </button>

              <button 
                onClick={() => setAccessType('ADMIN')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-slate-900 hover:text-white border-2 border-transparent hover:border-slate-800 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white group-hover:bg-slate-800 rounded-2xl text-slate-800 group-hover:text-white shadow-sm transition-colors"><Lock size={24} /></div>
                  <div className="text-left">
                    <p className="font-black group-hover:text-white text-slate-800">Administrativo</p>
                    <p className="text-xs text-slate-400 group-hover:text-slate-400 font-medium">Gestão & Diretoria</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-white" />
              </button>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <button 
                onClick={() => { setAccessType(null); setRole(null); setError(''); setHotel(''); setPassword(''); setSelectedEmployeeId(''); setSelectedSectorId(''); }}
                className="text-xs font-black text-blue-500 hover:underline flex items-center"
              >
                <ChevronRight size={14} className="rotate-180 mr-1" /> Voltar
              </button>

              <div className="space-y-4">
                {/* Seleção de Unidade */}
                {(accessType === 'EMPLOYEE' || (accessType === 'ADMIN' && role === 'GERENCIA')) && (
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Building2 size={12} className="mr-1"/> Unidade</label>
                    <div className="grid grid-cols-1 gap-2">
                      {hotels.map(h => (
                        <button 
                          key={h.id}
                          onClick={() => { setHotel(h.id); handleFetchData(h.id); setError(''); }}
                          className={`p-4 rounded-2xl border-2 text-sm font-bold transition-all text-left ${
                            hotel === h.id ? 'border-slate-800 bg-slate-800 text-white shadow-md' : 'border-slate-100 bg-slate-50 text-slate-500 hover:border-slate-300'
                          }`}
                        >
                          {h.label}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Perfil Admin */}
                {accessType === 'ADMIN' && !role && (
                  <div className="grid grid-cols-1 gap-2 animate-in fade-in">
                    <button onClick={() => setRole('GERENCIA')} className="p-5 rounded-2xl border-2 border-slate-100 text-slate-600 font-bold text-sm hover:bg-slate-50">Supervisão / Gerência</button>
                    <button onClick={() => setRole('DIRETORIA')} className="p-5 rounded-2xl border-2 border-slate-100 text-slate-600 font-bold text-sm hover:bg-slate-50">Diretoria Nacional Inn</button>
                  </div>
                )}

                {/* Fluxo de Funcionário (Dinamico) */}
                {accessType === 'EMPLOYEE' && hotel && (
                  <div className="space-y-4 animate-in slide-in-from-top-2">
                    {isLoading ? (
                      <div className="flex flex-col items-center py-8">
                        <div className="w-8 h-8 border-4 border-slate-100 border-t-blue-500 rounded-full animate-spin"></div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-4 tracking-widest">Sincronizando...</p>
                      </div>
                    ) : (
                      <>
                        <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Briefcase size={12} className="mr-1"/> Setor</label>
                          <select 
                            value={selectedSectorId} 
                            onChange={(e) => { setSelectedSectorId(e.target.value); setSelectedEmployeeId(''); setPassword(''); }}
                            className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                          >
                            <option value="">Selecione o setor...</option>
                            {availableSectors.map(s => (
                              <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                          </select>
                        </div>

                        {selectedSectorId && (
                          <div className="animate-in slide-in-from-top-2 space-y-4">
                            <div>
                              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><UserIcon size={12} className="mr-1"/> Colaborador</label>
                              <select 
                                value={selectedEmployeeId} 
                                onChange={(e) => { setSelectedEmployeeId(e.target.value); setPassword(''); }}
                                className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                              >
                                <option value="">Quem está acessando?</option>
                                {filteredEmployees.map(e => (
                                  <option key={e.id} value={e.id}>{e.name}</option>
                                ))}
                              </select>
                            </div>

                            {selectedEmployeeId && (
                              <div className="animate-in slide-in-from-top-2">
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Lock size={12} className="mr-1"/> Senha de Acesso</label>
                                <div className="relative">
                                  <input 
                                    type={showPassword ? "text" : "password"}
                                    placeholder="Senha (nome+ano)"
                                    value={password}
                                    onChange={(e) => { setPassword(e.target.value); setError(''); }}
                                    className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-blue-400 outline-none transition-all font-bold text-slate-900"
                                  />
                                  <button 
                                    type="button" 
                                    onClick={() => setShowPassword(!showPassword)}
                                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400"
                                  >
                                    {showPassword ? <EyeOff size={20}/> : <Eye size={20}/>}
                                  </button>
                                </div>
                              </div>
                            )}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                )}

                {/* Senha Administrativa */}
                {accessType === 'ADMIN' && role && (
                  <div className="animate-in slide-in-from-top-2">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Lock size={12} className="mr-1"/> Senha de {role}</label>
                    <input 
                      type="password"
                      placeholder="••••••••"
                      value={password}
                      onChange={(e) => { setPassword(e.target.value); setError(''); }}
                      className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-blue-400 outline-none transition-all font-bold tracking-widest text-slate-900"
                    />
                  </div>
                )}

                {error && (
                  <div className="p-4 bg-red-50 text-red-500 rounded-2xl flex items-center space-x-3 text-xs font-bold border border-red-100 animate-shake">
                    <AlertCircle size={16} className="shrink-0" />
                    <span>{error}</span>
                  </div>
                )}

                <button 
                  onClick={handleEnter}
                  disabled={isLoading || (accessType === 'EMPLOYEE' && !selectedEmployeeId)}
                  className="w-full py-5 rounded-[1.5rem] font-black text-white shadow-xl transition-all active:scale-95 hover:brightness-110 disabled:opacity-50"
                  style={{ backgroundColor: getThemeColor() }}
                >
                  {isLoading ? 'Aguarde...' : 'Entrar no Sistema'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector, InventoryItem, InventoryOperation, Supplier } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyHwnTqgnBMecAsscAIJgpfe7gHPwjWbZ42qbm3EvXvX_oq9WzbrrT99knh7L4wdvDe4g/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v24');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);
    const targetHotel = hotelOverride || state.currentHotel;
    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, { method: 'GET', mode: 'cors' });
      const data = await response.json();
      if (data && data.status === 'success') {
        // Garantir que os setores padrão existam se a planilha não retornar nada
        const initial = getInitialHotelData();
        const mergedData = {
          ...data.data,
          sectors: data.data.sectors && data.data.sectors.length > 0 
            ? data.data.sectors 
            : (state.hotels[targetHotel]?.sectors || initial.sectors)
        };

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...mergedData
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return mergedData;
      }
    } catch (error) { 
      console.warn("Erro ao carregar dados da planilha:", error); 
    } finally { 
      setIsRefreshing(false); 
    }
  }, [state.currentHotel, state.hotels]);

  // Carregamento inicial para garantir que o login tenha dados
  useEffect(() => {
    loadDataFromSheet('VILLAGE');
    loadDataFromSheet('GOLDEN_PARK');
    loadDataFromSheet('THERMAL_RESORT');
  }, []);

  useEffect(() => { 
    if (state.currentUser) {
      loadDataFromSheet(); 
    }
  }, [state.currentUser, loadDataFromSheet]);

  useEffect(() => { 
    const stateToSave = { 
      ...state, 
      currentUser: null,
      hotels: state.hotels 
    }; 
    localStorage.setItem('hotel_village_state_v24', JSON.stringify(stateToSave)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    if (GLOBAL_SCRIPT_URL) {
      try {
        await fetch(GLOBAL_SCRIPT_URL, { 
          method: 'POST', 
          mode: 'no-cors', 
          body: JSON.stringify({ 
            dataType, 
            hotel: state.currentHotel, 
            ...data, 
            newFiles: files 
          }) 
        });
        setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));

        // RECARREGAR SEMPRE para garantir que o sistema não perca o dado recém criado
        if(dataType === 'DELETE' || dataType === 'INVENTORY_OP' || dataType === 'EMPLOYEE' || dataType === 'SECTOR' || files?.length || dataType === 'BUDGET') {
           setTimeout(() => loadDataFromSheet(), 3000);
        }
      } catch (err) { 
        console.error('Falha na sincronização:', err); 
      }
    }
  };

  const handleUpdateConfig = (config: any) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } }
      }
    }));
    syncToSheet('CONFIG', config);
  };

  const handleSaveInventory = (item: InventoryItem) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.inventory.find(i => i.id === item.id);
      const newInventory = exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: newInventory } } };
    });
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'INVENTORY', id });
  };

  const handleSaveSupplier = (supplier: Supplier) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.suppliers.find(s => s.id === supplier.id);
      const newSuppliers = exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: newSuppliers } } };
    });
    syncToSheet('SUPPLIER', supplier);
  };

  const handleDeleteSupplier = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'SUPPLIER', id });
  };

  const handleLogin = (user: User) => {
    setState(prev => {
      const nextView = user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD;
      return { 
        ...prev, 
        currentUser: user,
        currentHotel: user.hotel || prev.currentHotel,
        currentView: nextView
      };
    });
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme} 
            onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} 
            onSave={(updatedApt, files) => { 
              setState(prev => ({
                ...prev, 
                hotels: {
                  ...prev.hotels, 
                  [prev.currentHotel]: {
                    ...prev.hotels[prev.currentHotel], 
                    apartments: {
                      ...prev.hotels[prev.currentHotel].apartments, 
                      [updatedApt.id]: updatedApt
                    }
                  }
                }
              })); 
              syncToSheet('APARTMENT', updatedApt, files); 
            }} 
          />
        );
      }
      if (state.selectedFloor !== null) {
        return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      }
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }
    if (state.currentView === ViewType.BUDGETS) return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={(b, f) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], budgets: prev.hotels[prev.currentHotel].budgets.find(ex => ex.id === b.id) ? prev.hotels[prev.currentHotel].budgets.map(ex => ex.id === b.id ? b : ex) : [b, ...prev.hotels[prev.currentHotel].budgets]}}})); syncToSheet('BUDGET', b, f); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], budgets: prev.hotels[prev.currentHotel].budgets.filter(b => b.id !== id)}}})); syncToSheet('DELETE', { targetType: 'BUDGET', id }); }} />;
    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={handleSaveInventory} onDelete={handleDeleteInventory} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const newQuantity = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity; const updatedItem = { ...item, quantity: newQuantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={handleUpdateConfig} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        currentHotel={state.currentHotel} 
        onHotelChange={h => setState(prev => ({...prev, currentHotel: h}))} 
        onLogout={() => setState(prev => ({...prev, currentUser: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <BottomNav 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserRole, HotelType, User, Sector, Employee } from '../types';
import { Hotel, User as UserIcon, Lock, ChevronRight, AlertCircle, Building2, Briefcase, Eye, EyeOff, Users } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
  onFetchHotelData: (hotel: HotelType) => Promise<any>;
}

const Login: React.FC<LoginProps> = ({ onLogin, onFetchHotelData }) => {
  const [accessType, setAccessType] = useState<'ADMIN' | 'EMPLOYEE' | null>(null);
  const [role, setRole] = useState<UserRole | null>(null);
  const [hotel, setHotel] = useState<HotelType | ''>('');
  const [selectedSectorId, setSelectedSectorId] = useState<string>('');
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<string>('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const [availableSectors, setAvailableSectors] = useState<Sector[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);

  const hotels: { id: HotelType; label: string }[] = [
    { id: 'VILLAGE', label: 'Village Inn' },
    { id: 'GOLDEN_PARK', label: 'Hotel Golden Park' },
    { id: 'THERMAL_RESORT', label: 'Thermas Resort' },
  ];

  const handleFetchData = async (h: HotelType) => {
    setIsLoading(true);
    setError('');
    // Limpar seleções anteriores ao mudar de hotel
    setSelectedSectorId('');
    setSelectedEmployeeId('');
    setPassword('');

    try {
      const data = await onFetchHotelData(h);
      if (data) {
        setAvailableSectors(data.sectors || []);
        setAvailableEmployees(data.employees || []);
      }
    } catch (err) {
      setError('Erro ao carregar dados do hotel. Verifique a conexão.');
    } finally {
      setIsLoading(false);
    }
  };

  const normalizeString = (str: string) => {
    if (!str) return '';
    return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
  };

  const handleEnter = () => {
    setError('');

    if (accessType === 'ADMIN') {
      if (!role) return;
      if (role === 'GERENCIA') {
        if (!hotel) { setError('Selecione uma unidade'); return; }
        if (password === '123') onLogin({ role, hotel });
        else setError('Senha incorreta para Supervisão');
      } else if (role === 'DIRETORIA') {
        if (password === '0000') onLogin({ role });
        else setError('Senha incorreta para Diretoria');
      }
    } else if (accessType === 'EMPLOYEE') {
      if (!hotel || !selectedSectorId || !selectedEmployeeId) {
        setError('Preencha todos os campos para entrar');
        return;
      }

      const employee = availableEmployees.find(e => e.id === selectedEmployeeId);
      const sector = availableSectors.find(s => s.id === selectedSectorId);

      if (employee && sector) {
        const firstName = normalizeString(employee.name.split(' ')[0]);

        let regYear = '2024';
        if (employee.startDate) {
          if (employee.startDate.includes('-')) {
            regYear = employee.startDate.split('-')[0];
          } else if (employee.startDate.includes('/')) {
            const parts = employee.startDate.split('/');
            regYear = parts[parts.length - 1];
          }
        }

        const expectedPassword = firstName + regYear;

        if (normalizeString(password) === expectedPassword) {
          onLogin({ 
            role: 'FUNCIONARIO', 
            hotel: hotel as HotelType, 
            name: employee.name, 
            sectorId: selectedSectorId,
            sectorName: sector.name
          });
        } else {
          setError(`Senha incorreta. Dica: seu primeiro nome + ano de registro (${regYear})`);
        }
      }
    }
  };

  const getThemeColor = () => {
    if (hotel === 'VILLAGE') return '#26A6A6';
    if (hotel === 'GOLDEN_PARK') return '#BF984E';
    if (hotel === 'THERMAL_RESORT') return '#68A672';
    return '#1e293b';
  };

  const filteredEmployees = availableEmployees.filter(e => e.sectorId === selectedSectorId);

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans text-slate-900">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-500">
        <div className="p-10 space-y-8">
          <div className="text-center space-y-2">
            <h1 className="text-4xl font-black text-slate-800 tracking-tighter">Nacional Inn</h1>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em]">Gestão Hotel Village</p>
          </div>

          {!accessType ? (
            <div className="space-y-4">
              <p className="text-sm font-bold text-slate-500 text-center mb-6">Selecione o tipo de acesso</p>
              <button 
                onClick={() => setAccessType('EMPLOYEE')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-emerald-50 border-2 border-transparent hover:border-emerald-200 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white rounded-2xl text-emerald-500 shadow-sm"><Users size={24} /></div>
                  <div className="text-left">
                    <p className="font-black text-slate-800">Colaborador</p>
                    <p className="text-xs text-slate-400 font-medium">Equipe Operacional</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-emerald-500" />
              </button>

              <button 
                onClick={() => setAccessType('ADMIN')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-slate-900 hover:text-white border-2 border-transparent hover:border-slate-800 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white group-hover:bg-slate-800 rounded-2xl text-slate-800 group-hover:text-white shadow-sm transition-colors"><Lock size={24} /></div>
                  <div className="text-left">
                    <p className="font-black group-hover:text-white text-slate-800">Administrativo</p>
                    <p className="text-xs text-slate-400 group-hover:text-slate-400 font-medium">Gestão & Diretoria</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-white" />
              </button>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <button 
                onClick={() => { setAccessType(null); setRole(null); setError(''); setHotel(''); setPassword(''); setSelectedEmployeeId(''); setSelectedSectorId(''); }}
                className="text-xs font-black text-blue-500 hover:underline flex items-center"
              >
                <ChevronRight size={14} className="rotate-180 mr-1" /> Voltar
              </button>

              <div className="space-y-4">
                {(accessType === 'EMPLOYEE' || (accessType === 'ADMIN' && role === 'GERENCIA')) && (
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Building2 size={12} className="mr-1"/> Unidade</label>
                    <div className="grid grid-cols-1 gap-2">
                      {hotels.map(h => (
                        <button 
                          key={h.id}
                          onClick={() => { setHotel(h.id); handleFetchData(h.id); }}
                          className={`p-4 rounded-2xl border-2 text-sm font-bold transition-all text-left ${
                            hotel === h.id ? 'border-slate-800 bg-slate-800 text-white shadow-md' : 'border-slate-100 bg-slate-50 text-slate-500 hover:border-slate-300'
                          }`}
                        >
                          {h.label}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {accessType === 'ADMIN' && !role && (
                  <div className="grid grid-cols-1 gap-2 animate-in fade-in">
                    <button onClick={() => setRole('GERENCIA')} className="p-5 rounded-2xl border-2 border-slate-100 text-slate-600 font-bold text-sm hover:bg-slate-50">Supervisão / Gerência</button>
                    <button onClick={() => setRole('DIRETORIA')} className="p-5 rounded-2xl border-2 border-slate-100 text-slate-600 font-bold text-sm hover:bg-slate-50">Diretoria Nacional Inn</button>
                  </div>
                )}

                {accessType === 'EMPLOYEE' && hotel && (
                  <div className="space-y-4 animate-in slide-in-from-top-2">
                    {isLoading ? (
                      <div className="flex flex-col items-center py-8">
                        <div className="w-8 h-8 border-4 border-slate-100 border-t-blue-500 rounded-full animate-spin"></div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-4 tracking-widest">Sincronizando...</p>
                      </div>
                    ) : (
                      <>
                        <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Briefcase size={12} className="mr-1"/> Setor</label>
                          <select 
                            value={selectedSectorId} 
                            onChange={(e) => { setSelectedSectorId(e.target.value); setSelectedEmployeeId(''); setPassword(''); }}
                            className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                          >
                            <option value="">Selecione o setor...</option>
                            {availableSectors.map(s => (
                              <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                          </select>
                        </div>

                        {selectedSectorId && (
                          <div className="animate-in slide-in-from-top-2 space-y-4">
                            <div>
                              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><UserIcon size={12} className="mr-1"/> Colaborador</label>
                              <select 
                                value={selectedEmployeeId} 
                                onChange={(e) => { setSelectedEmployeeId(e.target.value); setPassword(''); }}
                                className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                              >
                                <option value="">Quem está acessando?</option>
                                {filteredEmployees.map(e => (
                                  <option key={e.id} value={e.id}>{e.name}</option>
                                ))}
                              </select>
                            </div>

                            {selectedEmployeeId && (
                              <div className="animate-in slide-in-from-top-2">
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Lock size={12} className="mr-1"/> Senha de Acesso</label>
                                <div className="relative">
                                  <input 
                                    type={showPassword ? "text" : "password"}
                                    placeholder="Senha (nome+ano)"
                                    value={password}
                                    onChange={(e) => { setPassword(e.target.value); setError(''); }}
                                    className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-blue-400 outline-none transition-all font-bold text-slate-900"
                                  />
                                  <button 
                                    type="button" 
                                    onClick={() => setShowPassword(!showPassword)}
                                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400"
                                  >
                                    {showPassword ? <EyeOff size={20}/> : <Eye size={20}/>}
                                  </button>
                                </div>
                              </div>
                            )}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                )}

                {accessType === 'ADMIN' && role && (
                  <div className="animate-in slide-in-from-top-2">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Lock size={12} className="mr-1"/> Senha de {role}</label>
                    <input 
                      type="password"
                      placeholder="••••••••"
                      value={password}
                      onChange={(e) => { setPassword(e.target.value); setError(''); }}
                      className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-blue-400 outline-none transition-all font-bold tracking-widest text-slate-900"
                    />
                  </div>
                )}

                {error && (
                  <div className="p-4 bg-red-50 text-red-500 rounded-2xl flex items-center space-x-3 text-xs font-bold border border-red-100 animate-shake">
                    <AlertCircle size={16} className="shrink-0" />
                    <span>{error}</span>
                  </div>
                )}

                <button 
                  onClick={handleEnter}
                  disabled={isLoading || (accessType === 'EMPLOYEE' && !selectedEmployeeId)}
                  className="w-full py-5 rounded-[1.5rem] font-black text-white shadow-xl transition-all active:scale-95 hover:brightness-110 disabled:opacity-50"
                  style={{ backgroundColor: getThemeColor() }}
                >
                  {isLoading ? 'Aguarde...' : 'Entrar no Sistema'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector, InventoryItem, InventoryOperation, Supplier } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyHwnTqgnBMecAsscAIJgpfe7gHPwjWbZ42qbm3EvXvX_oq9WzbrrT99knh7L4wdvDe4g/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v24');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);
    const targetHotel = hotelOverride || state.currentHotel;
    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, { method: 'GET', mode: 'cors' });
      const data = await response.json();
      if (data && data.status === 'success') {
        // NORMALIZAÇÃO: Garantir que IDs de setor sejam sempre strings para comparação correta
        const normalizedEmployees = (data.data.employees || []).map((emp: any) => ({
          ...emp,
          sectorId: emp.sectorId ? emp.sectorId.toString() : ''
        }));

        const normalizedSectors = (data.data.sectors || []).map((sec: any) => ({
          ...sec,
          id: sec.id ? sec.id.toString() : ''
        }));

        const mergedData = {
          ...data.data,
          employees: normalizedEmployees,
          sectors: normalizedSectors.length > 0 ? normalizedSectors : state.hotels[targetHotel].sectors
        };

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...mergedData
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return mergedData;
      }
    } catch (error) { 
      console.warn("Erro ao carregar dados da planilha:", error); 
    } finally { 
      setIsRefreshing(false); 
    }
  }, [state.currentHotel, state.hotels]);

  // Carregamento inicial exaustivo para evitar que o login inicie vazio
  useEffect(() => {
    const init = async () => {
      await loadDataFromSheet('VILLAGE');
      await loadDataFromSheet('GOLDEN_PARK');
      await loadDataFromSheet('THERMAL_RESORT');
    };
    init();
  }, [loadDataFromSheet]);

  useEffect(() => { 
    if (state.currentUser) {
      loadDataFromSheet(); 
    }
  }, [state.currentUser, loadDataFromSheet]);

  useEffect(() => { 
    const stateToSave = { 
      ...state, 
      currentUser: state.currentUser, // Manter o usuário logado se quiser, mas aqui resetamos para login
      hotels: state.hotels 
    }; 
    localStorage.setItem('hotel_village_state_v24', JSON.stringify(stateToSave)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    if (GLOBAL_SCRIPT_URL) {
      try {
        await fetch(GLOBAL_SCRIPT_URL, { 
          method: 'POST', 
          mode: 'no-cors', 
          body: JSON.stringify({ 
            dataType, 
            hotel: state.currentHotel, 
            ...data, 
            newFiles: files 
          }) 
        });
        setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));

        // RECARREGAR IMEDIATAMENTE após salvar funcionário
        if(dataType === 'EMPLOYEE' || dataType === 'SECTOR' || dataType === 'DELETE') {
           setTimeout(() => loadDataFromSheet(), 2000);
        }
      } catch (err) { 
        console.error('Falha na sincronização:', err); 
      }
    }
  };

  const handleUpdateConfig = (config: any) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } }
      }
    }));
    syncToSheet('CONFIG', config);
  };

  const handleSaveInventory = (item: InventoryItem) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.inventory.find(i => i.id === item.id);
      const newInventory = exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: newInventory } } };
    });
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'INVENTORY', id });
  };

  const handleSaveSupplier = (supplier: Supplier) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.suppliers.find(s => s.id === supplier.id);
      const newSuppliers = exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: newSuppliers } } };
    });
    syncToSheet('SUPPLIER', supplier);
  };

  const handleDeleteSupplier = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'SUPPLIER', id });
  };

  const handleLogin = (user: User) => {
    setState(prev => {
      const nextView = user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD;
      return { 
        ...prev, 
        currentUser: user,
        currentHotel: user.hotel || prev.currentHotel,
        currentView: nextView
      };
    });
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme} 
            onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} 
            onSave={(updatedApt, files) => { 
              setState(prev => ({
                ...prev, 
                hotels: {
                  ...prev.hotels, 
                  [prev.currentHotel]: {
                    ...prev.hotels[prev.currentHotel], 
                    apartments: {
                      ...prev.hotels[prev.currentHotel].apartments, 
                      [updatedApt.id]: updatedApt
                    }
                  }
                }
              })); 
              syncToSheet('APARTMENT', updatedApt, files); 
            }} 
          />
        );
      }
      if (state.selectedFloor !== null) {
        return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      }
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }
    if (state.currentView === ViewType.BUDGETS) return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={(b, f) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], budgets: prev.hotels[prev.currentHotel].budgets.find(ex => ex.id === b.id) ? prev.hotels[prev.currentHotel].budgets.map(ex => ex.id === b.id ? b : ex) : [b, ...prev.hotels[prev.currentHotel].budgets]}}})); syncToSheet('BUDGET', b, f); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], budgets: prev.hotels[prev.currentHotel].budgets.filter(b => b.id !== id)}}})); syncToSheet('DELETE', { targetType: 'BUDGET', id }); }} />;
    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={handleSaveInventory} onDelete={handleDeleteInventory} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const newQuantity = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity; const updatedItem = { ...item, quantity: newQuantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={handleUpdateConfig} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        currentHotel={state.currentHotel} 
        onHotelChange={h => setState(prev => ({...prev, currentHotel: h}))} 
        onLogout={() => setState(prev => ({...prev, currentUser: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <BottomNav 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserRole, HotelType, User, Sector, Employee } from '../types';
import { Hotel, User as UserIcon, Lock, ChevronRight, AlertCircle, Building2, Briefcase, Eye, EyeOff, Users } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
  onFetchHotelData: (hotel: HotelType) => Promise<any>;
}

const Login: React.FC<LoginProps> = ({ onLogin, onFetchHotelData }) => {
  const [accessType, setAccessType] = useState<'ADMIN' | 'EMPLOYEE' | null>(null);
  const [role, setRole] = useState<UserRole | null>(null);
  const [hotel, setHotel] = useState<HotelType | ''>('');
  const [selectedSectorId, setSelectedSectorId] = useState<string>('');
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<string>('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const [availableSectors, setAvailableSectors] = useState<Sector[]>([]);
  const [availableEmployees, setAvailableEmployees] = useState<Employee[]>([]);

  const hotels: { id: HotelType; label: string }[] = [
    { id: 'VILLAGE', label: 'Village Inn' },
    { id: 'GOLDEN_PARK', label: 'Hotel Golden Park' },
    { id: 'THERMAL_RESORT', label: 'Thermas Resort' },
  ];

  const handleFetchData = async (h: HotelType) => {
    setIsLoading(true);
    setError('');
    setSelectedSectorId('');
    setSelectedEmployeeId('');
    setPassword('');

    try {
      const data = await onFetchHotelData(h);
      if (data) {
        setAvailableSectors(data.sectors || []);
        setAvailableEmployees(data.employees || []);
      }
    } catch (err) {
      setError('Erro ao carregar dados do hotel. Verifique a conexão.');
    } finally {
      setIsLoading(false);
    }
  };

  const normalizeString = (str: string) => {
    if (!str) return '';
    return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
  };

  const handleEnter = () => {
    setError('');

    if (accessType === 'ADMIN') {
      if (!role) return;
      if (role === 'GERENCIA') {
        if (!hotel) { setError('Selecione uma unidade'); return; }
        if (password === '123') onLogin({ role, hotel });
        else setError('Senha incorreta para Supervisão');
      } else if (role === 'DIRETORIA') {
        if (password === '0000') onLogin({ role });
        else setError('Senha incorreta para Diretoria');
      }
    } else if (accessType === 'EMPLOYEE') {
      if (!hotel || !selectedSectorId || !selectedEmployeeId) {
        setError('Preencha todos os campos para entrar');
        return;
      }

      const employee = availableEmployees.find(e => e.id.toString() === selectedEmployeeId.toString());
      const sector = availableSectors.find(s => s.id.toString() === selectedSectorId.toString());

      if (employee && sector) {
        const firstName = normalizeString(employee.name.split(' ')[0]);

        let regYear = '2024';
        if (employee.startDate) {
          const dateStr = employee.startDate.toString();
          if (dateStr.includes('-')) {
            regYear = dateStr.split('-')[0];
          } else if (dateStr.includes('/')) {
            const parts = dateStr.split('/');
            regYear = parts[parts.length - 1];
          }
        }

        const expectedPassword = firstName + regYear;

        if (normalizeString(password) === expectedPassword) {
          onLogin({ 
            role: 'FUNCIONARIO', 
            hotel: hotel as HotelType, 
            name: employee.name, 
            sectorId: selectedSectorId,
            sectorName: sector.name
          });
        } else {
          setError(`Senha incorreta. Dica: seu primeiro nome + ano de registro (${regYear})`);
        }
      }
    }
  };

  const getThemeColor = () => {
    if (hotel === 'VILLAGE') return '#26A6A6';
    if (hotel === 'GOLDEN_PARK') return '#BF984E';
    if (hotel === 'THERMAL_RESORT') return '#68A672';
    return '#1e293b';
  };

  // Comparação flexível para evitar problemas com string vs number do Sheets
  const filteredEmployees = availableEmployees.filter(e => e.sectorId.toString() === selectedSectorId.toString());

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans text-slate-900">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-500">
        <div className="p-10 space-y-8">
          <div className="text-center space-y-2">
            <h1 className="text-4xl font-black text-slate-800 tracking-tighter">Nacional Inn</h1>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em]">Gestão Hotel Village</p>
          </div>

          {!accessType ? (
            <div className="space-y-4">
              <p className="text-sm font-bold text-slate-500 text-center mb-6">Selecione o tipo de acesso</p>
              <button 
                onClick={() => setAccessType('EMPLOYEE')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-emerald-50 border-2 border-transparent hover:border-emerald-200 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white rounded-2xl text-emerald-500 shadow-sm"><Users size={24} /></div>
                  <div className="text-left">
                    <p className="font-black text-slate-800">Colaborador</p>
                    <p className="text-xs text-slate-400 font-medium">Equipe Operacional</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-emerald-500" />
              </button>

              <button 
                onClick={() => setAccessType('ADMIN')}
                className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-slate-900 hover:text-white border-2 border-transparent hover:border-slate-800 rounded-3xl transition-all group"
              >
                <div className="flex items-center space-x-4">
                  <div className="p-3 bg-white group-hover:bg-slate-800 rounded-2xl text-slate-800 group-hover:text-white shadow-sm transition-colors"><Lock size={24} /></div>
                  <div className="text-left">
                    <p className="font-black group-hover:text-white text-slate-800">Administrativo</p>
                    <p className="text-xs text-slate-400 group-hover:text-slate-400 font-medium">Gestão & Diretoria</p>
                  </div>
                </div>
                <ChevronRight size={20} className="text-slate-300 group-hover:text-white" />
              </button>
            </div>
          ) : (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <button 
                onClick={() => { setAccessType(null); setRole(null); setError(''); setHotel(''); setPassword(''); setSelectedEmployeeId(''); setSelectedSectorId(''); }}
                className="text-xs font-black text-blue-500 hover:underline flex items-center"
              >
                <ChevronRight size={14} className="rotate-180 mr-1" /> Voltar
              </button>

              <div className="space-y-4">
                {(accessType === 'EMPLOYEE' || (accessType === 'ADMIN' && role === 'GERENCIA')) && (
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Building2 size={12} className="mr-1"/> Unidade</label>
                    <div className="grid grid-cols-1 gap-2">
                      {hotels.map(h => (
                        <button 
                          key={h.id}
                          onClick={() => { setHotel(h.id); handleFetchData(h.id); }}
                          className={`p-4 rounded-2xl border-2 text-sm font-bold transition-all text-left ${
                            hotel === h.id ? 'border-slate-800 bg-slate-800 text-white shadow-md' : 'border-slate-100 bg-slate-50 text-slate-500 hover:border-slate-300'
                          }`}
                        >
                          {h.label}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {accessType === 'ADMIN' && !role && (
                  <div className="grid grid-cols-1 gap-2 animate-in fade-in">
                    <button onClick={() => setRole('GERENCIA')} className="p-5 rounded-2xl border-2 border-slate-100 text-slate-600 font-bold text-sm hover:bg-slate-50">Supervisão / Gerência</button>
                    <button onClick={() => setRole('DIRETORIA')} className="p-5 rounded-2xl border-2 border-slate-100 text-slate-600 font-bold text-sm hover:bg-slate-50">Diretoria Nacional Inn</button>
                  </div>
                )}

                {accessType === 'EMPLOYEE' && hotel && (
                  <div className="space-y-4 animate-in slide-in-from-top-2">
                    {isLoading ? (
                      <div className="flex flex-col items-center py-8">
                        <div className="w-8 h-8 border-4 border-slate-100 border-t-blue-500 rounded-full animate-spin"></div>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-4 tracking-widest">Sincronizando...</p>
                      </div>
                    ) : (
                      <>
                        <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Briefcase size={12} className="mr-1"/> Setor</label>
                          <select 
                            value={selectedSectorId} 
                            onChange={(e) => { setSelectedSectorId(e.target.value); setSelectedEmployeeId(''); setPassword(''); }}
                            className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                          >
                            <option value="">Selecione o setor...</option>
                            {availableSectors.map(s => (
                              <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                          </select>
                        </div>

                        {selectedSectorId && (
                          <div className="animate-in slide-in-from-top-2 space-y-4">
                            <div>
                              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><UserIcon size={12} className="mr-1"/> Colaborador</label>
                              <select 
                                value={selectedEmployeeId} 
                                onChange={(e) => { setSelectedEmployeeId(e.target.value); setPassword(''); }}
                                className="w-full p-4 rounded-2xl border-2 border-slate-100 font-bold text-slate-800 outline-none focus:border-blue-400"
                              >
                                <option value="">Quem está acessando?</option>
                                {filteredEmployees.map(e => (
                                  <option key={e.id} value={e.id}>{e.name}</option>
                                ))}
                              </select>
                            </div>

                            {selectedEmployeeId && (
                              <div className="animate-in slide-in-from-top-2">
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Lock size={12} className="mr-1"/> Senha de Acesso</label>
                                <div className="relative">
                                  <input 
                                    type={showPassword ? "text" : "password"}
                                    placeholder="Senha (nome+ano)"
                                    value={password}
                                    onChange={(e) => { setPassword(e.target.value); setError(''); }}
                                    className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-blue-400 outline-none transition-all font-bold text-slate-900"
                                  />
                                  <button 
                                    type="button" 
                                    onClick={() => setShowPassword(!showPassword)}
                                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400"
                                  >
                                    {showPassword ? <EyeOff size={20}/> : <Eye size={20}/>}
                                  </button>
                                </div>
                              </div>
                            )}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                )}

                {accessType === 'ADMIN' && role && (
                  <div className="animate-in slide-in-from-top-2">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><Lock size={12} className="mr-1"/> Senha de {role}</label>
                    <input 
                      type="password"
                      placeholder="••••••••"
                      value={password}
                      onChange={(e) => { setPassword(e.target.value); setError(''); }}
                      className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-blue-400 outline-none transition-all font-bold tracking-widest text-slate-900"
                    />
                  </div>
                )}

                {error && (
                  <div className="p-4 bg-red-50 text-red-500 rounded-2xl flex items-center space-x-3 text-xs font-bold border border-red-100 animate-shake">
                    <AlertCircle size={16} className="shrink-0" />
                    <span>{error}</span>
                  </div>
                )}

                <button 
                  onClick={handleEnter}
                  disabled={isLoading || (accessType === 'EMPLOYEE' && !selectedEmployeeId)}
                  className="w-full py-5 rounded-[1.5rem] font-black text-white shadow-xl transition-all active:scale-95 hover:brightness-110 disabled:opacity-50"
                  style={{ backgroundColor: getThemeColor() }}
                >
                  {isLoading ? 'Aguarde...' : 'Entrar no Sistema'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { Integration, HotelTheme } from '../types';
import { Copy, FileSpreadsheet, XCircle } from 'lucide-react';

interface IntegrationsViewProps {
  integrations: Integration[];
  theme: HotelTheme;
  onUpdate: (integration: Integration) => void;
}

const APPS_SCRIPT_CODE = `/**
 * Google Apps Script para Gestão Hotel Village - V24 (Full Connection)
 * Sincronização Completa: Apartamentos, Estoque, Funcionários, Setores e Orçamentos.
 */

function doGet(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = e.parameter.hotel || 'VILLAGE';
    var result = {
      apartments: {}, budgets: [], employees: [], sectors: [], inventory: [], inventoryHistory: [], suppliers: [], config: {}
    };

    // 1. Apartamentos
    var sheetApts = ss.getSheetByName('Apartamentos_' + hotel);
    if (sheetApts) {
      var data = sheetApts.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        var num = data[i][0]; var floor = data[i][1]; if(!num || !floor) continue;
        var aptId = floor + "-" + num;
        result.apartments[aptId] = {
          id: aptId, roomNumber: num, floor: floor, pisoType: data[i][2], pisoStatus: data[i][3], banheiroType: data[i][4],
          banheiroStatus: data[i][5], temCofre: data[i][6] === 'Sim', temCortina: data[i][7] === 'Sim',
          cortinaStatus: data[i][8], cortinaSize: data[i][9], cortinaCoverage: data[i][10], temEspelhoCorpo: data[i][11] === 'Sim',
          espelhoCorpoStatus: data[i][12], acBrand: data[i][13], moveisStatus: data[i][14],
          moveisDetalhes: safeParse(data[i][15], []), beds: safeParse(data[i][16], []),
          temPortaControle: data[i][17] === 'Sim', temCabide: data[i][18] === 'Sim', cabideQuantity: data[i][19] || 0,
          temSuportePapel: data[i][20] === 'Sim', temSuporteShampoo: data[i][21] === 'Sim', suporteShampooStatus: data[i][22],
          luminariaType: data[i][23], luminariaColor: data[i][24], tvBrand: data[i][25], defects: safeParse(data[i][26], [])
        };
      }
    }

    // 2. Estoque
    var sheetInv = ss.getSheetByName('Estoque_' + hotel);
    if (sheetInv) {
      var dataI = sheetInv.getDataRange().getValues();
      for (var m = 1; m < dataI.length; m++) {
        if(!dataI[m][0]) continue;
        result.inventory.push({ 
          id: dataI[m][0].toString(), ean: dataI[m][1].toString(), name: dataI[m][2], category: dataI[m][3], 
          quantity: parseFloat(dataI[m][4]) || 0, minQuantity: dataI[m][5] || 0, unit: dataI[m][6], price: dataI[m][7] || 0, 
          supplierId: dataI[m][8] ? dataI[m][8].toString() : '', lastUpdate: dataI[m][9] ? new Date(dataI[m][9]).getTime() : Date.now()
        });
      }
    }

    // 3. Fornecedores
    var sheetSup = ss.getSheetByName('Fornecedores_' + hotel);
    if (sheetSup) {
      var dataS = sheetSup.getDataRange().getValues();
      for (var j = 1; j < dataS.length; j++) {
        if(!dataS[j][0]) continue;
        result.suppliers.push({ id: dataS[j][0].toString(), name: dataS[j][1], contact: dataS[j][2], category: dataS[j][3] });
      }
    }

    // 4. Funcionários
    var sheetEmp = ss.getSheetByName('Funcionarios_' + hotel);
    if (sheetEmp) {
      var dE = sheetEmp.getDataRange().getValues();
      for (var k = 1; k < dE.length; k++) { 
        if(!dE[k][0]) continue; 
        result.employees.push({ 
          id: dE[k][0].toString(), 
          name: dE[k][1], 
          role: dE[k][2], 
          contact: dE[k][3], 
          startDate: dE[k][4], 
          salary: dE[k][5], 
          department: dE[k][6], 
          sectorId: dE[k][7] ? dE[k][7].toString() : '', 
          status: dE[k][8], 
          scheduleType: dE[k][9], 
          shiftType: dE[k][10], 
          workingHours: dE[k][11], 
          weeklyDayOff: dE[k][12], 
          monthlySundayOff: dE[k][13], 
          vacationStatus: dE[k][14], 
          uniforms: safeParse(dE[k][15], []) 
        }); 
      }
    }

    // 5. Setores
    var sheetSec = ss.getSheetByName('Setores_' + hotel);
    if (sheetSec) {
      var dSc = sheetSec.getDataRange().getValues();
      for (var s = 1; s < dSc.length; s++) {
        if(!dSc[s][0]) continue;
        result.sectors.push({ id: dSc[s][0].toString(), name: dSc[s][1], standardUniform: safeParse(dSc[s][2], []) });
      }
    }

    // 6. Orçamentos
    var sheetOrc = ss.getSheetByName('Orcamentos_' + hotel);
    if (sheetOrc) {
      var dO = sheetOrc.getDataRange().getValues();
      for (var n = 1; n < dO.length; n++) {
        if(!dO[n][0]) continue;
        result.budgets.push({ id: dO[n][0].toString(), title: dO[n][1], objective: dO[n][2], items: safeParse(dO[n][3], []), quotes: safeParse(dO[n][4], []), status: dO[n][5], createdAt: dO[n][6] ? new Date(dO[n][6]).getTime() : Date.now() });
      }
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var req = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = req.hotel || 'VILLAGE';
    var folder = getFolder("Gestão Hotel Village - Arquivos");

    if (req.newFiles && req.newFiles.length > 0) {
      req.newFiles.forEach(function(f) {
        var blob = Utilities.newBlob(Utilities.base64Decode(f.data), f.mimeType, f.fileName);
        var driveFile = folder.createFile(blob);
        driveFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
        var driveUrl = "https://drive.google.com/thumbnail?id=" + driveFile.getId() + "&sz=w1000";

        if (req.dataType === 'APARTMENT') {
           req.defects.forEach(function(d) { if(d.fileName === f.fileName) { d.driveLink = driveUrl; delete d.data; } });
        }
        if (req.dataType === 'BUDGET') {
           req.quotes.forEach(function(q) { 
             if(q.files) q.files.forEach(function(bf) { if(bf.fileName === f.fileName) { bf.driveLink = driveUrl; delete bf.data; } });
           });
        }
      });
    }

    if (req.dataType === 'DELETE') {
       var target = "";
       if(req.targetType === 'INVENTORY') target = 'Estoque_' + hotel;
       else if(req.targetType === 'SUPPLIER') target = 'Fornecedores_' + hotel;
       else if(req.targetType === 'BUDGET') target = 'Orcamentos_' + hotel;
       else if(req.targetType === 'EMPLOYEE') target = 'Funcionarios_' + hotel;
       else if(req.targetType === 'SECTOR') target = 'Setores_' + hotel;
       if(target) deleteRow(ss.getSheetByName(target), req.id);
    } 
    else if (req.dataType === 'EMPLOYEE') {
       var sheet = ss.getSheetByName('Funcionarios_' + hotel) || ss.insertSheet('Funcionarios_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.name, req.role, req.contact, req.startDate, req.salary, req.department, req.sectorId.toString(), req.status, req.scheduleType, req.shiftType || '', req.workingHours, req.weeklyDayOff, req.monthlySundayOff, req.vacationStatus, JSON.stringify(req.uniforms)]);
    }
    else if (req.dataType === 'SECTOR') {
       var sheet = ss.getSheetByName('Setores_' + hotel) || ss.insertSheet('Setores_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.name, JSON.stringify(req.standardUniform)]);
    }
    else if (req.dataType === 'BUDGET') {
       var sheet = ss.getSheetByName('Orcamentos_' + hotel) || ss.insertSheet('Orcamentos_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.title, req.objective, JSON.stringify(req.items), JSON.stringify(req.quotes), req.status, new Date(req.createdAt)]);
    }
    else if (req.dataType === 'INVENTORY_OP') {
       var sheetEst = ss.getSheetByName('Estoque_' + hotel);
       if (sheetEst) updateInventoryBalance(sheetEst, req.itemId, req.type, req.quantity);
    } 
    else if (req.dataType === 'INVENTORY') {
       var sheet = ss.getSheetByName('Estoque_' + hotel) || ss.insertSheet('Estoque_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.ean || '', req.name, req.category, req.quantity, 0, req.unit, req.price || 0, req.supplierId ? req.supplierId.toString() : '', new Date()]);
    } 
    else if (req.dataType === 'SUPPLIER') {
       var sheet = ss.getSheetByName('Fornecedores_' + hotel) || ss.insertSheet('Fornecedores_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.name, req.contact, req.category]);
    } 
    else if (req.dataType === 'APARTMENT') {
       var sheet = ss.getSheetByName('Apartamentos_' + hotel) || ss.insertSheet('Apartamentos_' + hotel);
       upsert(sheet, req.roomNumber + '-' + req.floor, [req.roomNumber, req.floor, req.pisoType, req.pisoStatus, req.banheiroType, req.banheiroStatus, req.temCofre?'Sim':'Não', req.temCortina?'Sim':'Não', req.cortinaStatus, req.cortinaSize, req.cortinaCoverage, req.temEspelhoCorpo?'Sim':'Não', req.espelhoCorpoStatus, req.acBrand, req.moveisStatus, JSON.stringify(req.moveisDetalhes), JSON.stringify(req.beds), req.temPortaControle?'Sim':'Não', req.temCabide?'Sim':'Não', req.cabideQuantity, req.temSuportePapel?'Sim':'Não', req.temSuporteShampoo?'Sim':'Não', req.suporteShampooStatus, req.luminariaType, req.luminariaColor, req.tvBrand, JSON.stringify(req.defects)]);
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

function safeParse(s, f) { try { if (!s || s == "") return f; return JSON.parse(s); } catch(e) { return f; } }
function getFolder(n) { var fs = DriveApp.getFoldersByName(n); return fs.hasNext() ? fs.next() : DriveApp.createFolder(n); }
function upsert(s, id, r) { var d = s.getDataRange().getValues(); var ids = id.toString().trim(); for (var i = 1; i < d.length; i++) { if (d[i][0].toString().trim() == ids) { s.getRange(i+1, 1, 1, r.length).setValues([r]); return; } } s.appendRow(r); }
function deleteRow(s, id) { if(!s) return; var d = s.getDataRange().getValues(); var ids = id.toString().trim(); for (var i = 1; i < d.length; i++) { if (d[i][0].toString().trim() == ids) { s.deleteRow(i + 1); break; } } }
function updateInventoryBalance(s, id, t, q) { var d = s.getDataRange().getValues(); var ids = id.toString().trim(); for (var i = 1; i < d.length; i++) { if (d[i][0].toString().trim() == ids) { var cur = parseFloat(d[i][4]) || 0; var nxt = (t === 'Entrada') ? cur + q : cur - q; s.getRange(i + 1, 5).setValue(nxt); s.getRange(i + 1, 10).setValue(new Date()); return; } } }
`;

