    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v25');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL) return;
    setIsRefreshing(true);
    const targetHotel = hotelOverride || state.currentHotel;
    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, { method: 'GET', mode: 'cors' });
      const data = await response.json();
      if (data && data.status === 'success') {
        const normalizedEmployees = (data.data.employees || []).map((emp: any) => ({
          ...emp,
          sectorId: emp.sectorId ? emp.sectorId.toString() : ''
        }));

        const normalizedSectors = (data.data.sectors || []).map((sec: any) => ({
          ...sec,
          id: sec.id ? sec.id.toString() : ''
        }));

        const mergedData = {
          ...data.data,
          employees: normalizedEmployees,
          sectors: normalizedSectors.length > 0 ? normalizedSectors : state.hotels[targetHotel].sectors
        };

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...mergedData
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return mergedData;
      }
    } catch (error) { 
      console.warn("Erro ao carregar dados da planilha:", error); 
    } finally { 
      setIsRefreshing(false); 
    }
  }, [state.currentHotel, state.hotels]);

  useEffect(() => {
    const init = async () => {
      await loadDataFromSheet('VILLAGE');
      await loadDataFromSheet('GOLDEN_PARK');
      await loadDataFromSheet('THERMAL_RESORT');
    };
    init();
  }, [loadDataFromSheet]);

  useEffect(() => { 
    if (state.currentUser) {
      loadDataFromSheet(); 
    }
  }, [state.currentUser, loadDataFromSheet]);

  useEffect(() => { 
    const stateToSave = { ...state, hotels: state.hotels }; 
    localStorage.setItem('hotel_village_state_v25', JSON.stringify(stateToSave)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    if (GLOBAL_SCRIPT_URL) {
      try {
        await fetch(GLOBAL_SCRIPT_URL, { 
          method: 'POST', 
          mode: 'no-cors', 
          body: JSON.stringify({ 
            dataType, 
            hotel: state.currentHotel, 
            ...data, 
            newFiles: files 
          }) 
        });
        setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));
        if(dataType === 'EMPLOYEE' || dataType === 'SECTOR' || dataType === 'DELETE' || dataType === 'BUDGET') {
           setTimeout(() => loadDataFromSheet(), 2000);
        }
      } catch (err) { 
        console.error('Falha na sincronização:', err); 
      }
    }
  };

  const handleUpdateConfig = (config: any) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } }
      }
    }));
    syncToSheet('CONFIG', config);
  };

  const handleSaveInventory = (item: InventoryItem) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.inventory.find(i => i.id === item.id);
      const newInventory = exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: newInventory } } };
    });
    syncToSheet('INVENTORY', item);
  };

  const handleDeleteInventory = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'INVENTORY', id });
  };

  const handleSaveSupplier = (supplier: Supplier) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      const exists = hotel.suppliers.find(s => s.id === supplier.id);
      const newSuppliers = exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: newSuppliers } } };
    });
    syncToSheet('SUPPLIER', supplier);
  };

  const handleDeleteSupplier = (id: string) => {
    setState(prev => {
      const hotel = prev.hotels[prev.currentHotel];
      return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } };
    });
    syncToSheet('DELETE', { targetType: 'SUPPLIER', id });
  };

  const handleLogin = (user: User) => {
    setState(prev => {
      const nextView = user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD;
      return { 
        ...prev, 
        currentUser: user,
        currentHotel: user.hotel || prev.currentHotel,
        currentView: nextView
      };
    });
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme} 
            onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} 
            onSave={(updatedApt, files) => { 
              setState(prev => ({
                ...prev, 
                hotels: {
                  ...prev.hotels, 
                  [prev.currentHotel]: {
                    ...prev.hotels[prev.currentHotel], 
                    apartments: {
                      ...prev.hotels[prev.currentHotel].apartments, 
                      [updatedApt.id]: updatedApt
                    }
                  }
                }
              })); 
              syncToSheet('APARTMENT', updatedApt, files); 
            }} 
          />
        );
      }
      if (state.selectedFloor !== null) {
        return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      }
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }

    if (state.currentView === ViewType.BUDGETS) {
      return (
        <BudgetsView 
          budgets={currentHotelData.budgets} 
          theme={theme} 
          onSave={(b, f) => { 
            setState(prev => {
              const hotel = prev.hotels[prev.currentHotel];
              const exists = hotel.budgets.some(ex => ex.id === b.id);
              const updatedBudgets = exists 
                ? hotel.budgets.map(ex => ex.id === b.id ? b : ex)
                : [b, ...hotel.budgets];

              return {
                ...prev,
                hotels: {
                  ...prev.hotels,
                  [prev.currentHotel]: {
                    ...hotel,
                    budgets: updatedBudgets
                  }
                }
              };
            });
            syncToSheet('BUDGET', b, f); 
          }} 
          onDelete={(id) => { 
            setState(prev => ({
              ...prev, 
              hotels: {
                ...prev.hotels, 
                [prev.currentHotel]: {
                  ...prev.hotels[prev.currentHotel], 
                  budgets: prev.hotels[prev.currentHotel].budgets.filter(b => b.id !== id)
                }
              }
            })); 
            syncToSheet('DELETE', { targetType: 'BUDGET', id }); 
          }} 
        />
      );
    }

    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={handleSaveInventory} onDelete={handleDeleteInventory} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const newQuantity = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity; const updatedItem = { ...item, quantity: newQuantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={handleUpdateConfig} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={handleSaveSupplier} onDeleteSupplier={handleDeleteSupplier} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        currentHotel={state.currentHotel} 
        onHotelChange={h => setState(prev => ({...prev, currentHotel: h}))} 
        onLogout={() => setState(prev => ({...prev, currentUser: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <BottomNav 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  DollarSign, 
  ChevronDown,
  ChevronUp,
  X,
  Clock,
  Paperclip,
  File,
  Info,
  Layers,
  Wrench,
  Calendar,
  MessageSquare,
  Truck,
  Calculator,
  Edit2,
  User as UserIcon
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentQuoteIndexRef = useRef<number | null>(null);

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
    setEditingBudget(null);
  };

  const handleEdit = (budget: Budget) => {
    setEditingBudget(budget);
    setTitle(budget.title);
    setObjective(budget.objective);
    setItems(budget.items.map(it => ({ 
      ...it, 
      serviceProvider: it.serviceProvider || '',
      estimatedTime: it.estimatedTime || '' 
    })));

    const budgetQuotes = budget.quotes || [];
    const filledQuotes = [...budgetQuotes];
    while (filledQuotes.length < 3) {
      filledQuotes.push({ id: (Date.now() + filledQuotes.length).toString(), supplier: '', value: 0, files: [] });
    }
    setQuotes(filledQuotes);
    setStatus(budget.status);
    setIsAdding(true);
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...(item.materials || []), { 
            id: Date.now().toString(), 
            name: '', 
            quantity: 1, 
            price: 0,
            unit: 'Un',
            supplier: '',
            observation: ''
          }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: item.materials.filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  const calculateItemSubtotal = (item: BudgetItem) => {
    const materialsTotal = (item.materials || []).reduce((acc, m) => acc + (m.quantity * (m.price || 0)), 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  const totalCalculated = useMemo(() => {
    return items.reduce((acc, item) => acc + calculateItemSubtotal(item), 0);
  }, [items]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBudget: Budget = {
      id: editingBudget?.id || Date.now().toString(),
      title: title || 'Novo Orçamento',
      objective,
      items,
      quotes: (quotes as Quote[]).filter(q => q.supplier || q.value > 0),
      status,
      createdAt: editingBudget?.createdAt || Date.now()
    };

    const allFilesForSync: {data: string, mimeType: string, fileName: string}[] = [];
    quotes.forEach(q => {
      q.files?.forEach(f => {
        if (f.data) {
          allFilesForSync.push({ data: f.data, mimeType: f.fileType!, fileName: f.fileName! });
        }
      });
    });

    onSave(finalBudget, allFilesForSync);
    resetForm();
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500';
      default: return 'bg-amber-400 text-slate-800 border-amber-400';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Buscar orçamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:border-blue-500 outline-none shadow-sm transition-all bg-white text-slate-800 font-bold"
          />
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
          style={{ backgroundColor: theme.primary, boxShadow: `0 10px 15px -3px ${theme.primary}40` }}
        >
          <Plus size={20} />
          <span>Novo Orçamento</span>
        </button>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">{editingBudget ? 'Editar Orçamento' : 'Novo Orçamento'}</h2>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">
                    {editingBudget ? `ID: ${editingBudget.id}` : 'Integração Total com Planilha e Drive'}
                  </p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Título do Projeto</label>
                    <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma do Lobby" className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all font-bold text-slate-800" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Objetivo / Justificativa</label>
                    <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Por que este orçamento é necessário?" className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all h-20 font-bold text-slate-800" />
                  </div>
                </div>

                <div className="space-y-6">
                   <div className="flex justify-between items-center">
                      <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center">
                        <Layers size={16} className="mr-2 text-blue-500" /> Detalhamento de Itens
                      </h3>
                      <button type="button" onClick={addServiceItem} className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl font-black text-[10px] uppercase border border-blue-100 hover:bg-blue-100 transition-all">+ Item de Serviço</button>
                   </div>

                   {items.map((item, idx) => (
                     <div key={item.id} className="p-6 bg-white rounded-[2rem] border border-slate-200 relative shadow-sm">
                        <button type="button" onClick={() => removeServiceItem(item.id)} className="absolute top-6 right-6 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={20}/></button>

                        <div className="space-y-6">
                          <div>
                            <label className="block text-[9px] font-black text-slate-400 uppercase mb-2">Descrição do Serviço / Local</label>
                            <input type="text" value={item.description} onChange={(e) => updateItem(item.id, 'description', e.target.value)} placeholder="Ex: Pintura e Reparo de Alvenaria" className="w-full px-4 py-3 rounded-xl border border-slate-100 bg-slate-50 outline-none focus:border-blue-300 text-sm font-bold" />
                          </div>

                          <div className="space-y-3">
                            <div className="flex justify-between items-center">
                               <p className="text-[9px] font-black text-slate-400 uppercase">Materiais e Insumos</p>
                               <button type="button" onClick={() => addMaterial(item.id)} className="text-[9px] font-black text-emerald-600 uppercase flex items-center"><Plus size={14} className="mr-1"/> Adicionar Material</button>
                            </div>

                            <div className="space-y-3">
                               {(item.materials || []).map((mat, mIdx) => (
                                 <div key={mat.id} className="p-4 bg-slate-50/50 rounded-2xl border border-slate-100 space-y-3">
                                    <div className="flex flex-wrap md:flex-nowrap gap-3 items-end">
                                       <div className="flex-1 min-w-[150px]">
                                          <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Nome do Material</label>
                                          <input type="text" value={mat.name} onChange={e => updateMaterial(item.id, mat.id, 'name', e.target.value)} className="w-full px-3 py-2 rounded-lg border border-slate-200 text-xs font-bold" placeholder="Ex: Tinta Branca" />
                                       </div>
                                       <div className="w-20">
                                          <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Qtd</label>
                                          <input type="number" value={mat.quantity} onChange={e => updateMaterial(item.id, mat.id, 'quantity', parseFloat(e.target.value))} className="w-full px-3 py-2 rounded-lg border border-slate-200 text-xs font-bold text-center" />
                                       </div>
                                       <div className="w-32">
                                          <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">R$ Unitário</label>
                                          <div className="relative">
                                             <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-300">R$</span>
                                             <input type="number" step="0.01" value={mat.price || ''} onChange={e => updateMaterial(item.id, mat.id, 'price', parseFloat(e.target.value))} className="w-full pl-7 pr-3 py-2 rounded-lg border border-slate-200 text-xs font-bold" />
                                          </div>
                                       </div>
                                       <button type="button" onClick={() => removeMaterial(item.id, mat.id)} className="p-2 text-rose-300 hover:text-rose-500"><Trash2 size={18}/></button>
                                    </div>
                                 </div>
                               ))}
                            </div>
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 pt-6 border-t border-slate-50">
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><UserIcon size={10} className="mr-1"/> Prestador</label>
                                <input type="text" placeholder="Nome do Prestador" value={item.serviceProvider || ''} onChange={e => updateItem(item.id, 'serviceProvider', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                             </div>
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><Wrench size={10} className="mr-1"/> Mão de Obra</label>
                                <div className="relative">
                                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 font-bold">R$</span>
                                  <input type="number" step="0.01" value={item.laborCost || ''} onChange={e => updateItem(item.id, 'laborCost', e.target.value)} className="w-full pl-8 pr-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                                </div>
                             </div>
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><Clock size={10} className="mr-1"/> Tempo Estimado</label>
                                <input type="text" placeholder="Ex: 3 dias" value={item.estimatedTime || ''} onChange={e => updateItem(item.id, 'estimatedTime', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                             </div>
                             <div className="flex flex-col justify-end text-right">
                                <p className="text-[8px] font-black text-slate-300 uppercase">Subtotal</p>
                                <p className="text-lg font-black text-blue-600">R$ {calculateItemSubtotal(item).toLocaleString('pt-BR')}</p>
                             </div>
                          </div>
                        </div>
                     </div>
                   ))}
                </div>

                <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-center gap-6 shadow-2xl">
                   <div className="flex items-center space-x-4">
                      <div className="p-4 bg-white/10 rounded-2xl"><Calculator size={32} className="text-emerald-400" /></div>
                      <div>
                         <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Valor Total do Projeto</p>
                         <h4 className="text-4xl font-black tracking-tighter text-emerald-400">R$ {totalCalculated.toLocaleString('pt-BR')}</h4>
                      </div>
                   </div>
                   <div className="flex gap-4 w-full md:w-auto">
                      <button type="button" onClick={resetForm} className="flex-1 md:flex-none px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest bg-white/5 hover:bg-white/10 transition-all">Cancelar</button>
                      <button type="submit" className="flex-1 md:flex-none px-12 py-4 rounded-2xl font-black text-xs uppercase tracking-widest bg-emerald-500 hover:bg-emerald-400 shadow-lg shadow-emerald-500/20 transition-all active:scale-95">
                        {editingBudget ? 'Atualizar Orçamento' : 'Salvar Orçamento'}
                      </button>
                   </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-4">
        {filteredBudgets.length === 0 ? (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300">
            <Receipt size={64} className="mb-4 opacity-10" />
            <p className="text-xl font-black italic uppercase tracking-tighter">Nenhum orçamento em aberto</p>
          </div>
        ) : (
          filteredBudgets.map(budget => {
            const budgetTotal = (budget.items || []).reduce((acc, item) => acc + calculateItemSubtotal(item), 0);

            return (
              <div key={budget.id} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all overflow-hidden group">
                <div className="p-6 md:p-8 cursor-pointer" onClick={() => setExpandedId(expandedId === budget.id ? null : budget.id)}>
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center space-x-6">
                      <div className="p-5 bg-slate-50 text-slate-900 rounded-[1.5rem] border border-slate-100 group-hover:bg-blue-50 transition-colors">
                        <Receipt size={28} />
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-xl leading-none mb-2">{budget.title}</h4>
                        <div className="flex items-center space-x-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                          <span className="flex items-center"><Layers size={12} className="mr-1" /> {budget.items?.length || 0} Itens</span>
                          <span className="w-1.5 h-1.5 bg-slate-200 rounded-full"></span>
                          <span>{new Date(budget.createdAt).toLocaleDateString('pt-BR')}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between md:justify-end space-x-8">
                      <div className="text-right">
                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Valor do Projeto</p>
                        <p className="text-2xl font-black text-blue-600 leading-none mt-1">R$ {budgetTotal.toLocaleString('pt-BR')}</p>
                      </div>
                      <div className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase border-2 ${getStatusStyle(budget.status)}`}>
                        {budget.status}
                      </div>

                      <div className="flex items-center space-x-3">
                        <button 
                          onClick={(e) => { e.stopPropagation(); handleEdit(budget); }}
                          className="p-3 text-slate-300 hover:text-blue-500 hover:bg-blue-50 rounded-xl transition-all"
                        >
                          <Edit2 size={20} />
                        </button>
                        {expandedId === budget.id ? <ChevronUp size={24} className="text-slate-300" /> : <ChevronDown size={24} className="text-slate-300" />}
                      </div>
                    </div>
                  </div>
                </div>

                {expandedId === budget.id && (
                  <div className="px-8 pb-10 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 bg-slate-50/30">
                    <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      <div className="lg:col-span-3 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {(budget.items || []).map((item, iIdx) => (
                            <div key={item.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                              <div className="flex justify-between items-start mb-4">
                                <span className="text-[10px] font-black text-blue-500 uppercase">Item {iIdx + 1}</span>
                              </div>
                              <h6 className="font-black text-slate-800 mb-3">{item.description}</h6>
                              <div className="space-y-2 mb-4">
                                {(item.materials || []).map(m => (
                                  <div key={m.id} className="p-3 bg-slate-50/50 rounded-xl space-y-1 border border-slate-100">
                                    <div className="flex justify-between text-[10px] font-black">
                                      <span className="text-slate-800">{m.quantity}{m.unit} • {m.name}</span>
                                      <span className="text-blue-600">R$ {(m.quantity * (m.price || 0)).toLocaleString('pt-BR')}</span>
                                    </div>
                                  </div>
                                ))}
                              </div>
                              <div className="flex flex-col space-y-1 pt-2 border-t border-slate-50">
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400">Prestador</span>
                                  <span className="text-slate-800">{item.serviceProvider || '---'}</span>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400">Tempo Est.</span>
                                  <span className="text-slate-800">{item.estimatedTime || '---'}</span>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400">Mão de Obra</span>
                                  <span className="text-slate-800">R$ {(Number(item.laborCost) || 0).toLocaleString('pt-BR')}</span>
                                </div>
                              </div>
                              <div className="flex justify-between items-center text-xs font-black uppercase pt-3 border-t border-slate-100 mt-2">
                                <span className="text-blue-600">Total do Item</span>
                                <span className="text-blue-600 font-black">R$ {calculateItemSubtotal(item).toLocaleString('pt-BR')}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      <div className="lg:col-span-1 space-y-4">
                        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm text-center">
                          <p className="text-[10px] font-black text-slate-400 uppercase mb-4">Ações de Gestão</p>
                          <div className="space-y-2">
                             <button onClick={() => handleEdit(budget)} className="w-full py-4 rounded-xl bg-slate-800 text-white font-black text-xs uppercase shadow-lg active:scale-95 transition-all mb-2">Editar Orçamento</button>
                             <button onClick={() => updateStatus(budget, 'Aprovado')} className="w-full py-4 rounded-xl bg-emerald-500 text-white font-black text-xs uppercase shadow-lg active:scale-95 transition-all">Aprovar</button>
                             <button onClick={() => updateStatus(budget, 'Rejeitado')} className="w-full py-4 rounded-xl bg-white border-2 border-rose-100 text-rose-500 font-black text-xs uppercase active:scale-95 transition-all">Rejeitar</button>
                          </div>
                          <button onClick={() => onDelete(budget.id)} className="w-full mt-8 flex items-center justify-center space-x-2 text-[10px] font-black text-slate-300 hover:text-rose-500 uppercase transition-colors">
                            <Trash2 size={16} /> <span>Excluir</span>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default BudgetsView;

import React, { useState, useRef, useMemo } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  DollarSign, 
  ChevronDown,
  ChevronUp,
  X,
  Clock,
  Paperclip,
  File,
  Info,
  Layers,
  Wrench,
  Calendar,
  MessageSquare,
  Truck,
  Calculator,
  Edit2,
  User as UserIcon
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentQuoteIndexRef = useRef<number | null>(null);

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
    setEditingBudget(null);
  };

  const handleEdit = (budget: Budget) => {
    setEditingBudget(budget);
    setTitle(budget.title);
    setObjective(budget.objective);
    setItems(budget.items.map(it => ({ 
      ...it, 
      serviceProvider: it.serviceProvider || '',
      estimatedTime: it.estimatedTime || '' 
    })));

    const budgetQuotes = budget.quotes || [];
    const filledQuotes = [...budgetQuotes];
    while (filledQuotes.length < 3) {
      filledQuotes.push({ id: (Date.now() + filledQuotes.length).toString(), supplier: '', value: 0, files: [] });
    }
    setQuotes(filledQuotes);
    setStatus(budget.status);
    setIsAdding(true);
  };

  // Fix: Added missing updateStatus function to handle budget status changes
  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...(item.materials || []), { 
            id: Date.now().toString(), 
            name: '', 
            quantity: 1, 
            price: 0,
            unit: 'Un',
            supplier: '',
            observation: ''
          }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: item.materials.filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  const calculateItemSubtotal = (item: BudgetItem) => {
    const materialsTotal = (item.materials || []).reduce((acc, m) => acc + (m.quantity * (m.price || 0)), 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  const totalCalculated = useMemo(() => {
    return items.reduce((acc, item) => acc + calculateItemSubtotal(item), 0);
  }, [items]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBudget: Budget = {
      id: editingBudget?.id || Date.now().toString(),
      title: title || 'Novo Orçamento',
      objective,
      items,
      quotes: (quotes as Quote[]).filter(q => q.supplier || q.value > 0),
      status,
      createdAt: editingBudget?.createdAt || Date.now()
    };

    const allFilesForSync: {data: string, mimeType: string, fileName: string}[] = [];
    quotes.forEach(q => {
      q.files?.forEach(f => {
        if (f.data) {
          allFilesForSync.push({ data: f.data, mimeType: f.fileType!, fileName: f.fileName! });
        }
      });
    });

    onSave(finalBudget, allFilesForSync);
    resetForm();
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500';
      default: return 'bg-amber-400 text-slate-800 border-amber-400';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Buscar orçamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:border-blue-500 outline-none shadow-sm transition-all bg-white text-slate-800 font-bold"
          />
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
          style={{ backgroundColor: theme.primary, boxShadow: `0 10px 15px -3px ${theme.primary}40` }}
        >
          <Plus size={20} />
          <span>Novo Orçamento</span>
        </button>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">{editingBudget ? 'Editar Orçamento' : 'Novo Orçamento'}</h2>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">
                    {editingBudget ? `ID: ${editingBudget.id}` : 'Integração Total com Planilha e Drive'}
                  </p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Título do Projeto</label>
                    <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma do Lobby" className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all font-bold text-slate-800" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Objetivo / Justificativa</label>
                    <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Por que este orçamento é necessário?" className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all h-20 font-bold text-slate-800" />
                  </div>
                </div>

                <div className="space-y-6">
                   <div className="flex justify-between items-center">
                      <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center">
                        <Layers size={16} className="mr-2 text-blue-500" /> Detalhamento de Itens
                      </h3>
