  startDate: string;
  salary: number;
  department: string;
  sectorId: string;
  status: 'Ativo' | 'Inativo';
  scheduleType: '6x1' | '12x36' | 'Intermitente';
  shiftType?: 'Par' | 'Ímpar';
  workingHours: string;
  weeklyDayOff: string;
  monthlySundayOff: string;
  vacationStatus: 'Pendente' | 'Concedida';
