}

export interface BedConfig {
  type: 'Casal' | 'Solteiro';
  baseStatus?: 'Nova' | 'Antiga';
  baseColor?: string;
  mattressStatus?: 'Novo' | 'Antigo';
  mattressColor?: string;
  hasSkirt?: boolean;
  skirtColor?: string;
}

export interface Apartment {
  id: string;
  floor: number;
  roomNumber: number;
  defects: Defect[];
  pisoType?: 'Granito' | 'Madeira' | 'Cerâmica';
  pisoStatus?: 'Bom estado' | 'Tolerável' | 'Reparo urgente';
  banheiroType?: 'Reformado' | 'Antigo';
  banheiroStatus?: 'Tolerável' | 'Reparo urgente';
  temCofre?: boolean;
  temCortina?: boolean;
  cortinaStatus?: 'Nova' | 'Antiga';
  cortinaSize?: string;
  cortinaCoverage?: 'Dois lados' | 'Um lado';
  temEspelhoCorpo?: boolean;
  espelhoCorpoStatus?: 'Bom estado' | 'Manchado' | 'Danificado';
  acBrand?: 'Midea' | 'LG' | 'Grey';
  moveisStatus?: 'Bom estado' | 'Danificado';
  moveisDetalhes?: string[];
  beds?: BedConfig[];
  temPortaControle?: boolean;
  temCabide?: boolean;
  cabideQuantity?: number;
  temSuportePapel?: boolean;
  temSuporteShampoo?: boolean;
  suporteShampooStatus?: 'Bom estado' | 'Enferrujado';
  luminariaType?: 'Arandela' | 'Vidro' | 'Quadrado';
  luminariaColor?: 'Branco' | 'Preto';
  tvBrand?: 'LG' | 'Samsung' | 'Philco' | 'Smart Roku' | 'Toshiba';
}

export interface HotelData {
  apartments: Record<string, Apartment>;
  budgets: Budget[];
  employees: Employee[];
  sectors: Sector[];
  inventory: InventoryItem[];
  inventoryHistory: InventoryOperation[];
  suppliers: Supplier[];
  config?: {
    showSuppliersTab: boolean;
  };
}

export interface AppState {
  currentView: ViewType;
  currentHotel: HotelType;
  hotels: Record<HotelType, HotelData>;
  selectedFloor: number | null;
  selectedApartmentId: string | null;
  selectedSectorId: string | null;
  integrations: Integration[];
  currentUser: User | null;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector, InventoryItem, InventoryOperation, Supplier } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyHwnTqgnBMecAsscAIJgpfe7gHPwjWbZ42qbm3EvXvX_oq9WzbrrT99knh7L4wdvDe4g/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v26');
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...parsed, currentUser: null };
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    if (!GLOBAL_SCRIPT_URL || GLOBAL_SCRIPT_URL.includes("macros/s/")) {
       // Apenas tenta se o link parecer válido.
    } else {
       return;
    }

    setIsRefreshing(true);
    const targetHotel = hotelOverride || state.currentHotel;
    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&t=${Date.now()}`, { 
        method: 'GET', 
        mode: 'cors',
        headers: { 'Accept': 'application/json' }
      });
      const data = await response.json();
      if (data && data.status === 'success') {
        const normalizedEmployees = (data.data.employees || []).map((emp: any) => ({
          ...emp,
          sectorId: emp.sectorId ? emp.sectorId.toString() : ''
        }));

        const normalizedSectors = (data.data.sectors || []).map((sec: any) => ({
          ...sec,
          id: sec.id ? sec.id.toString() : ''
        }));

        const mergedData = {
          ...data.data,
          employees: normalizedEmployees,
          sectors: normalizedSectors.length > 0 ? normalizedSectors : state.hotels[targetHotel].sectors
        };

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...mergedData
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return mergedData;
      }
    } catch (error) { 
      // Silencia erros de fetch para não poluir o console do usuário se o link não estiver ativo
      setState(prev => ({
        ...prev,
        integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, status: 'Disconnected' } : i)
      }));
    } finally { 
      setIsRefreshing(false); 
    }
  }, [state.currentHotel, state.hotels]);

  useEffect(() => {
    const init = async () => {
      await loadDataFromSheet('VILLAGE');
      await loadDataFromSheet('GOLDEN_PARK');
      await loadDataFromSheet('THERMAL_RESORT');
    };
    init();
  }, [loadDataFromSheet]);

  useEffect(() => { 
    if (state.currentUser) {
      loadDataFromSheet(); 
    }
  }, [state.currentUser, loadDataFromSheet]);

  useEffect(() => { 
    const stateToSave = { ...state, hotels: state.hotels }; 
    localStorage.setItem('hotel_village_state_v26', JSON.stringify(stateToSave)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    if (GLOBAL_SCRIPT_URL) {
      try {
        await fetch(GLOBAL_SCRIPT_URL, { 
          method: 'POST', 
          mode: 'no-cors', 
          body: JSON.stringify({ 
            dataType, 
            hotel: state.currentHotel, 
            ...data, 
            newFiles: files 
          }) 
        });
        setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));
        if(dataType === 'EMPLOYEE' || dataType === 'SECTOR' || dataType === 'DELETE' || dataType === 'BUDGET') {
           setTimeout(() => loadDataFromSheet(), 2000);
        }
      } catch (err) { 
        // Silencioso em caso de erro de rede
      }
    }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return (
          <ApartmentDetailView 
            apartment={apt} 
            theme={theme} 
            onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} 
            onSave={(updatedApt, files) => { 
              setState(prev => ({
                ...prev, 
                hotels: {
                  ...prev.hotels, 
                  [prev.currentHotel]: {
                    ...prev.hotels[prev.currentHotel], 
                    apartments: {
                      ...prev.hotels[prev.currentHotel].apartments, 
                      [updatedApt.id]: updatedApt
                    }
                  }
                }
              })); 
              syncToSheet('APARTMENT', updatedApt, files); 
            }} 
          />
        );
      }
      if (state.selectedFloor !== null) {
        return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      }
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }

    if (state.currentView === ViewType.BUDGETS) {
      return (
        <BudgetsView 
          budgets={currentHotelData.budgets} 
          theme={theme} 
          onSave={(b, f) => { 
            setState(prev => {
              const hotel = prev.hotels[prev.currentHotel];
              const exists = hotel.budgets.find(ex => ex.id === b.id);
              const updatedBudgets = exists 
                ? hotel.budgets.map(ex => ex.id === b.id ? b : ex)
                : [b, ...hotel.budgets];
              return {
                ...prev,
                hotels: {
                  ...prev.hotels,
                  [prev.currentHotel]: { ...hotel, budgets: updatedBudgets }
                }
              };
            });
            syncToSheet('BUDGET', b, f); 
          }} 
          onDelete={(id) => { 
            setState(prev => ({
              ...prev, 
              hotels: {
                ...prev.hotels, 
                [prev.currentHotel]: {
                  ...prev.hotels[prev.currentHotel], 
                  budgets: prev.hotels[prev.currentHotel].budgets.filter(b => b.id !== id)
                }
              }
            })); 
            syncToSheet('DELETE', { targetType: 'BUDGET', id }); 
          }} 
        />
      );
    }

    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={(item) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.inventory.find(i => i.id === item.id); const newInventory = exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: newInventory } } }; }); syncToSheet('INVENTORY', item); }} onDelete={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'INVENTORY', id }); }} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const newQuantity = op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity; const updatedItem = { ...item, quantity: newQuantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); const newSuppliers = exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: newSuppliers } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={(config) => { setState(prev => ({ ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } } } })); syncToSheet('CONFIG', config); }} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); const newSuppliers = exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: newSuppliers } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        currentHotel={state.currentHotel} 
        onHotelChange={h => setState(prev => ({...prev, currentHotel: h}))} 
        onLogout={() => setState(prev => ({...prev, currentUser: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <BottomNav 
        currentView={state.currentView} 
        onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} 
        theme={theme} 
        role={state.currentUser.role} 
        sectorId={state.currentUser.sectorId}
        sectorName={state.currentUser.sectorName}
      />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  ChevronDown,
  ChevronUp,
  X,
  Clock,
  Layers,
  Wrench,
  Calculator,
  Edit2,
  User as UserIcon,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
    setEditingBudget(null);
  };

  const handleEdit = (budget: Budget) => {
    setEditingBudget(budget);
    setTitle(budget.title);
    setObjective(budget.objective);
    setItems(budget.items.map(it => ({ 
      ...it, 
      serviceProvider: it.serviceProvider || '',
      estimatedTime: it.estimatedTime || '' 
    })));

    const budgetQuotes = budget.quotes || [];
    const filledQuotes = [...budgetQuotes];
    while (filledQuotes.length < 3) {
      filledQuotes.push({ id: (Date.now() + filledQuotes.length).toString(), supplier: '', value: 0, files: [] });
    }
    setQuotes(filledQuotes);
    setStatus(budget.status);
    setIsAdding(true);
  };

  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...(item.materials || []), { 
            id: Date.now().toString(), 
            name: '', 
            quantity: 1, 
            price: 0,
            unit: 'Un'
          }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: item.materials.filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  const calculateItemSubtotal = (item: BudgetItem) => {
    const materialsTotal = (item.materials || []).reduce((acc, m) => acc + (m.quantity * (m.price || 0)), 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  const totalCalculated = useMemo(() => {
    return items.reduce((acc, item) => acc + calculateItemSubtotal(item), 0);
  }, [items]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBudget: Budget = {
      id: editingBudget?.id || Date.now().toString(),
      title: title || 'Novo Orçamento',
      objective,
      items,
      quotes: (quotes as Quote[]).filter(q => q.supplier || q.value > 0),
      status,
      createdAt: editingBudget?.createdAt || Date.now()
    };

    onSave(finalBudget);
    resetForm();
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500 shadow-emerald-200';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500 shadow-rose-200';
