          ...sec,
          id: sec.id?.toString() || '',
          standardUniform: typeof sec.standardUniform === 'string' ? JSON.parse(sec.standardUniform) : (sec.standardUniform || [])
        }));

        const normalizedBudgets = (incomingData.budgets || []).map((b: any) => ({
          ...b,
          id: b.id?.toString() || '',
          items: (typeof b.items === 'string' ? JSON.parse(b.items) : (b.items || [])).map((it: any) => ({
            ...it,
            serviceProvider: it.serviceProvider || '',
            estimatedTime: it.estimatedTime || ''
          })),
          quotes: typeof b.quotes === 'string' ? JSON.parse(b.quotes) : (b.quotes || []),
          createdAt: typeof b.createdAt === 'string' ? new Date(b.createdAt).getTime() : (b.createdAt || Date.now())
        }));

        const normalizedApts = incomingData.apartments || {};
        Object.keys(normalizedApts).forEach(key => {
          const apt = normalizedApts[key];
          if (typeof apt.defects === 'string') apt.defects = JSON.parse(apt.defects);
          if (typeof apt.beds === 'string') apt.beds = JSON.parse(apt.beds);
          if (typeof apt.moveisDetalhes === 'string') apt.moveisDetalhes = JSON.parse(apt.moveisDetalhes);
        });

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...incomingData,
              apartments: normalizedApts,
              employees: normalizedEmployees,
              sectors: normalizedSectors,
              budgets: normalizedBudgets
            }
          },
          integrations: prev.integrations.map(i => 
            i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i
          )
        }));

        console.log(`Sucesso: Dados da unidade ${targetHotel} refletidos.`);
        return incomingData;
      } else {
        throw new Error(result?.message || "Erro na resposta da planilha.");
      }
    } catch (error) { 
      console.error("Erro ao puxar dados:", error);
      setState(prev => ({
        ...prev,
        integrations: prev.integrations.map(i => 
          i.id === 'global-sync' ? { ...i, status: 'Disconnected' } : i
        )
      }));
      return null;
    } finally { 
      setIsRefreshing(false); 
    }
  }, [state.currentHotel, state.integrations[0].url]); // Reduzidas as dependências para evitar loops

