                          />
                          <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                            <Maximize2 size={20} className="text-white" />
                          </div>
                        </div>
                      )}
                      <div className="flex-1">
                        <p className="text-[11px] font-black text-slate-800 uppercase leading-tight">{defect.description}</p>
                        {defect.driveLink && defect.driveLink !== 'pendente' && (
                          <div className="mt-2 flex items-center space-x-2">
                             <span className="text-[7px] font-black text-emerald-500 bg-emerald-50 px-1.5 py-0.5 rounded uppercase flex items-center"><ExternalLink size={8} className="mr-1"/> No Drive</span>
                          </div>
                        )}
                      </div>
                   </div>
                   <button onClick={() => setData(prev => ({ ...prev, defects: prev.defects.filter(d => d.id !== defect.id) }))} className="text-slate-300 hover:text-rose-500 transition-colors">
                     <Trash2 size={20}/>
                   </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      <div className="fixed bottom-8 left-0 right-0 px-6 z-[120]">
        <button 
          onClick={handleSaveAndExit}
          disabled={isSaving}
          className="w-full bg-slate-900 text-white py-5 rounded-[2.2rem] font-black text-sm shadow-2xl flex items-center justify-center space-x-3 active:scale-95 transition-all hover:bg-slate-800"
        >
          {isSaving ? (
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
          ) : (
            <Save size={20} className="text-emerald-400" />
          )}
          <span>{isSaving ? 'PROCESSANDO...' : 'SALVAR E SAIR'}</span>
        </button>
      </div>
    </div>
  );
};

export default ApartmentDetailView;

import React, { useState, useRef, useMemo } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem, MaterialQuote } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  ChevronDown,
  ChevronUp,
  X,
  Clock,
  Layers,
  Wrench,
  Calculator,
  Edit2,
  User as UserIcon,
  CheckCircle2,
  AlertCircle,
  Package,
  Truck,
  MessageSquare,
  TrendingDown,
  TrendingUp,
  DollarSign
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
    setEditingBudget(null);
  };

  const handleEdit = (budget: Budget) => {
    setEditingBudget(budget);
    setTitle(budget.title);
    setObjective(budget.objective);
    setItems(budget.items.map(it => ({ 
      ...it, 
      serviceProvider: it.serviceProvider || '',
      estimatedTime: it.estimatedTime || '',
      materials: (it.materials || []).map(m => ({
        ...m,
        quotes: (m.quotes && m.quotes.length === 3) 
          ? m.quotes 
          : [
              { supplier: '', value: 0 },
              { supplier: '', value: 0 },
              { supplier: '', value: 0 }
            ]
      }))
    })));

    const budgetQuotes = budget.quotes || [];
    const filledQuotes = [...budgetQuotes];
    while (filledQuotes.length < 3) {
      filledQuotes.push({ id: (Date.now() + filledQuotes.length).toString(), supplier: '', value: 0, files: [] });
    }
    setQuotes(filledQuotes);
    setStatus(budget.status);
    setIsAdding(true);
  };

  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...(item.materials || []), { 
            id: Date.now().toString(), 
            name: '', 
            quantity: 1, 
            unit: 'Un',
            observation: '',
            quotes: [
              { supplier: '', value: 0 },
              { supplier: '', value: 0 },
              { supplier: '', value: 0 }
            ]
          }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const updateMaterialQuote = (itemId: string, matId: string, quoteIdx: number, field: keyof MaterialQuote, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: item.materials.map(m => {
            if (m.id === matId) {
              const newQuotes = [...m.quotes];
              newQuotes[quoteIdx] = { ...newQuotes[quoteIdx], [field]: value };
              return { ...m, quotes: newQuotes };
            }
            return m;
          })
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: item.materials.filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  // Calcula o melhor preço (menor valor maior que zero) entre as 3 cotações de um material
  const getBestMaterialPrice = (m: MaterialItem) => {
    const validPrices = m.quotes.map(q => Number(q.value) || 0).filter(v => v > 0);
    if (validPrices.length === 0) return 0;
    return Math.min(...validPrices);
  };

  const calculateItemSubtotal = (item: BudgetItem) => {
    const materialsTotal = (item.materials || []).reduce((acc, m) => {
      const bestPrice = getBestMaterialPrice(m);
      return acc + (m.quantity * bestPrice);
    }, 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  const totalCalculated = useMemo(() => {
    return items.reduce((acc, item) => acc + calculateItemSubtotal(item), 0);
  }, [items]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBudget: Budget = {
      id: editingBudget?.id || Date.now().toString(),
      title: title || 'Novo Orçamento',
      objective,
      items,
      quotes: (quotes as Quote[]).filter(q => q.supplier || q.value > 0),
      status,
      createdAt: editingBudget?.createdAt || Date.now()
    };

    onSave(finalBudget);
    resetForm();
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500 shadow-emerald-200';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500 shadow-rose-200';
      default: return 'bg-amber-400 text-slate-800 border-amber-400 shadow-amber-200';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Buscar orçamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:border-blue-500 outline-none shadow-sm transition-all bg-white text-slate-800 font-bold"
          />
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
          style={{ backgroundColor: theme.primary, boxShadow: `0 10px 15px -3px ${theme.primary}40` }}
        >
          <Plus size={20} />
          <span>Novo Orçamento</span>
        </button>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-6xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">{editingBudget ? 'Editar Orçamento' : 'Novo Orçamento'}</h2>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">
                    {editingBudget ? `ID: ${editingBudget.id}` : 'Detalhamento de Execução com Tripla Cotação'}
                  </p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Título do Projeto</label>
                    <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma do Lobby" className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all font-bold text-slate-800" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Objetivo / Justificativa</label>
                    <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Justificativa do investimento..." className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all h-20 font-bold text-slate-800" />
                  </div>
                </div>

                <div className="space-y-6">
                   <div className="flex justify-between items-center px-2">
                      <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center">
                        <Layers size={16} className="mr-2 text-blue-500" /> Detalhamento de Serviços
                      </h3>
                      <button type="button" onClick={addServiceItem} className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl font-black text-[10px] uppercase border border-blue-100 hover:bg-blue-100 transition-all">+ Novo Serviço</button>
                   </div>

                   {items.map((item) => (
                     <div key={item.id} className="p-6 bg-white rounded-[2rem] border border-slate-200 relative shadow-sm">
                        <button type="button" onClick={() => removeServiceItem(item.id)} className="absolute top-6 right-6 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={20}/></button>

                        <div className="space-y-6">
                          <div>
                            <label className="block text-[9px] font-black text-slate-400 uppercase mb-2">Descrição do Serviço / Local</label>
                            <input type="text" value={item.description} onChange={(e) => updateItem(item.id, 'description', e.target.value)} placeholder="Ex: Pintura da Sala de Estar" className="w-full px-4 py-3 rounded-xl border border-slate-100 bg-slate-50 outline-none focus:border-blue-300 text-sm font-bold" />
                          </div>

                          <div className="space-y-4">
                            <div className="flex justify-between items-center">
                               <p className="text-[9px] font-black text-slate-400 uppercase flex items-center"><Package size={14} className="mr-1"/> Materiais & Tripla Cotação</p>
                               <button type="button" onClick={() => addMaterial(item.id)} className="text-[9px] font-black text-emerald-600 uppercase flex items-center hover:scale-105 transition-all"><Plus size={14} className="mr-1"/> Adicionar Material</button>
                            </div>

                            <div className="space-y-6">
                               {(item.materials || []).map((mat) => {
                                 const bestPrice = getBestMaterialPrice(mat);
                                 return (
                                   <div key={mat.id} className="p-6 bg-slate-50/50 rounded-[2.5rem] border border-slate-100 animate-in fade-in slide-in-from-left-2 space-y-4">
                                      <div className="flex flex-wrap gap-4 items-end">
                                        <div className="flex-1 min-w-[200px]">
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Material / Insumo</label>
                                           <input type="text" value={mat.name} onChange={e => updateMaterial(item.id, mat.id, 'name', e.target.value)} placeholder="Nome do material" className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold" />
                                        </div>
                                        <div className="w-20">
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Unidade</label>
                                           <input type="text" value={mat.unit || ''} onChange={e => updateMaterial(item.id, mat.id, 'unit', e.target.value)} placeholder="Ex: Un, Kg" className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold text-center" />
                                        </div>
                                        <div className="w-20">
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Qtd</label>
                                           <input type="number" value={mat.quantity} onChange={e => updateMaterial(item.id, mat.id, 'quantity', parseFloat(e.target.value))} className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold text-center" />
                                        </div>
                                        <div className="w-40 bg-white p-2.5 rounded-xl border border-blue-100 shadow-sm">
                                           <p className="text-[8px] font-black text-blue-400 uppercase leading-none mb-1">Melhor Valor Unit.</p>
                                           <p className="text-sm font-black text-blue-600">R$ {bestPrice.toLocaleString('pt-BR')}</p>
                                        </div>
                                        <button type="button" onClick={() => removeMaterial(item.id, mat.id)} className="p-2.5 text-rose-300 hover:text-rose-500 transition-colors"><Trash2 size={20}/></button>
                                      </div>

                                      {/* Tripla Cotação Grid */}
                                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                        {mat.quotes.map((quote, qIdx) => (
                                          <div key={qIdx} className={`p-4 rounded-2xl border-2 transition-all ${Number(quote.value) > 0 && Number(quote.value) === bestPrice ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-white'}`}>
                                            <div className="flex items-center justify-between mb-2">
                                              <span className="text-[8px] font-black text-slate-400 uppercase">Cotação {qIdx + 1}</span>
                                              {Number(quote.value) > 0 && Number(quote.value) === bestPrice && <TrendingDown size={12} className="text-emerald-500" />}
                                            </div>
                                            <div className="space-y-2">
                                              <input 
                                                type="text" 
                                                value={quote.supplier} 
                                                onChange={e => updateMaterialQuote(item.id, mat.id, qIdx, 'supplier', e.target.value)} 
                                                placeholder="Fornecedor" 
                                                className="w-full px-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold outline-none" 
                                              />
                                              <div className="relative">
                                                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] text-slate-300 font-black">R$</span>
                                                <input 
                                                  type="number" 
                                                  step="0.01"
                                                  value={quote.value || ''} 
                                                  onChange={e => updateMaterialQuote(item.id, mat.id, qIdx, 'value', parseFloat(e.target.value))} 
                                                  placeholder="Valor" 
                                                  className="w-full pl-6 pr-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold outline-none" 
                                                />
                                              </div>
                                            </div>
                                          </div>
                                        ))}
                                      </div>

                                      <div className="relative">
                                         <label className="block text-[8px] font-black text-slate-400 uppercase mb-1 flex items-center"><MessageSquare size={10} className="mr-1"/> Observação técnica</label>
                                         <input type="text" value={mat.observation || ''} onChange={e => updateMaterial(item.id, mat.id, 'observation', e.target.value)} placeholder="Ex: Marca específica, cor, tamanho..." className="w-full px-4 py-2 rounded-xl border border-slate-200 text-[10px] font-bold bg-white" />
                                      </div>
                                   </div>
                                 );
                               })}
                            </div>
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 pt-6 border-t border-slate-50 items-end">
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><UserIcon size={10} className="mr-1"/> Prestador de Serviço</label>
                                <input type="text" placeholder="Nome do Prestador" value={item.serviceProvider || ''} onChange={e => updateItem(item.id, 'serviceProvider', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                             </div>
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><Wrench size={10} className="mr-1"/> Valor Mão de Obra</label>
                                <div className="relative">
                                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 font-bold text-xs">R$</span>
                                  <input type="number" step="0.01" value={item.laborCost || ''} onChange={e => updateItem(item.id, 'laborCost', e.target.value)} className="w-full pl-8 pr-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                                </div>
                             </div>
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><Clock size={10} className="mr-1 text-blue-500"/> Tempo Estimado</label>
                                <input type="text" placeholder="Ex: 5 dias" value={item.estimatedTime || ''} onChange={e => updateItem(item.id, 'estimatedTime', e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 bg-white font-bold text-xs focus:border-blue-400 outline-none shadow-inner" />
                             </div>
                             <div className="flex flex-col justify-end text-right">
                                <p className="text-[8px] font-black text-slate-300 uppercase">Subtotal (Melhores Preços)</p>
                                <p className="text-xl font-black text-blue-600">R$ {calculateItemSubtotal(item).toLocaleString('pt-BR')}</p>
                             </div>
                          </div>
                        </div>
                     </div>
                   ))}
                </div>

                <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-center gap-6 shadow-2xl">
                   <div className="flex items-center space-x-4">
                      <div className="p-4 bg-white/10 rounded-2xl"><Calculator size={32} className="text-emerald-400" /></div>
                      <div>
                         <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Investimento Total Estimado (Melhores Cotações)</p>
                         <h4 className="text-4xl font-black tracking-tighter text-emerald-400">R$ {totalCalculated.toLocaleString('pt-BR')}</h4>
                      </div>
                   </div>
                   <div className="flex gap-4 w-full md:w-auto">
                      <button type="button" onClick={resetForm} className="flex-1 md:flex-none px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest bg-white/5 hover:bg-white/10 transition-all">Descartar</button>
                      <button type="submit" className="flex-1 md:flex-none px-12 py-4 rounded-2xl font-black text-xs uppercase tracking-widest bg-emerald-500 hover:bg-emerald-400 shadow-lg shadow-emerald-500/20 transition-all active:scale-95">
                        {editingBudget ? 'Atualizar Orçamento' : 'Concluir Lançamento'}
                      </button>
                   </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-4">
        {filteredBudgets.length === 0 ? (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300">
            <Receipt size={64} className="mb-4 opacity-10" />
            <p className="text-xl font-black italic uppercase tracking-tighter">Nenhum orçamento encontrado</p>
          </div>
        ) : (
          filteredBudgets.map(budget => {
            const budgetTotal = (budget.items || []).reduce((acc, item) => acc + calculateItemSubtotal(item), 0);

            return (
              <div key={budget.id} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all overflow-hidden group">
                <div className="p-6 md:p-8 cursor-pointer" onClick={() => setExpandedId(expandedId === budget.id ? null : budget.id)}>
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center space-x-6">
                      <div className="p-5 bg-slate-50 text-slate-900 rounded-[1.5rem] border border-slate-100 group-hover:bg-blue-50 transition-colors">
                        <Receipt size={28} />
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-xl leading-none mb-2">{budget.title}</h4>
                        <div className="flex items-center space-x-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                          <span className="flex items-center"><Layers size={12} className="mr-1" /> {budget.items?.length || 0} Serviços</span>
                          <span className="w-1.5 h-1.5 bg-slate-200 rounded-full"></span>
                          <span>{new Date(budget.createdAt).toLocaleDateString('pt-BR')}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between md:justify-end space-x-8">
                      <div className="text-right">
                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Melhor Valor Total</p>
                        <p className="text-2xl font-black text-blue-600 leading-none mt-1">R$ {budgetTotal.toLocaleString('pt-BR')}</p>
                      </div>
                      <div className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase border-2 shadow-sm ${getStatusStyle(budget.status)}`}>
                        {budget.status}
                      </div>

                      <div className="flex items-center space-x-3">
                        <button 
                          onClick={(e) => { e.stopPropagation(); handleEdit(budget); }}
                          className="p-3 text-slate-300 hover:text-blue-500 hover:bg-blue-50 rounded-xl transition-all"
                        >
                          <Edit2 size={20} />
                        </button>
                        {expandedId === budget.id ? <ChevronUp size={24} className="text-slate-300" /> : <ChevronDown size={24} className="text-slate-300" />}
                      </div>
                    </div>
                  </div>
                </div>

                {expandedId === budget.id && (
                  <div className="px-8 pb-10 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 bg-slate-50/30">
                    <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      <div className="lg:col-span-3 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {(budget.items || []).map((item, iIdx) => (
                            <div key={item.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:border-blue-100 transition-colors">
                              <div className="flex justify-between items-start mb-4">
                                <span className="text-[10px] font-black text-blue-500 uppercase">Serviço {iIdx + 1}</span>
                              </div>
                              <h6 className="font-black text-slate-800 mb-3">{item.description}</h6>

                              <div className="space-y-3 mb-4">
                                {(item.materials || []).map(m => {
                                  const bestPrice = getBestMaterialPrice(m);
                                  return (
                                    <div key={m.id} className="p-4 bg-slate-50/50 rounded-2xl border border-slate-100">
                                      <div className="flex justify-between items-center mb-2">
                                        <span className="text-[10px] font-black text-slate-800">
                                          {m.quantity} {m.unit || 'Un'} • {m.name}
                                        </span>
                                        <div className="text-right">
                                          <p className="text-[8px] font-black text-slate-400 uppercase">Melhor Total</p>
                                          <span className="text-blue-600 font-black text-xs">
                                            R$ {(m.quantity * bestPrice).toLocaleString('pt-BR')}
                                          </span>
                                        </div>
                                      </div>

                                      <div className="grid grid-cols-3 gap-2 mt-2">
                                        {m.quotes.map((q, qIdx) => (
                                          <div key={qIdx} className={`p-2 rounded-xl border text-[8px] ${Number(q.value) > 0 && Number(q.value) === bestPrice ? 'bg-emerald-100 border-emerald-200 text-emerald-700' : 'bg-white border-slate-100 text-slate-400'}`}>
                                            <p className="font-black truncate">{q.supplier || `Fornec. ${qIdx + 1}`}</p>
                                            <p className="font-bold">R$ {(Number(q.value) || 0).toLocaleString('pt-BR')}</p>
                                          </div>
                                        ))}
                                      </div>

                                      {m.observation && (
                                        <div className="mt-2 flex items-center text-[8px] font-medium text-slate-400 italic">
                                          <MessageSquare size={10} className="mr-1 opacity-50"/> Obs: {m.observation}
                                        </div>
                                      )}
                                    </div>
                                  );
                                })}
                              </div>

                              <div className="flex flex-col space-y-1 pt-2 border-t border-slate-50">
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400 flex items-center"><UserIcon size={10} className="mr-1"/> Prestador</span>
                                  <span className="text-slate-800">{item.serviceProvider || 'Não informado'}</span>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400 flex items-center"><Clock size={10} className="mr-1"/> Tempo Estimado</span>
                                  <span className="text-blue-600 font-black">{item.estimatedTime || 'Não informado'}</span>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400 flex items-center"><Wrench size={10} className="mr-1"/> Mão de Obra</span>
                                  <span className="text-slate-800">R$ {(Number(item.laborCost) || 0).toLocaleString('pt-BR')}</span>
                                </div>
                              </div>
                              <div className="flex justify-between items-center text-xs font-black uppercase pt-3 border-t border-slate-100 mt-2">
                                <span className="text-blue-600">Subtotal Serviço</span>
                                <span className="text-blue-600 font-black">R$ {calculateItemSubtotal(item).toLocaleString('pt-BR')}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                        {budget.objective && (
                          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                            <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><AlertCircle size={14} className="mr-1 text-blue-500" /> Justificativa do Projeto</h5>
                            <p className="text-sm text-slate-600 font-medium">{budget.objective}</p>
                          </div>
                        )}
                      </div>

                      <div className="lg:col-span-1 space-y-4">
                        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm text-center">
                          <p className="text-[10px] font-black text-slate-400 uppercase mb-4 tracking-widest">Controle Gestão</p>
                          <div className="space-y-2">
                             <button onClick={() => handleEdit(budget)} className="w-full py-4 rounded-xl bg-slate-800 text-white font-black text-xs uppercase shadow-lg active:scale-95 transition-all mb-2">Editar Tudo</button>
                             <button onClick={() => updateStatus(budget, 'Aprovado')} className="w-full py-4 rounded-xl bg-emerald-500 text-white font-black text-xs uppercase shadow-lg active:scale-95 transition-all flex items-center justify-center space-x-2">
                               <CheckCircle2 size={16}/> <span>Aprovar</span>
                             </button>
                             <button onClick={() => updateStatus(budget, 'Rejeitado')} className="w-full py-4 rounded-xl bg-white border-2 border-rose-100 text-rose-500 font-black text-xs uppercase active:scale-95 transition-all flex items-center justify-center space-x-2">
                               <X size={16}/> <span>Rejeitar</span>
                             </button>
                          </div>
                          <button onClick={() => onDelete(budget.id)} className="w-full mt-8 flex items-center justify-center space-x-2 text-[10px] font-black text-slate-300 hover:text-rose-500 uppercase transition-colors">
                            <Trash2 size={16} /> <span>Excluir Orçamento</span>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default BudgetsView;

import React, { useState, useRef, useMemo } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem, MaterialQuote } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  ChevronDown,
  ChevronUp,
  X,
  Clock,
  Layers,
  Wrench,
  Calculator,
  Edit2,
  User as UserIcon,
  CheckCircle2,
  AlertCircle,
  Package,
  Truck,
  MessageSquare,
  TrendingDown,
  TrendingUp,
  DollarSign
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }
  ]);
  const [quotes, setQuotes] = useState<Partial<Quote>[]>([
    { id: '1', supplier: '', value: 0, files: [] },
    { id: '2', supplier: '', value: 0, files: [] },
    { id: '3', supplier: '', value: 0, files: [] }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
    setQuotes([
      { id: '1', supplier: '', value: 0, files: [] },
      { id: '2', supplier: '', value: 0, files: [] },
      { id: '3', supplier: '', value: 0, files: [] }
    ]);
    setStatus('Pendente');
    setIsAdding(false);
    setEditingBudget(null);
  };

  const handleEdit = (budget: Budget) => {
    setEditingBudget(budget);
    setTitle(budget.title);
    setObjective(budget.objective);
    setItems((budget.items || []).map(it => ({ 
      ...it, 
      serviceProvider: it.serviceProvider || '',
      estimatedTime: it.estimatedTime || '',
      materials: (it.materials || []).map(m => ({
        ...m,
        quotes: (m.quotes && m.quotes.length === 3) 
          ? m.quotes 
          : [
              { supplier: '', value: 0 },
              { supplier: '', value: 0 },
              { supplier: '', value: 0 }
            ]
      }))
    })));

    const budgetQuotes = budget.quotes || [];
    const filledQuotes = [...budgetQuotes];
    while (filledQuotes.length < 3) {
      filledQuotes.push({ id: (Date.now() + filledQuotes.length).toString(), supplier: '', value: 0, files: [] });
    }
    setQuotes(filledQuotes);
    setStatus(budget.status);
    setIsAdding(true);
  };

  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...(item.materials || []), { 
            id: Date.now().toString(), 
            name: '', 
            quantity: 1, 
            unit: 'Un',
            observation: '',
            quotes: [
              { supplier: '', value: 0 },
              { supplier: '', value: 0 },
              { supplier: '', value: 0 }
            ]
          }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: (item.materials || []).map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const updateMaterialQuote = (itemId: string, matId: string, quoteIdx: number, field: keyof MaterialQuote, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: (item.materials || []).map(m => {
            if (m.id === matId) {
              const currentQuotes = m.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }];
              const newQuotes = [...currentQuotes];
              newQuotes[quoteIdx] = { ...newQuotes[quoteIdx], [field]: value };
              return { ...m, quotes: newQuotes };
            }
            return m;
          })
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: (item.materials || []).filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  // Calcula o melhor preço (menor valor maior que zero) entre as 3 cotações de um material
  const getBestMaterialPrice = (m: MaterialItem) => {
    const validPrices = (m.quotes || []).map(q => Number(q.value) || 0).filter(v => v > 0);
    if (validPrices.length === 0) return 0;
    return Math.min(...validPrices);
  };

  const calculateItemSubtotal = (item: BudgetItem) => {
    const materialsTotal = (item.materials || []).reduce((acc, m) => {
      const bestPrice = getBestMaterialPrice(m);
      return acc + (m.quantity * bestPrice);
    }, 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  const totalCalculated = useMemo(() => {
    return items.reduce((acc, item) => acc + calculateItemSubtotal(item), 0);
  }, [items]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const finalBudget: Budget = {
      id: editingBudget?.id || Date.now().toString(),
      title: title || 'Novo Orçamento',
      objective,
      items,
      quotes: (quotes as Quote[]).filter(q => q.supplier || q.value > 0),
      status,
      createdAt: editingBudget?.createdAt || Date.now()
    };

    onSave(finalBudget);
    resetForm();
  };

  const filteredBudgets = budgets.filter(b => 
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusStyle = (s: string) => {
    switch(s) {
      case 'Aprovado': return 'bg-emerald-500 text-white border-emerald-500 shadow-emerald-200';
      case 'Rejeitado': return 'bg-rose-500 text-white border-rose-500 shadow-rose-200';
      default: return 'bg-amber-400 text-slate-800 border-amber-400 shadow-amber-200';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Buscar orçamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:border-blue-500 outline-none shadow-sm transition-all bg-white text-slate-800 font-bold"
          />
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="w-full md:w-auto text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
          style={{ backgroundColor: theme.primary, boxShadow: `0 10px 15px -3px ${theme.primary}40` }}
        >
          <Plus size={20} />
          <span>Novo Orçamento</span>
        </button>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-6xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">{editingBudget ? 'Editar Orçamento' : 'Novo Orçamento'}</h2>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">
                    {editingBudget ? `ID: ${editingBudget.id}` : 'Detalhamento de Execução com Tripla Cotação'}
                  </p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Título do Projeto</label>
                    <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma do Lobby" className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all font-bold text-slate-800" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Objetivo / Justificativa</label>
                    <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Justificativa do investimento..." className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all h-20 font-bold text-slate-800" />
                  </div>
                </div>

                <div className="space-y-6">
                   <div className="flex justify-between items-center px-2">
                      <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center">
                        <Layers size={16} className="mr-2 text-blue-500" /> Detalhamento de Serviços
                      </h3>
                      <button type="button" onClick={addServiceItem} className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl font-black text-[10px] uppercase border border-blue-100 hover:bg-blue-100 transition-all">+ Novo Serviço</button>
                   </div>

                   {items.map((item) => (
                     <div key={item.id} className="p-6 bg-white rounded-[2rem] border border-slate-200 relative shadow-sm">
                        <button type="button" onClick={() => removeServiceItem(item.id)} className="absolute top-6 right-6 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={20}/></button>

                        <div className="space-y-6">
                          <div>
                            <label className="block text-[9px] font-black text-slate-400 uppercase mb-2">Descrição do Serviço / Local</label>
                            <input type="text" value={item.description} onChange={(e) => updateItem(item.id, 'description', e.target.value)} placeholder="Ex: Pintura da Sala de Estar" className="w-full px-4 py-3 rounded-xl border border-slate-100 bg-slate-50 outline-none focus:border-blue-300 text-sm font-bold" />
                          </div>

                          <div className="space-y-4">
                            <div className="flex justify-between items-center">
                               <p className="text-[9px] font-black text-slate-400 uppercase flex items-center"><Package size={14} className="mr-1"/> Materiais & Tripla Cotação</p>
                               <button type="button" onClick={() => addMaterial(item.id)} className="text-[9px] font-black text-emerald-600 uppercase flex items-center hover:scale-105 transition-all"><Plus size={14} className="mr-1"/> Adicionar Material</button>
                            </div>

                            <div className="space-y-6">
                               {(item.materials || []).map((mat) => {
                                 const bestPrice = getBestMaterialPrice(mat);
                                 const currentQuotes = mat.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }];
                                 return (
                                   <div key={mat.id} className="p-6 bg-slate-50/50 rounded-[2.5rem] border border-slate-100 animate-in fade-in slide-in-from-left-2 space-y-4">
                                      <div className="flex flex-wrap gap-4 items-end">
                                        <div className="flex-1 min-w-[200px]">
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Material / Insumo</label>
                                           <input type="text" value={mat.name} onChange={e => updateMaterial(item.id, mat.id, 'name', e.target.value)} placeholder="Nome do material" className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold" />
                                        </div>
                                        <div className="w-20">
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Unidade</label>
                                           <input type="text" value={mat.unit || ''} onChange={e => updateMaterial(item.id, mat.id, 'unit', e.target.value)} placeholder="Ex: Un, Kg" className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold text-center" />
                                        </div>
                                        <div className="w-20">
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Qtd</label>
                                           <input type="number" value={mat.quantity} onChange={e => updateMaterial(item.id, mat.id, 'quantity', parseFloat(e.target.value))} className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold text-center" />
                                        </div>
                                        <div className="w-40 bg-white p-2.5 rounded-xl border border-blue-100 shadow-sm">
                                           <p className="text-[8px] font-black text-blue-400 uppercase leading-none mb-1">Melhor Valor Unit.</p>
                                           <p className="text-sm font-black text-blue-600">R$ {bestPrice.toLocaleString('pt-BR')}</p>
                                        </div>
                                        <button type="button" onClick={() => removeMaterial(item.id, mat.id)} className="p-2.5 text-rose-300 hover:text-rose-500 transition-colors"><Trash2 size={20}/></button>
                                      </div>

                                      {/* Tripla Cotação Grid */}
                                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                        {currentQuotes.map((quote, qIdx) => (
                                          <div key={qIdx} className={`p-4 rounded-2xl border-2 transition-all ${Number(quote.value) > 0 && Number(quote.value) === bestPrice ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-white'}`}>
                                            <div className="flex items-center justify-between mb-2">
                                              <span className="text-[8px] font-black text-slate-400 uppercase">Cotação {qIdx + 1}</span>
                                              {Number(quote.value) > 0 && Number(quote.value) === bestPrice && <TrendingDown size={12} className="text-emerald-500" />}
                                            </div>
                                            <div className="space-y-2">
                                              <input 
                                                type="text" 
                                                value={quote.supplier} 
                                                onChange={e => updateMaterialQuote(item.id, mat.id, qIdx, 'supplier', e.target.value)} 
                                                placeholder="Fornecedor" 
                                                className="w-full px-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold outline-none" 
                                              />
                                              <div className="relative">
                                                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] text-slate-300 font-black">R$</span>
                                                <input 
                                                  type="number" 
                                                  step="0.01"
                                                  value={quote.value || ''} 
                                                  onChange={e => updateMaterialQuote(item.id, mat.id, qIdx, 'value', parseFloat(e.target.value))} 
                                                  placeholder="Valor" 
                                                  className="w-full pl-6 pr-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold outline-none" 
                                                />
                                              </div>
                                            </div>
                                          </div>
                                        ))}
                                      </div>

                                      <div className="relative">
                                         <label className="block text-[8px] font-black text-slate-400 uppercase mb-1 flex items-center"><MessageSquare size={10} className="mr-1"/> Observação técnica</label>
                                         <input type="text" value={mat.observation || ''} onChange={e => updateMaterial(item.id, mat.id, 'observation', e.target.value)} placeholder="Ex: Marca específica, cor, tamanho..." className="w-full px-4 py-2 rounded-xl border border-slate-200 text-[10px] font-bold bg-white" />
                                      </div>
                                   </div>
                                 );
                               })}
                            </div>
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 pt-6 border-t border-slate-50 items-end">
                             <div className="md:col-span-1">
