                                      {m.observation && (
                                        <div className="mt-2 flex items-center text-[8px] font-medium text-slate-400 italic">
                                          <MessageSquare size={10} className="mr-1 opacity-50"/> Obs: {m.observation}
                                        </div>
                                      )}
                                    </div>
                                  );
                                })}
                              </div>

                              <div className="flex flex-col space-y-1 pt-2 border-t border-slate-50">
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400 flex items-center"><UserIcon size={10} className="mr-1"/> Prestador</span>
                                  <span className="text-slate-800">{item.serviceProvider || 'Não informado'}</span>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400 flex items-center"><Clock size={10} className="mr-1"/> Tempo Estimado</span>
                                  <span className="text-blue-600 font-black">{item.estimatedTime || 'Não informado'}</span>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400 flex items-center"><Wrench size={10} className="mr-1"/> Mão de Obra</span>
                                  <span className="text-slate-800">R$ {(Number(item.laborCost) || 0).toLocaleString('pt-BR')}</span>
                                </div>
                              </div>
                              <div className="flex justify-between items-center text-xs font-black uppercase pt-3 border-t border-slate-100 mt-2">
                                <span className="text-blue-600">Subtotal Serviço</span>
                                <span className="text-blue-600 font-black">R$ {calculateItemSubtotal(item).toLocaleString('pt-BR')}</span>
                              </div>
                            </div>
                          ))}
                        </div>
                        {budget.objective && (
                          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                            <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center"><AlertCircle size={14} className="mr-1 text-blue-500" /> Justificativa do Projeto</h5>
                            <p className="text-sm text-slate-600 font-medium">{budget.objective}</p>
                          </div>
                        )}
                      </div>

                      <div className="lg:col-span-1 space-y-4">
                        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm text-center">
                          <p className="text-[10px] font-black text-slate-400 uppercase mb-4 tracking-widest">Controle Gestão</p>
                          <div className="space-y-2">
                             <button onClick={() => handleEdit(budget)} className="w-full py-4 rounded-xl bg-slate-800 text-white font-black text-xs uppercase shadow-lg active:scale-95 transition-all mb-2">Editar Tudo</button>
                             <button onClick={() => updateStatus(budget, 'Aprovado')} className="w-full py-4 rounded-xl bg-emerald-500 text-white font-black text-xs uppercase shadow-lg active:scale-95 transition-all flex items-center justify-center space-x-2">
                               <CheckCircle2 size={16}/> <span>Aprovar</span>
                             </button>
                             <button onClick={() => updateStatus(budget, 'Rejeitado')} className="w-full py-4 rounded-xl bg-white border-2 border-rose-100 text-rose-500 font-black text-xs uppercase active:scale-95 transition-all flex items-center justify-center space-x-2">
                               <X size={16}/> <span>Rejeitar</span>
                             </button>
                          </div>
                          <button onClick={() => onDelete(budget.id)} className="w-full mt-8 flex items-center justify-center space-x-2 text-[10px] font-black text-slate-300 hover:text-rose-500 uppercase transition-colors">
                            <Trash2 size={16} /> <span>Excluir Orçamento</span>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default BudgetsView;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector, InventoryItem, InventoryOperation, Supplier } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyHwnTqgnBMecAsscAIJgpfe7gHPwjWbZ42qbm3EvXvX_oq9WzbrrT99knh7L4wdvDe4g/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const initialSyncRef = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v33');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return { ...parsed, currentUser: null };
      } catch (e) {
        console.error("Erro ao carregar estado salvo:", e);
      }
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    const targetHotel = hotelOverride || state.currentHotel;
    setIsRefreshing(true);
    try {
      const scriptUrl = GLOBAL_SCRIPT_URL;
      const fetchUrl = `${scriptUrl}?hotel=${targetHotel}&nocache=${Date.now()}`;

      const response = await fetch(fetchUrl, {
        method: 'GET',
        mode: 'cors',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const result = await response.json();

      if (result && result.status === 'success') {
        const incomingData = result.data;

        // Normalização Robusta
        const normalizedEmployees = (incomingData.employees || []).map((emp: any) => ({
          ...emp,
          id: emp.id?.toString() || '',
          sectorId: emp.sectorId?.toString() || '',
          uniforms: typeof emp.uniforms === 'string' ? JSON.parse(emp.uniforms) : (emp.uniforms || [])
        }));

        const normalizedSectors = (incomingData.sectors || []).map((sec: any) => ({
          ...sec,
          id: sec.id?.toString() || '',
          standardUniform: typeof sec.standardUniform === 'string' ? JSON.parse(sec.standardUniform) : (sec.standardUniform || [])
        }));

        const normalizedBudgets = (incomingData.budgets || []).map((b: any) => ({
          ...b,
          id: b.id?.toString() || '',
          items: (typeof b.items === 'string' ? JSON.parse(b.items) : (b.items || [])).map((it: any) => ({
            ...it,
            serviceProvider: it.serviceProvider || '',
            estimatedTime: it.estimatedTime || '',
            materials: (it.materials || []).map((m: any) => ({
              ...m,
              quotes: m.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }]
            }))
          })),
          quotes: typeof b.quotes === 'string' ? JSON.parse(b.quotes) : (b.quotes || []),
          createdAt: typeof b.createdAt === 'string' ? new Date(b.createdAt).getTime() : (b.createdAt || Date.now())
        }));

        const normalizedApartments: Record<string, Apartment> = {};
        Object.entries(incomingData.apartments || {}).forEach(([id, apt]: [string, any]) => {
          normalizedApartments[id] = {
            ...apt,
            defects: Array.isArray(apt.defects) ? apt.defects : []
          };
        });

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...incomingData,
              apartments: normalizedApartments,
              employees: normalizedEmployees,
              sectors: normalizedSectors,
              budgets: normalizedBudgets
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return incomingData;
      }
    } catch (error) { 
      console.warn(`Erro ao carregar ${targetHotel}:`, error);
    } finally { 
      setIsRefreshing(false); 
    }
    return null;
  }, [state.currentHotel]);

  useEffect(() => {
    if (initialSyncRef.current) return;
    initialSyncRef.current = true;
    const runSync = async () => {
      await loadDataFromSheet(state.currentHotel);
      const others = (['VILLAGE', 'GOLDEN_PARK', 'THERMAL_RESORT'] as HotelType[]).filter(h => h !== state.currentHotel);
      for (const h of others) {
        await delay(4500);
        await loadDataFromSheet(h);
      }
    };
    runSync();
  }, [loadDataFromSheet, state.currentHotel]);

  useEffect(() => { 
    localStorage.setItem('hotel_village_state_v33', JSON.stringify(state)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    try {
      await fetch(GLOBAL_SCRIPT_URL, { 
        method: 'POST', 
        mode: 'no-cors', 
        body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files }) 
      });
      setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));
      if(['EMPLOYEE', 'SECTOR', 'DELETE', 'BUDGET', 'APARTMENT'].includes(dataType)) {
         setTimeout(() => loadDataFromSheet(), 4000);
      }
    } catch (err) { 
      console.error('Erro no envio:', err);
    }
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ 
      ...prev, 
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD,
      selectedFloor: null,
      selectedApartmentId: null
    }));
    if (user.hotel) setTimeout(() => loadDataFromSheet(user.hotel), 500);
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return <ApartmentDetailView apartment={apt} theme={theme} onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} onSave={(updatedApt, files) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], apartments: {...prev.hotels[prev.currentHotel].apartments, [updatedApt.id]: updatedApt}}}})); syncToSheet('APARTMENT', updatedApt, files); }} />;
      }
      if (state.selectedFloor !== null) return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }
    if (state.currentView === ViewType.BUDGETS) return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={(b, f) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.budgets.find(ex => ex.id === b.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, budgets: exists ? hotel.budgets.map(ex => ex.id === b.id ? b : ex) : [b, ...hotel.budgets] } } }; }); syncToSheet('BUDGET', b, f); }} onDelete={(id) => { setState(prev => ({ ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], budgets: (prev.hotels[prev.currentHotel].budgets || []).filter(b => b.id !== id) } } })); syncToSheet('DELETE', { targetType: 'BUDGET', id }); }} />;
    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={(item) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.inventory.find(i => i.id === item.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item] } } }; }); syncToSheet('INVENTORY', item); }} onDelete={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'INVENTORY', id }); }} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const updatedItem = { ...item, quantity: op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier] } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={(config) => { setState(prev => ({ ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } } } })); syncToSheet('CONFIG', config); }} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier] } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} currentHotel={state.currentHotel} onHotelChange={h => { setState(prev => ({...prev, currentHotel: h})); loadDataFromSheet(h); }} onLogout={() => setState(prev => ({...prev, currentUser: null}))} theme={theme} role={state.currentUser.role} />
      <BottomNav currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} theme={theme} role={state.currentUser.role} />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { Budget, Quote, BudgetFile, HotelTheme, BudgetItem, MaterialItem, MaterialQuote } from '../types';
import { 
  Plus, 
  Search, 
  Receipt, 
  Trash2, 
  ChevronDown,
  ChevronUp,
  X,
  Clock,
  Layers,
  Wrench,
  Calculator,
  Edit2,
  User as UserIcon,
  CheckCircle2,
  AlertCircle,
  Package,
  Truck,
  MessageSquare,
  TrendingDown,
  TrendingUp,
  DollarSign,
  Filter
} from 'lucide-react';

interface BudgetsViewProps {
  budgets: Budget[];
  theme: HotelTheme;
  onSave: (budget: Budget, newFiles?: {data: string, mimeType: string, fileName: string}[]) => void;
  onDelete: (id: string) => void;
}

const BudgetsView: React.FC<BudgetsViewProps> = ({ budgets, theme, onSave, onDelete }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingBudget, setEditingBudget] = useState<Budget | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  // Form State
  const [title, setTitle] = useState('');
  const [objective, setObjective] = useState('');
  const [items, setItems] = useState<BudgetItem[]>([
    { id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }
  ]);
  const [status, setStatus] = useState<'Pendente' | 'Aprovado' | 'Rejeitado'>('Pendente');

  const resetForm = () => {
    setTitle('');
    setObjective('');
    setItems([{ id: '1', description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
    setStatus('Pendente');
    setIsAdding(false);
    setEditingBudget(null);
  };

  const handleEdit = (budget: Budget) => {
    setEditingBudget(budget);
    setTitle(budget.title);
    setObjective(budget.objective);
    setItems((budget.items || []).map(it => ({ 
      ...it, 
      serviceProvider: it.serviceProvider || '',
      estimatedTime: it.estimatedTime || '',
      materials: (it.materials || []).map(m => ({
        ...m,
        quotes: (m.quotes && m.quotes.length === 3) 
          ? m.quotes 
          : [
              { supplier: '', value: 0 },
              { supplier: '', value: 0 },
              { supplier: '', value: 0 }
            ]
      }))
    })));
    setStatus(budget.status);
    setIsAdding(true);
  };

  const updateStatus = (budget: Budget, newStatus: 'Pendente' | 'Aprovado' | 'Rejeitado') => {
    onSave({ ...budget, status: newStatus });
    // Se estivermos mudando o status, o item sumirá da aba atual, o que é o comportamento desejado
  };

  const addServiceItem = () => {
    setItems([...items, { id: Date.now().toString(), description: '', materials: [], laborCost: 0, estimatedTime: '', serviceProvider: '' }]);
  };

  const removeServiceItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const updateItem = (id: string, field: keyof BudgetItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const addMaterial = (itemId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: [...(item.materials || []), { 
            id: Date.now().toString(), 
            name: '', 
            quantity: 1, 
            unit: 'Un',
            observation: '',
            quotes: [
              { supplier: '', value: 0 },
              { supplier: '', value: 0 },
              { supplier: '', value: 0 }
            ]
          }]
        };
      }
      return item;
    }));
  };

  const updateMaterial = (itemId: string, matId: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: (item.materials || []).map(m => m.id === matId ? { ...m, [field]: value } : m)
        };
      }
      return item;
    }));
  };

  const updateMaterialQuote = (itemId: string, matId: string, quoteIdx: number, field: keyof MaterialQuote, value: any) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return {
          ...item,
          materials: (item.materials || []).map(m => {
            if (m.id === matId) {
              const currentQuotes = m.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }];
              const newQuotes = [...currentQuotes];
              newQuotes[quoteIdx] = { ...newQuotes[quoteIdx], [field]: value };
              return { ...m, quotes: newQuotes };
            }
            return m;
          })
        };
      }
      return item;
    }));
  };

  const removeMaterial = (itemId: string, matId: string) => {
    setItems(items.map(item => {
      if (item.id === itemId) {
        return { ...item, materials: (item.materials || []).filter(m => m.id !== matId) };
      }
      return item;
    }));
  };

  const getBestMaterialPrice = (m: MaterialItem) => {
    const validPrices = (m.quotes || []).map(q => Number(q.value) || 0).filter(v => v > 0);
    if (validPrices.length === 0) return 0;
    return Math.min(...validPrices);
  };

  const calculateItemSubtotal = (item: BudgetItem) => {
    const materialsTotal = (item.materials || []).reduce((acc, m) => {
      const bestPrice = getBestMaterialPrice(m);
      return acc + (m.quantity * bestPrice);
    }, 0);
    return materialsTotal + (Number(item.laborCost) || 0);
  };

  // Funções de somatório para o Orçamento Completo
  const calculateBudgetTotals = (budgetItems: BudgetItem[]) => {
    let totalPrice = 0;
    let totalDays = 0;

    (budgetItems || []).forEach(item => {
      totalPrice += calculateItemSubtotal(item);
      // Tenta extrair apenas números do tempo estimado (ex: "5 dias" -> 5)
      const daysMatch = (item.estimatedTime || '').match(/\d+/);
      if (daysMatch) {
        totalDays += parseInt(daysMatch[0]);
      }
    });

    return { totalPrice, totalDays };
  };

  const formTotals = useMemo(() => calculateBudgetTotals(items), [items]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalBudget: Budget = {
      id: editingBudget?.id || Date.now().toString(),
      title: title || 'Novo Orçamento',
      objective,
      items,
      quotes: [], // Cotações de anexo simplificadas pelo novo sistema de materiais
      status,
      createdAt: editingBudget?.createdAt || Date.now()
    };
    onSave(finalBudget);
    resetForm();
  };

  const filteredBudgets = budgets.filter(b => 
    b.status === activeTab &&
    b.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStatusTabStyle = (status: string) => {
    const isActive = activeTab === status;
    if (!isActive) return 'text-slate-400 hover:text-slate-600';

    switch(status) {
      case 'Aprovado': return 'bg-emerald-500 text-white shadow-emerald-200';
      case 'Rejeitado': return 'bg-rose-500 text-white shadow-rose-200';
      default: return 'bg-amber-400 text-slate-800 shadow-amber-200';
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">

      {/* Sistema de Abas */}
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm w-full md:w-auto">
          {['Pendente', 'Aprovado', 'Rejeitado'].map((s) => (
            <button
              key={s}
              onClick={() => setActiveTab(s as any)}
              className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${getStatusTabStyle(s)}`}
            >
              {s}s ({budgets.filter(b => b.status === s).length})
            </button>
          ))}
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input 
              type="text"
              placeholder="Buscar orçamento..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-4 py-2.5 rounded-xl border border-slate-100 focus:border-blue-500 outline-none text-xs font-bold bg-white"
            />
          </div>
          <button 
            onClick={() => { resetForm(); setIsAdding(true); }}
            className="text-white px-6 py-3 rounded-xl font-bold flex items-center justify-center space-x-2 shadow-lg transition-all active:scale-95"
            style={{ backgroundColor: theme.primary }}
          >
            <Plus size={18} />
            <span>Novo</span>
          </button>
        </div>
      </div>

      {isAdding && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-6xl rounded-[2.5rem] shadow-2xl max-h-[95vh] overflow-y-auto animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800">{editingBudget ? 'Editar Orçamento' : 'Novo Orçamento'}</h2>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Gestão Hotel Village - Comparativo de Preços</p>
                </div>
                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Título do Projeto</label>
                    <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex: Reforma Banheiro Apto 205" className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all font-bold text-slate-800" />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 uppercase mb-2 ml-1">Objetivo do Investimento</label>
                    <textarea value={objective} onChange={(e) => setObjective(e.target.value)} placeholder="Justificativa da necessidade..." className="w-full px-5 py-3 rounded-xl border-2 border-white focus:border-blue-400 outline-none transition-all h-20 font-bold text-slate-800" />
                  </div>
                </div>

                <div className="space-y-6">
                   <div className="flex justify-between items-center px-2">
                      <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center">
                        <Layers size={16} className="mr-2 text-blue-500" /> Serviços e Materiais
                      </h3>
                      <button type="button" onClick={addServiceItem} className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl font-black text-[10px] uppercase border border-blue-100 hover:bg-blue-100 transition-all">+ Adicionar Serviço</button>
                   </div>

                   {items.map((item) => (
                     <div key={item.id} className="p-6 bg-white rounded-[2rem] border border-slate-200 relative shadow-sm">
                        <button type="button" onClick={() => removeServiceItem(item.id)} className="absolute top-6 right-6 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={20}/></button>

                        <div className="space-y-6">
                          <div>
                            <label className="block text-[9px] font-black text-slate-400 uppercase mb-2">Local / Descrição do Serviço</label>
                            <input type="text" value={item.description} onChange={(e) => updateItem(item.id, 'description', e.target.value)} placeholder="Ex: Pintura e Troca de Piso" className="w-full px-4 py-3 rounded-xl border border-slate-100 bg-slate-50 outline-none focus:border-blue-300 text-sm font-bold" />
                          </div>

                          <div className="space-y-4">
                            <div className="flex justify-between items-center">
                               <p className="text-[9px] font-black text-slate-400 uppercase flex items-center"><Package size={14} className="mr-1"/> Tripla Cotação de Materiais</p>
                               <button type="button" onClick={() => addMaterial(item.id)} className="text-[9px] font-black text-emerald-600 uppercase flex items-center hover:scale-105 transition-all"><Plus size={14} className="mr-1"/> Adicionar Material</button>
                            </div>

                            <div className="space-y-6">
                               {(item.materials || []).map((mat) => {
                                 const bestPrice = getBestMaterialPrice(mat);
                                 const currentQuotes = mat.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }];
                                 return (
                                   <div key={mat.id} className="p-5 bg-slate-50/50 rounded-[2.5rem] border border-slate-100 space-y-4">
                                      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                                        <div className="md:col-span-2">
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Material</label>
                                           <input type="text" value={mat.name} onChange={e => updateMaterial(item.id, mat.id, 'name', e.target.value)} placeholder="Nome do insumo" className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold" />
                                        </div>
                                        <div>
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Unidade</label>
                                           <input type="text" value={mat.unit || ''} onChange={e => updateMaterial(item.id, mat.id, 'unit', e.target.value)} placeholder="Ex: Un, Kg, m²" className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold" />
                                        </div>
                                        <div>
                                           <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Quantidade</label>
                                           <input type="number" value={mat.quantity} onChange={e => updateMaterial(item.id, mat.id, 'quantity', parseFloat(e.target.value))} className="w-full px-4 py-2 rounded-xl border border-slate-200 text-xs font-bold" />
                                        </div>
                                      </div>

                                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                        {currentQuotes.map((quote, qIdx) => (
                                          <div key={qIdx} className={`p-4 rounded-2xl border-2 transition-all ${Number(quote.value) > 0 && Number(quote.value) === bestPrice ? 'bg-emerald-50 border-emerald-200 shadow-sm' : 'bg-white border-white'}`}>
                                            <div className="flex items-center justify-between mb-2">
                                              <span className="text-[8px] font-black text-slate-400 uppercase">Fornecedor {qIdx + 1}</span>
                                              {Number(quote.value) > 0 && Number(quote.value) === bestPrice && <TrendingDown size={14} className="text-emerald-500" />}
                                            </div>
                                            <div className="space-y-2">
                                              <input 
                                                type="text" 
                                                value={quote.supplier} 
                                                onChange={e => updateMaterialQuote(item.id, mat.id, qIdx, 'supplier', e.target.value)} 
                                                placeholder="Nome do Fornecedor" 
                                                className="w-full px-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold outline-none" 
                                              />
                                              <div className="relative">
                                                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-[10px] text-slate-300 font-black">R$</span>
                                                <input 
                                                  type="number" 
                                                  step="0.01"
                                                  value={quote.value || ''} 
                                                  onChange={e => updateMaterialQuote(item.id, mat.id, qIdx, 'value', parseFloat(e.target.value))} 
                                                  placeholder="Valor Unitário" 
                                                  className="w-full pl-6 pr-3 py-1.5 rounded-lg border border-slate-100 text-[10px] font-bold outline-none" 
                                                />
                                              </div>
                                            </div>
                                          </div>
                                        ))}
                                      </div>

                                      <div className="flex items-center justify-between px-2 text-[9px] font-black uppercase text-slate-400">
                                         <div className="flex items-center">
                                            <MessageSquare size={12} className="mr-1"/>
                                            <input type="text" value={mat.observation || ''} onChange={e => updateMaterial(item.id, mat.id, 'observation', e.target.value)} placeholder="Adicionar observação técnica..." className="bg-transparent border-none outline-none w-64" />
                                         </div>
                                         <div className="text-right">
                                            Melhor Subtotal: <span className="text-blue-600">R$ {(mat.quantity * bestPrice).toLocaleString('pt-BR')}</span>
                                         </div>
                                      </div>
                                   </div>
                                 );
                               })}
                            </div>
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 pt-6 border-t border-slate-50 items-end">
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><UserIcon size={10} className="mr-1"/> Prestador / Empresa</label>
                                <input type="text" placeholder="Executor do serviço" value={item.serviceProvider || ''} onChange={e => updateItem(item.id, 'serviceProvider', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                             </div>
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><Wrench size={10} className="mr-1"/> R$ Mão de Obra</label>
                                <input type="number" step="0.01" value={item.laborCost || ''} onChange={e => updateItem(item.id, 'laborCost', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                             </div>
                             <div className="md:col-span-1">
                                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center"><Clock size={10} className="mr-1 text-blue-500"/> Prazo Estimado</label>
                                <input type="text" placeholder="Ex: 3 dias" value={item.estimatedTime || ''} onChange={e => updateItem(item.id, 'estimatedTime', e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 font-bold text-xs" />
                             </div>
                             <div className="flex flex-col justify-end text-right">
                                <p className="text-[8px] font-black text-slate-300 uppercase">Subtotal do Serviço</p>
                                <p className="text-xl font-black text-blue-600">R$ {calculateItemSubtotal(item).toLocaleString('pt-BR')}</p>
                             </div>
                          </div>
                        </div>
                     </div>
                   ))}
                </div>

                {/* Resumo de Custos e Tempo */}
                <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] flex flex-col md:flex-row justify-between items-center gap-6 shadow-2xl">
                   <div className="flex flex-wrap items-center gap-8">
                      <div className="flex items-center space-x-4">
                        <div className="p-4 bg-emerald-500/10 rounded-2xl"><Calculator size={28} className="text-emerald-400" /></div>
                        <div>
                           <p className="text-[9px] font-black text-white/40 uppercase tracking-widest">Valor Total do Projeto</p>
                           <h4 className="text-3xl font-black text-emerald-400">R$ {formTotals.totalPrice.toLocaleString('pt-BR')}</h4>
                        </div>
                      </div>
                      <div className="flex items-center space-x-4 border-l border-white/10 pl-8">
                        <div className="p-4 bg-blue-500/10 rounded-2xl"><Clock size={28} className="text-blue-400" /></div>
                        <div>
                           <p className="text-[9px] font-black text-white/40 uppercase tracking-widest">Tempo Total Estimado</p>
                           <h4 className="text-3xl font-black text-blue-400">{formTotals.totalDays} dias</h4>
                        </div>
                      </div>
                   </div>
                   <div className="flex gap-4 w-full md:w-auto">
                      <button type="button" onClick={resetForm} className="flex-1 md:flex-none px-8 py-4 rounded-2xl font-black text-xs uppercase text-white/60 hover:text-white transition-all">Cancelar</button>
                      <button type="submit" className="flex-1 md:flex-none px-12 py-4 rounded-2xl font-black text-xs uppercase tracking-widest bg-emerald-500 hover:bg-emerald-400 shadow-lg shadow-emerald-500/20 transition-all active:scale-95">
                        {editingBudget ? 'Atualizar Dados' : 'Salvar Orçamento'}
                      </button>
                   </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Lista de Orçamentos por Status */}
      <div className="space-y-4">
        {filteredBudgets.length === 0 ? (
          <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300">
            <Receipt size={64} className="mb-4 opacity-10" />
            <p className="text-xl font-black italic uppercase tracking-tighter">Sem orçamentos {activeTab}s</p>
          </div>
        ) : (
          filteredBudgets.map(budget => {
            const { totalPrice, totalDays } = calculateBudgetTotals(budget.items);
            return (
              <div key={budget.id} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all overflow-hidden group">
                <div className="p-6 md:p-8 cursor-pointer" onClick={() => setExpandedId(expandedId === budget.id ? null : budget.id)}>
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center space-x-6">
                      <div className="p-5 bg-slate-50 text-slate-900 rounded-[1.5rem] border border-slate-100">
                        <Receipt size={28} />
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-xl leading-none mb-2">{budget.title}</h4>
                        <div className="flex items-center space-x-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                          <span className="flex items-center"><Layers size={12} className="mr-1" /> {(budget.items || []).length} Serviços</span>
                          <span className="w-1.5 h-1.5 bg-slate-200 rounded-full"></span>
                          <span className="flex items-center"><Clock size={12} className="mr-1" /> {totalDays} dias</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between md:justify-end space-x-8">
                      <div className="text-right">
                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Valor do Melhor Preço</p>
                        <p className="text-2xl font-black text-blue-600 leading-none mt-1">R$ {totalPrice.toLocaleString('pt-BR')}</p>
                      </div>

                      <div className="flex items-center space-x-3">
                        <button 
                          onClick={(e) => { e.stopPropagation(); handleEdit(budget); }}
                          className="p-3 text-slate-300 hover:text-blue-500 hover:bg-blue-50 rounded-xl transition-all"
                        >
                          <Edit2 size={20} />
                        </button>
                        {expandedId === budget.id ? <ChevronUp size={24} className="text-slate-300" /> : <ChevronDown size={24} className="text-slate-300" />}
                      </div>
                    </div>
                  </div>
                </div>

                {expandedId === budget.id && (
                  <div className="px-8 pb-10 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 bg-slate-50/30">
                    <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      <div className="lg:col-span-3 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {(budget.items || []).map((item, iIdx) => (
                            <div key={item.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                              <h6 className="font-black text-slate-800 mb-3">{item.description}</h6>

                              <div className="space-y-3 mb-4">
                                {(item.materials || []).map(m => {
                                  const bestPrice = getBestMaterialPrice(m);
                                  return (
                                    <div key={m.id} className="p-3 bg-slate-50/50 rounded-2xl border border-slate-100">
                                      <div className="flex justify-between items-center mb-1">
                                        <span className="text-[10px] font-black text-slate-800">{m.quantity}{m.unit} • {m.name}</span>
                                        <span className="text-emerald-600 font-black text-[10px]">R$ {(m.quantity * bestPrice).toLocaleString('pt-BR')}</span>
                                      </div>
                                      <div className="grid grid-cols-3 gap-1">
                                        {m.quotes.map((q, qIdx) => q.value > 0 && (
                                          <div key={qIdx} className={`text-[7px] font-bold p-1 rounded border ${q.value === bestPrice ? 'bg-emerald-100 border-emerald-200' : 'bg-white border-slate-50 text-slate-400'}`}>
                                            {q.supplier || `F${qIdx+1}`}: R${q.value}
                                          </div>
                                        ))}
                                      </div>
                                    </div>
                                  );
                                })}
                              </div>

                              <div className="flex flex-col space-y-1 pt-2 border-t border-slate-50">
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400">Prestador:</span>
                                  <span className="text-slate-800">{item.serviceProvider}</span>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase">
                                  <span className="text-slate-400">Mão de Obra:</span>
                                  <span className="text-slate-800">R$ {item.laborCost.toLocaleString('pt-BR')}</span>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      <div className="lg:col-span-1">
                        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
                           <p className="text-[10px] font-black text-slate-400 uppercase text-center tracking-widest">Controle de Status</p>
                           <button onClick={() => updateStatus(budget, 'Aprovado')} className="w-full py-4 rounded-xl bg-emerald-500 text-white font-black text-xs uppercase shadow-lg active:scale-95 transition-all flex items-center justify-center space-x-2">
                             <CheckCircle2 size={16}/> <span>Aprovar Orçamento</span>
                           </button>
                           <button onClick={() => updateStatus(budget, 'Rejeitado')} className="w-full py-4 rounded-xl bg-white border-2 border-rose-100 text-rose-500 font-black text-xs uppercase active:scale-95 transition-all flex items-center justify-center space-x-2">
                             <X size={16}/> <span>Rejeitar</span>
                           </button>
                           <button onClick={() => onDelete(budget.id)} className="w-full py-4 text-slate-300 hover:text-rose-500 font-black text-[10px] uppercase transition-all">Excluir Registro</button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

