        {/* ACESSÓRIOS DO QUARTO */}
        <section className="bg-white p-6 rounded-[2.5rem] border border-slate-50 shadow-sm space-y-5">
          <SectionTitle icon={Box} title="Acessórios & Itens" color="text-amber-600" />

