                  <button onClick={() => updateField('suporteShampooStatus', 'Bom estado')} className={getStatusBtnClass(data.suporteShampooStatus, 'Bom estado', 'bg-emerald-500')}>BOM ESTADO</button>
                  <button onClick={() => updateField('suporteShampooStatus', 'Enferrujado')} className={getStatusBtnClass(data.suporteShampooStatus, 'Enferrujado', 'bg-rose-500')}>ENFERRUJADO</button>
                </div>
              )}
            </div>
            <button onClick={() => updateField('temSuportePapel', !data.temSuportePapel)} className={`w-full p-5 rounded-2xl border-2 flex items-center justify-between transition-all ${data.temSuportePapel ? 'bg-slate-800 border-transparent text-white shadow-lg' : 'bg-white border-slate-50 text-slate-400'}`}>
               <span className="text-[9px] font-black uppercase">Suporte de Papel Higiênico</span>
               <span className="text-xs font-black">{data.temSuportePapel ? 'POSSUI' : 'NÃO TEM'}</span>
            </button>
        </section>

        {/* ILUMINAÇÃO */}
        <section className="bg-white p-6 rounded-[2.5rem] border border-slate-50 shadow-sm space-y-4">
          <SectionTitle icon={Lightbulb} title="Iluminação" color="text-yellow-600" />
          <div className="grid grid-cols-3 gap-2">
            {['Arandela', 'Vidro', 'Quadrado'].map(t => (
              <button key={t} onClick={() => updateField('luminariaType', t as any)} className={getStatusBtnClass(data.luminariaType, t, 'bg-yellow-600')}>{t}</button>
            ))}
          </div>
          {data.luminariaType === 'Quadrado' && (
             <div className="p-4 bg-slate-50 rounded-2xl space-y-3">
                <div className="grid grid-cols-2 gap-2">
                   {['Branco', 'Preto'].map(color => (
                     <button key={color} onClick={() => updateField('luminariaColor', color as any)} className={`py-4 rounded-xl text-[10px] font-black border-2 transition-all ${data.luminariaColor === color ? 'bg-white border-slate-200 text-slate-800 shadow-sm' : 'bg-white border-transparent text-slate-300'}`}>{color.toUpperCase()}</button>
                   ))}
                </div>
             </div>
          )}
        </section>

        {/* CONFIGURAÇÃO DAS CAMAS */}
        <div className="pt-2 space-y-4">
          <SectionTitle icon={Bed} title="Configuração das Camas" color="text-emerald-600" />

          {(data.beds || []).map((bed, idx) => (
            <section key={idx} className="bg-white p-6 rounded-[2.5rem] border border-slate-50 shadow-sm space-y-6">
              <div className="flex justify-between items-center">
                <h4 className="text-[11px] font-black text-slate-800 uppercase tracking-tighter">Cama {idx + 1}</h4>
                <div className="bg-emerald-50 text-emerald-500 px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest">
                  {bed.type}
                </div>
              </div>

              {/* Base da Cama */}
              <div className="space-y-3">
                <label className="text-[9px] font-black text-slate-300 uppercase ml-1 tracking-widest">Base da Cama:</label>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => updateBed(idx, { baseStatus: 'Nova' })} className={getStatusBtnClass(bed.baseStatus, 'Nova', 'bg-emerald-500')}>NOVA</button>
                  <button onClick={() => updateBed(idx, { baseStatus: 'Antiga' })} className={getStatusBtnClass(bed.baseStatus, 'Antiga', 'bg-amber-400 !text-slate-900')}>ANTIGA</button>
                </div>
                {bed.baseStatus === 'Antiga' && (
                  <div className="grid grid-cols-3 gap-1.5 animate-in slide-in-from-top-2">
                    {['Rosa', 'Beje', 'Amarela', 'Branca', 'Preta Fosca', 'Cinza'].map(color => (
                      <button 
                        key={color} 
                        onClick={() => updateBed(idx, { baseColor: color })} 
                        className={`py-2 rounded-lg text-[8px] font-black border-2 transition-all ${bed.baseColor === color ? 'bg-slate-800 text-white border-transparent' : 'bg-white text-slate-300 border-slate-50'}`}
                      >
                        {color.toUpperCase()}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Colchão */}
              <div className="space-y-3">
                <label className="text-[9px] font-black text-slate-300 uppercase ml-1 tracking-widest">Colchão:</label>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => updateBed(idx, { mattressStatus: 'Novo' })} className={getStatusBtnClass(bed.mattressStatus, 'Novo', 'bg-emerald-500')}>NOVO</button>
                  <button onClick={() => updateBed(idx, { mattressStatus: 'Antigo' })} className={getStatusBtnClass(bed.mattressStatus, 'Antigo', 'bg-amber-400 !text-slate-900')}>ANTIGO</button>
                </div>
                {bed.mattressStatus === 'Antigo' && (
                  <div className="grid grid-cols-3 gap-1.5 animate-in slide-in-from-top-2">
                    {['Cinza', 'Bege', 'Rosa'].map(color => (
                      <button 
                        key={color} 
                        onClick={() => updateBed(idx, { mattressColor: color })} 
                        className={`py-2 rounded-lg text-[8px] font-black border-2 transition-all ${bed.mattressColor === color ? 'bg-slate-800 text-white border-transparent' : 'bg-white text-slate-300 border-slate-50'}`}
                      >
                        {color.toUpperCase()}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Saia de Cama */}
              <div className="space-y-3">
                <div className="flex items-center justify-between px-1">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Saia de Cama?</span>
                  <button 
                    onClick={() => updateBed(idx, { hasSkirt: !bed.hasSkirt })} 
                    className={`px-5 py-2 rounded-xl text-[9px] font-black transition-all ${bed.hasSkirt ? 'bg-emerald-500 text-white shadow-md' : 'bg-slate-50 text-slate-300 border-2 border-slate-50'}`}
                  >
                    {bed.hasSkirt ? 'POSSUI' : 'NÃO TEM'}
                  </button>
                </div>
                {bed.hasSkirt && (
                  <div className="grid grid-cols-2 gap-2 animate-in fade-in">
                    {['Cinza', 'Verde'].map(color => (
                      <button 
                        key={color} 
                        onClick={() => updateBed(idx, { skirtColor: color })} 
                        className={`py-3 rounded-2xl text-[9px] font-black border-2 transition-all ${bed.skirtColor === color ? 'bg-slate-800 text-white border-transparent' : 'bg-white text-slate-300 border-slate-50'}`}
                      >
                        {color.toUpperCase()}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </section>
          ))}
        </div>

        {/* RELATO DE DEFEITOS */}
        <section className="bg-white p-6 rounded-[2.5rem] border border-slate-50 shadow-xl space-y-4">
          <SectionTitle icon={Paperclip} title="Relato de Defeitos" color="text-rose-500" />
          <textarea 
            value={newDefectText} 
            onChange={(e) => setNewDefectText(e.target.value)} 
            placeholder="Descreva o problema..." 
            className="w-full p-4 rounded-2xl bg-slate-50 border-transparent focus:bg-white focus:border-rose-200 outline-none transition-all text-xs font-bold min-h-[100px] shadow-inner text-slate-700" 
          />
          <button onClick={() => fileInputRef.current?.click()} className="w-full bg-rose-500 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center space-x-3 active:scale-95 transition-all shadow-lg uppercase tracking-widest">
            <ImageIcon size={20} />
            <span>FOTOGRAFAR AVARIA</span>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" capture="environment" />

          <div className="space-y-4 pt-2">
            {(data.defects || []).map(defect => (
              <div key={defect.id} className="flex flex-col p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-right-2">
                <div className="flex items-start justify-between gap-4">
                   <div className="flex items-start space-x-3 flex-1">
                      {(defect.data || (defect.driveLink && defect.driveLink !== 'pendente')) && (
                        <div className="relative group cursor-pointer" onClick={() => setSelectedImage(defect.data || defect.driveLink || null)}>
                          <img src={defect.data || defect.driveLink} className="w-20 h-20 rounded-xl object-cover shadow-sm border group-hover:brightness-75 transition-all" alt="Evidência" />
                          <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                            <Maximize2 size={20} className="text-white" />
                          </div>
                        </div>
                      )}
                      <div className="flex-1">
                        <p className="text-[11px] font-black text-slate-800 uppercase leading-tight">{defect.description}</p>
                      </div>
                   </div>
                   <button onClick={() => setData(prev => ({ ...prev, defects: prev.defects.filter(d => d.id !== defect.id) }))} className="text-slate-300 hover:text-rose-500 transition-colors">
                     <Trash2 size={20}/>
                   </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      <div className="fixed bottom-8 left-0 right-0 px-6 z-[120]">
        <button onClick={handleSaveAndExit} disabled={isSaving} className="w-full bg-slate-900 text-white py-5 rounded-[2.2rem] font-black text-sm shadow-2xl flex items-center justify-center space-x-3 active:scale-95 transition-all hover:bg-slate-800">
          {isSaving ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Save size={20} className="text-emerald-400" />}
          <span>SALVAR VISTORIA</span>
        </button>
      </div>
    </div>
  );
};

export default ApartmentDetailView;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ViewType, AppState, Apartment, Budget, Employee, Integration, HotelType, HotelData, HotelTheme, User, Sector, InventoryItem, InventoryOperation, Supplier } from './types';
import Sidebar from './components/Sidebar';
import BottomNav from './components/BottomNav';
import Dashboard from './components/Dashboard';
import ApartmentsView from './components/ApartmentsView';
import FloorDetailView from './components/FloorDetailView';
import ApartmentDetailView from './components/ApartmentDetailView';
import BudgetsView from './components/BudgetsView';
import EmployeesView from './components/EmployeesView';
import InventoryView from './components/InventoryView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import Login from './components/Login';

const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyHwnTqgnBMecAsscAIJgpfe7gHPwjWbZ42qbm3EvXvX_oq9WzbrrT99knh7L4wdvDe4g/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [{ name: 'Camisa Social', quantity: 2 }, { name: 'Calça Social', quantity: 2 }] },
    { id: '2', name: 'Governança', standardUniform: [{ name: 'Jaleco', quantity: 3 }, { name: 'Calça Branca', quantity: 2 }] },
    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const initialSyncRef = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v33');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return { ...parsed, currentUser: null };
      } catch (e) {
        console.error("Erro ao carregar estado salvo:", e);
      }
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    const targetHotel = hotelOverride || state.currentHotel;
    setIsRefreshing(true);
    try {
      const scriptUrl = GLOBAL_SCRIPT_URL;
      const fetchUrl = `${scriptUrl}?hotel=${targetHotel}&nocache=${Date.now()}`;

      const response = await fetch(fetchUrl, {
        method: 'GET',
        mode: 'cors',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const result = await response.json();

      if (result && result.status === 'success') {
        const incomingData = result.data;

        // 1. Normalização de Funcionários e Setores
        const normalizedEmployees = (incomingData.employees || []).map((emp: any) => ({
          ...emp,
          id: emp.id?.toString() || '',
          sectorId: emp.sectorId?.toString() || '',
          uniforms: typeof emp.uniforms === 'string' ? JSON.parse(emp.uniforms) : (emp.uniforms || [])
        }));

        const normalizedSectors = (incomingData.sectors || []).map((sec: any) => ({
          ...sec,
          id: sec.id?.toString() || '',
          standardUniform: typeof sec.standardUniform === 'string' ? JSON.parse(sec.standardUniform) : (sec.standardUniform || [])
        }));

        // 2. Normalização de Orçamentos (Novos Campos Técnicos)
        const normalizedBudgets = (incomingData.budgets || []).map((b: any) => ({
          ...b,
          id: b.id?.toString() || '',
          items: (typeof b.items === 'string' ? JSON.parse(b.items) : (b.items || [])).map((it: any) => ({
            ...it,
            serviceProvider: it.serviceProvider || '',
            estimatedTime: it.estimatedTime || '',
            materials: (it.materials || []).map((m: any) => ({
              ...m,
              observation: m.observation || '',
              quotes: m.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }]
            }))
          })),
          quotes: typeof b.quotes === 'string' ? JSON.parse(b.quotes) : (b.quotes || []),
          createdAt: typeof b.createdAt === 'string' ? new Date(b.createdAt).getTime() : (b.createdAt || Date.now())
        }));

        // 3. Normalização de Apartamentos (Novas Opções Visuais)
        const normalizedApartments: Record<string, Apartment> = {};
        Object.entries(incomingData.apartments || {}).forEach(([id, apt]: [string, any]) => {
          normalizedApartments[id] = {
            ...apt,
            defects: Array.isArray(apt.defects) ? apt.defects : [],
            beds: Array.isArray(apt.beds) ? apt.beds : [],
            moveisDetalhes: Array.isArray(apt.moveisDetalhes) ? apt.moveisDetalhes : []
          };
        });

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...incomingData,
              apartments: normalizedApartments,
              employees: normalizedEmployees,
              sectors: normalizedSectors,
              budgets: normalizedBudgets
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return incomingData;
      }
    } catch (error) { 
      console.warn(`Erro ao carregar ${targetHotel}:`, error);
    } finally { 
      setIsRefreshing(false); 
    }
    return null;
  }, [state.currentHotel]);

  useEffect(() => {
    if (initialSyncRef.current) return;
    initialSyncRef.current = true;
    const runSync = async () => {
      await loadDataFromSheet(state.currentHotel);
      const others = (['VILLAGE', 'GOLDEN_PARK', 'THERMAL_RESORT'] as HotelType[]).filter(h => h !== state.currentHotel);
      for (const h of others) {
        await delay(4500);
        await loadDataFromSheet(h);
      }
    };
    runSync();
  }, [loadDataFromSheet, state.currentHotel]);

  useEffect(() => { 
    localStorage.setItem('hotel_village_state_v33', JSON.stringify(state)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    try {
      await fetch(GLOBAL_SCRIPT_URL, { 
        method: 'POST', 
        mode: 'no-cors', 
        body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files }) 
      });
      setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));
      // Recarrega dados após sincronização crítica
      if(['EMPLOYEE', 'SECTOR', 'DELETE', 'BUDGET', 'APARTMENT'].includes(dataType)) {
         setTimeout(() => loadDataFromSheet(), 4500);
      }
    } catch (err) { 
      console.error('Erro no envio:', err);
    }
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ 
      ...prev, 
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD,
      selectedFloor: null,
      selectedApartmentId: null
    }));
    if (user.hotel) setTimeout(() => loadDataFromSheet(user.hotel), 500);
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return <ApartmentDetailView apartment={apt} theme={theme} onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} onSave={(updatedApt, files) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], apartments: {...prev.hotels[prev.currentHotel].apartments, [updatedApt.id]: updatedApt}}}})); syncToSheet('APARTMENT', updatedApt, files); }} />;
      }
      if (state.selectedFloor !== null) return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }
    if (state.currentView === ViewType.BUDGETS) return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={(b, f) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.budgets.find(ex => ex.id === b.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, budgets: exists ? hotel.budgets.map(ex => ex.id === b.id ? b : ex) : [b, ...hotel.budgets] } } }; }); syncToSheet('BUDGET', b, f); }} onDelete={(id) => { setState(prev => ({ ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], budgets: (prev.hotels[prev.currentHotel].budgets || []).filter(b => b.id !== id) } } })); syncToSheet('DELETE', { targetType: 'BUDGET', id }); }} />;
    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={(item) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.inventory.find(i => i.id === item.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item] } } }; }); syncToSheet('INVENTORY', item); }} onDelete={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'INVENTORY', id }); }} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const updatedItem = { ...item, quantity: op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier] } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={(config) => { setState(prev => ({ ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } } } })); syncToSheet('CONFIG', config); }} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier] } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} currentHotel={state.currentHotel} onHotelChange={h => { setState(prev => ({...prev, currentHotel: h})); loadDataFromSheet(h); }} onLogout={() => setState(prev => ({...prev, currentUser: null}))} theme={theme} role={state.currentUser.role} />
      <BottomNav currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} theme={theme} role={state.currentUser.role} />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Integration, HotelTheme } from '../types';
import { Copy, FileSpreadsheet, XCircle } from 'lucide-react';

interface IntegrationsViewProps {
  integrations: Integration[];
  theme: HotelTheme;
  onUpdate: (integration: Integration) => void;
}

const APPS_SCRIPT_CODE = `/**
 * Google Apps Script para Gestão Hotel Village - V26 (Total Sync & Media)
 * Sincronização Otimizada com suporte para novos campos visuais e acessórios.
 */

function doGet(e) {
  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = e.parameter.hotel || 'VILLAGE';
    var result = {
      apartments: {}, budgets: [], employees: [], sectors: [], inventory: [], inventoryHistory: [], suppliers: [], config: {}
    };

    // 1. Apartamentos (Mapeamento de 27 Colunas)
    var sheetApts = ss.getSheetByName('Apartamentos_' + hotel);
    if (sheetApts) {
      var data = sheetApts.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        var num = data[i][0]; var floor = data[i][1]; if(!num || !floor) continue;
        var aptId = floor + "-" + num;
        result.apartments[aptId] = {
          id: aptId, roomNumber: num, floor: floor, pisoType: data[i][2], pisoStatus: data[i][3], banheiroType: data[i][4],
          banheiroStatus: data[i][5], temCofre: data[i][6] === 'Sim', temCortina: data[i][7] === 'Sim',
          cortinaStatus: data[i][8], cortinaSize: data[i][9], cortinaCoverage: data[i][10], temEspelhoCorpo: data[i][11] === 'Sim',
          espelhoCorpoStatus: data[i][12], acBrand: data[i][13], moveisStatus: data[i][14],
          moveisDetalhes: safeParse(data[i][15], []), beds: safeParse(data[i][16], []),
          temPortaControle: data[i][17] === 'Sim', temCabide: data[i][18] === 'Sim', cabideQuantity: data[i][19] || 0,
          temSuportePapel: data[i][20] === 'Sim', temSuporteShampoo: data[i][21] === 'Sim', suporteShampooStatus: data[i][22],
          luminariaType: data[i][23], luminariaColor: data[i][24], tvBrand: data[i][25], defects: safeParse(data[i][26], [])
        };
      }
    }

    // 2. Estoque
    var sheetInv = ss.getSheetByName('Estoque_' + hotel);
    if (sheetInv) {
      var dataI = sheetInv.getDataRange().getValues();
      for (var m = 1; m < dataI.length; m++) {
        if(!dataI[m][0]) continue;
        result.inventory.push({ 
          id: dataI[m][0].toString(), ean: dataI[m][1].toString(), name: dataI[m][2], category: dataI[m][3], 
          quantity: parseFloat(dataI[m][4]) || 0, minQuantity: dataI[m][5] || 0, unit: dataI[m][6], price: dataI[m][7] || 0, 
          supplierId: dataI[m][8] ? dataI[m][8].toString() : '', lastUpdate: dataI[m][9] ? new Date(dataI[m][9]).getTime() : Date.now()
        });
      }
    }

    // 3. Fornecedores
    var sheetSup = ss.getSheetByName('Fornecedores_' + hotel);
    if (sheetSup) {
      var dataS = sheetSup.getDataRange().getValues();
      for (var j = 1; j < dataS.length; j++) {
        if(!dataS[j][0]) continue;
        result.suppliers.push({ id: dataS[j][0].toString(), name: dataS[j][1], contact: dataS[j][2], category: dataS[j][3] });
      }
    }

    // 4. Funcionários
    var sheetEmp = ss.getSheetByName('Funcionarios_' + hotel);
    if (sheetEmp) {
      var dE = sheetEmp.getDataRange().getValues();
      for (var k = 1; k < dE.length; k++) { 
        if(!dE[k][0]) continue; 
        result.employees.push({ 
          id: dE[k][0].toString(), name: dE[k][1], role: dE[k][2], contact: dE[k][3], startDate: dE[k][4], salary: dE[k][5], 
          department: dE[k][6], sectorId: dE[k][7] ? dE[k][7].toString() : '', status: dE[k][8], scheduleType: dE[k][9], 
          shiftType: dE[k][10], workingHours: dE[k][11], weeklyDayOff: dE[k][12], monthlySundayOff: dE[k][13], 
          vacationStatus: dE[k][14], uniforms: safeParse(dE[k][15], []) 
        }); 
      }
    }

    // 5. Setores
    var sheetSec = ss.getSheetByName('Setores_' + hotel);
    if (sheetSec) {
      var dSc = sheetSec.getDataRange().getValues();
      for (var s = 1; s < dSc.length; s++) {
        if(!dSc[s][0]) continue;
        result.sectors.push({ id: dSc[s][0].toString(), name: dSc[s][1], standardUniform: safeParse(dSc[s][2], []) });
      }
    }

    // 6. Orçamentos
    var sheetOrc = ss.getSheetByName('Orcamentos_' + hotel);
    if (sheetOrc) {
      var dO = sheetOrc.getDataRange().getValues();
      for (var n = 1; n < dO.length; n++) {
        if(!dO[n][0]) continue;
        result.budgets.push({ 
          id: dO[n][0].toString(), title: dO[n][1], objective: dO[n][2], items: safeParse(dO[n][3], []), 
          quotes: safeParse(dO[n][4], []), status: dO[n][5], createdAt: dO[n][6] ? new Date(dO[n][6]).getTime() : Date.now() 
        });
      }
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(15000);
    var req = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = req.hotel || 'VILLAGE';
    var folder = getFolder("Gestão Hotel Village - Arquivos");

    if (req.newFiles && req.newFiles.length > 0) {
      req.newFiles.forEach(function(f) {
        var blob = Utilities.newBlob(Utilities.base64Decode(f.data), f.mimeType, f.fileName);
        var driveFile = folder.createFile(blob);
        driveFile.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
        var driveUrl = "https://drive.google.com/thumbnail?id=" + driveFile.getId() + "&sz=w1000";

        if (req.dataType === 'APARTMENT') {
           req.defects.forEach(function(d) { if(d.fileName === f.fileName) { d.driveLink = driveUrl; delete d.data; } });
        }
      });
    }

    if (req.dataType === 'DELETE') {
       var target = "";
       if(req.targetType === 'INVENTORY') target = 'Estoque_' + hotel;
       else if(req.targetType === 'SUPPLIER') target = 'Fornecedores_' + hotel;
       else if(req.targetType === 'BUDGET') target = 'Orcamentos_' + hotel;
       else if(req.targetType === 'EMPLOYEE') target = 'Funcionarios_' + hotel;
       else if(req.targetType === 'SECTOR') target = 'Setores_' + hotel;
       if(target) deleteRow(ss.getSheetByName(target), req.id);
    } 
    else if (req.dataType === 'EMPLOYEE') {
       var sheet = ss.getSheetByName('Funcionarios_' + hotel) || ss.insertSheet('Funcionarios_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.name, req.role, req.contact, req.startDate, req.salary, req.department, req.sectorId.toString(), req.status, req.scheduleType, req.shiftType || '', req.workingHours, req.weeklyDayOff, req.monthlySundayOff, req.vacationStatus, JSON.stringify(req.uniforms)]);
    }
    else if (req.dataType === 'SECTOR') {
       var sheet = ss.getSheetByName('Setores_' + hotel) || ss.insertSheet('Setores_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.name, JSON.stringify(req.standardUniform)]);
    }
    else if (req.dataType === 'BUDGET') {
       var sheet = ss.getSheetByName('Orcamentos_' + hotel) || ss.insertSheet('Orcamentos_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.title, req.objective, JSON.stringify(req.items), JSON.stringify(req.quotes), req.status, new Date(req.createdAt)]);
    }
    else if (req.dataType === 'INVENTORY_OP') {
       var sheetEst = ss.getSheetByName('Estoque_' + hotel);
       if (sheetEst) updateInventoryBalance(sheetEst, req.itemId, req.type, req.quantity);
    } 
    else if (req.dataType === 'INVENTORY') {
       var sheet = ss.getSheetByName('Estoque_' + hotel) || ss.insertSheet('Estoque_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.ean || '', req.name, req.category, req.quantity, 0, req.unit, req.price || 0, req.supplierId ? req.supplierId.toString() : '', new Date()]);
    } 
    else if (req.dataType === 'SUPPLIER') {
       var sheet = ss.getSheetByName('Fornecedores_' + hotel) || ss.insertSheet('Fornecedores_' + hotel);
       upsert(sheet, req.id.toString(), [req.id.toString(), req.name, req.contact, req.category]);
    } 
    else if (req.dataType === 'APARTMENT') {
       var sheet = ss.getSheetByName('Apartamentos_' + hotel) || ss.insertSheet('Apartamentos_' + hotel);
       upsert(sheet, req.roomNumber + '-' + req.floor, [req.roomNumber, req.floor, req.pisoType, req.pisoStatus, req.banheiroType, req.banheiroStatus, req.temCofre?'Sim':'Não', req.temCortina?'Sim':'Não', req.cortinaStatus, req.cortinaSize, req.cortinaCoverage, req.temEspelhoCorpo?'Sim':'Não', req.espelhoCorpoStatus, req.acBrand, req.moveisStatus, JSON.stringify(req.moveisDetalhes), JSON.stringify(req.beds), req.temPortaControle?'Sim':'Não', req.temCabide?'Sim':'Não', req.cabideQuantity, req.temSuportePapel?'Sim':'Não', req.temSuporteShampoo?'Sim':'Não', req.suporteShampooStatus, req.luminariaType, req.luminariaColor, req.tvBrand, JSON.stringify(req.defects)]);
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function safeParse(s, f) { try { if (!s || s == "") return f; return JSON.parse(s); } catch(e) { return f; } }
function getFolder(n) { var fs = DriveApp.getFoldersByName(n); return fs.hasNext() ? fs.next() : DriveApp.createFolder(n); }
function upsert(s, id, r) { var d = s.getDataRange().getValues(); var ids = id.toString().trim(); for (var i = 1; i < d.length; i++) { if (d[i][0].toString().trim() == ids) { s.getRange(i+1, 1, 1, r.length).setValues([r]); return; } } s.appendRow(r); }
function deleteRow(s, id) { if(!s) return; var d = s.getDataRange().getValues(); var ids = id.toString().trim(); for (var i = 1; i < d.length; i++) { if (d[i][0].toString().trim() == ids) { s.deleteRow(i + 1); break; } } }
function updateInventoryBalance(s, id, t, q) { var d = s.getDataRange().getValues(); var ids = id.toString().trim(); for (var i = 1; i < d.length; i++) { if (d[i][0].toString().trim() == ids) { var cur = parseFloat(d[i][4]) || 0; var nxt = (t === 'Entrada') ? cur + q : cur - q; s.getRange(i + 1, 5).setValue(nxt); s.getRange(i + 1, 10).setValue(new Date()); return; } } }
`;

const IntegrationsView: React.FC<IntegrationsViewProps> = ({ integrations, theme, onUpdate }) => {
