    { id: '3', name: 'Rouparia', standardUniform: [{ name: 'Camiseta Logotipo', quantity: 3 }, { name: 'Bermuda Tactel', quantity: 2 }] },
  ],
  config: {
    showSuppliersTab: true
  }
});

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const initialSyncRef = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v33');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return { ...parsed, currentUser: null };
      } catch (e) {
        console.error("Erro ao carregar estado salvo:", e);
      }
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    const targetHotel = hotelOverride || state.currentHotel;
    setIsRefreshing(true);
    try {
      const scriptUrl = GLOBAL_SCRIPT_URL;
      const fetchUrl = `${scriptUrl}?hotel=${targetHotel}&nocache=${Date.now()}`;

      const response = await fetch(fetchUrl, {
        method: 'GET',
        mode: 'cors',
        redirect: 'follow'
      });

      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const result = await response.json();

      if (result && result.status === 'success') {
        const incomingData = result.data;

        // 1. Normalização de Funcionários e Setores (Evita erros de toLowerCase em campos nulos)
        const normalizedEmployees = (incomingData.employees || []).map((emp: any) => ({
          ...emp,
          id: emp.id?.toString() || '',
          name: emp.name || 'Sem Nome',
          gender: emp.gender || 'M',
          fixedDayOff: emp.fixedDayOff || 'Segunda-feira',
          sundayOffs: typeof emp.sundayOffs === 'string' ? JSON.parse(emp.sundayOffs) : (Array.isArray(emp.sundayOffs) ? emp.sundayOffs : []),
          sectorId: emp.sectorId?.toString() || '',
          uniforms: typeof emp.uniforms === 'string' ? JSON.parse(emp.uniforms) : (emp.uniforms || [])
        }));

        const normalizedSectors = (incomingData.sectors || []).map((sec: any) => ({
          ...sec,
          id: sec.id?.toString() || '',
          name: sec.name || 'Setor Sem Nome',
          standardUniform: typeof sec.standardUniform === 'string' ? JSON.parse(sec.standardUniform) : (sec.standardUniform || [])
        }));

        // 2. Normalização de Orçamentos
        const normalizedBudgets = (incomingData.budgets || []).map((b: any) => ({
          ...b,
          id: b.id?.toString() || '',
          title: b.title || 'Sem Título',
          objective: b.objective || '',
          items: (typeof b.items === 'string' ? JSON.parse(b.items) : (b.items || [])).map((it: any) => ({
            ...it,
            description: it.description || 'Serviço',
            serviceProvider: it.serviceProvider || '',
            estimatedTime: it.estimatedTime || '',
            materials: (it.materials || []).map((m: any) => ({
              ...m,
              name: m.name || 'Material',
              observation: m.observation || '',
              quotes: m.quotes || [{ supplier: '', value: 0 }, { supplier: '', value: 0 }, { supplier: '', value: 0 }]
            }))
          })),
          quotes: typeof b.quotes === 'string' ? JSON.parse(b.quotes) : (b.quotes || []),
          createdAt: typeof b.createdAt === 'string' ? new Date(b.createdAt).getTime() : (b.createdAt || Date.now())
        }));

        // 3. Normalização de Apartamentos
        const normalizedApartments: Record<string, Apartment> = {};
        Object.entries(incomingData.apartments || {}).forEach(([id, apt]: [string, any]) => {
          normalizedApartments[id] = {
            ...apt,
            defects: Array.isArray(apt.defects) ? apt.defects : [],
            beds: Array.isArray(apt.beds) ? apt.beds : [],
            moveisDetalhes: Array.isArray(apt.moveisDetalhes) ? apt.moveisDetalhes : []
          };
        });

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...incomingData,
              apartments: normalizedApartments,
              employees: normalizedEmployees,
              sectors: normalizedSectors,
              budgets: normalizedBudgets
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
        return incomingData;
      }
    } catch (error) { 
      console.warn(`Erro ao carregar ${targetHotel}:`, error);
    } finally { 
      setIsRefreshing(false); 
    }
    return null;
  }, [state.currentHotel]);

  useEffect(() => {
    if (initialSyncRef.current) return;
    initialSyncRef.current = true;
    const runSync = async () => {
      await loadDataFromSheet(state.currentHotel);
      const others = (['VILLAGE', 'GOLDEN_PARK', 'THERMAL_RESORT'] as HotelType[]).filter(h => h !== state.currentHotel);
      for (const h of others) {
        await delay(4500);
        await loadDataFromSheet(h);
      }
    };
    runSync();
  }, [loadDataFromSheet, state.currentHotel]);

  useEffect(() => { 
    localStorage.setItem('hotel_village_state_v33', JSON.stringify(state)); 
  }, [state]);

  const syncToSheet = async (dataType: 'APARTMENT' | 'BUDGET' | 'EMPLOYEE' | 'SECTOR' | 'INVENTORY' | 'INVENTORY_OP' | 'SUPPLIER' | 'CONFIG' | 'DELETE', data: any, files?: any[]) => {
    try {
      await fetch(GLOBAL_SCRIPT_URL, { 
        method: 'POST', 
        mode: 'no-cors', 
        body: JSON.stringify({ dataType, hotel: state.currentHotel, ...data, newFiles: files }) 
      });
      setState(prev => ({ ...prev, integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now() } : i) }));
      // Recarrega dados após sincronização crítica
      if(['EMPLOYEE', 'SECTOR', 'DELETE', 'BUDGET', 'APARTMENT'].includes(dataType)) {
         setTimeout(() => loadDataFromSheet(), 4500);
      }
    } catch (err) { 
      console.error('Erro no envio:', err);
    }
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ 
      ...prev, 
      currentUser: user,
      currentHotel: user.hotel || prev.currentHotel,
      currentView: user.role === 'FUNCIONARIO' ? ViewType.APARTMENTS : ViewType.DASHBOARD,
      selectedFloor: null,
      selectedApartmentId: null
    }));
    if (user.hotel) setTimeout(() => loadDataFromSheet(user.hotel), 500);
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const renderContent = () => {
    if (state.currentView === ViewType.APARTMENTS) {
      if (state.selectedApartmentId) {
        const aptId = state.selectedApartmentId;
        const apt = currentHotelData.apartments[aptId] || { id: aptId, floor: parseInt(aptId.split('-')[0]), roomNumber: parseInt(aptId.split('-')[1]), defects: [] };
        return <ApartmentDetailView apartment={apt} theme={theme} onBack={() => setState(prev => ({...prev, selectedApartmentId: null}))} onSave={(updatedApt, files) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], apartments: {...prev.hotels[prev.currentHotel].apartments, [updatedApt.id]: updatedApt}}}})); syncToSheet('APARTMENT', updatedApt, files); }} />;
      }
      if (state.selectedFloor !== null) return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={id => setState(prev => ({...prev, selectedApartmentId: id}))} />;
      return <ApartmentsView onSelectFloor={f => setState(prev => ({...prev, selectedFloor: f}))} theme={theme} hotelName={state.currentHotel} />;
    }
    if (state.currentView === ViewType.BUDGETS) return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={(b, f) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.budgets.find(ex => ex.id === b.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, budgets: exists ? hotel.budgets.map(ex => ex.id === b.id ? b : ex) : [b, ...hotel.budgets] } } }; }); syncToSheet('BUDGET', b, f); }} onDelete={(id) => { setState(prev => ({ ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], budgets: (prev.hotels[prev.currentHotel].budgets || []).filter(b => b.id !== id) } } })); syncToSheet('DELETE', { targetType: 'BUDGET', id }); }} />;
    // Fixed typo in onSaveSector callback where 'x' was used instead of 'ex' in a map function.
    if (state.currentView === ViewType.EMPLOYEES) return <EmployeesView employees={currentHotelData.employees} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={id => setState(prev => ({...prev, selectedSectorId: id}))} theme={theme} onSave={(e) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.find(ex => ex.id === e.id) ? prev.hotels[prev.currentHotel].employees.map(ex => ex.id === e.id ? e : ex) : [e, ...prev.hotels[prev.currentHotel].employees]}}})); syncToSheet('EMPLOYEE', e); }} onDelete={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], employees: prev.hotels[prev.currentHotel].employees.filter(e => e.id !== id)}}})); syncToSheet('DELETE', { targetType: 'EMPLOYEE', id }); }} onSaveSector={(s) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.find(ex => ex.id === s.id) ? prev.hotels[prev.currentHotel].sectors.map(ex => ex.id === s.id ? s : ex) : [...prev.hotels[prev.currentHotel].sectors, s]}}})); syncToSheet('SECTOR', s); }} onDeleteSector={(id) => { setState(prev => ({...prev, hotels: {...prev.hotels, [prev.currentHotel]: {...prev.hotels[prev.currentHotel], sectors: prev.hotels[prev.currentHotel].sectors.filter(s => s.id !== id)}}})); syncToSheet('DELETE', { targetType: 'SECTOR', id }); }} />;
    if (state.currentView === ViewType.INVENTORY) return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={(item) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.inventory.find(i => i.id === item.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: exists ? hotel.inventory.map(i => i.id === item.id ? item : i) : [...hotel.inventory, item] } } }; }); syncToSheet('INVENTORY', item); }} onDelete={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.filter(i => i.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'INVENTORY', id }); }} onOperation={(op) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const item = hotel.inventory.find(i => i.id === op.itemId); if (!item) return prev; const updatedItem = { ...item, quantity: op.type === 'Entrada' ? item.quantity + op.quantity : item.quantity - op.quantity, lastUpdate: Date.now() }; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, inventory: hotel.inventory.map(i => i.id === op.itemId ? updatedItem : i), inventoryHistory: [op, ...hotel.inventoryHistory] } } }; }); syncToSheet('INVENTORY_OP', op); }} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier] } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
    if (state.currentView === ViewType.REPORTS) return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={id => setState(prev => ({ ...prev, currentView: ViewType.APARTMENTS, selectedApartmentId: id }))} />;
    if (state.currentView === ViewType.SETTINGS) return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={(config) => { setState(prev => ({ ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], config: { ...prev.hotels[prev.currentHotel].config, ...config } } } })); syncToSheet('CONFIG', config); }} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={(supplier) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; const exists = hotel.suppliers.find(s => s.id === supplier.id); return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: exists ? hotel.suppliers.map(s => s.id === supplier.id ? supplier : s) : [...hotel.suppliers, supplier] } } }; }); syncToSheet('SUPPLIER', supplier); }} onDeleteSupplier={(id) => { setState(prev => { const hotel = prev.hotels[prev.currentHotel]; return { ...prev, hotels: { ...prev.hotels, [prev.currentHotel]: { ...hotel, suppliers: hotel.suppliers.filter(s => s.id !== id) } } }; }); syncToSheet('DELETE', { targetType: 'SUPPLIER', id }); }} onUpdate={i => setState(prev => ({...prev, integrations: prev.integrations.map(existing => existing.id === i.id ? i : existing)}))} />;
    if (state.currentView === ViewType.DASHBOARD) return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
    return null;
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;
  return (
    <div className="flex flex-col md:flex-row min-h-screen" style={{ backgroundColor: theme.bg }}>
      <Sidebar currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} currentHotel={state.currentHotel} onHotelChange={h => { setState(prev => ({...prev, currentHotel: h})); loadDataFromSheet(h); }} onLogout={() => setState(prev => ({...prev, currentUser: null}))} theme={theme} role={state.currentUser.role} />
      <BottomNav currentView={state.currentView} onViewChange={v => setState(prev => ({...prev, currentView: v, selectedFloor: null, selectedApartmentId: null}))} theme={theme} role={state.currentUser.role} />
      <main className={`flex-1 transition-all duration-300 p-4 md:p-8 ${state.selectedApartmentId ? 'p-0' : ''} mb-20 md:mb-0 md:ml-64`}>
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Employee, HotelTheme, Sector, UniformItem } from '../types';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Building2,
  X,
  Plus,
  Clock,
  AlertTriangle,
  CheckCircle2,
  Layers,
  ChevronLeft,
  Shirt,
  Edit2,
  Package,
  Info,
  Calendar as CalendarIcon,
  Filter,
  User as UserIcon,
  ChevronRight,
  Printer
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee) => void;
  onDelete: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [editingSector, setEditingSector] = useState<Sector | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'LIST' | 'SCALE'>('LIST');
  const [activeFormTab, setActiveFormTab] = useState<'DADOS' | 'ESCALA' | 'UNIFORMES'>('DADOS');

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [fixedDayOff, setFixedDayOff] = useState('Segunda-feira');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Form State Sector
  const [sectorName, setSectorName] = useState('');
  const [standardUniforms, setStandardUniforms] = useState<UniformItem[]>([]);

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setSalary('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setUniforms([]); setScheduleType('6x1'); setShiftType('Par');
    setWorkingHours('08:00 - 16:20'); setFixedDayOff('Segunda-feira');
    setSundayOffs([]); setVacationStatus('Pendente');
    setIsAddingEmployee(false); setEditingEmployee(null); setActiveFormTab('DADOS');
  };

  const resetSectorForm = () => {
    setSectorName(''); setStandardUniforms([]);
    setIsAddingSector(false); setEditingSector(null);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name || ''); setRole(emp.role || ''); setGender(emp.gender || 'M');
    setContact(emp.contact || ''); setStartDate(emp.startDate || ''); setSalary((emp.salary || 0).toString());
    setUniforms(emp.uniforms || []); setScheduleType(emp.scheduleType || '6x1');
    setShiftType(emp.shiftType || 'Par'); setWorkingHours(emp.workingHours || '');
    setFixedDayOff(emp.fixedDayOff || 'Segunda-feira');
    setSundayOffs(emp.sundayOffs || []); setVacationStatus(emp.vacationStatus || 'Pendente');
    setIsAddingEmployee(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', role: role || 'Cargo', gender, contact, startDate,
      salary: parseFloat(salary) || 0, department: sectors.find(s => s.id === selectedSectorId)?.name || '',
      sectorId: selectedSectorId!, status: 'Ativo', scheduleType, shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours, fixedDayOff, sundayOffs, weeklyDayOff: fixedDayOff, monthlySundayOff: '', vacationStatus, uniforms
    };
    onSave(newEmp);
    resetEmployeeForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!sectorName) return;
    onSaveSector({ id: editingSector?.id || Date.now().toString(), name: sectorName, standardUniform: standardUniforms });
    resetSectorForm();
  };

  const filteredEmployees = employees.filter(e => 
    e.sectorId === selectedSectorId && 
    (e.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  // Escala Logic
  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getDayName = (year: number, month: number, day: number) => {
    const date = new Date(year, month, day);
    return date.toLocaleDateString('pt-BR', { weekday: 'long' });
  };

  const daysArray = useMemo(() => {
    const now = new Date();
    const days = getDaysInMonth(now.getFullYear(), now.getMonth());
    return Array.from({ length: days }, (_, i) => ({
      day: i + 1,
      name: getDayName(now.getFullYear(), now.getMonth(), i + 1),
      isSunday: new Date(now.getFullYear(), now.getMonth(), i + 1).getDay() === 0
    }));
  }, []);

  const getSundayIndex = (day: number) => {
    const now = new Date();
    let count = 0;
    for(let i = 1; i <= day; i++) {
       if(new Date(now.getFullYear(), now.getMonth(), i).getDay() === 0) count++;
    }
    return count;
  };

  if (!selectedSectorId) {
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="flex justify-between items-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Selecione o Setor</p>
          <button onClick={() => setIsAddingSector(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
            <Plus size={18} /> <span>Novo Setor</span>
          </button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {sectors.map((sec) => (
            <div key={sec.id} className="relative group">
              <button onClick={() => onSelectSector(sec.id)} className="w-full bg-white h-48 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all border border-slate-50 flex flex-col items-center justify-center overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1.5" style={{ backgroundColor: theme.primary }}></div>
                <div className="p-5 rounded-2xl mb-3 bg-slate-50 text-slate-400 group-hover:scale-110 transition-transform">
                  <Building2 size={32} />
                </div>
                <h3 className="text-xl font-black text-slate-800">{sec.name}</h3>
                <p className="text-slate-400 text-[10px] font-black uppercase mt-1">
                  {employees.filter(e => e.sectorId === sec.id).length} Colaboradores
                </p>
              </button>
              <div className="absolute top-4 right-4 flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={(e) => { e.stopPropagation(); setEditingSector(sec); setSectorName(sec.name || ''); setStandardUniforms(sec.standardUniform || []); setIsAddingSector(true); }} className="p-2 bg-white rounded-full text-blue-500 shadow-sm border"><Edit2 size={12}/></button>
                <button onClick={(e) => { e.stopPropagation(); onDeleteSector(sec.id); }} className="p-2 bg-white rounded-full text-rose-500 shadow-sm border"><Trash2 size={12}/></button>
              </div>
            </div>
          ))}
        </div>

        {isAddingSector && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl animate-in zoom-in duration-200">
               <div className="p-8 border-b flex justify-between items-center">
                  <h2 className="text-xl font-black text-slate-800">{editingSector ? 'Editar Setor' : 'Novo Setor'}</h2>
                  <button onClick={resetSectorForm} className="text-slate-300 hover:text-slate-500"><X size={24}/></button>
               </div>
               <form onSubmit={handleSaveSectorSubmit} className="p-8 space-y-6">
                  <input type="text" value={sectorName} onChange={e => setSectorName(e.target.value)} className="w-full px-4 py-3 rounded-xl border-2 font-bold" placeholder="Nome do Setor" required />
                  <button type="submit" className="w-full py-4 text-white rounded-2xl font-black text-xs uppercase" style={{ backgroundColor: theme.primary }}>Salvar Setor</button>
               </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-3">
          <button onClick={() => onSelectSector(null)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-slate-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-800 uppercase tracking-tighter">{currentSector?.name}</h2>
            <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">{filteredEmployees.length} Colaboradores</p>
          </div>
        </div>

        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
          <button onClick={() => setViewMode('LIST')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'LIST' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Listagem</button>
          <button onClick={() => setViewMode('SCALE')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${viewMode === 'SCALE' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Escala Mensal</button>
        </div>

        <button onClick={() => setIsAddingEmployee(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
          <UserPlus size={18} /> <span className="hidden sm:inline">Novo Colaborador</span>
        </button>
      </div>

      {viewMode === 'LIST' ? (
        <div className="space-y-4">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input type="text" placeholder="Buscar colaborador..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 text-sm font-bold bg-white" />
          </div>

          <div className="grid grid-cols-1 gap-4">
            {filteredEmployees.map(emp => (
              <div key={emp.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row items-center gap-6 group hover:border-blue-200 transition-all">
                <div className="flex items-center space-x-4 flex-1">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-md ${emp.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                    {(emp.name || 'S')[0]}
                  </div>
                  <div>
                    <h4 className="font-black text-slate-800">{emp.name || 'Sem Nome'}</h4>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{emp.role} • Folga: {emp.fixedDayOff}</p>
                  </div>
                </div>
                <div className="flex gap-4 items-center">
                  <div className="text-right">
                    <p className="text-[8px] font-black text-slate-300 uppercase">Status</p>
                    <span className="text-[9px] font-black text-emerald-500 uppercase flex items-center"><CheckCircle2 size={10} className="mr-1"/> Ativo</span>
                  </div>
                  <div className="flex space-x-2">
                    <button onClick={() => handleEditEmployee(emp)} className="p-3 bg-slate-50 text-slate-400 hover:text-blue-500 rounded-xl transition-all"><Edit2 size={18}/></button>
                    <button onClick={() => onDelete(emp.id)} className="p-3 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-xl transition-all"><Trash2 size={18}/></button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-xl overflow-hidden animate-in zoom-in-95">
          <div className="p-8 border-b bg-slate-50/50 flex justify-between items-center">
             <div>
                <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter">ESCALA {currentSector?.name}</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{new Date().toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}</p>
             </div>
             <button onClick={() => window.print()} className="p-3 bg-white rounded-xl border text-slate-400 hover:text-slate-900 transition-all"><Printer size={20}/></button>
          </div>

          <div className="overflow-x-auto p-4 md:p-8">
             <table className="w-full border-collapse border border-slate-300 text-[10px] shadow-sm">
                <thead>
                   <tr>
                      <th className="border border-slate-400 p-2 text-left min-w-[200px] uppercase font-black bg-slate-100 text-slate-700">COLABORADOR</th>
                      <th className="border border-slate-400 p-2 text-center min-w-[80px] uppercase font-black bg-slate-100 text-slate-700">JORNADA</th>
                      {daysArray.map(d => (
                         <th key={d.day} className={`border border-slate-400 p-1 text-center min-w-[30px] font-black ${d.isSunday ? 'bg-slate-200' : 'bg-slate-50'}`}>
                            <div className="text-[7px] uppercase opacity-70 mb-0.5">{d.name.slice(0,3)}</div>
                            <div className="text-slate-800">{d.day}</div>
                         </th>
                      ))}
                   </tr>
                </thead>
                <tbody>
                   {filteredEmployees.map(emp => (
                      <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                         <td className="border border-slate-300 p-2 font-bold uppercase text-slate-700 bg-slate-50/30">{emp.name || 'Sem Nome'}</td>
                         <td className="border border-slate-300 p-2 text-center font-bold text-slate-500">{emp.workingHours}</td>
                         {daysArray.map(d => {
                            let content = '';
                            const empFixedDayOff = emp.fixedDayOff || '';
                            const isFixedOff = d.name.toLowerCase() === empFixedDayOff.toLowerCase();
                            const isSundayOff = d.isSunday && (emp.sundayOffs || []).includes(getSundayIndex(d.day));

                            let bgColor = '';
                            let textColor = 'text-slate-800';

                            if(isSundayOff) {
                               content = 'D';
                               bgColor = 'bg-amber-100';
                               textColor = 'text-amber-700';
                            } else if(isFixedOff) {
                               content = 'F';
                               bgColor = 'bg-blue-100';
                               textColor = 'text-blue-700';
                            } else if(d.isSunday) {
                               bgColor = 'bg-slate-100/50';
                            }

                            return (
                               <td key={d.day} className={`border border-slate-300 p-1 text-center font-black ${bgColor} ${textColor} transition-colors`}>
                                  {content}
                               </td>
                            );
                         })}
                      </tr>
                   ))}
                </tbody>
             </table>

             <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-8 no-print">
                <div className="space-y-3">
                   <h5 className="font-black text-slate-800 uppercase text-xs mb-2 border-b-2 border-slate-900 inline-block tracking-tight">LEGENDA DA ESCALA</h5>
                   <div className="grid grid-cols-2 border border-slate-300 rounded-lg overflow-hidden">
                      <div className="border border-slate-300 p-2 font-black text-center bg-blue-100 text-blue-700">F</div>
                      <div className="border border-slate-300 p-2 pl-4 uppercase font-bold text-slate-600 bg-white">FOLGA FIXA</div>
                      <div className="border border-slate-300 p-2 font-black text-center bg-slate-50 text-slate-400">-</div>
                      <div className="border border-slate-300 p-2 pl-4 uppercase font-bold text-slate-600 bg-white">DIA DE TRABALHO</div>
                      <div className="border border-slate-300 p-2 font-black text-center bg-slate-900 text-white">BH</div>
                      <div className="border border-slate-300 p-2 pl-4 uppercase font-bold text-slate-600 bg-white">BANCO DE HORA</div>
                      <div className="border border-slate-300 p-2 font-black text-center bg-amber-100 text-amber-700">D</div>
                      <div className="border border-slate-300 p-2 pl-4 uppercase font-bold text-slate-600 bg-white">DOMINGO (FOLGA)</div>
                   </div>
                </div>
                <div className="space-y-3">
                   <h5 className="font-black text-slate-800 uppercase text-xs mb-2 border-b-2 border-slate-900 inline-block tracking-tight">OBSERVAÇÕES GERAIS:</h5>
                   <div className="border border-slate-300 rounded-lg h-28 p-4 bg-slate-50 text-slate-400 italic uppercase font-bold text-[9px] shadow-inner">
                      Utilize este espaço para anotações manuais após a impressão ou notas internas da gerência...
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Modal Cadastro Colaborador */}
      {isAddingEmployee && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-3xl rounded-[3rem] shadow-2xl max-h-[90vh] overflow-hidden flex flex-col animate-in zoom-in duration-300">
              <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
                 <div>
                    <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{editingEmployee ? 'Editar' : 'Novo'} Colaborador</h2>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{currentSector?.name}</p>
                 </div>
                 <button onClick={resetEmployeeForm} className="p-2 text-slate-300 hover:text-slate-900 transition-all"><X size={32}/></button>
              </div>

              <div className="flex bg-slate-100 p-1.5 mx-8 mt-6 rounded-2xl border">
                 <button onClick={() => setActiveFormTab('DADOS')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'DADOS' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Dados Pessoais</button>
                 <button onClick={() => setActiveFormTab('ESCALA')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'ESCALA' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Escala & Folgas</button>
                 <button onClick={() => setActiveFormTab('UNIFORMES')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'UNIFORMES' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Uniformes</button>
              </div>

              <form onSubmit={handleSaveEmployeeSubmit} className="p-8 flex-1 overflow-y-auto space-y-8">
                 {activeFormTab === 'DADOS' && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-left-4">
                       <div className="col-span-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Nome Completo</label>
                          <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" required />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Gênero (Regra Domingos CLT)</label>
                          <div className="grid grid-cols-2 gap-2">
                             <button type="button" onClick={() => setGender('M')} className={`py-3 rounded-xl border-2 font-black text-xs ${gender === 'M' ? 'bg-blue-500 border-blue-500 text-white' : 'bg-white'}`}>HOMEM (1 D)</button>
                             <button type="button" onClick={() => setGender('F')} className={`py-3 rounded-xl border-2 font-black text-xs ${gender === 'F' ? 'bg-rose-500 border-rose-500 text-white' : 'bg-white'}`}>MULHER (2 D)</button>
                          </div>
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Cargo / Função</label>
                          <input type="text" value={role} onChange={e => setRole(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" required />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Contato</label>
                          <input type="text" value={contact} onChange={e => setContact(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Salário Base (R$)</label>
                          <input type="number" value={salary} onChange={e => setSalary(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                       </div>
                    </div>
                 )}

                 {activeFormTab === 'ESCALA' && (
                    <div className="space-y-8 animate-in slide-in-from-right-4">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                             <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Folga Fixa (Semanal)</label>
                             <select value={fixedDayOff} onChange={e => setFixedDayOff(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold bg-white">
                                {['Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado'].map(d => <option key={d} value={d}>{d}</option>)}
                             </select>
                          </div>
                          <div>
                             <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Horário de Trabalho</label>
                             <input type="text" value={workingHours} onChange={e => setWorkingHours(e.target.value)} placeholder="08:00 - 16:20" className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                          </div>
                       </div>

                       <div className="p-6 bg-slate-50 rounded-3xl border border-slate-200">
                          <label className="text-[10px] font-black text-slate-500 uppercase mb-4 block flex items-center">
                             <CalendarIcon size={14} className="mr-2"/> Domingos de Folga no Mês
                             <span className="ml-auto text-[8px] italic">{gender === 'F' ? 'Mulher: Escolha 2' : 'Homem: Escolha 1'}</span>
                          </label>
                          <div className="grid grid-cols-5 gap-3">
                             {[1, 2, 3, 4, 5].map(num => (
                                <button
                                   key={num}
                                   type="button"
                                   onClick={() => {
                                      if(sundayOffs.includes(num)) setSundayOffs(sundayOffs.filter(n => n !== num));
                                      else setSundayOffs([...sundayOffs, num]);
                                   }}
                                   className={`p-4 rounded-2xl border-2 font-black text-xs transition-all ${sundayOffs.includes(num) ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white text-slate-400'}`}
                                >
                                   {num}º D
                                </button>
                             ))}
                          </div>
                          {((gender === 'F' && sundayOffs.length !== 2) || (gender === 'M' && sundayOffs.length !== 1)) && (
                             <p className="text-[8px] text-rose-500 font-bold mt-3 uppercase tracking-widest animate-pulse">Atenção: A quantidade selecionada não coincide com a regra de gênero.</p>
                          )}
                       </div>
                    </div>
                 )}

                 {activeFormTab === 'UNIFORMES' && (
                    <div className="space-y-6 animate-in fade-in">
                       <p className="text-[10px] font-black text-slate-400 uppercase text-center border-2 border-dashed p-10 rounded-3xl">Módulo de Uniformes mantido para gerenciamento individual.</p>
                    </div>
                 )}

                 <div className="flex gap-4 pt-6 mt-6 border-t">
                    <button type="button" onClick={resetEmployeeForm} className="flex-1 py-4 font-black uppercase text-xs text-slate-400">Cancelar</button>
                    <button type="submit" className="flex-1 py-4 rounded-[1.5rem] font-black uppercase text-xs text-white shadow-xl" style={{ backgroundColor: theme.primary }}>Confirmar Cadastro</button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default EmployeesView;

import React, { useState, useMemo } from 'react';
import { Employee, HotelTheme, Sector, UniformItem } from '../types';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Building2,
  X,
  Plus,
  Clock,
  AlertTriangle,
  CheckCircle2,
  Layers,
  ChevronLeft,
  Shirt,
  Edit2,
  Package,
  Info,
  Calendar as CalendarIcon,
  Filter,
  User as UserIcon,
  ChevronRight,
  Printer
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee) => void;
  onDelete: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [editingSector, setEditingSector] = useState<Sector | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'LIST' | 'SCALE'>('LIST');
  const [activeFormTab, setActiveFormTab] = useState<'DADOS' | 'ESCALA' | 'UNIFORMES'>('DADOS');

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [fixedDayOff, setFixedDayOff] = useState('Segunda-feira');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Form State Sector
  const [sectorName, setSectorName] = useState('');
  const [standardUniforms, setStandardUniforms] = useState<UniformItem[]>([]);

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setSalary('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setUniforms([]); setScheduleType('6x1'); setShiftType('Par');
    setWorkingHours('08:00 - 16:20'); setFixedDayOff('Segunda-feira');
    setSundayOffs([]); setVacationStatus('Pendente');
    setIsAddingEmployee(false); setEditingEmployee(null); setActiveFormTab('DADOS');
  };

  const resetSectorForm = () => {
    setSectorName(''); setStandardUniforms([]);
    setIsAddingSector(false); setEditingSector(null);
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name || ''); setRole(emp.role || ''); setGender(emp.gender || 'M');
    setContact(emp.contact || ''); setStartDate(emp.startDate || ''); setSalary((emp.salary || 0).toString());
    setUniforms(emp.uniforms || []); setScheduleType(emp.scheduleType || '6x1');
    setShiftType(emp.shiftType || 'Par'); setWorkingHours(emp.workingHours || '');
    setFixedDayOff(emp.fixedDayOff || 'Segunda-feira');
    setSundayOffs(emp.sundayOffs || []); setVacationStatus(emp.vacationStatus || 'Pendente');
    setIsAddingEmployee(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', role: role || 'Cargo', gender, contact, startDate,
      salary: parseFloat(salary) || 0, department: sectors.find(s => s.id === selectedSectorId)?.name || '',
      sectorId: selectedSectorId!, status: 'Ativo', scheduleType, shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours, fixedDayOff, sundayOffs, weeklyDayOff: fixedDayOff, monthlySundayOff: '', vacationStatus, uniforms
    };
    onSave(newEmp);
    resetEmployeeForm();
  };

  const handleSaveSectorSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!sectorName) return;
    onSaveSector({ id: editingSector?.id || Date.now().toString(), name: sectorName, standardUniform: standardUniforms });
    resetSectorForm();
  };

  const filteredEmployees = employees.filter(e => 
    e.sectorId === selectedSectorId && 
    (e.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  // Escala Logic
  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getDayName = (year: number, month: number, day: number) => {
    const date = new Date(year, month, day);
    return date.toLocaleDateString('pt-BR', { weekday: 'long' });
  };

  const daysArray = useMemo(() => {
    const now = new Date();
    const days = getDaysInMonth(now.getFullYear(), now.getMonth());
    return Array.from({ length: days }, (_, i) => ({
      day: i + 1,
      name: getDayName(now.getFullYear(), now.getMonth(), i + 1),
      isSunday: new Date(now.getFullYear(), now.getMonth(), i + 1).getDay() === 0
    }));
  }, []);

  const getSundayIndex = (day: number) => {
    const now = new Date();
    let count = 0;
    for(let i = 1; i <= day; i++) {
       if(new Date(now.getFullYear(), now.getMonth(), i).getDay() === 0) count++;
    }
    return count;
  };

  if (!selectedSectorId) {
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
