                      <div className="border border-slate-300 p-2 font-black text-center text-amber-500">D</div>
                      <div className="border border-slate-300 p-2 pl-4 uppercase font-bold text-slate-600 bg-white">DOMINGO (FOLGA)</div>
                   </div>
                </div>
                <div className="space-y-3">
                   <h5 className="font-black text-slate-800 uppercase text-xs mb-2 border-b-2 border-slate-900 inline-block tracking-tight">OBSERVAÇÕES GERAIS:</h5>
                   <div className="border border-slate-300 rounded-lg h-28 p-4 bg-slate-50 text-slate-400 italic uppercase font-bold text-[9px] shadow-inner">
                      Utilize este espaço para anotações manuais após a impressão ou notas internas da gerência...
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}

