    setContact(emp.contact || ''); setStartDate(emp.startDate || ''); setSalary((emp.salary || 0).toString());
    setUniforms(emp.uniforms || []); setScheduleType(emp.scheduleType || '6x1');
    setShiftType(emp.shiftType || 'Par'); setWorkingHours(emp.workingHours || '');
    setFixedDayOff(emp.fixedDayOff || 'Segunda-feira');
    setSundayOffs(emp.sundayOffs || []); setVacationStatus(emp.vacationStatus || 'Pendente');
    setIsAddingEmployee(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', role: role || 'Cargo', gender, contact, startDate,
      salary: parseFloat(salary) || 0, department: sectors.find(s => s.id === selectedSectorId)?.name || '',
      sectorId: selectedSectorId!, status: 'Ativo', scheduleType, shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours, fixedDayOff, sundayOffs, weeklyDayOff: fixedDayOff, monthlySundayOff: '', vacationStatus, uniforms
    };
    onSave(newEmp);
    resetEmployeeForm();
  };

  const filteredEmployees = employees.filter(e => 
    e.sectorId === selectedSectorId && 
    (e.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  // Escala Logic
  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getDayName = (year: number, month: number, day: number) => {
    const date = new Date(year, month, day);
    return date.toLocaleDateString('pt-BR', { weekday: 'long' });
  };

  const daysArray = useMemo(() => {
    const now = new Date();
    const days = getDaysInMonth(now.getFullYear(), now.getMonth());
    return Array.from({ length: days }, (_, i) => ({
      day: i + 1,
      name: getDayName(now.getFullYear(), now.getMonth(), i + 1),
      isSunday: new Date(now.getFullYear(), now.getMonth(), i + 1).getDay() === 0
    }));
  }, []);

  const getSundayIndex = (day: number) => {
    const now = new Date();
    let count = 0;
    for(let i = 1; i <= day; i++) {
       if(new Date(now.getFullYear(), now.getMonth(), i).getDay() === 0) count++;
    }
    return count;
