                <tbody>
                   {filteredEmployees.map(emp => (
                      <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                         <td className="border border-slate-400 p-2 font-bold uppercase text-slate-700 bg-slate-50/30">{emp.name || 'Sem Nome'}</td>
                         <td className="border border-slate-400 p-2 text-center font-bold text-slate-500">{emp.workingHours}</td>
                         {daysArray.map(d => {
                            let content = '';
                            const empFixedDayOff = emp.fixedDayOff || '';
                            const isFixedOff = d.name.toLowerCase() === empFixedDayOff.toLowerCase();
                            const isSundayOff = d.isSunday && (emp.sundayOffs || []).includes(getSundayIndex(d.day));

                            let textColor = 'text-slate-800';
                            let bgColor = '';

                            if(isSundayOff) {
                               content = 'D';
                               textColor = 'text-amber-500';
                            } else if(isFixedOff) {
                               content = 'F';
                               textColor = 'text-blue-500';
                            } else if(d.isSunday) {
                               bgColor = 'bg-slate-100'; // Coluna de domingo cinza sólido
                            }

                            return (
                               <td key={d.day} className={`border border-slate-400 p-1 text-center font-black ${bgColor} ${textColor} transition-colors`}>
                                  {content}
                                </td>
                            );
                         })}
                      </tr>
                   ))}
                </tbody>
             </table>
          </div>
        </div>
      )}
    </div>
  );
};

