  APARTMENTS = 'APARTMENTS',
  BUDGETS = 'BUDGETS',
  SETTINGS = 'SETTINGS',
  EMPLOYEES = 'EMPLOYEES',
  INVENTORY = 'INVENTORY',
  REPORTS = 'REPORTS'
}

