interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  extras: ExtraLabor[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee) => void;
  onDelete: (id: string) => void;
  onSaveExtra: (extra: ExtraLabor) => void;
  onDeleteExtra: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  extras,
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveExtra,
  onDeleteExtra,
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [isAddingExtra, setIsAddingExtra] = useState(false);
  const [editingExtra, setEditingExtra] = useState<ExtraLabor | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'LIST' | 'SCALE' | 'TODAY' | 'EXTRAS'>('LIST');
  const [activeFormTab, setActiveFormTab] = useState<'DADOS' | 'ESCALA' | 'UNIFORMES'>('DADOS');

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [fixedDayOff, setFixedDayOff] = useState('Segunda-feira');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Form State Extra
  const [extraName, setExtraName] = useState('');
  const [extraPhone, setExtraPhone] = useState('');
  const [extraAvailability, setExtraAvailability] = useState(10);
  const [extraService, setExtraService] = useState(10);

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setSalary('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setUniforms([]); setScheduleType('6x1'); setShiftType('Par');
    setWorkingHours('08:00 - 16:20'); setFixedDayOff('Segunda-feira');
    setSundayOffs([]); setVacationStatus('Pendente');
    setIsAddingEmployee(false); setEditingEmployee(null); setActiveFormTab('DADOS');
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name || ''); setRole(emp.role || ''); setGender(emp.gender || 'M');
    setContact(emp.contact || ''); setStartDate(emp.startDate || ''); setSalary((emp.salary || 0).toString());
    setUniforms(emp.uniforms || []); setScheduleType(emp.scheduleType || '6x1');
    setShiftType(emp.shiftType || 'Par'); setWorkingHours(emp.workingHours || '');
    setFixedDayOff(emp.fixedDayOff || 'Segunda-feira');
    setSundayOffs(emp.sundayOffs || []); setVacationStatus(emp.vacationStatus || 'Pendente');
    setIsAddingEmployee(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEmp: Employee = {
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', role: role || 'Cargo', gender, contact, startDate,
      salary: parseFloat(salary) || 0, department: sectors.find(s => s.id === selectedSectorId)?.name || '',
      sectorId: selectedSectorId!, status: 'Ativo', scheduleType, shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours, fixedDayOff, sundayOffs, weeklyDayOff: fixedDayOff, monthlySundayOff: '', vacationStatus, uniforms
    };
    onSave(newEmp);
    resetEmployeeForm();
  };

  const resetExtraForm = () => {
    setExtraName(''); setExtraPhone(''); setExtraAvailability(10); setExtraService(10);
    setEditingExtra(null); setIsAddingExtra(false);
  };

  const handleSaveExtraSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId) return;
    onSaveExtra({
      id: editingExtra?.id || Date.now().toString(),
      name: extraName,
      phone: extraPhone,
      availability: extraAvailability,
      serviceQuality: extraService,
      sectorId: selectedSectorId
    });
    resetExtraForm();
  };

  const filteredEmployees = employees.filter(e => 
    e.sectorId === selectedSectorId && 
    (e.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const sectorExtras = extras.filter(e => e.sectorId === selectedSectorId);

  const currentSector = sectors.find(s => s.id === selectedSectorId);

  // Escala Logic
  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getDayName = (year: number, month: number, day: number) => {
    const date = new Date(year, month, day);
    return date.toLocaleDateString('pt-BR', { weekday: 'long' });
  };

  const daysArray = useMemo(() => {
    const now = new Date();
    const days = getDaysInMonth(now.getFullYear(), now.getMonth());
    return Array.from({ length: days }, (_, i) => ({
      day: i + 1,
      name: getDayName(now.getFullYear(), now.getMonth(), i + 1),
      isSunday: new Date(now.getFullYear(), now.getMonth(), i + 1).getDay() === 0
    }));
  }, []);

  const getSundayIndex = (day: number) => {
    const now = new Date();
    let count = 0;
    for(let i = 1; i <= day; i++) {
       if(new Date(now.getFullYear(), now.getMonth(), i).getDay() === 0) count++;
    }
    return count;
  };

  const todayInfo = useMemo(() => {
    const now = new Date();
    return {
      weekday: now.toLocaleDateString('pt-BR', { weekday: 'long' }),
      isSunday: now.getDay() === 0,
      sundayIdx: getSundayIndex(now.getDate()),
      formatted: now.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long' })
    };
  }, []);

  const scheduledToday = useMemo(() => {
    return filteredEmployees.filter(emp => {
      const isFixedOff = emp.fixedDayOff?.toLowerCase() === todayInfo.weekday.toLowerCase();
      const isSundayOff = todayInfo.isSunday && (emp.sundayOffs || []).includes(todayInfo.sundayIdx);
      return !isFixedOff && !isSundayOff;
    });
  }, [filteredEmployees, todayInfo]);

  if (!selectedSectorId) {
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="flex justify-between items-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Selecione o Setor</p>
          <button onClick={() => setIsAddingSector(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
            <Plus size={18} /> <span>Novo Setor</span>
          </button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {sectors.map((sec) => (
            <div key={sec.id} className="relative group">
              <button onClick={() => onSelectSector(sec.id)} className="w-full bg-white h-48 rounded-[2.5rem] shadow-sm hover:shadow-xl transition-all border border-slate-50 flex flex-col items-center justify-center overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1.5" style={{ backgroundColor: theme.primary }}></div>
                <div className="p-5 rounded-2xl mb-3 bg-slate-50 text-slate-400 group-hover:scale-110 transition-transform">
                  <Building2 size={32} />
                </div>
                <h3 className="text-xl font-black text-slate-800">{sec.name}</h3>
                <p className="text-slate-400 text-[10px] font-black uppercase mt-1">
                  {employees.filter(e => e.sectorId === sec.id).length} Colaboradores
                </p>
              </button>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-3">
          <button onClick={() => onSelectSector(null)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-slate-600 transition-colors">
            <ChevronLeft size={20} />
          </button>
          <div>
            <h2 className="text-xl font-black text-slate-800 uppercase tracking-tighter">{currentSector?.name}</h2>
            <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">{filteredEmployees.length} Colaboradores</p>
          </div>
        </div>

        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100 overflow-x-auto">
          <button onClick={() => setViewMode('LIST')} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${viewMode === 'LIST' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Listagem</button>
          <button onClick={() => setViewMode('TODAY')} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${viewMode === 'TODAY' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Hoje</button>
          <button onClick={() => setViewMode('SCALE')} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${viewMode === 'SCALE' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Escala</button>
          <button onClick={() => setViewMode('EXTRAS')} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${viewMode === 'EXTRAS' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}>Extras</button>
        </div>

        <button onClick={() => setIsAddingEmployee(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
          <UserPlus size={18} /> <span className="hidden sm:inline">Novo</span>
        </button>
      </div>

      {viewMode === 'LIST' && (
        <div className="space-y-4">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <input type="text" placeholder="Buscar colaborador..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-3 rounded-xl border border-slate-100 text-sm font-bold bg-white" />
          </div>

          <div className="grid grid-cols-1 gap-4">
            {filteredEmployees.map(emp => (
              <div key={emp.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row items-center gap-6 group hover:border-blue-200 transition-all">
                <div className="flex items-center space-x-4 flex-1">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-md ${emp.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                    {(emp.name || 'S')[0]}
                  </div>
                  <div>
                    <h4 className="font-black text-slate-800">{emp.name || 'Sem Nome'}</h4>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{emp.role} • Folga: {emp.fixedDayOff}</p>
                  </div>
                </div>
                <div className="flex gap-4 items-center">
                  <div className="text-right">
                    <p className="text-[8px] font-black text-slate-300 uppercase">Status</p>
                    <span className="text-[9px] font-black text-emerald-500 uppercase flex items-center"><CheckCircle2 size={10} className="mr-1"/> Ativo</span>
                  </div>
                  <div className="flex space-x-2">
                    <button onClick={() => handleEditEmployee(emp)} className="p-3 bg-slate-50 text-slate-400 hover:text-blue-500 rounded-xl transition-all"><Edit2 size={18}/></button>
                    <button onClick={() => onDelete(emp.id)} className="p-3 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-xl transition-all"><Trash2 size={18}/></button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {viewMode === 'TODAY' && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm animate-in fade-in">
           <div className="flex items-center justify-between mb-8">
              <div className="flex items-center space-x-4">
                 <div className="p-4 bg-emerald-50 text-emerald-500 rounded-2xl"><CalendarDays size={24}/></div>
                 <div>
                    <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter">Escalados Hoje</h3>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{todayInfo.formatted} • {todayInfo.weekday}</p>
                 </div>
              </div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {scheduledToday.map(emp => (
                <div key={emp.id} className="p-5 bg-slate-50 rounded-2xl flex items-center space-x-4">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-white ${emp.gender === 'F' ? 'bg-rose-400' : 'bg-blue-400'}`}>
                    {emp.name[0]}
                  </div>
                  <div>
                    <p className="text-xs font-black text-slate-800 uppercase">{emp.name}</p>
                    <p className="text-[9px] font-bold text-slate-400 uppercase">{emp.role} • {emp.workingHours}</p>
                  </div>
                </div>
              ))}
              {scheduledToday.length === 0 && <p className="col-span-full py-10 text-center text-slate-400 italic font-bold">Ninguém escalado hoje.</p>}
           </div>
        </div>
      )}

      {viewMode === 'SCALE' && (
        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-xl overflow-hidden animate-in zoom-in-95">
          <div className="p-8 border-b bg-slate-50/50 flex justify-between items-center">
             <div>
                <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter">ESCALA {currentSector?.name}</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{new Date().toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}</p>
             </div>
             <button onClick={() => window.print()} className="p-3 bg-white rounded-xl border text-slate-400 hover:text-slate-900 transition-all"><Printer size={20}/></button>
          </div>
          <div className="overflow-x-auto p-4 md:p-8">
             <table className="w-full border-collapse border border-slate-400 text-[10px] shadow-sm">
                <thead>
                   <tr>
                      <th className="border border-slate-500 p-2 text-left min-w-[200px] uppercase font-black bg-slate-100 text-slate-700">COLABORADOR</th>
                      {daysArray.map(d => (
                         <th key={d.day} className={`border border-slate-500 p-1 text-center min-w-[30px] font-black ${d.isSunday ? 'bg-slate-200' : 'bg-slate-50'}`}>
                            <div className="text-[7px] uppercase opacity-70 mb-0.5">{d.name.slice(0,3)}</div>
                            <div className="text-slate-800">{d.day}</div>
                         </th>
                      ))}
                   </tr>
                </thead>
                <tbody>
                   {filteredEmployees.map(emp => (
                      <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                         <td className="border border-slate-400 p-2 font-bold uppercase text-slate-700 bg-slate-50/30">{emp.name || 'Sem Nome'}</td>
                         {daysArray.map(d => {
                            let content = '';
                            const isFixedOff = d.name.toLowerCase() === emp.fixedDayOff?.toLowerCase();
                            const isSundayOff = d.isSunday && (emp.sundayOffs || []).includes(getSundayIndex(d.day));

                            if(isSundayOff) content = 'D';
                            else if(isFixedOff) content = 'F';

                            return (
                               <td key={d.day} className={`border border-slate-400 p-1 text-center font-black text-slate-800 ${d.isSunday ? 'bg-slate-100' : ''}`}>
                                  {content}
                                </td>
                            );
                         })}
                      </tr>
                   ))}
                </tbody>
             </table>
          </div>
        </div>
      )}

      {viewMode === 'EXTRAS' && (
        <div className="space-y-6 animate-in fade-in">
           <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter">Extras Disponíveis</h3>
              <button onClick={() => setIsAddingExtra(true)} className="text-white px-6 py-3 rounded-xl font-bold flex items-center space-x-2 shadow-lg" style={{ backgroundColor: theme.primary }}>
                 <Plus size={18}/> <span>Novo Extra</span>
              </button>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {sectorExtras.map(extra => (
                <div key={extra.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm relative group">
                   <div className="absolute top-4 right-4 flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => { setEditingExtra(extra); setExtraName(extra.name); setExtraPhone(extra.phone); setExtraAvailability(extra.availability); setExtraService(extra.serviceQuality); setIsAddingExtra(true); }} className="p-2 text-slate-300 hover:text-blue-500"><Edit2 size={16}/></button>
                      <button onClick={() => onDeleteExtra(extra.id)} className="p-2 text-slate-300 hover:text-rose-500"><Trash2 size={16}/></button>
                   </div>
                   <div className="flex items-center space-x-4 mb-4">
                      <div className="p-4 bg-slate-50 text-slate-400 rounded-2xl"><UserCheck size={24}/></div>
                      <div>
                         <p className="font-black text-slate-800 text-lg leading-none">{extra.name}</p>
                         <p className="text-[10px] font-bold text-slate-400 uppercase flex items-center mt-1"><Phone size={10} className="mr-1"/> {extra.phone}</p>
                      </div>
                   </div>
                   <div className="grid grid-cols-2 gap-4 pt-4 border-t border-slate-50">
                      <div className="text-center">
                         <p className="text-[8px] font-black text-slate-300 uppercase mb-1">Disponibilidade</p>
                         <div className="flex items-center justify-center space-x-1">
                            <Star size={12} className="text-amber-400 fill-amber-400"/>
                            <span className="font-black text-slate-800">{extra.availability}/10</span>
                         </div>
                      </div>
                      <div className="text-center border-l border-slate-50">
                         <p className="text-[8px] font-black text-slate-300 uppercase mb-1">Qualidade Serviço</p>
                         <div className="flex items-center justify-center space-x-1">
                            <Star size={12} className="text-blue-400 fill-blue-400"/>
                            <span className="font-black text-slate-800">{extra.serviceQuality}/10</span>
                         </div>
                      </div>
                   </div>
                </div>
              ))}
              {sectorExtras.length === 0 && <p className="col-span-full py-20 text-center text-slate-300 italic font-bold border-2 border-dashed rounded-[3rem]">Nenhum extra cadastrado neste setor.</p>}
           </div>
        </div>
      )}

      {/* Modal Cadastro/Edição Colaborador */}
      {isAddingEmployee && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-3xl rounded-[3rem] shadow-2xl max-h-[90vh] overflow-hidden flex flex-col animate-in zoom-in duration-300">
              <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
                 <div>
                    <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{editingEmployee ? 'Editar' : 'Novo'} Colaborador</h2>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{currentSector?.name}</p>
                 </div>
                 <button onClick={resetEmployeeForm} className="p-2 text-slate-300 hover:text-slate-900 transition-all"><X size={32}/></button>
              </div>

              <div className="flex bg-slate-100 p-1.5 mx-8 mt-6 rounded-2xl border">
                 <button onClick={() => setActiveFormTab('DADOS')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'DADOS' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Dados Pessoais</button>
                 <button onClick={() => setActiveFormTab('ESCALA')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'ESCALA' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Escala & Folgas</button>
                 <button onClick={() => setActiveFormTab('UNIFORMES')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeFormTab === 'UNIFORMES' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400'}`}>Uniformes</button>
              </div>

              <form onSubmit={handleSaveEmployeeSubmit} className="p-8 flex-1 overflow-y-auto space-y-8">
                 {activeFormTab === 'DADOS' && (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-left-4">
                       <div className="col-span-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Nome Completo</label>
                          <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" required />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Gênero (Regra CLT)</label>
                          <div className="grid grid-cols-2 gap-2">
                             <button type="button" onClick={() => setGender('M')} className={`py-3 rounded-xl border-2 font-black text-xs ${gender === 'M' ? 'bg-blue-500 border-blue-500 text-white' : 'bg-white'}`}>HOMEM</button>
                             <button type="button" onClick={() => setGender('F')} className={`py-3 rounded-xl border-2 font-black text-xs ${gender === 'F' ? 'bg-rose-500 border-rose-500 text-white' : 'bg-white'}`}>MULHER</button>
                          </div>
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Cargo / Função</label>
                          <input type="text" value={role} onChange={e => setRole(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" required />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Contato</label>
                          <input type="text" value={contact} onChange={e => setContact(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                       </div>
                       <div>
                          <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Salário Base (R$)</label>
                          <input type="number" value={salary} onChange={e => setSalary(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                       </div>
                    </div>
                 )}

                 {activeFormTab === 'ESCALA' && (
                    <div className="space-y-8 animate-in slide-in-from-right-4">
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                             <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Folga Fixa (Semanal)</label>
                             <select value={fixedDayOff} onChange={e => setFixedDayOff(e.target.value)} className="w-full px-5 py-4 rounded-2xl border-2 font-bold bg-white text-slate-800">
                                {['Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado'].map(d => <option key={d} value={d}>{d}</option>)}
                             </select>
                          </div>
                          <div>
                             <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Horário de Trabalho</label>
                             <input type="text" value={workingHours} onChange={e => setWorkingHours(e.target.value)} placeholder="08:00 - 16:20" className="w-full px-5 py-4 rounded-2xl border-2 font-bold text-slate-800" />
                          </div>
                       </div>
                       <div className="p-6 bg-slate-50 rounded-3xl border border-slate-200">
                          <label className="text-[10px] font-black text-slate-500 uppercase mb-4 block flex items-center">
                             <CalendarIcon size={14} className="mr-2"/> Domingos de Folga no Mês
                          </label>
                          <div className="grid grid-cols-5 gap-3">
                             {[1, 2, 3, 4, 5].map(num => (
                                <button
                                   key={num}
                                   type="button"
                                   onClick={() => {
                                      if(sundayOffs.includes(num)) setSundayOffs(sundayOffs.filter(n => n !== num));
                                      else setSundayOffs([...sundayOffs, num]);
                                   }}
                                   className={`p-4 rounded-2xl border-2 font-black text-xs transition-all ${sundayOffs.includes(num) ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white text-slate-400'}`}
                                >
                                   {num}º D
                                </button>
                             ))}
                          </div>
                       </div>
                    </div>
                 )}

                 <div className="flex gap-4 pt-6 mt-6 border-t">
                    <button type="button" onClick={resetEmployeeForm} className="flex-1 py-4 font-black uppercase text-xs text-slate-400">Cancelar</button>
                    <button type="submit" className="flex-1 py-4 rounded-[1.5rem] font-black uppercase text-xs text-white shadow-xl" style={{ backgroundColor: theme.primary }}>Confirmar Cadastro</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {/* Modal Cadastro/Edição Extra */}
      {isAddingExtra && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[3rem] shadow-2xl animate-in zoom-in duration-300 overflow-hidden">
              <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
                 <h2 className="text-xl font-black text-slate-800 uppercase">Novo Extra - {currentSector?.name}</h2>
                 <button onClick={resetExtraForm} className="text-slate-300 hover:text-slate-900"><X size={32}/></button>
              </div>
              <form onSubmit={handleSaveExtraSubmit} className="p-8 space-y-6">
                 <div className="space-y-4">
                    <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Nome do Extra</label>
                       <input type="text" value={extraName} onChange={e => setExtraName(e.target.value)} className="w-full px-5 py-3 rounded-2xl border-2 font-bold text-slate-800" required />
                    </div>
                    <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Telefone</label>
                       <input type="text" value={extraPhone} onChange={e => setExtraPhone(e.target.value)} className="w-full px-5 py-3 rounded-2xl border-2 font-bold text-slate-800" placeholder="(00) 00000-0000" />
                    </div>

                    <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block">Disponibilidade (0 a 10)</label>
                       <div className="flex flex-wrap gap-2">
                          {[...Array(11)].map((_, i) => (
                             <button key={i} type="button" onClick={() => setExtraAvailability(i)} className={`w-8 h-8 rounded-lg font-black text-xs transition-all ${extraAvailability === i ? 'bg-amber-500 text-white shadow-md' : 'bg-slate-50 text-slate-400 border border-slate-100'}`}>
                                {i}
                             </button>
                          ))}
                       </div>
                    </div>

                    <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase mb-3 block">Qualidade de Serviço (0 a 10)</label>
                       <div className="flex flex-wrap gap-2">
                          {[...Array(11)].map((_, i) => (
                             <button key={i} type="button" onClick={() => setExtraService(i)} className={`w-8 h-8 rounded-lg font-black text-xs transition-all ${extraService === i ? 'bg-blue-500 text-white shadow-md' : 'bg-slate-50 text-slate-400 border border-slate-100'}`}>
                                {i}
                             </button>
                          ))}
                       </div>
                    </div>
                 </div>
                 <button type="submit" className="w-full py-4 text-white rounded-[1.5rem] font-black text-xs uppercase shadow-xl" style={{ backgroundColor: theme.primary }}>Salvar Extra</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default EmployeesView;

import React, { useState, useMemo, useEffect } from 'react';
import { Employee, HotelTheme, Sector, UniformItem, ExtraLabor } from '../types';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Building2,
  X,
  Plus,
  Clock,
  AlertTriangle,
  CheckCircle2,
  ChevronLeft,
  Edit2,
  Calendar as CalendarIcon,
  User as UserIcon,
  Printer,
  CalendarDays,
  Phone,
  Star,
  UserCheck,
  Award,
  Zap
} from 'lucide-react';

interface EmployeesViewProps {
  employees: Employee[];
  sectors: Sector[];
  extras: ExtraLabor[];
  selectedSectorId: string | null;
  onSelectSector: (id: string | null) => void;
  theme: HotelTheme;
  onSave: (employee: Employee) => void;
  onDelete: (id: string) => void;
  onSaveExtra: (extra: ExtraLabor) => void;
  onDeleteExtra: (id: string) => void;
  onSaveSector: (sector: Sector) => void;
  onDeleteSector: (id: string) => void;
}

const EmployeesView: React.FC<EmployeesViewProps> = ({ 
  employees, 
  sectors, 
  extras,
  selectedSectorId, 
  onSelectSector, 
  theme, 
  onSave, 
  onDelete, 
  onSaveExtra,
  onDeleteExtra,
  onSaveSector, 
  onDeleteSector 
}) => {
  const [isAddingEmployee, setIsAddingEmployee] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [isAddingSector, setIsAddingSector] = useState(false);
  const [isAddingExtra, setIsAddingExtra] = useState(false);
  const [editingExtra, setEditingExtra] = useState<ExtraLabor | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'LIST' | 'SCALE' | 'TODAY' | 'EXTRAS'>('LIST');
  const [activeFormTab, setActiveFormTab] = useState<'DADOS' | 'ESCALA' | 'UNIFORMES'>('DADOS');

  // Form State Employee
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [gender, setGender] = useState<'M' | 'F'>('M');
  const [contact, setContact] = useState('');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [salary, setSalary] = useState('');
  const [uniforms, setUniforms] = useState<UniformItem[]>([]);
  const [scheduleType, setScheduleType] = useState<'6x1' | '12x36' | 'Intermitente'>('6x1');
  const [shiftType, setShiftType] = useState<'Par' | 'Ímpar'>('Par');
  const [workingHours, setWorkingHours] = useState('08:00 - 16:20');
  const [fixedDayOff, setFixedDayOff] = useState('Segunda-feira');
  const [sundayOffs, setSundayOffs] = useState<number[]>([]);
  const [vacationStatus, setVacationStatus] = useState<'Pendente' | 'Concedida'>('Pendente');

  // Form State Extra
  const [extraName, setExtraName] = useState('');
  const [extraPhone, setExtraPhone] = useState('');
  const [extraAvailability, setExtraAvailability] = useState(10);
  const [extraService, setExtraService] = useState(10);

  const resetEmployeeForm = () => {
    setName(''); setRole(''); setGender('M'); setContact(''); setSalary('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setUniforms([]); setScheduleType('6x1'); setShiftType('Par');
    setWorkingHours('08:00 - 16:20'); setFixedDayOff('Segunda-feira');
    setSundayOffs([]); setVacationStatus('Pendente');
    setIsAddingEmployee(false); setEditingEmployee(null); setActiveFormTab('DADOS');
  };

  const handleEditEmployee = (emp: Employee) => {
    setEditingEmployee(emp);
    setName(emp.name || ''); 
    setRole(emp.role || ''); 
    setGender(emp.gender || 'M');
    setContact(emp.contact || ''); 
    setStartDate(emp.startDate || ''); 
    setSalary((emp.salary || 0).toString());
    setUniforms(emp.uniforms || []); 
    setScheduleType(emp.scheduleType || '6x1');
    setShiftType(emp.shiftType || 'Par'); 
    setWorkingHours(emp.workingHours || '');
    setFixedDayOff(emp.fixedDayOff || 'Segunda-feira');
    setSundayOffs(emp.sundayOffs || []); 
    setVacationStatus(emp.vacationStatus || 'Pendente');
    setIsAddingEmployee(true);
  };

  const handleSaveEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEmp: Employee = {
      ...editingEmployee,
      id: editingEmployee?.id || Date.now().toString(),
      name: name || 'Sem Nome', 
      role: role || 'Cargo', 
      gender, 
      contact, 
      startDate,
      salary: parseFloat(salary) || 0, 
      department: currentSector?.name || '',
      sectorId: selectedSectorId!, 
      status: editingEmployee?.status || 'Ativo', 
      scheduleType, 
      shiftType: scheduleType === '12x36' ? shiftType : undefined,
      workingHours, 
      fixedDayOff, 
      sundayOffs, 
      weeklyDayOff: fixedDayOff, 
      monthlySundayOff: '', 
      vacationStatus, 
      uniforms
    };
    onSave(newEmp);
    resetEmployeeForm();
  };

  const resetExtraForm = () => {
    setExtraName(''); setExtraPhone(''); setExtraAvailability(10); setExtraService(10);
    setEditingExtra(null); setIsAddingExtra(false);
  };

  const handleSaveExtraSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSectorId) return;
    onSaveExtra({
      id: editingExtra?.id || Date.now().toString(),
      name: extraName,
      phone: extraPhone,
      availability: extraAvailability,
      serviceQuality: extraService,
      sectorId: selectedSectorId
    });
    resetExtraForm();
  };

  const filteredEmployees = employees.filter(e => 
    e.sectorId === selectedSectorId && 
    (e.name || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const sectorExtras = extras.filter(e => e.sectorId === selectedSectorId);
  const currentSector = sectors.find(s => s.id === selectedSectorId);

  const daysArray = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    const days = new Date(year, month + 1, 0).getDate();
    return Array.from({ length: days }, (_, i) => ({
      day: i + 1,
      name: new Date(year, month, i + 1).toLocaleDateString('pt-BR', { weekday: 'long' }),
      isSunday: new Date(year, month, i + 1).getDay() === 0
    }));
  }, []);

  const getSundayIndex = (day: number) => {
    const now = new Date();
    let count = 0;
    for(let i = 1; i <= day; i++) {
       if(new Date(now.getFullYear(), now.getMonth(), i).getDay() === 0) count++;
    }
    return count;
  };

  const todayInfo = useMemo(() => {
    const now = new Date();
    return {
      weekday: now.toLocaleDateString('pt-BR', { weekday: 'long' }),
      isSunday: now.getDay() === 0,
      sundayIdx: getSundayIndex(now.getDate()),
      formatted: now.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long' })
    };
  }, []);

  const scheduledToday = useMemo(() => {
    return filteredEmployees.filter(emp => {
      const isFixedOff = emp.fixedDayOff?.toLowerCase() === todayInfo.weekday.toLowerCase();
      const isSundayOff = todayInfo.isSunday && (emp.sundayOffs || []).includes(todayInfo.sundayIdx);
      return !isFixedOff && !isSundayOff;
    });
