      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    const targetHotel = hotelOverride || state.currentHotel;
    setIsRefreshing(true);
    try {
      const fetchUrl = `${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&nocache=${Date.now()}`;
      const response = await fetch(fetchUrl);
      const result = await response.json();

      if (result && result.status === 'success') {
        const incomingData = result.data;
        // Normalização omitida para brevidade (mantendo a lógica do arquivo anterior)
        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...incomingData
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
      }
    } catch (error) { 
      console.warn(`Erro ao carregar ${targetHotel}:`, error);
    } finally { 
      setIsRefreshing(false); 
    }
  }, [state.currentHotel]);

  useEffect(() => {
    if (initialSyncRef.current) return;
    initialSyncRef.current = true;
    loadDataFromSheet(state.currentHotel);
  }, [loadDataFromSheet, state.currentHotel]);

  useEffect(() => { 
    localStorage.setItem('hotel_village_state_v40', JSON.stringify(state)); 
  }, [state]);

  const currentHotelData = state.hotels[state.currentHotel];

  const handleLogin = (user: User) => setState(prev => ({ ...prev, currentUser: user }));
  const handleLogout = () => setState(prev => ({ ...prev, currentUser: null, currentView: ViewType.DASHBOARD }));
  const handleViewChange = (view: ViewType) => setState(prev => ({ ...prev, currentView: view }));
  const handleHotelChange = (hotel: HotelType) => setState(prev => ({ ...prev, currentHotel: hotel }));

  const handleUpdateOccupancy = (occ: any[]) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], occupancy: occ }
      }
    }));
  };

  const handleUpdateMaidsConfig = (maids: number, max: number) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { 
          ...prev.hotels[prev.currentHotel], 
          config: { ...prev.hotels[prev.currentHotel].config!, maidsPerFloor: maids, maxAptsPerMaid: max }
        }
      }
    }));
  };

  const renderContent = () => {
    // ... manter lógica de apartamento e andar ...
    if (state.selectedApartmentId) return null; // Placeholder para ApartmentDetailView
    if (state.selectedFloor) return null; // Placeholder para FloorDetailView

    switch (state.currentView) {
      case ViewType.DASHBOARD:
        return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
      case ViewType.WEEKLY_SCALE:
        return (
          <WeeklyScaleView 
            occupancy={currentHotelData.occupancy} 
            employees={currentHotelData.employees} 
            extras={currentHotelData.extras} 
            config={currentHotelData.config!} 
            theme={theme} 
            onUpdateOccupancy={handleUpdateOccupancy}
            onUpdateConfig={handleUpdateMaidsConfig}
          />
        );
      case ViewType.EMPLOYEES:
        return <EmployeesView employees={currentHotelData.employees} extras={currentHotelData.extras} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={(id) => setState(prev => ({ ...prev, selectedSectorId: id }))} theme={theme} onSave={() => {}} onDelete={() => {}} onSaveExtra={() => {}} onDeleteExtra={() => {}} onSaveSector={() => {}} onDeleteSector={() => {}} />;
      case ViewType.APARTMENTS:
        return <ApartmentsView onSelectFloor={(floor) => setState(prev => ({ ...prev, selectedFloor: floor }))} theme={theme} hotelName={state.currentHotel} />;
      default:
        return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} />;
    }
  };

  if (!state.currentUser) return <Login onLogin={handleLogin} onFetchHotelData={loadDataFromSheet} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      <Sidebar currentView={state.currentView} onViewChange={handleViewChange} currentHotel={state.currentHotel} onHotelChange={handleHotelChange} onLogout={handleLogout} theme={theme} role={state.currentUser.role} />
      <main className="flex-1 p-4 md:p-8 md:ml-64 mb-20 md:mb-0">
        {renderContent()}
      </main>
      <BottomNav currentView={state.currentView} onViewChange={handleViewChange} theme={theme} role={state.currentUser.role} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Employee, ExtraLabor, HotelTheme, OccupancyDay } from '../types';
import { 
  Calendar, 
  Users, 
  TrendingUp, 
  AlertCircle, 
  CheckCircle2, 
  UserPlus, 
  Settings,
  Star,
  Phone,
  ChevronRight,
  Calculator
} from 'lucide-react';

interface WeeklyScaleViewProps {
  occupancy: OccupancyDay[];
  employees: Employee[];
  extras: ExtraLabor[];
  config: { maidsPerFloor: number; maxAptsPerMaid: number };
  theme: HotelTheme;
  onUpdateOccupancy: (occ: OccupancyDay[]) => void;
  onUpdateConfig: (maids: number, max: number) => void;
}

const WeeklyScaleView: React.FC<WeeklyScaleViewProps> = ({ 
  occupancy, 
  employees, 
  extras, 
  config, 
  theme, 
  onUpdateOccupancy,
  onUpdateConfig
}) => {
  const [showConfig, setShowConfig] = useState(false);

  const weekDays = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];

  // Inicializar dados da semana se estiverem vazios
  const currentWeek = useMemo(() => {
    if (occupancy.length === 7) return occupancy;
    return weekDays.map(day => ({ date: day, checkins: 0, checkouts: 0 }));
  }, [occupancy]);

  const handleArrivalChange = (dayIndex: number, value: number) => {
    const newOcc = [...currentWeek];
    newOcc[dayIndex].checkins = value;
    onUpdateOccupancy(newOcc);
  };

  const getMaidsForDay = (dayName: string) => {
    // Aqui filtraria as camareiras que não estão de folga no dia
    return employees.filter(e => 
      e.sectorId === '2' && // Setor Governança
      e.fixedDayOff !== dayName && 
      e.status === 'Ativo'
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-4">
          <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl shadow-sm"><Calendar size={28}/></div>
          <div>
            <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Escala Inteligente</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Dimensionamento Semanal de Governança</p>
          </div>
        </div>
        <button 
          onClick={() => setShowConfig(!showConfig)}
          className="flex items-center space-x-2 px-6 py-3 bg-slate-100 rounded-xl text-slate-600 font-bold hover:bg-slate-200 transition-all"
        >
          <Settings size={18} />
          <span>Configurações</span>
        </button>
      </div>

      {showConfig && (
        <div className="bg-white p-8 rounded-[2rem] border-2 border-slate-100 shadow-xl animate-in slide-in-from-top-4 space-y-6">
          <h3 className="font-black text-slate-800 flex items-center"><Calculator size={20} className="mr-2"/> Parâmetros de Cálculo</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Camareiras CLT por Andar (Base)</label>
              <div className="flex items-center space-x-4">
                <input 
                  type="range" min="1" max="4" 
                  value={config.maidsPerFloor} 
                  onChange={e => onUpdateConfig(parseInt(e.target.value), config.maxAptsPerMaid)}
                  className="flex-1 accent-blue-600"
                />
                <span className="text-xl font-black text-blue-600">{config.maidsPerFloor}</span>
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Capacidade Máxima de Check-ins p/ Camareira</label>
              <div className="flex items-center space-x-4">
                <input 
                  type="range" min="3" max="10" 
                  value={config.maxAptsPerMaid} 
                  onChange={e => onUpdateConfig(config.maidsPerFloor, parseInt(e.target.value))}
                  className="flex-1 accent-emerald-600"
                />
                <span className="text-xl font-black text-emerald-600">{config.maxAptsPerMaid}</span>
              </div>
            </div>
          </div>
          <p className="text-[9px] text-slate-400 font-bold uppercase italic">* Atualmente configurado para 6 andares fixos.</p>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {currentWeek.map((day, idx) => {
          const arrivals = day.checkins || 0;
          const arrivalsPerFloor = arrivals / 6;
          const arrivalsPerMaid = arrivalsPerFloor / config.maidsPerFloor;
          const isOverloaded = arrivalsPerMaid > config.maxAptsPerMaid;

          // Cálculo de extras necessários:
          // Se 1 camareira faz 6 aptos, e temos 100 checkins totais:
          // Necessário = 100 / 6 = 16.6 camareiras.
          // Temos = MaidsPerFloor (2) * 6 andares = 12 camareiras.
          // Extras = 17 - 12 = 5 extras.
          const totalMaidsNeeded = Math.ceil(arrivals / config.maxAptsPerMaid);
          const currentStaff = config.maidsPerFloor * 6;
          const extrasNeeded = Math.max(0, totalMaidsNeeded - currentStaff);

          // Filtrar extras disponíveis
          const availableExtras = extras
            .filter(ext => ext.availability.includes(day.date))
            .sort((a, b) => b.serviceQuality - a.serviceQuality);

          return (
            <div key={idx} className={`bg-white rounded-[2.5rem] border-2 transition-all overflow-hidden ${isOverloaded ? 'border-rose-100 shadow-rose-100/20' : 'border-slate-50'} shadow-lg`}>
              <div className={`p-6 border-b ${isOverloaded ? 'bg-rose-50/50' : 'bg-slate-50/50'}`}>
                <div className="flex justify-between items-start">
                  <div>
                    <h4 className="font-black text-slate-800 text-lg">{day.date}</h4>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Dimensionamento</p>
                  </div>
                  <div className={`p-2 rounded-xl ${isOverloaded ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                    {isOverloaded ? <AlertCircle size={20}/> : <CheckCircle2 size={20}/>}
                  </div>
                </div>
              </div>

              <div className="p-6 space-y-6">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block tracking-widest">Total de Chegadas</label>
                  <input 
                    type="number" 
                    value={day.checkins || ''} 
                    onChange={e => handleArrivalChange(idx, parseInt(e.target.value) || 0)}
                    className="w-full text-2xl font-black text-slate-800 bg-slate-50 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-400 outline-none transition-all"
                    placeholder="0"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Por Andar</p>
                    <p className="text-lg font-black text-slate-800">{arrivalsPerFloor.toFixed(1)}</p>
                  </div>
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Por Moça</p>
                    <p className={`text-lg font-black ${isOverloaded ? 'text-rose-500' : 'text-slate-800'}`}>
                      {arrivalsPerMaid.toFixed(1)}
                    </p>
                  </div>
                </div>

                {isOverloaded && (
                  <div className="space-y-4 pt-4 border-t border-rose-50 animate-in slide-in-from-bottom-2">
                    <div className="flex items-center justify-between">
                      <p className="text-[10px] font-black text-rose-500 uppercase flex items-center">
                        <UserPlus size={14} className="mr-1"/> Contratar {extrasNeeded} Extras
                      </p>
                    </div>

                    <div className="space-y-2">
                      <p className="text-[8px] font-black text-slate-300 uppercase tracking-widest">Sugestão (Disponíveis):</p>
                      {availableExtras.slice(0, 3).map(ext => (
                        <div key={ext.id} className="flex items-center justify-between p-3 bg-slate-900 rounded-2xl text-white shadow-lg group hover:scale-[1.02] transition-transform cursor-pointer">
                          <div className="flex items-center space-x-3">
                            <div className="w-8 h-8 rounded-xl bg-white/10 flex items-center justify-center text-[10px] font-black">
                              {ext.serviceQuality}
                            </div>
                            <span className="text-[10px] font-black uppercase truncate max-w-[80px]">{ext.name}</span>
                          </div>
                          <ChevronRight size={14} className="text-white/30 group-hover:text-white transition-colors" />
                        </div>
                      ))}
                      {availableExtras.length === 0 && (
                        <p className="text-[9px] text-rose-300 font-bold italic">Nenhum extra disponível para este dia.</p>
                      )}
                    </div>
                  </div>
                )}

                {!isOverloaded && arrivals > 0 && (
                  <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100 text-center">
                    <p className="text-[10px] font-black text-emerald-600 uppercase">Equipe Suporta a Carga</p>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default WeeklyScaleView;

