          onClick={onLogout}
          className="w-full flex items-center space-x-3 text-red-400/70 hover:text-red-400 transition-colors px-2 pt-4 border-t border-slate-800/30"
        >
          <LogOut size={18} />
          <span className="text-sm font-bold">Encerrar Sessão</span>
        </button>
      </div>
    </aside>
  );
};

