import TodayScheduleView from './components/TodayScheduleView';
import Login from './components/Login';

const GLOBAL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyHwnTqgnBMecAsscAIJgpfe7gHPwjWbZ42qbm3EvXvX_oq9WzbrrT99knh7L4wdvDe4g/exec";

const getInitialHotelData = (): HotelData => ({
  apartments: {},
  budgets: [],
  employees: [],
  extras: [],
  inventory: [],
  inventoryHistory: [],
  suppliers: [],
  occupancy: [
    { date: 'Segunda', checkins: 0, checkouts: 0 },
    { date: 'Terça', checkins: 0, checkouts: 0 },
    { date: 'Quarta', checkins: 0, checkouts: 0 },
    { date: 'Quinta', checkins: 0, checkouts: 0 },
    { date: 'Sexta', checkins: 0, checkouts: 0 },
    { date: 'Sábado', checkins: 0, checkouts: 0 },
    { date: 'Domingo', checkins: 0, checkouts: 0 },
  ],
  sectors: [
    { id: '1', name: 'Recepção', standardUniform: [] },
    { id: '2', name: 'Governança', standardUniform: [] },
    { id: '3', name: 'Manutenção', standardUniform: [] },
  ],
  config: {
    showSuppliersTab: true,
    maxAptsPerMaid: 6
  }
});

const App: React.FC = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const initialSyncRef = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('hotel_village_state_v42');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return { ...parsed, currentUser: null };
      } catch (e) {
        console.error("Erro ao carregar estado salvo:", e);
      }
    }
    return {
      currentView: ViewType.DASHBOARD,
      currentHotel: 'VILLAGE',
      hotels: {
        VILLAGE: getInitialHotelData(),
        GOLDEN_PARK: getInitialHotelData(),
        THERMAL_RESORT: getInitialHotelData(),
      },
      selectedFloor: null,
      selectedApartmentId: null,
      selectedSectorId: null,
      integrations: [
        { 
          id: 'global-sync', 
          name: 'Integração Direta Google Sheets & Drive', 
          type: 'Spreadsheet', 
          status: 'Disconnected', 
          lastSync: 0,
          url: GLOBAL_SCRIPT_URL
        },
      ],
      currentUser: null
    };
  });

  const theme: HotelTheme = useMemo(() => {
    switch(state.currentHotel) {
      case 'VILLAGE': return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
      case 'GOLDEN_PARK': return { primary: '#BF984E', secondary: '#A68444', accent: '#A67A44', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#BF984E', '#A68444', '#A67A44', '#A6A6A6'] };
      case 'THERMAL_RESORT': return { primary: '#68A672', secondary: '#4B94F2', accent: '#B49B5D', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#68A672', '#4B94F2', '#B49B5D', '#0D0D0D'] };
      default: return { primary: '#26A6A6', secondary: '#34BFA6', accent: '#29D9A7', bg: '#F8FAFC', text: '#1E293B', chartColors: ['#26A6A6', '#34BFA6', '#29D9A7', '#737373'] };
    }
  }, [state.currentHotel]);

  const loadDataFromSheet = useCallback(async (hotelOverride?: HotelType) => {
    const targetHotel = hotelOverride || state.currentHotel;
    setIsRefreshing(true);
    try {
      const response = await fetch(`${GLOBAL_SCRIPT_URL}?hotel=${targetHotel}&nocache=${Date.now()}`);
      const result = await response.json();

      if (result && result.status === 'success') {
        const incoming = result.data;

        setState(prev => ({
          ...prev,
          hotels: {
            ...prev.hotels,
            [targetHotel]: {
              ...prev.hotels[targetHotel],
              ...incoming,
              occupancy: incoming.occupancy?.length === 7 ? incoming.occupancy : prev.hotels[targetHotel].occupancy,
              config: { ...prev.hotels[targetHotel].config, ...incoming.config }
            }
          },
          integrations: prev.integrations.map(i => i.id === 'global-sync' ? { ...i, lastSync: Date.now(), status: 'Connected' } : i)
        }));
      }
    } catch (error) { 
      console.warn(`Erro ao carregar ${targetHotel}:`, error);
    } finally { 
      setIsRefreshing(false); 
    }
  }, [state.currentHotel]);

  useEffect(() => {
    if (initialSyncRef.current) return;
    initialSyncRef.current = true;
    loadDataFromSheet(state.currentHotel);
  }, [loadDataFromSheet, state.currentHotel]);

  useEffect(() => { 
    localStorage.setItem('hotel_village_state_v42', JSON.stringify(state)); 
  }, [state]);

  const syncToSheet = async (dataType: string, data: any) => {
    try {
      await fetch(GLOBAL_SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors',
        body: JSON.stringify({ hotel: state.currentHotel, dataType, ...data })
      });
    } catch (e) { console.error("Erro na sincronização:", e); }
  };

  const currentHotelData = state.hotels[state.currentHotel];

  const handleUpdateOccupancy = (occ: OccupancyDay[]) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: { ...prev.hotels[prev.currentHotel], occupancy: occ }
      }
    }));
    syncToSheet('OCCUPANCY', { data: occ });
  };

  const handleUpdateConfig = (config: any) => {
    setState(prev => ({
      ...prev,
      hotels: {
        ...prev.hotels,
        [prev.currentHotel]: {
          ...prev.hotels[prev.currentHotel],
          config: { ...prev.hotels[prev.currentHotel].config, ...config }
        }
      }
    }));
    syncToSheet('CONFIG', config);
  };

  const handleHotelChange = (hotel: HotelType) => {
    setState(prev => ({ ...prev, currentHotel: hotel, selectedFloor: null, selectedApartmentId: null }));
    loadDataFromSheet(hotel);
  };

  const renderContent = () => {
    if (state.selectedApartmentId) return <ApartmentDetailView apartment={currentHotelData.apartments[state.selectedApartmentId]} theme={theme} onBack={() => setState(prev => ({ ...prev, selectedApartmentId: null }))} onSave={() => {}} />;
    if (state.selectedFloor) return <FloorDetailView floor={state.selectedFloor} theme={theme} apartments={currentHotelData.apartments} onBack={() => setState(prev => ({ ...prev, selectedFloor: null }))} onSelectApartment={(id) => setState(prev => ({ ...prev, selectedApartmentId: id }))} />;

    switch (state.currentView) {
      case ViewType.DASHBOARD:
        return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} lastSync={state.integrations[0].lastSync} onRefresh={() => loadDataFromSheet()} isRefreshing={isRefreshing} />;
      case ViewType.WEEKLY_SCALE:
        return <WeeklyScaleView occupancy={currentHotelData.occupancy} employees={currentHotelData.employees} extras={currentHotelData.extras} config={currentHotelData.config!} theme={theme} onUpdateOccupancy={handleUpdateOccupancy} />;
      case ViewType.TODAY_SCHEDULE:
        return <TodayScheduleView employees={currentHotelData.employees} theme={theme} />;
      case ViewType.APARTMENTS:
        return <ApartmentsView onSelectFloor={(floor) => setState(prev => ({ ...prev, selectedFloor: floor }))} theme={theme} hotelName={state.currentHotel} />;
      case ViewType.BUDGETS:
        return <BudgetsView budgets={currentHotelData.budgets} theme={theme} onSave={() => {}} onDelete={() => {}} />;
      case ViewType.EMPLOYEES:
        return <EmployeesView employees={currentHotelData.employees} extras={currentHotelData.extras} sectors={currentHotelData.sectors} selectedSectorId={state.selectedSectorId} onSelectSector={(id) => setState(prev => ({ ...prev, selectedSectorId: id }))} theme={theme} onSave={() => {}} onDelete={() => {}} onSaveExtra={() => {}} onDeleteExtra={() => {}} onSaveSector={() => {}} onDeleteSector={() => {}} />;
      case ViewType.INVENTORY:
        return <InventoryView inventory={currentHotelData.inventory} history={currentHotelData.inventoryHistory} suppliers={currentHotelData.suppliers} showSuppliersTab={currentHotelData.config?.showSuppliersTab} theme={theme} onSave={() => {}} onDelete={() => {}} onOperation={() => {}} onSaveSupplier={() => {}} onDeleteSupplier={() => {}} role={state.currentUser?.role} currentUser={state.currentUser?.name} />;
      case ViewType.REPORTS:
        return <ReportsView apartments={currentHotelData.apartments} theme={theme} onSelectApartment={(id) => setState(prev => ({ ...prev, selectedApartmentId: id }))} />;
      case ViewType.SETTINGS:
        return <SettingsView integrations={state.integrations} hotelConfig={currentHotelData.config} onUpdateConfig={handleUpdateConfig} theme={theme} suppliers={currentHotelData.suppliers} onSaveSupplier={() => {}} onDeleteSupplier={() => {}} onUpdate={() => {}} />;
      default:
        return <Dashboard apartments={currentHotelData.apartments} employees={currentHotelData.employees} theme={theme} />;
    }
  };

  if (!state.currentUser) return <Login onLogin={(user) => setState(prev => ({ ...prev, currentUser: user }))} onFetchHotelData={loadDataFromSheet} />;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      <Sidebar currentView={state.currentView} onViewChange={(v) => setState(prev => ({ ...prev, currentView: v, selectedFloor: null, selectedApartmentId: null }))} currentHotel={state.currentHotel} onHotelChange={handleHotelChange} onLogout={() => setState(prev => ({ ...prev, currentUser: null }))} theme={theme} role={state.currentUser.role} />
      <main className="flex-1 p-4 md:p-8 md:ml-64 mb-20 md:mb-0">
        {renderContent()}
      </main>
      <BottomNav currentView={state.currentView} onViewChange={(v) => setState(prev => ({ ...prev, currentView: v, selectedFloor: null, selectedApartmentId: null }))} theme={theme} role={state.currentUser.role} />
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Employee, ExtraLabor, HotelTheme, OccupancyDay } from '../types';
import { 
  Calculator, 
  AlertTriangle, 
  CheckCircle2, 
  UserPlus, 
  ChevronRight,
  TrendingUp,
  Clock,
  Briefcase
} from 'lucide-react';

interface WeeklyScaleViewProps {
  occupancy: OccupancyDay[];
  employees: Employee[];
  extras: ExtraLabor[];
  config: { maxAptsPerMaid: number };
  theme: HotelTheme;
  onUpdateOccupancy: (occ: OccupancyDay[]) => void;
}

const WeeklyScaleView: React.FC<WeeklyScaleViewProps> = ({ 
  occupancy, 
  employees, 
  extras, 
  config, 
  theme, 
  onUpdateOccupancy 
}) => {
  const weekDays = ['Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];

  // Verifica se funcionário trabalha hoje baseado em 6x1 ou 12x36
  const isWorkingToday = (emp: Employee, dayName: string, simulatedDay: number) => {
    if (emp.status === 'Inativo' || emp.scheduleType === 'Intermitente') return false;

    if (emp.scheduleType === '6x1') {
      return emp.fixedDayOff?.toLowerCase() !== dayName.toLowerCase();
    }

    if (emp.scheduleType === '12x36') {
      const isEven = simulatedDay % 2 === 0;
      return emp.shiftType === 'Par' ? isEven : !isEven;
    }
    return true;
  };

  const handleValueChange = (idx: number, val: number) => {
    const newOcc = [...occupancy];
    newOcc[idx].checkins = val;
    onUpdateOccupancy(newOcc);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center space-x-4">
          <div className="p-4 bg-emerald-50 text-emerald-500 rounded-2xl shadow-sm"><Calculator size={28}/></div>
          <div>
            <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Escala Inteligente</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Dimensionamento Governança / 6 Andares</p>
          </div>
        </div>
        <div className="flex bg-slate-50 p-4 rounded-2xl border border-slate-100">
          <div className="text-right">
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Capacidade Alvo</p>
             <p className="text-xs font-black text-slate-700">{config.maxAptsPerMaid} Check-ins / Moça</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {occupancy.map((day, idx) => {
          const simulatedDay = idx + 1;
          const maidsToday = employees.filter(emp => 
            emp.sectorId === '2' && // Governança
            isWorkingToday(emp, day.date, simulatedDay)
          );

          const totalCheckins = day.checkins || 0;
          const perFloor = totalCheckins / 6;
          const maidsPerFloor = maidsToday.length / 6;
          const workload = maidsPerFloor > 0 ? perFloor / maidsPerFloor : totalCheckins > 0 ? 100 : 0;

          const isOverloaded = workload > config.maxAptsPerMaid;

          const availableExtras = extras
            .filter(ext => ext.availability.includes(day.date))
            .sort((a, b) => b.serviceQuality - a.serviceQuality);

          return (
            <div key={idx} className={`bg-white rounded-[2.5rem] border-2 transition-all shadow-lg overflow-hidden ${isOverloaded ? 'border-rose-100' : 'border-slate-50'}`}>
              <div className={`p-6 border-b flex justify-between items-center ${isOverloaded ? 'bg-rose-50/50' : 'bg-slate-50/50'}`}>
                 <div>
                    <h4 className="font-black text-slate-800 text-lg uppercase tracking-tighter">{day.date}</h4>
                    <span className="text-[9px] font-black text-slate-400 uppercase">{maidsToday.length} Moças CLT Ativas</span>
                 </div>
                 {isOverloaded ? <AlertTriangle className="text-rose-500" size={24}/> : <CheckCircle2 className="text-emerald-500" size={24}/>}
              </div>

              <div className="p-6 space-y-6">
                 <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block ml-1 tracking-widest">Previsão de Check-ins</label>
                    <input 
                      type="number" 
                      value={day.checkins || ''} 
                      onChange={e => handleValueChange(idx, parseInt(e.target.value) || 0)}
                      className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xl font-black text-slate-800 outline-none focus:ring-2 focus:ring-blue-400" 
                      placeholder="0"
                    />
                 </div>

                 <div className="grid grid-cols-2 gap-3">
                    <div className="p-3 bg-slate-50 rounded-2xl border border-slate-100 text-center">
                       <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Check-ins / Andar</p>
                       <p className="text-sm font-black text-slate-800">{perFloor.toFixed(1)}</p>
                    </div>
                    <div className={`p-3 rounded-2xl border text-center ${isOverloaded ? 'bg-rose-50 border-rose-100' : 'bg-slate-50 border-slate-100'}`}>
                       <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Check-ins / Moça</p>
                       <p className={`text-sm font-black ${isOverloaded ? 'text-rose-500' : 'text-slate-800'}`}>{workload.toFixed(1)}</p>
                    </div>
                 </div>

                 {isOverloaded && (
                    <div className="space-y-4 pt-4 border-t border-rose-100 animate-in slide-in-from-top-2">
                       <p className="text-[10px] font-black text-rose-500 uppercase flex items-center">
                          <UserPlus size={14} className="mr-2"/> Sugestão de Extras:
                       </p>

                       <div className="space-y-2">
                          {availableExtras.slice(0, 2).map(ext => (
                             <div key={ext.id} className="flex items-center justify-between p-3 bg-slate-900 rounded-2xl text-white shadow-md group cursor-pointer hover:scale-[1.02] transition-transform">
                                <div className="flex items-center space-x-3">
                                   <div className="w-8 h-8 rounded-xl bg-white/10 flex items-center justify-center text-[10px] font-black">
                                      {ext.serviceQuality}
                                   </div>
                                   <span className="text-[9px] font-black uppercase truncate max-w-[80px]">{ext.name}</span>
                                </div>
                                <ChevronRight size={14} className="text-white/40 group-hover:text-white transition-colors"/>
                             </div>
                          ))}
                          {availableExtras.length === 0 && <p className="text-[9px] text-slate-400 font-bold italic">Nenhum extra disponível hoje.</p>}
                       </div>
                    </div>
                 )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default WeeklyScaleView;

import React, { useState } from 'react';
import { Integration, HotelTheme } from '../types';
import { Copy, FileSpreadsheet, XCircle } from 'lucide-react';

interface IntegrationsViewProps {
  integrations: Integration[];
  theme: HotelTheme;
  onUpdate: (integration: Integration) => void;
}

const APPS_SCRIPT_CODE = `/**
 * Google Apps Script para Gestão Hotel Village - V42 (Total Sync)
 * Suporte completo para: Funcionários, Extras, Apartamentos, Ocupação e Configurações.
 */

function doGet(e) {
  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = e.parameter.hotel || 'VILLAGE';
    var result = {
      apartments: {}, employees: [], extras: [], sectors: [], inventory: [], occupancy: [], config: {}
    };

    // 1. Ocupação (Escala Semanal)
    var sheetOcc = ss.getSheetByName('Ocupacao_' + hotel);
    if (sheetOcc) {
      var dO = sheetOcc.getDataRange().getValues();
      for (var o = 1; o < dO.length; o++) {
        result.occupancy.push({ date: dO[o][0], checkins: dO[o][1], checkouts: dO[o][2] });
      }
    }

    // 2. Apartamentos
    var sheetApts = ss.getSheetByName('Apartamentos_' + hotel);
    if (sheetApts) {
      var data = sheetApts.getDataRange().getValues();
      for (var i = 1; i < data.length; i++) {
        var num = data[i][0]; var floor = data[i][1]; if(!num || !floor) continue;
        var aptId = floor + "-" + num;
        result.apartments[aptId] = {
          id: aptId, roomNumber: num, floor: floor, pisoType: data[i][2], pisoStatus: data[i][3], banheiroType: data[i][4],
          banheiroStatus: data[i][5], temCofre: data[i][6] === 'Sim', temCortina: data[i][7] === 'Sim',
          cortinaStatus: data[i][8], cortinaSize: data[i][9], cortinaCoverage: data[i][10], temEspelhoCorpo: data[i][11] === 'Sim',
          espelhoCorpoStatus: data[i][12], acBrand: data[i][13], moveisStatus: data[i][14],
          moveisDetalhes: safeParse(data[i][15], []), beds: safeParse(data[i][16], []),
          temPortaControle: data[i][17] === 'Sim', temCabide: data[i][18] === 'Sim', cabideQuantity: data[i][19] || 0,
          temSuportePapel: data[i][20] === 'Sim', temSuporteShampoo: data[i][21] === 'Sim', suporteShampooStatus: data[i][22],
          luminariaType: data[i][23], luminariaColor: data[i][24], tvBrand: data[i][25], defects: safeParse(data[i][26], [])
        };
      }
    }

    // 3. Funcionários
    var sheetEmp = ss.getSheetByName('Funcionarios_' + hotel);
    if (sheetEmp) {
      var dE = sheetEmp.getDataRange().getValues();
      for (var k = 1; k < dE.length; k++) { 
        if(!dE[k][0]) continue; 
        result.employees.push({ 
          id: dE[k][0].toString(), name: dE[k][1], role: dE[k][2], gender: dE[k][3],
          contact: dE[k][4], salary: dE[k][5], sectorId: dE[k][6].toString(), 
          fixedDayOff: dE[k][7], sundayOffs: safeParse(dE[k][8], []), workingHours: dE[k][9], 
          status: dE[k][10], scheduleType: dE[k][12], shiftType: dE[k][15]
        }); 
      }
    }

    // 4. Extras
    var sheetExtra = ss.getSheetByName('Extras_' + hotel);
    if (sheetExtra) {
      var dExt = sheetExtra.getDataRange().getValues();
      for (var l = 1; l < dExt.length; l++) {
        if(!dExt[l][0]) continue;
        result.extras.push({
          id: dExt[l][0].toString(), name: dExt[l][1], phone: dExt[l][2],
          availability: safeParse(dExt[l][3], []), serviceQuality: dExt[l][4], sectorId: dExt[l][6].toString()
        });
      }
    }

    // 5. Configurações
    var sheetCfg = ss.getSheetByName('Config_' + hotel);
    if (sheetCfg) {
       var dC = sheetCfg.getDataRange().getValues();
       result.config = { showSuppliersTab: dC[1][0] === 'Sim', maxAptsPerMaid: dC[1][1] || 6 };
    }

    return ContentService.createTextOutput(JSON.stringify({status: 'success', data: result})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(15000);
    var req = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var hotel = req.hotel || 'VILLAGE';

    if (req.dataType === 'OCCUPANCY') {
       var sheet = ss.getSheetByName('Ocupacao_' + hotel) || ss.insertSheet('Ocupacao_' + hotel);
       sheet.clear();
       sheet.appendRow(['Data', 'Checkins', 'Checkouts']);
       req.data.forEach(function(d) { sheet.appendRow([d.date, d.checkins, d.checkouts]); });
    }
    else if (req.dataType === 'CONFIG') {
       var sheet = ss.getSheetByName('Config_' + hotel) || ss.insertSheet('Config_' + hotel);
       sheet.clear();
       sheet.appendRow(['ShowSuppliers', 'MaxAptsPerMaid']);
       sheet.appendRow([req.showSuppliersTab?'Sim':'Não', req.maxAptsPerMaid]);
    }
    // Adicionar outros tipos de sync (Apartment, Employee, Extra...) mantendo o padrão upsert

    return ContentService.createTextOutput(JSON.stringify({status: 'success'})).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: 'error', message: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

function safeParse(s, f) { try { if (!s || s == "") return f; return JSON.parse(s); } catch(e) { return f; } }
function upsert(s, id, r) { var d = s.getDataRange().getValues(); var ids = id.toString().trim(); for (var i = 1; i < d.length; i++) { if (d[i][0].toString().trim() == ids) { s.getRange(i+1, 1, 1, r.length).setValues([r]); return; } } s.appendRow(r); }
`;

