  const [showScriptModal, setShowScriptModal] = useState(false);
  const globalInt = integrations[0];
  const [url, setUrl] = useState(globalInt?.url || '');

  const saveUrl = () => {
    onUpdate({ ...globalInt, url, status: url ? 'Connected' : 'Disconnected', lastSync: Date.now() });
    alert('Conexão Global V42 configurada com sucesso!');
  };

  return (
    <div className="space-y-6">
      <div className="p-8 rounded-[2.5rem] text-white relative overflow-hidden shadow-lg" style={{ backgroundColor: theme.primary }}>
        <h2 className="text-xl font-black mb-1">Total Sync V42</h2>
        <p className="opacity-80 text-[10px] font-bold uppercase tracking-widest">Suporte a Escala Semanal e Inteligência de Carga</p>
        <FileSpreadsheet className="absolute right-[-20px] bottom-[-20px] text-white/10" size={160} />
      </div>

      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
        <input type="text" value={url} onChange={e => setUrl(e.target.value)} placeholder="Link do Apps Script Web App..." className="w-full px-4 py-3 rounded-xl border-2 border-slate-50 focus:border-blue-400 outline-none text-sm font-bold bg-slate-50" />
        <button onClick={saveUrl} className="w-full py-4 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-lg active:scale-95 transition-all" style={{ backgroundColor: theme.primary }}>Atualizar Conexão Global</button>
        <div className="p-5 bg-amber-50 rounded-2xl border border-amber-100">
           <p className="text-[10px] font-black text-amber-700 uppercase tracking-widest mb-2">Atenção!</p>
           <p className="text-[9px] text-amber-600 leading-relaxed font-bold">Certifique-se de atualizar o código no seu painel do Google Apps Script para a versão V42 para suportar a escala semanal.</p>
           <button onClick={() => setShowScriptModal(true)} className="text-[9px] font-black text-blue-600 underline uppercase tracking-widest mt-3 hover:text-blue-800 transition-colors">Ver Código V42</button>
        </div>
      </div>

      {showScriptModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-4xl rounded-[3rem] shadow-2xl max-h-[85vh] overflow-hidden flex flex-col animate-in zoom-in duration-300">
            <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
              <h3 className="text-xl font-black text-slate-800">Apps Script V42 - Total Sync</h3>
              <button onClick={() => setShowScriptModal(false)} className="p-3 hover:bg-slate-100 rounded-full transition-colors text-slate-400"><XCircle size={32} /></button>
            </div>
            <div className="p-8 overflow-y-auto flex-1">
              <div className="relative">
                <button onClick={() => { navigator.clipboard.writeText(APPS_SCRIPT_CODE); alert('Código V42 copiado!'); }} className="absolute top-4 right-4 p-3 bg-slate-900 text-white rounded-2xl shadow-xl flex items-center space-x-2 text-[10px] font-black uppercase">
                  <Copy size={16} /> <span>Copiar V42</span>
                </button>
                <pre className="bg-slate-950 text-emerald-400 p-10 rounded-[2.5rem] overflow-x-auto text-[10px] leading-relaxed font-mono shadow-inner border border-slate-800">
                  {APPS_SCRIPT_CODE}
                </pre>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default IntegrationsView;

import React, { useState } from 'react';
import { ViewType, HotelType, HotelTheme, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Hotel, 
  ReceiptPoundSterling, 
  Settings,
  Users,
  ChevronDown,
  ChevronRight,
  MapPin,
  LogOut,
  Package,
  FileBarChart,
  Calendar
} from 'lucide-react';

interface SidebarProps {
  currentView: ViewType;
  onViewChange: (view: ViewType) => void;
  currentHotel: HotelType;
  onHotelChange: (hotel: HotelType) => void;
  onLogout: () => void;
  theme: HotelTheme;
  role: UserRole;
}

const HotelLogo = ({ type }: { type: HotelType }) => {
  const logoStyles = "w-full h-auto max-h-24 object-contain";

  if (type === 'VILLAGE') {
    return (
      <img 
        src="https://static.pmweb.com.br/UDt4IZ8aLjmYHzWMKyDhqYu4WCo=/https://letsimage.s3.sa-east-1.amazonaws.com/editor/nacionalinn/pt/hoteis/hotel-village-inn-pocos-de-caldas/1687195313334-logo-vilage-inn-all-inclusive-pocos-de-caldas-%281%29.png" 
        alt="Hotel Village Inn" 
        className={logoStyles}
      />
    );
  }
  if (type === 'GOLDEN_PARK') {
    return (
      <img 
        src="https://static.pmweb.com.br/I5TMfCWS1GgWNcDKMjm4pzsFBbo=/https://letsimage.s3.sa-east-1.amazonaws.com/editor/nacionalinn/pt/hoteis/hotel-golden-park-pocos-de-caldas/1687196969718-logo-golden-park-all-inclusive-pocos-de-caldas.png" 
        alt="Hotel Golden Park" 
        className={logoStyles}
      />
    );
  }
  return (
    <img 
      src="https://static.pmweb.com.br/WYDXC2CrV6p3J-8GhYITK6Y2YJY=/https://letsimage.s3.sa-east-1.amazonaws.com/editor/nacionalinn/pt/hoteis/hotel-thermas-resort-walter-world/1686788413004-logo-thermas-.png" 
      alt="Thermas Resort" 
      className={logoStyles}
    />
  );
};

const Sidebar: React.FC<SidebarProps> = ({ currentView, onViewChange, currentHotel, onHotelChange, onLogout, theme, role }) => {
  const [isHotelOpen, setIsHotelOpen] = useState(true);

  const menuItems = [
    { id: ViewType.DASHBOARD, label: 'Dashboard', icon: LayoutDashboard, visible: role === 'GESTOR' },
    { id: ViewType.WEEKLY_SCALE, label: 'Escala Semanal', icon: Calendar, visible: role === 'GESTOR' },
    { id: ViewType.APARTMENTS, label: 'Apartamentos', icon: Hotel, visible: true },
    { id: ViewType.REPORTS, label: 'Relatórios', icon: FileBarChart, visible: true },
    { id: ViewType.BUDGETS, label: 'Orçamentos', icon: ReceiptPoundSterling, visible: role === 'GESTOR' },
    { id: ViewType.INVENTORY, label: 'Estoque', icon: Package, visible: true },
    { id: ViewType.EMPLOYEES, label: 'Equipe & Extras', icon: Users, visible: role === 'GESTOR' },
  ];

  const hotels: { id: HotelType; label: string }[] = [
    { id: 'VILLAGE', label: 'Village Inn' },
    { id: 'GOLDEN_PARK', label: 'Hotel Golden Park' },
    { id: 'THERMAL_RESORT', label: 'Thermas Resort' },
  ];

  return (
    <aside className="hidden md:flex w-64 bg-slate-900 text-white h-screen fixed left-0 top-0 shadow-xl z-50 flex-col">
      <div className="p-4 flex-1 overflow-y-auto scrollbar-hide">
        <div className="mb-8 mt-2 px-2">
          <div className="bg-white rounded-2xl p-4 shadow-xl flex items-center justify-center overflow-hidden">
            <HotelLogo type={currentHotel} />
          </div>
        </div>

        {role === 'GESTOR' && (
          <div className="mb-6">
            <button 
              onClick={() => setIsHotelOpen(!isHotelOpen)}
              className="w-full flex items-center justify-between px-4 py-2 text-slate-400 hover:text-white transition-colors"
            >
              <div className="flex items-center space-x-3">
                <MapPin size={16} />
                <span className="font-bold uppercase text-[10px] tracking-widest">Unidade</span>
              </div>
              {isHotelOpen ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
            </button>

            {isHotelOpen && (
              <div className="mt-2 ml-2 space-y-1 animate-in slide-in-from-top-2 duration-200">
                {hotels.map((hotel) => (
                  <button
                    key={hotel.id}
                    onClick={() => onHotelChange(hotel.id)}
                    className={`w-full text-left px-4 py-2.5 rounded-xl text-xs transition-all flex items-center justify-between ${
                      currentHotel === hotel.id 
                      ? 'bg-white/10 text-white font-bold ring-1 ring-white/20' 
                      : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
                    }`}
                  >
                    <div className="flex items-center space-x-2">
                      <div 
                        className="w-1.5 h-1.5 rounded-full" 
                        style={{ backgroundColor: currentHotel === hotel.id ? theme.primary : 'transparent' }} 
                      />
                      <span>{hotel.label}</span>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        <div className="h-px bg-slate-800/50 mb-6 mx-2"></div>

        <nav className="space-y-1.5">
          {menuItems.filter(i => i.visible).map((item) => {
            const Icon = item.icon;
            const isActive = currentView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => onViewChange(item.id)}
                className={`w-full flex items-center space-x-3.5 px-5 py-3 rounded-2xl transition-all duration-300 group ${
                  isActive 
                  ? 'text-white shadow-lg' 
                  : 'text-slate-500 hover:bg-white/5 hover:text-slate-300'
                }`}
                style={{ 
                  backgroundColor: isActive ? theme.primary : 'transparent',
                  boxShadow: isActive ? `0 10px 15px -3px ${theme.primary}40` : 'none'
                }}
              >
                <Icon size={18} className={isActive ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'} />
                <span className="font-bold text-sm">{item.label}</span>
              </button>
            );
          })}
        </nav>
      </div>

      <div className="p-6 border-t border-slate-800/50 bg-slate-900/50 flex flex-col space-y-2">
        {role === 'GESTOR' && (
          <button 
            onClick={() => onViewChange(ViewType.SETTINGS)}
            className={`w-full flex items-center space-x-3 transition-colors px-2 py-3 rounded-xl ${
              currentView === ViewType.SETTINGS ? 'text-white bg-white/10' : 'text-slate-500 hover:text-white'
            }`}
          >
            <Settings size={18} />
            <span className="text-sm font-medium">Configurações</span>
          </button>
        )}
        <button 
          onClick={onLogout}
          className="w-full flex items-center space-x-3 text-red-400/70 hover:text-red-400 transition-colors px-2 pt-4 border-t border-slate-800/30"
        >
          <LogOut size={18} />
          <span className="text-sm font-bold">Encerrar Sessão</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

import React from 'react';
import { ViewType, UserRole, HotelTheme } from '../types';
import { 
  LayoutDashboard, 
  Hotel, 
  ReceiptPoundSterling, 
  Users,
  Package,
  FileBarChart,
  Calendar
} from 'lucide-react';

interface BottomNavProps {
  currentView: ViewType;
  onViewChange: (view: ViewType) => void;
  theme: HotelTheme;
  role: UserRole;
}

const BottomNav: React.FC<BottomNavProps> = ({ currentView, onViewChange, theme, role }) => {
  const menuItems = [
    { id: ViewType.DASHBOARD, label: 'Início', icon: LayoutDashboard, visible: role === 'GESTOR' },
    { id: ViewType.WEEKLY_SCALE, label: 'Escala', icon: Calendar, visible: role === 'GESTOR' },
    { id: ViewType.APARTMENTS, label: 'Aptos', icon: Hotel, visible: true },
    { id: ViewType.REPORTS, label: 'Rels', icon: FileBarChart, visible: true },
    { id: ViewType.EMPLOYEES, label: 'Equipe', icon: Users, visible: role === 'GESTOR' },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 z-[100] md:hidden px-2 pb-safe">
      <div className="flex justify-around items-center h-16">
        {menuItems.filter(i => i.visible).map((item) => {
          const Icon = item.icon;
          const isActive = currentView === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onViewChange(item.id)}
              className="flex flex-col items-center justify-center w-full h-full relative group transition-all"
            >
              <div 
                className={`p-2 rounded-xl transition-all ${isActive ? 'bg-slate-50' : 'text-slate-400'}`}
                style={{ color: isActive ? theme.primary : undefined }}
              >
                <Icon size={22} strokeWidth={isActive ? 2.5 : 2} />
              </div>
              <span 
                className={`text-[9px] font-black uppercase tracking-tighter mt-0.5 ${isActive ? 'opacity-100' : 'opacity-40'}`}
                style={{ color: isActive ? theme.primary : undefined }}
              >
                {item.label}
              </span>
              {isActive && (
                <div 
                  className="absolute top-0 w-8 h-1 rounded-b-full" 
                  style={{ backgroundColor: theme.primary }} 
                />
              )}
            </button>
          );
        })}
      </div>
    </nav>
  );
};

export default BottomNav;

export enum ViewType {
  DASHBOARD = 'DASHBOARD',
  APARTMENTS = 'APARTMENTS',
  BUDGETS = 'BUDGETS',
  SETTINGS = 'SETTINGS',
  EMPLOYEES = 'EMPLOYEES',
  INVENTORY = 'INVENTORY',
  REPORTS = 'REPORTS',
  TODAY_SCHEDULE = 'TODAY_SCHEDULE',
  WEEKLY_SCALE = 'WEEKLY_SCALE'
}

export type UserRole = 'GESTOR' | 'FUNCIONARIO';

export interface User {
  role: UserRole;
  hotel?: HotelType;
  name?: string;
}

export type HotelType = 'VILLAGE' | 'GOLDEN_PARK' | 'THERMAL_RESORT';

export interface HotelTheme {
  primary: string;
  secondary: string;
  accent: string;
  bg: string;
  text: string;
  chartColors: string[];
}

export interface Defect {
  id: string;
  driveLink: string;
  description: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface MaterialQuote {
  supplier: string;
  value: number;
}

export interface MaterialItem {
  id: string;
  name: string;
  quantity: number;
  unit?: string;
  observation?: string;
  quotes: MaterialQuote[];
}

export interface BudgetItem {
  id: string;
  description: string;
  materials: MaterialItem[];
  laborCost: number;
  estimatedTime: string;
  serviceProvider?: string;
}

export interface BudgetFile {
  id: string;
  driveLink: string;
  timestamp: number;
  fileName?: string;
  fileType?: string;
  data?: string;
}

export interface Quote {
  id: string;
  supplier: string;
  value: number;
  files: BudgetFile[];
}

export interface Budget {
  id: string;
  title: string;
  objective: string;
  items: BudgetItem[];
  quotes: Quote[];
  status: 'Pendente' | 'Aprovado' | 'Rejeitado';
  createdAt: number;
}

export interface UniformItem {
  name: string;
  quantity: number;
}

export interface Sector {
  id: string;
  name: string;
  standardUniform: UniformItem[];
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  gender: 'M' | 'F';
  contact: string;
  startDate: string;
  salary: number;
  department: string;
  sectorId: string;
  status: 'Ativo' | 'Inativo';
  scheduleType: '6x1' | '12x36' | 'Intermitente';
  shiftType?: 'Par' | 'Ímpar';
  workingHours: string;
  fixedDayOff: string;
  sundayOffs: number[];
  monthlySundayOff: string;
  weeklyDayOff: string;
  vacationStatus: 'Pendente' | 'Concedida';
  uniforms: UniformItem[];
}

export interface ExtraLabor {
  id: string;
  name: string;
  phone: string;
  availability: string[];
  serviceQuality: number;
  observation: string;
  sectorId: string;
}

export interface OccupancyDay {
  date: string;
  checkins: number;
  checkouts: number;
}

export interface Supplier {
  id: string;
  name: string;
  contact: string;
  category: string;
}

export interface InventoryItem {
  id: string;
  ean?: string;
  name: string;
  category: string;
  quantity: number;
  minQuantity: number;
  unit: string;
  price: number;
  supplierId?: string;
  lastUpdate: number;
}

export interface InventoryOperation {
  id: string;
  itemId: string;
  itemName: string;
  type: 'Entrada' | 'Saída';
  quantity: number;
  timestamp: number;
  user: string;
  reason?: string;
}

export interface Integration {
  id: string;
  name: string;
  type: 'Spreadsheet' | 'ExternalAPI';
  status: 'Connected' | 'Disconnected' | 'Pending';
  lastSync?: number;
  url?: string;
}

// Added BedConfig interface to fix the missing exported member error in ApartmentDetailView.tsx
export interface BedConfig {
  type: 'Casal' | 'Solteiro';
  baseStatus: 'Nova' | 'Antiga';
